def client_venv_check_code() -> str:
    """The Python the image's last client-venv step runs — every top-level pin
    imported and version-asserted. Preflight re-runs the SAME snippet by argv
    (``[CLIENT_PY, "-c", code]``): the earlier shell re-quoting broke on the
    snippet's own ``'0.3.260'`` quotes and reported a SyntaxError as a pin
    failure (2026-09-03)."""
    pins = C.CLIENT_TOP_LEVEL_PINS
    return (
        "from importlib.metadata import version as v; "
        "import inspect_ai, inspect_evals, evalplus, aiohttp, transformers, datasets; "
        # the agentic-sandbox deps live in THIS venv (the bcb-bfcl-200 owned
        # sandbox provider is an inspect-sandboxes subclass)
        "import inspect_sandboxes, swebench, modal; "
        # the driver's own heavy imports (sisteer.models needs torch; registry readers scipy)
        "import torch, scipy; "
        # ifeval-canonical-battery (P7): the IFEval checker (the VCS line,
        # installed at its exact commit) and the two deps the `ifeval` extra /
        # the .in bring — imported so a build without them fails HERE, not in
        # the first GPU container's scorer
        "import instruction_following_eval, langdetect, immutabledict; "
        f"assert v('immutabledict') == '{pins['immutabledict']}', v('immutabledict'); "
        f"assert inspect_ai.__version__ == '{pins['inspect_ai']}', inspect_ai.__version__; "
        f"assert aiohttp.__version__ == '{pins['aiohttp']}', aiohttp.__version__; "
        f"assert transformers.__version__ == '{pins['transformers']}', transformers.__version__; "
        f"assert datasets.__version__ == '{pins['datasets']}', datasets.__version__; "
        f"assert v('inspect_evals') == '{pins['inspect_evals']}', v('inspect_evals'); "
        f"assert v('evalplus') == '{pins['evalplus']}', v('evalplus'); "
        f"assert v('inspect-sandboxes') == '{pins['inspect-sandboxes']}', v('inspect-sandboxes'); "
        f"assert v('swebench') == '{pins['swebench']}', v('swebench'); "
        f"assert v('torch') == '{pins['torch']}', v('torch'); "
        f"assert v('scipy') == '{pins['scipy']}', v('scipy'); "
        "print('CLIENT OK', inspect_ai.__version__, v('inspect_evals'), v('evalplus'), "
        "'inspect-sandboxes', v('inspect-sandboxes'), 'swebench', v('swebench'), 'modal', v('modal'))")


#: The argparse probe preflight runs instead of reading ``generate --help``
#: (whose formatting crashes on the driver's own help text — an unescaped ``%``
#: in the ``--vllm-log`` help, driver-owned): every tinycap flag with a
#: parse-valid dummy value plus ONE sentinel flag that does not exist, so
#: argparse itself lists what it did not recognise; a missing real flag shows up
#: beside the sentinel. Argparse exits 2 there, before the driver body runs.
DRIVER_PROBE_VALUES: Mapping[str, str] = {
    C.FLAG_THINKING: C.THINKING_OFF, C.FLAG_SAMPLES: "1", C.FLAG_INSPECT_LIMIT: "1",
    C.FLAG_LEDGER_URL: "http://127.0.0.1:1/v1", C.FLAG_OUT_ROOT: "/tmp/tinycap-preflight-probe",
    # fit-support transfer: the two VALUED flags an
    # out-of-support launch probes for. A value-taking flag probed bare makes
    # argparse stop at "expected one argument" BEFORE the unrecognized-arguments
    # line the probe reads (verified against the driver's parser), so each
    # carries a dummy value here the way the always-probed flags do.
    C.FLAG_OOS_PROMPT_BUDGET: f"/tmp/tinycap-preflight-probe/{C.OOS_PROMPT_BUDGET_FILENAME}",
    C.FLAG_EXPECT_OBJECT_SHA256: "0" * 64,
    # ifeval-canonical-battery follow-up (Appendix A): the attempt-scoped producer contract's id
    C.FLAG_ATTEMPT_ID: "a1",
    # bcb-bfcl-200 §S2b: the truncation ladder's two VALUED flags, probed on a
    # ladder launch (argparse recognition only; the sentinel stops the parse)
    C.FLAG_CAP_OVERRIDE: f"{C.LADDER_ROW_TASKS[0]}={C.LADDER_CAP_TO}",
    C.FLAG_ITEM_SELECTION_JSON: "{}",
    # tinycap-full22 §7 step 5, ported from 0fdddae3 for THIS tree's driver: every VALUED
    # flag an IFEval configuration composes, each with a dummy the driver's parser accepts. Probed
    # bare, argparse stopped at "expected one argument" before the unrecognized-arguments line the
    # probe reads, and every full22 preflight failed driver_accepts_tinycap_flags. The dropped
    # battery's lane / EvalPlus / only-controls flags do not exist on this driver and are not probed.
    C.FLAG_TINYCAP_IDENTITY_VERSION: str(C.TINYCAP_IDENTITY_VERSION_2),
    C.FLAG_MAX_TOKENS_BY_TASK: f"{C.IFEVAL_TASK_NAME}={C.IFEVAL_MAX_TOKENS_OFF}",
    # the mode flag's dummy is a NON-DEFAULT choice the merged driver's parser accepts — a driver
    # whose --sampling choices predate it stops at "invalid choice", which the probe reports as a
    # parse failure (the right refusal). `vendor_preset` (the IFEval wave this preflight admits) is
    # the value probed; bcb-bfcl-200-widen §S2's `protocol` is another valid choice of the same parser.
    C.FLAG_SAMPLING: C.SAMPLING_VENDOR_PRESET,
    C.FLAG_OFF_CAP_BY_TASK: f"{C.IFEVAL_TASK_NAME}={C.IFEVAL_CAP_LADDER[1]}",
    C.FLAG_ON_CAP_BY_TASK: f"{C.GSM8K_PAIRED_TASK_NAME}={C.G8K_CAP}",
    C.FLAG_ITEM_SUBSET: "/tmp/tinycap-preflight-probe/rung_subset.json",
    C.FLAG_BANK_VIEW: C.BANK_VIEW_MAIN,
    # bcb-bfcl-200-widen §S2: the preflight's resolved-parameter record flag, on a protocol launch
    C.FLAG_PROTOCOL_CHECK: f"/tmp/tinycap-preflight-probe/{C.PROTOCOL_CHECK_FILENAME}",
    # tinycap-shared-standup §1.1.4 (module F): the row runner's per-cell record flag, probed on a ROW launch only
    C.FLAG_ROW_ENGINE_RECORD: "/tmp/tinycap-preflight-probe/row_engine.json",
    # tinycap-shared-standup landing 2 (§2.2.3): the generate driver's phase flag, probed on a ROW launch only
    C.FLAG_VERIFICATION_PHASE: C.VERIFICATION_PHASE_COUPLED}
DRIVER_PROBE_SENTINEL = "--tinycap-preflight-probe"


def driver_probe_argv(tree: str, python: str = CLIENT_PY,
                      extra_flags: Sequence[str] = ()) -> List[str]:
    """The argparse probe's argv. ``extra_flags`` are appended beside the
    always-probed :data:`C.TINYCAP_DRIVER_FLAGS`, each with its
    :data:`DRIVER_PROBE_VALUES` dummy when it takes a value and bare when it is
    a switch (store_true): a launch that will compose
    ``--allow-out-of-support-thinking`` (PW-oos), ``--oos-prompt-budget`` or
    ``--expect-object-sha256`` probes for them here, so a
    staged tree whose driver predates a flag refuses on the CPU instead of
    dying in a container after a standup was paid for."""
    argv = [python, f"{tree}/scripts/served_capability_run.py", "generate",
            "--proxy-url", "http://127.0.0.1:1/v1",
            "--routing-table", "/nonexistent/routing_table.json", "--cell", C.CELL_PSRKL_SAFETY]
    for flag in C.TINYCAP_DRIVER_FLAGS:
        argv += [flag, DRIVER_PROBE_VALUES[flag]]
    for flag in extra_flags:
        argv += [flag] + ([DRIVER_PROBE_VALUES[flag]] if flag in DRIVER_PROBE_VALUES else [])
    return argv + [DRIVER_PROBE_SENTINEL]


DRIVER_REL = "scripts/served_capability_run.py"


def driver_accepts_per_task(tree: str | Path) -> Optional[bool]:
    """Whether the driver on this tree accepts ``--thinking per-task`` (O7 item
    4; the driver adds it). ``None`` when the file cannot be read.

    Read from the ``choices=`` of the driver's own ``--thinking`` argument, so
    the answer is the argparse fact rather than a grep for the word: the whole
    point is to SAY the flag is not there yet instead of composing it into an
    argv that would die inside a container after a standup was paid for."""
    src = Path(tree) / DRIVER_REL
    try:
        text = src.read_text(encoding="utf-8")
    except OSError:
        return None
    head = text.find("FLAG_THINKING")
    while head != -1:
        seg = text[head:head + 400]
        if "add_argument" in text[max(0, head - 40):head]:
            for name in ("LAUNCHER_THINKING_MODES", "THINKING_PER_TASK",
                         repr(C.THINKING_PER_TASK)):
                if name in seg.split(")")[0] or name in seg[:200]:
                    return True
            return False
        head = text.find("FLAG_THINKING", head + 1)
    return None


def per_task_note(tree: str | Path) -> str:
    """The dry run's one line about the per-task flag, whichever way it goes —
    a launcher that composed a flag the driver rejects would look fine here and
    fail in the container."""
    accepts = driver_accepts_per_task(tree)
    flag = f"{C.FLAG_THINKING} {C.THINKING_PER_TASK}"
    if accepts is True:
        return (f"   per-task: the driver on this tree accepts {flag} — one standup serves the "
                f"battery with each task at its own arm (contracts.THINKING_BY_TASK), and the "
                f"identity records thinking_by_task")
    if accepts is False:
        return (f"   per-task: WARNING — the driver on this tree does NOT accept {flag} (its "
                f"--thinking choices are the two whole arms). Lane W20b-D is landing it; until "
                f"then this configuration would fail inside the container, so run --modes off / "
                f"on, or launch at a sha whose driver has the flag")
    return (f"   per-task: could not read {DRIVER_REL} on this tree, so whether it accepts "
            f"{flag} is UNKNOWN — check before launching")


def unrecognized_flags(stderr: str) -> Optional[List[str]]:
    """The ``--flags`` in argparse's ``unrecognized arguments: …`` line (their
    dummy values dropped); ``None`` when argparse never got that far."""
    m = re.search(r"unrecognized arguments: (.+)", stderr or "")
    if not m:
        return None
    return [t for t in m.group(1).split() if t.startswith("--")]


#: The datasets library derives a DIFFERENT cache key for a ``data_dir=``
#: load online and offline (datasets 5.0.1, reproduced 2026-09-03 with the
#: exact inspect_ai call): online the hub listing turns ``data_dir`` into
#: ``data_files`` and the config id is a hash of them
#: (``default-8cbc416ed05c3005``); offline nothing can be listed, so the
#: cache lookup builds the id from the kwargs alone
#: (``BuilderConfig("default").create_config_id({"data_dir": "main"})`` =
#: ``default-data_dir=main``) and misses. inspect_evals 0.18.0's ``gsm8k``
#: loads ``openai/gsm8k`` with ``data_dir="main"`` at a pinned revision, so
#: the GPU containers (``HF_HUB_OFFLINE=1``) could not resolve it after a
#: healthy prime (an earlier preflight). This snippet — spliced into the loader
#: code — records every ``data_dir`` load made through ``datasets.load_dataset``
#: (inspect_ai calls the module attribute, so the wrapper sees it) and, ONLINE
#: only, COPIES the cache directory the load produced (``Dataset.cache_files``
#: names it: ``<root>/<ns___name>/<online id>/<version>/<hash>``) to the path
#: the offline lookup will build from the same kwargs. A copy, not a symlink:
#: Modal Volumes are not relied on for symlinks, and the two GSM8K arrow
#: files are ~5 MB. Verified offline in the laneB venv: the copy resolves
#: ``load_dataset`` and the full ``inspect_evals.gsm8k()`` constructor.
DATA_DIR_ALIAS_CODE = """
import shutil
import datasets as _datasets
_DATA_DIR_LOADS = []
_ORIG_LOAD_DATASET = _datasets.load_dataset
def _recording_load_dataset(path, name=None, data_dir=None, *args, **kwargs):
    ds = _ORIG_LOAD_DATASET(path, name, data_dir, *args, **kwargs)
    if data_dir is not None and isinstance(path, str) and "/" in path:
        _DATA_DIR_LOADS.append({"path": path, "name": name, "data_dir": data_dir,
                                "revision": kwargs.get("revision"), "ds": ds})
    return ds
_datasets.load_dataset = _recording_load_dataset
def _cache_dir_of(ds):
    files = getattr(ds, "cache_files", None)
    if not files and hasattr(ds, "values"):            # a DatasetDict: any split's files
        for split in ds.values():
            files = getattr(split, "cache_files", None)
            if files:
                break
    return Path(files[0]["filename"]).parent if files else None
def alias_data_dir_caches(loads, *, create):
    out = []
    for rec in loads:
        entry = {k: rec[k] for k in ("path", "name", "data_dir", "revision")}
        real = _cache_dir_of(rec["ds"])
        if real is None:
            out.append({**entry, "created": False, "err": "the load exposes no cache_files"})
            continue
        offline_id = _datasets.BuilderConfig(rec["name"] or "default").create_config_id(
            {"data_dir": rec["data_dir"]})
        dataset_root = real.parent.parent.parent          # <root>/<ns___name>/
        alias = dataset_root / offline_id / real.parts[-2] / real.parts[-1]
        entry.update(target=str(real), alias=str(alias), offline_config_id=offline_id)
        if alias.resolve() == real.resolve():
            out.append({**entry, "created": False, "present": True})
        elif alias.is_dir():
            out.append({**entry, "created": False, "present": True})
        elif not create:
            out.append({**entry, "created": False, "present": False,
                        "err": "alias absent and this run is offline (stage creates it)"})
        else:
            try:
                shutil.copytree(real, alias)
                out.append({**entry, "created": True, "present": True})
            except BaseException as e:
                out.append({**entry, "created": False, "present": False,
                            "err": f"{type(e).__name__}: {str(e)[:300]}"})
    return out
"""

#: The Inspect family's datasets go through the SAME second cache (inspect_ai's
#: ``hf_dataset`` calls ``datasets.load_dataset`` whenever a ``revision`` is
#: pinned, which inspect_evals 0.18.0 always does), so the stage primes it by
#: running the EXACT loaders the driver runs — the lane's own (MATH-500 ids,
#: the MATH-lighteval selection check, the HellaSwag pairing) and
#: inspect_evals' task constructors — in the client venv, online; preflight
#: re-runs them OFFLINE. A GATED repo (walledai/XSTest: 401/403 for every
#: token on this workspace) is recorded as unavailable, never as a step
#: failure; anything else failing fails the step. BFCL's constructor also
#: fills inspect_evals' own ``INSPECT_EVALS_CACHE_DIR/BFCL`` at its pinned
#: commit. argv[1] = the staged tree; argv[2] = ``online`` | ``offline`` (the
#: online run also lays down the ``data_dir`` cache aliases above, reported
#: under the ``__data_dir_cache_aliases__`` key).
INSPECT_LOADER_CODE = """
import importlib, json, sys
from pathlib import Path
tree = Path(sys.argv[1]); online = sys.argv[2] == "online"; out = {}
def go(name, fn):
    try:
        fn(); out[name] = {"ok": True}
    except BaseException as e:
        msg = f"{type(e).__name__}: {str(e)[:300]}"
        out[name] = {"ok": False, "err": msg,
                     "gated": ("gated" in msg.lower()) or (" 401 " in msg) or (" 403 " in msg)}
def ie(mod, fn):
    return getattr(importlib.import_module(f"inspect_evals.{mod}"), fn)
import yaml
""" + DATA_DIR_ALIAS_CODE + """
from datasets import load_dataset
pins = yaml.safe_load((tree / "configs/capeval/pins.yaml").read_text())["datasets"]
go("pins.gsm8k_platinum", lambda: load_dataset(pins["gsm8k_platinum"]["repo_id"], "main",
                                               split="test", revision=pins["gsm8k_platinum"]["revision"]))
go("pins.mmlu_validation", lambda: load_dataset(pins["mmlu"]["repo_id"], "all", split="validation",
                                                revision=pins["mmlu"]["revision"]))
from sisteer.capeval.tiers import inspect_served as I
go("lane.math500_problems", lambda: I.math500_problems())
go("lane.math500_selection", lambda: I.verify_math500_selection(I.math500_sample_ids()))
go("inspect_evals.math", lambda: ie("math.math", "math")())
go("inspect_evals.gsm8k", lambda: ie("gsm8k.gsm8k", "gsm8k")())
def _bfcl():
    tcats = importlib.import_module("inspect_evals.bfcl.utils.task_categories")
    cats = sorted(c for c in (set(tcats.V1_CATEGORIES) | set(tcats.V2_CATEGORIES)) if c != "rest")
    return ie("bfcl.bfcl", "bfcl")(categories=cats)
go("inspect_evals.bfcl", _bfcl)
go("inspect_evals.xstest", lambda: ie("xstest.xstest", "xstest")())
# ifeval-canonical-battery: the stock ifeval task at the pinned dataset revision (staged
# under STAGE_PINNED_KEYS "ifeval"), and the josejg checker's NLTK loader — it reads punkt /
# punkt_tab from the container user's ~/.cache/nltk_data ONLY (decisions I1), which the image
# bakes; nltk.download is replaced by a refusal for the call, so a loader that would have
# fetched anything fails HERE, on the CPU, not in the first GPU container's scorer
go("inspect_evals.ifeval", lambda: ie("ifeval.ifeval", "ifeval")())
def _ifeval_checker_nltk():
    import nltk
    from instruction_following_eval import evaluation as _ife
    def _refuse(*a, **k):
        raise RuntimeError("the IFEval checker tried to DOWNLOAD nltk data: punkt / punkt_tab are not baked")
    nltk.download = _refuse
    _ife.ensure_nltk_resource()
go("lane.ifeval_checker_nltk", _ifeval_checker_nltk)
# bcb-bfcl-200 (offline priming): the pinned BigCodeBench parquet
# through the THIN TASK (the stock constructor's own load_dataset at the pinned
# revision, the compose check, the position == id assertion) so the offline
# preflight proves the cache resolves; the two pins through the contracts'
# verified loaders. load_repo_task takes ONE positional argument, and the task
# dir it imports from must be THIS staged tree's (never the mounted repo's).
from sisteer.capeval.tinycap import contracts as CT
assert Path(I.INSPECT_TASKS_DIR).resolve().is_relative_to(tree.resolve()), (I.INSPECT_TASKS_DIR, tree)
go("lane.bcb_200_pin", lambda: CT.load_bcb_pin(I.REPO_ROOT))
go("lane.bfcl_200_pin", lambda: CT.load_bfcl_pin(I.REPO_ROOT))
# the three bcb-bfcl-200 modules the driver / provider import, resolved INSIDE
# the staged tree (a mounted copy would be another revision's code)
def _staged(name):
    mod = importlib.import_module(name)
    assert Path(mod.__file__).resolve().is_relative_to(tree.resolve()), (name, mod.__file__, tree)
go("lane.staged.sandbox_scope", lambda: _staged("sisteer.capeval.tinycap.sandbox_scope"))
go("lane.staged.rung_probe", lambda: _staged("sisteer.capeval.tinycap.rung_probe"))
go("lane.staged.sandbox_owned", lambda: _staged("sisteer.capeval.tiers.sandbox_owned"))   # needs the lock's modal + inspect-sandboxes
go("lane.bigcodebench_200", lambda: I.load_repo_task("bigcodebench_200")(ids=CT.load_bcb_pin(I.REPO_ROOT)["ids"]))
# capeval-full-tasks: the two FULL pins through their verified loaders and the full
# thin task (the same stock dataset load, the whole split)
go("lane.bcb_full_pin", lambda: CT.load_bcb_full_pin(I.REPO_ROOT))
go("lane.bfcl_full_pin", lambda: CT.load_bfcl_full_pin(I.REPO_ROOT))
go("lane.bigcodebench_full", lambda: I.load_repo_task("bigcodebench_full")(ids=CT.load_bcb_full_pin(I.REPO_ROOT)["ids"]))
out[sys.argv[3]] = alias_data_dir_caches(_DATA_DIR_LOADS, create=online)
print(json.dumps(out))
"""
#: The loader-output key under which the ``data_dir`` cache aliases ride
#: (argv[3] of the snippet; a list, not a loader verdict — the stage /
#: preflight readers split it off).
DATA_DIR_ALIASES_KEY = "__data_dir_cache_aliases__"
INSPECT_PRIME_STEP = "inspect_datasets_cache_primed"
#: The sha-pinned EvalPlus release archives the sandbox orchestrator stages
#: (``tinycap_sandbox.EVALPLUS_CACHE_DIR``) and executes against; the served
#: GENERATION reads the same bytes through evalplus's own full-file override
#: env vars (``configs/capeval/evalplus/datasets.json`` names them) instead
#: of the container's empty ``~/.cache/evalplus`` (which would re-download).
EVALPLUS_ARCHIVES_DIR = f"{C.VOL_CACHE_ROOT}/evalplus"
EVALPLUS_PINS_RELPATH = "configs/capeval/evalplus/datasets.json"


def inspect_loader_argv(tree: str, python: str = CLIENT_PY, *, offline: bool = False) -> List[str]:
    """The loader subprocess argv. ``-P`` (3.11+: never prepend the cwd to
    ``sys.path`` for ``-c``) — the stage of 0a7eb982 died on the staged-tree
    assertion because the container's cwd (``/root``, the image's mounted
    ``sisteer`` from ``add_local_python_source``) sat AHEAD of the PYTHONPATH
    the tree was first on, so ``inspect_served.REPO_ROOT`` resolved to ``/``;
    :func:`run_inspect_loaders` also runs it with ``cwd=<tree>``. The
    ``static-review-misses-container-paths`` class: the guard was right, the
    path it caught was the image's."""
    return [python, "-P", "-c", INSPECT_LOADER_CODE, str(tree), "offline" if offline else "online",
            DATA_DIR_ALIASES_KEY]


def run_inspect_loaders(tree: str, *, offline: bool, timeout_s: int = 3000
                        ) -> Tuple[Dict[str, Dict], List[Dict]]:
    """Every Inspect-family loader in the client venv: ``({name: {ok, err?,
    gated?}}, [data_dir cache alias records])``. Online it primes the
    datasets cache and lays down the aliases (stage); offline it proves the
    cache resolves (preflight; the alias list then only reports presence)."""
    env = dict(os.environ, PYTHONPATH=f"{tree}/src:{tree}/scripts")
    if offline:
        env["HF_HUB_OFFLINE"] = "1"
        env["HF_DATASETS_OFFLINE"] = "1"
    else:
        env.pop("HF_HUB_OFFLINE", None)
        env.pop("HF_DATASETS_OFFLINE", None)
    # the STAGED tree first on sys.path for the loader subprocess — PYTHONPATH
    # (src, then scripts) AND cwd=<tree> with -P (the image's /root copy of
    # sisteer must never win the import); the driver runs the same way
    r = subprocess.run(inspect_loader_argv(tree, offline=offline), capture_output=True, text=True,
                       env=env, cwd=str(tree), timeout=timeout_s)
    if r.returncode != 0:
        raise RuntimeError(
            f"inspect loaders ({'OFFLINE' if offline else 'online'}) died in the client venv: "
            f"{r.stderr[-2500:]}")
    out = json.loads(r.stdout.strip().splitlines()[-1])
    aliases = out.pop(DATA_DIR_ALIASES_KEY, [])
    return out, list(aliases)


def evalplus_override_env(tree: str, archives_dir: str = EVALPLUS_ARCHIVES_DIR) -> Dict[str, str]:
    """``{HUMANEVAL_OVERRIDE_PATH: <staged gz>, MBPP_OVERRIDE_PATH: <staged gz>}``
    from the tree's EvalPlus pins; refuses when a staged archive is missing
    (the sandbox orchestrator's ``--stage-datasets`` puts them there)."""
    pins = json.loads(Path(f"{tree}/{EVALPLUS_PINS_RELPATH}").read_text())["datasets"]
    env, missing = {}, []
    for pin in pins.values():
        path = Path(archives_dir) / pin["gz_filename"]
        if path.is_file():
            env[pin["override_env"]] = str(path)
        else:
            missing.append(str(path))
    if missing:
        raise FileNotFoundError(
            f"staged EvalPlus archives missing: {missing} — run `modal run "
            f"scripts/modal/tinycap_sandbox.py --stage-datasets --dry-run` first")
    return env


def client_venv_commands(lock_remote: str = CLIENT_LOCK_REMOTE,
                         hashed_remote: str = CLIENT_LOCK_HASHED) -> List[str]:
    """The image steps that build ``/opt/client`` from the hashed lock. Pure,
    so a test can read them: ``--no-deps --require-hashes`` on every hashed
    line (the build fails on non-resolution), the VCS lines — EXACTLY the
    contracts' allow-list ``C.CLIENT_VCS_PINS`` (since ifeval-canonical-battery
    P7, the josejg IFEval checker), each at its full commit, unhashable by
    construction — split out by NAME and installed at
    exactly those commits, then an import + version assertion."""
    venv, py = C.CLIENT_VENV, CLIENT_PY
    check = client_venv_check_code()
    vcs_names = [line.split(" @ ")[0] for line in C.CLIENT_VCS_PINS]
    return [
        f"uv venv --python {C.CLIENT_PYTHON} {venv}",
        # the hashed lines only: uv's --require-hashes refuses a VCS requirement
        # outright, so the commit-pinned git lines are split out (installed next)
        f"grep -v -E '^({'|'.join(vcs_names)}) @ ' {lock_remote} > {hashed_remote}",
        f"uv pip install --python {py} --no-deps --require-hashes -r {hashed_remote}",
        *(f"uv pip install --python {py} --no-deps '{line}'" for line in C.CLIENT_VCS_PINS),
        f"{py} -c \"{check}\"",
    ]


#: ifeval-canonical-battery (decisions I1): where the IFEval checker
#: (``instruction_following_eval.evaluation.ensure_nltk_resource``) reads its NLTK
#: tokenizers from — ``<home>/.cache/nltk_data`` of the CONTAINER user, the ONLY
#: path it consults (it ignores NLTK_DATA), so the image bakes punkt and
#: punkt_tab exactly there and the image env names the same directory for nltk.
NLTK_DATA_DIR = "/root/.cache/nltk_data"
NLTK_PUNKT_RESOURCES: Tuple[str, ...] = ("punkt", "punkt_tab")


def ifeval_nltk_check_code() -> str:
    """The Python the bake step ends with: the checker's OWN loader must return
    without downloading (``nltk.download`` is replaced by an exit for the call —
    offline it returns False rather than raising, so a missing resource would
    otherwise pass silently), and both tokenizers must resolve under
    :data:`NLTK_DATA_DIR`. Single quotes only: the step wraps it in double."""
    finds = " ".join(f"nltk.data.find('tokenizers/{r}', paths=['{NLTK_DATA_DIR}']);" for r in NLTK_PUNKT_RESOURCES)
    return ("import nltk, sys; from instruction_following_eval import evaluation as ife; "
            "nltk.download = lambda *a, **k: sys.exit('the IFEval checker tried to download nltk data - "
            f"{' / '.join(NLTK_PUNKT_RESOURCES)} are not baked under {NLTK_DATA_DIR}'); "
            f"ife.ensure_nltk_resource(); {finds} "
            f"print('NLTK OK', {', '.join(repr(r) for r in NLTK_PUNKT_RESOURCES)})")


def ifeval_nltk_bake_commands(py: str = CLIENT_PY) -> List[str]:
    """The image steps that bake the IFEval checker's NLTK data (decisions I1):
    ``punkt`` + ``punkt_tab`` downloaded into :data:`NLTK_DATA_DIR` by the CLIENT
    venv's nltk (the checker's dependency, from the lock), then
    :func:`ifeval_nltk_check_code`. Pure, so a test can read them; placed right
    after the client-venv layer, before the sibling-module copy layer."""
    downloads = "; ".join(f"nltk.download('{r}', download_dir='{NLTK_DATA_DIR}', quiet=True)"
                          for r in NLTK_PUNKT_RESOURCES)
    return [f"{py} -c \"import nltk; {downloads}\"",
            f"{py} -c \"{ifeval_nltk_check_code()}\""]



#: The launcher's sibling module ``scripts/modal/tinycap_images.py``, shipped INTO the image as a
#: COPY layer. ``modal run`` mounts nothing but the entrypoint, and this module imports
#: ``tinycap_images`` at load in EVERY container (stage, preflight, run_configuration) — the
#: donor's first stage container died with ``ModuleNotFoundError`` and crash-looped. A copy layer
#: (not a mount) because ``tinycap_images.build_image_of`` peels the trailing mount layer(s) to
#: derive ``image_nemotron`` and re-applies only ``add_local_python_source("sisteer")``.
TINYCAP_IMAGES_REMOTE = "/root/tinycap_images.py"
#: tinycap-shared-standup §1.5: the compile-cache sibling rides the SAME way (a copy layer under the mount, at /root
#: where the entrypoint lands and sys.path finds it); every container that imports this launcher needs it
TINYCAP_COMPILE_CACHE_REMOTE = "/root/tinycap_compile_cache.py"
#: The local files the shared image places under ``/root`` (beside whatever entrypoint Modal
#: mounts) — the ONE declaration a sibling Modal script (``tinycap_budget_measure.py``,
#: ``tinycap_parser_probe.py``) extends with its own mounts and a test rebuilds a container
#: root from (Modal mounts each function's OWN entrypoint only, so a sibling's
#: ``import tinycap_served`` resolves in its container only if that file is placed here too).
#: The lock files are copied to ``/opt`` and read at BUILD time only; ``sisteer`` rides
#: ``add_local_python_source``.
#: Verified 2026-09-13: ``add_local_python_source`` ships PYTHON
#: files ONLY (verified in a container: 260 ``.py``, 0 other), so the text ``sisteer.data.instructions``
#: vendors beside itself (``CONSTITUTION_FULL_PATH``, sha256 asserted at import) was absent at
#: ``/root/sisteer/data/`` in EVERY container — the first in-process import of the SI grammar
#: (``parse_launcher_cell`` -> ``resolve_si``) raised ``FileNotFoundError`` in five of five CPU
#: preflights (``config_and_objects_present``, ``object_identity_and_header_guard``,
#: ``derived_object_provenance``) and would have in every GPU container. Shipped as a COPY layer
#: beside the launcher's own files: a build step cannot follow a mount, and a copy layer survives
#: ``tinycap_images.build_image_of``'s peel, so ``image_nemotron`` inherits it with no second
#: spelling. The remote path is the module's own file name under the mount's package root, so a
#: rename of the vendored file fails loudly here, never silently in a container. NOT in
#: ``IMAGE_LOCAL_FILES`` (those are FLAT files beside the entrypoint, the shape the sibling
#: scripts' container-root tests rebuild); the siblings derive their images from ``image`` and so
#: inherit this layer.
CONSTITUTION_FULL_REMOTE = f"/root/sisteer/data/{_instructions.CONSTITUTION_FULL_PATH.name}"
#: The SAME failure class for the decode-policy export (2026-09-22). Since
#: 3b1d87dae / 2699c762f ``contracts`` loads ``sisteer.registry.decode_policy`` AT IMPORT, whose default path is the
#: package copy beside the module (``decode_policy.PACKAGE_EXPORT_PATH`` -> ``/root/sisteer/registry/decode_policy.json``
#: under the mount) and, failing that, ``<repo root>/configs/registry/decode_policy.json`` — a path that does not exist
#: in a container. ``add_local_python_source`` ships ``.py`` only (its default ``ignore=NON_PYTHON_FILES``, modal 1.5.4),
#: so EVERY function of this launcher (and of the siblings that import it) crash-looped at import from 2026-09-16 until
#: this copy layer: ``stage`` at tinycap-bcbw-stage-3ba0202 — ``NoPolicy: decode policy export not found at
#: /configs/registry/decode_policy.json``. Shipped exactly as the constitution text: a COPY layer under the mount, at
#: the package copy's own path, so image_nemotron inherits it and a moved export fails loudly here.
DECODE_POLICY_REMOTE = f"/root/sisteer/registry/{Path(_decode_policy.PACKAGE_EXPORT_PATH).name}"
IMAGE_VENDORED_FILES: Mapping[str, str] = {CONSTITUTION_FULL_REMOTE: str(_instructions.CONSTITUTION_FULL_PATH.resolve()),
                                           DECODE_POLICY_REMOTE: str(Path(_decode_policy.PACKAGE_EXPORT_PATH).resolve())}
IMAGE_LOCAL_FILES: Mapping[str, str] = {TINYCAP_IMAGES_REMOTE: str(Path(tinycap_images.__file__).resolve()),
                                        TINYCAP_COMPILE_CACHE_REMOTE: str(Path(CC.__file__).resolve())}

# the ONE serving image: capctrl_served.py's proven cu129 stack, verbatim, plus
# the client venv layer (P21) and the tinycap env
image = (
    modal.Image.from_registry("nvidia/cuda:12.9.1-devel-ubuntu22.04",
                              add_python="3.12")
    .apt_install("git", "build-essential")
    .env({"CUDA_HOME": "/usr/local/cuda"})
    .pip_install(
        *SERVING_STACK_SPECS, *serving_image_pin_specs(),     # R8: every helper pinned
        extra_index_url="https://download.pytorch.org/whl/cu129",
    )
    .pip_install(*TRANSFORMERS_SPECS, extra_options="--no-deps --force-reinstall")
    .run_commands(
        "python -c \"import torch, vllm, transformers, aiohttp, yaml; "
        "assert torch.__version__ == '2.11.0+cu129', torch.__version__; "
        "assert vllm.__version__.startswith('0.25.1'), vllm.__version__; "
        "print('IMAGE OK', vllm.__version__, torch.__version__)\"",
        "which vllm",
    )
    .pip_install(f"uv=={UV_PIN}")
    .add_local_file(str(REPO_LOCAL / C.CLIENT_LOCK_TXT), CLIENT_LOCK_REMOTE, copy=True)
    .run_commands(*client_venv_commands())
    # ifeval-canonical-battery (decisions I1): the checker's NLTK tokenizers, baked where
    # its loader reads them (NLTK_DATA_DIR), right after the venv that owns nltk
    .run_commands(*ifeval_nltk_bake_commands())
    # the sibling module the launcher process imports at load, as a COPY layer placed UNDER a
    # build layer (.env): a copy layer's own deps carry its context Mount, so as the TOP build layer
    # build_image_of would peel it too and the Nemotron containers would lack the file again
    .add_local_file(str(Path(tinycap_images.__file__).resolve()), TINYCAP_IMAGES_REMOTE, copy=True)
    # tinycap-shared-standup §1.5 (module D): the compile-cache sibling, the same copy layer right beside it
    .add_local_file(str(Path(CC.__file__).resolve()), TINYCAP_COMPILE_CACHE_REMOTE, copy=True)
    # the vendored constitution text the SI grammar asserts at import (CONSTITUTION_FULL_REMOTE above)
    .add_local_file(str(_instructions.CONSTITUTION_FULL_PATH.resolve()), CONSTITUTION_FULL_REMOTE, copy=True)
    # the decode-policy export `contracts` loads at import (DECODE_POLICY_REMOTE above)
    .add_local_file(str(Path(_decode_policy.PACKAGE_EXPORT_PATH).resolve()), DECODE_POLICY_REMOTE, copy=True)
    .env({"HF_HOME": f"{VOL_PATH}/hf", "HF_HUB_OFFLINE": "1",
          "TOKENIZERS_PARALLELISM": "false",
          "INSPECT_EVALS_CACHE_DIR": C.VOL_INSPECT_EVALS_CACHE,
          "SISTEER_HELDOUT_CORPUS_DIR": f"{VOL_PATH}/heldout_corpora",
          # ifeval-canonical-battery (decisions I1): nltk's own search path = the baked
          # directory (the checker ignores it and reads the same path by construction)
          "NLTK_DATA": NLTK_DATA_DIR})
    # The LAUNCHER PROCESS in the container imports ``contracts`` (names) and
    # ``geometry`` (the S computation) at module load, before any --sha is
    # known, so it needs a ``sisteer`` of its own: the local checkout's, mounted
    # at /root (the sandbox orchestrator's pattern; Modal mounts nothing but
    # the script by default — verified from the stage run's mount list). The
    # standup / ledger / driver SUBPROCESSES never see it: their PYTHONPATH is
    # the STAGED tree. Preflight refuses if the two copies of the modules the
    # launcher process uses differ (``launcher_modules_match_tree``).
    .add_local_python_source("sisteer")
)

#: The Nemotron image variant = ``image`` + the two source-built fused-kernel packages
#: (``tinycap_images.nemotron_image``). Bound at import because a Modal function's image is
#: fixed at decoration. A process whose ``modal`` lacks the image internals the builder
#: reads (a test double) records WHY and binds the base image instead — and ``main`` then
#: REFUSES any Nemotron launch (``IMAGE_NEMOTRON_UNBOUND``), so this is a loud gate, never
#: a silent fallback onto the kernel-less image.
IMAGE_NEMOTRON_ERROR: Optional[str] = None
try:
    image_nemotron = tinycap_images.nemotron_image(image)
except Exception as _e:  # noqa: BLE001 — recorded and refused at launch, never swallowed
    IMAGE_NEMOTRON_ERROR = f"{type(_e).__name__}: {_e}"
    image_nemotron = image

#: where the Nemotron backend attestations live on the volume (one per cache key)
NEMO_BACKEND_ROOT = f"{C.VOL_TINYCAP_ROOT}/nemo_backend"

#: The ``sisteer`` modules the launcher process itself executes in-container
#: (from the mount above); preflight asserts each is byte-identical to the
#: staged tree's copy, so a launch from a checkout other than ``--sha`` refuses.
LAUNCHER_PROCESS_MODULES: Tuple[str, ...] = (
    "capeval/tinycap/contracts.py", "capeval/tinycap/object_identity.py",
    # bcb-bfcl-200: the sandbox owner tuple + sweep (launcher AND driver), the
    # truncation ladder's rung probe + certificate (launcher), the owned
    # sandbox provider the driver's Inspect run registers
    "capeval/tinycap/sandbox_scope.py", "capeval/tinycap/rung_probe.py",
    "capeval/tiers/sandbox_owned.py",
    # bcb-bfcl-200-widen: the lane roster's snapshot reader (launcher AND analysis)
    "capeval/tinycap/widen_roster.py",
    # the BCB verifier transport — the driver installs it, the
    # launcher reads its spill ledger into the REC
    "capeval/tinycap/verifier_transport.py",
    "capeval/serving/proxy.py",
    "capeval/serving/geometry.py", "capeval/serving/vllm_server.py",
    # the resume identity check re-hashes a store's resolved_config (E12 item 1)
    "capeval/store.py", "capeval/manifest.py")


def sha256_file(path: str | Path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _lock_matches_tree(remote: str, staged: str, what: str) -> str:
    """sha256 of the lock the image was built from (mounted at ``remote``) must
    equal the staged tree's copy at ``staged``; returns the digest."""
    a, b = sha256_file(remote), sha256_file(staged)
    if a != b:
        raise AssertionError(f"image {what} {a[:12]} != staged tree {what} {b[:12]} — rebuild the "
                             "image from this tree or stage the tree the image was built from")
    return a


def check_client_lock_matches_tree(tree: str) -> Dict[str, str]:
    """The client venv the image carries was built from the staged tree's
    ``C.CLIENT_LOCK_TXT``, byte for byte (its sha256 is hashed identity in every
    tinycap store's ``frameworks`` block). Module-level — lifted out of
    ``preflight``'s closures — so a sibling launcher can run the SAME check
    before its generation."""
    return {"client_lock_sha256": _lock_matches_tree(
        CLIENT_LOCK_REMOTE, f"{tree}/{C.CLIENT_LOCK_TXT}", "lock")}


def check_launcher_modules_match_tree(
        tree: str, modules: Sequence[str] = LAUNCHER_PROCESS_MODULES) -> Dict[str, object]:
    """Every module the launcher PROCESS executes from its mounted ``sisteer``
    (the local checkout at launch) is byte-identical to the staged tree's copy.
    ``modules`` defaults to THIS launcher's inventory; a sibling launcher passes
    its EXTENDED one — a mounted-only edit of a module it runs would otherwise
    pass under an unchanged ``--sha``."""
    import sisteer
    mounted = Path(sisteer.__file__).resolve().parent
    staged = Path(f"{tree}/src/sisteer")
    out, bad = {}, []
    for rel in modules:
        a, b = sha256_file(mounted / rel), sha256_file(staged / rel)
        out[rel] = a[:12]
        if a != b:
            bad.append(f"{rel}: mounted {a[:12]} != staged {b[:12]}")
    if bad:
        raise AssertionError(
            "the launcher process's sisteer (the local checkout mounted at launch) "
            f"differs from the staged tree at {tree}: {bad} — launch from the checkout "
            "at --sha, or stage the tree you are launching from")
    return {"mounted_from": str(mounted), "sha256_12": out}


#: ``--smoke`` writes under ``<cell out_dir>/<SMOKE_OUT_SUBDIR>/`` unless
#: ``--out-suffix`` says otherwise: a ``--limit 5`` run files ordinary
#: ``done/<task>.json`` markers, which a later full pass-1 under the SAME root
#: would trust and skip the task — a separate root makes that impossible.
SMOKE_OUT_SUBDIR = "smoke"


# --------------------------------------------------------------------------- #
# The serving PATH the launcher asks the                                        #
# standup for, the ENGINE the standup then attests, and the row-facing          #
# vocabulary the stores and identities carry. W-A's contracts own the           #
# canonical names (SERVED_ENGINE_FIELD, REDUCTION_MODE_NOT_APPLICABLE, the two   #
# RECs, endpoint_is_native, served_identity_fields(native=)); each is read off   #
# contracts when it is there and stubbed to the literal otherwise, so           #
# this launcher composes the same records before and after that landing.        #
# --------------------------------------------------------------------------- #
SERVING_PATH_FLAG = C.FLAG_SERVING_PATH
SERVING_PATH_LORA_NATIVE = "lora_native"
SERVING_PATH_LENS = "lens"
SERVING_PATHS: Tuple[str, ...] = (SERVING_PATH_LORA_NATIVE, SERVING_PATH_LENS)
#: the ENTRY-POINT default — ``main`` / the ``modal run`` CLI / ``launch_argv`` (the argv mirror
#: of ``main``): the same constant as ``registry_adapter.DEFAULT_STANDUP_SERVING_PATH`` (pinned
#: equal by test wherever that name exists). Every LoRA cell serves natively by default
#:, and since native-psr-serving so does every residual-slot kind
#: (psr / vector / vector_all / diffmean / static_r — the object's position mode judged at
#: standup); a Class B kind outside ``defense_cells.NATIVE_LORA_SERVABLE_KINDS`` refuses at PLAN
#: time naming ``--serving-path lens``, which runs today's lens launch byte for byte.
SERVING_PATH_DEFAULT = SERVING_PATH_LORA_NATIVE
#: the LIBRARY default — the planners, the identity derivation, the argv composer, the Nemotron
#: readers and the probe: ``lens``, so a direct call without the argument composes today's lens
#: launch, identity and certificate key byte for byte (the golden lens tests stand unchanged);
#: ``main`` threads its explicit path into every one of them (§1.1's "the dataclass default stays
#: lens"). Judgement call (W-G): the two defaults are deliberately different constants.
SERVING_PATH_LIBRARY_DEFAULT = SERVING_PATH_LENS
#: the plan marker on a configuration, PRESENT IFF native (the SAMPLING_MODE_KEY pattern: every
#: lens plan is byte-identical, and the worker reads THIS off the configuration it was handed —
#: E54 #6 — never a kwarg beside it that could name the other engine)
SERVING_PATH_KEY = "serving_path"
#: ``endpoint.json.engine`` (the native core writes ``lora_native``; a lens standup writes no key,
#: or ``lens``) and the row-facing spelling every store / identity carries (``serving_engine``)
ENDPOINT_KEY_ENGINE = "engine"
ENGINE_LORA_NATIVE = "lora_native"
ENGINE_LENS = "lens"
ENGINES: Tuple[str, ...] = (ENGINE_LENS, ENGINE_LORA_NATIVE)
SERVED_ENGINE_FIELD: str = getattr(C, "SERVED_ENGINE_FIELD", "serving_engine")
REDUCTION_MODE_NOT_APPLICABLE: str = getattr(C, "REDUCTION_MODE_NOT_APPLICABLE", "not_applicable")
REC_SERVING_ENGINE_MISMATCH: str = getattr(C, "REC_SERVING_ENGINE_MISMATCH", "SERVING_ENGINE_MISMATCH")
REC_SERVING_ENGINE_CONFLICT: str = getattr(C, "REC_SERVING_ENGINE_CONFLICT", "SERVING_ENGINE_CONFLICT")
#: the native output NAMESPACE (defence in depth): a native launch's out root is
#: ``<gen root>/native/<model>/<cell>/thinking_<mode>``, so a native run cannot land in a lens
#: root BY DEFAULT; the TERMINAL check (:func:`engine_conflict_at_output`) is what refuses when an
#: operator points it there. Lens paths are byte-identical.
OUT_SUBDIR_NATIVE = C.OUT_SUBDIR_NATIVE
#: §1.9: the adapter bank off-cluster — exported into EVERY container (the native core's
#: ``resolve_adapter_bank`` reads it last) and ALSO passed explicitly as ``--adapter-bank
#: <root>/<model key>`` (the deterministic default, recorded in ``endpoint.json.adapter_bank``)
ADAPTER_BANK_ROOT_ENV = "SISTEER_ADAPTER_BANK_ROOT"
ADAPTER_BANK_ROOT = f"{C.VOL_TINYCAP_ROOT}/multilora_adapters"
ADAPTER_BANK_FLAG = "--adapter-bank"
#: ``/v1/models`` -> ``petri_proxy.engine.kind`` (``proxy.ENGINE_KEY``; the identity block the
#: driver reads too) — held equal to ``endpoint.json.engine`` under native (SERVING_ENGINE_MISMATCH
#: otherwise)
PROXY_IDENTITY_KEY = "petri_proxy"
PROXY_IDENTITY_ENGINE_KEY = "engine"
#: §1.8: ``endpoint.json.geometry.adjustments`` — the ONE ordered record of how the served S left
#: the budget's ([] identity; [kernel]; [kv]; [kernel, kv]); W-A's ``geometry.py`` owns the
#: validator (``geometry_adjustment_problem`` / ``kernel_ceiling_adjustment`` /
#: ``LORA_MAX_MODULE_DIM_BY_MODEL``), read off it when present, stubbed here to the same rule
GEOMETRY_ADJUSTMENTS_KEY = "adjustments"
#: the truncation ladder's DELIBERATE reduction record inside a ``geometry`` block (``geometry.LADDER_REDUCTION_KEY``):
#: written by THIS launcher for a native rung asked below the budget's identity S, at the top of its
#: served_geometry.json geometry block, where the scoring driver reads it
GEOMETRY_LADDER_REDUCTION_KEY = "ladder_reduction"
ADJUSTMENT_KERNEL = "lora_kernel_index_ceiling"
ADJUSTMENT_KV = "kv_shrink"
#: the class step (geometry.ADJUSTMENT_LAUNCH_CLASS, 53bd76ed0 / 3f1a19b48, 2026-10-01): the pinned site record's per-window S re-derived
#: over the launches whose adapter class DOMINATES the served standup — the one step that may RAISE S. It LEADS the chain; the shared
#: validator (geometry.geometry_adjustment_problem) re-derives it from the pinned record, the launcher APPLIES it exactly as the native
#: standup does (native_standup.launch_class_geometry: max_num_seqs -> to_S, seqs_source "override"), never through the KV path
#: (the launcher's vocabulary had not followed geometry's; tests/test_tinycap_launcher_native.py pins the mirror)
ADJUSTMENT_LAUNCH_CLASS = "launch_class"
ADJUSTMENT_KINDS: Tuple[str, ...] = (ADJUSTMENT_LAUNCH_CLASS, ADJUSTMENT_KERNEL, ADJUSTMENT_KV)
#: the widest adapted module (o_proj) per model — D of the LoRA kernel's int32 index ceiling,
#: pinned to the pulled certification attestations (gemma 4096, qwen 4096, nemotron 5120,
#: llama 4096); the launcher-side STUB of W-A's ``geometry.LORA_MAX_MODULE_DIM_BY_MODEL``
_LORA_MAX_MODULE_DIM_BY_MODEL_FALLBACK: Mapping[str, int] = {
    "gemma4e4b": 4096, "qwen35_4b": 4096, "nemotron3nano4b": 5120, "llama8b": 4096}
LORA_KERNEL_INDEX_LIMIT = 2 ** 31 - 1


def check_serving_path_arg(path: object) -> str:
    """The closed :data:`SERVING_PATHS` vocabulary; anything else refuses by name."""
    if path not in SERVING_PATHS:
        raise ValueError(f"{SERVING_PATH_FLAG} must be one of {list(SERVING_PATHS)}, got {path!r}")
    return str(path)


def is_native_path(path: str) -> bool:
    return check_serving_path_arg(path) == SERVING_PATH_LORA_NATIVE


def engine_of_serving_path(path: str) -> str:
    """The engine a standup under ``path`` attests: ``lora_native`` -> ``lora_native``, ``lens`` -> ``lens``."""
    return ENGINE_LORA_NATIVE if is_native_path(path) else ENGINE_LENS


def serving_path_of(cfg: Mapping) -> str:
    """The serving path a planned configuration runs under — the plan's :data:`SERVING_PATH_KEY`
    when present (native), else lens; an unknown value refuses."""
    return check_serving_path_arg(str(cfg.get(SERVING_PATH_KEY) or SERVING_PATH_LENS))


def native_gen_root(root: Optional[str] = None) -> str:
    """``<root>/native`` — the native launches' out-root namespace (:data:`OUT_SUBDIR_NATIVE`);
    ``root`` defaults to ``contracts.VOL_GEN_ROOT`` read at CALL time (the tests and the dispatcher
    re-point it)."""
    root = C.VOL_GEN_ROOT if root is None else root
    # THE ONE derivation, shared with the sandbox watcher (``contracts.gen_root_for_engine``;
    # ``tinycap_sandbox_watch.cell_out_dir``), so the watcher looks for a native run's attempt pointers
    # exactly where this launcher plans its out dirs
    return C.gen_root_for_engine(str(root), ENGINE_LORA_NATIVE)


def ladder_gen_root(root: str, serving_path: str) -> str:
    """The root a truncation ladder's RECORDS (``<root>/<model>/_ladder/<suffix>/rung_probe.<cell>.json``,
    ``rung_admission.json``) are filed under for a launch on ``serving_path`` — ``root`` itself on the
    lens (every historical certificate address byte-identical), :func:`native_gen_root` on the native
    engine: the native ladder's records live in the native namespace beside its out roots, so a native
    certify never trips LADDER_CERTIFICATE_EXISTS on a lens certificate of the same suffix, nor a
    lens launch on a native one."""
    return native_gen_root(root) if is_native_path(serving_path) else str(root).rstrip("/")


def adapter_bank_for(model_key: object) -> str:
    """``--adapter-bank`` for a native standup: ``<ADAPTER_BANK_ROOT>/<model key>`` — exactly what the
    core's ``resolve_adapter_bank`` derives from :data:`ADAPTER_BANK_ROOT_ENV`, stated explicitly so
    ``endpoint.json.adapter_bank`` records a deterministic path. Refuses a geometry that names no model."""
    if not model_key:
        raise ValueError("a native standup needs the geometry's model_key to name its adapter bank "
                         f"({ADAPTER_BANK_ROOT}/<model key>); this geometry names none")
    return f"{ADAPTER_BANK_ROOT}/{model_key}"


def endpoint_engine(endpoint: Mapping) -> str:
    """The engine a standup's ``endpoint.json`` attests: ``engine`` when stated (``lora_native`` /
    ``lens``), ``lens`` when the key is absent (every lens standup before the native landing wrote
    none — lens BY ERA). An unknown value is a ``ValueError`` naming it. Imports nothing (read
    inside the container after the bring-up, like :func:`endpoint_reduction_mode`)."""
    if not isinstance(endpoint, Mapping):
        raise ValueError(f"endpoint record is not a mapping ({type(endpoint).__name__}); no engine can be read")
    engine = endpoint.get(ENDPOINT_KEY_ENGINE)
    if isinstance(engine, Mapping):
        engine = engine.get("kind")        # the /v1/models identity block spells the engine as a block
    row_engine = endpoint.get(SERVED_ENGINE_FIELD)     # the row-facing spelling the native core writes beside it
    if engine is not None and row_engine is not None and engine != row_engine:
        raise ValueError(f"endpoint.json states {ENDPOINT_KEY_ENGINE}={engine!r} and {SERVED_ENGINE_FIELD}="
                         f"{row_engine!r} — two spellings of one engine that disagree; a torn record")
    engine = engine if engine is not None else row_engine
    if engine is None:
        return ENGINE_LENS
    if engine not in ENGINES:
        raise ValueError(f"endpoint.json {ENDPOINT_KEY_ENGINE}={engine!r} is not one of {list(ENGINES)}")
    return str(engine)


def endpoint_is_native(endpoint: Mapping) -> bool:
    """``contracts.endpoint_is_native`` when the contracts have it (W-A), else the same reading."""
    fn = getattr(C, "endpoint_is_native", None)
    if callable(fn):
        return bool(fn(endpoint))
    return isinstance(endpoint, Mapping) and endpoint.get(ENDPOINT_KEY_ENGINE) == ENGINE_LORA_NATIVE


def _served_identity_fields(*, protocol_sampling: bool, native: bool) -> Tuple[str, ...]:
    """``contracts.served_identity_fields(protocol_sampling, native=)`` —
    the ONE key set the launcher's expectation, its store-trust exact-keys check and the driver's
    own assertion derive. Until the contracts take ``native=``, the launcher appends
    :data:`SERVED_ENGINE_FIELD` itself, PRESENT IFF native (the lens key set is byte-identical)."""
    import inspect as _inspect
    fn = C.served_identity_fields
    if "native" in _inspect.signature(fn).parameters:
        return tuple(fn(protocol_sampling=protocol_sampling, native=native))
    fields = tuple(fn(protocol_sampling=protocol_sampling))
    return (*fields, SERVED_ENGINE_FIELD) if native else fields


def _cell_grammar_modules():
    """``defense_cells`` + ``registry_adapter`` by MODULE, lazily and torch-free (the rule
    ``contracts._cell_grammar`` states: never through ``harness_cell_id``, which pulls torch)."""
    from sisteer.capeval.petri import defense_cells as dc
    from sisteer.capeval.petri import registry_adapter as ra
    return dc, ra


def native_kind_of_cell(cell: str) -> Optional[str]:
    """The OBJECT kind a fitted cell's arm stores (``registry_adapter.ARM_OBJECT_KINDS``: psr_kl_all
    -> ``psr``, lora_r4 / lora_r4_ce -> ``lora_all``, lora_r4_ce_minus_ctl -> ``lora_subtraction``,
    a bare Class B id -> its own kind) — ``None`` for ``none`` and a prompted cell (passthrough legs,
    served on either engine). Unknown arm: refused by name (the grammar admitted a cell the kind
    table does not know — a real gap, never read as servable)."""
    parsed = C.parse_launcher_cell(cell)
    if parsed.kind != C.CELL_KIND_FITTED:
        return None
    _dc, ra = _cell_grammar_modules()
    arm = parsed.arm or parsed.cell
    kind = ra.ARM_OBJECT_KINDS.get(arm)
    if not kind:
        raise ValueError(f"cell {cell!r}: arm {arm!r} has no object kind in registry_adapter.ARM_OBJECT_KINDS — "
                         "its native disposition cannot be judged")
    return str(kind)


def native_serving_disposition(kind: str) -> Tuple[str, Optional[str]]:
    """``defense_cells.native_serving_disposition(kind, resolved_spec=None)`` when
    the tree has it; else the same verdict through the backstop ``native_lora_unservable_reason`` —
    ``serve`` when the KIND is natively servable (a PEFT-exportable LoRA kind, or — since
    native-psr-serving — a residual-slot kind: psr / vector / vector_all / diffmean / static_r),
    ``skip`` (a structural exclusion: AlphaSteer / antidote / LoReFT / the stacked wrapper have no
    native form) otherwise. ``refuse`` needs a resolved spec the planner has not read, so it never
    arises here."""
    dc, _ra = _cell_grammar_modules()
    fn = getattr(dc, "native_serving_disposition", None)
    if callable(fn):
        verdict, reason = fn(kind, None)
        return str(verdict), reason
    reason = dc.native_lora_unservable_reason(kind, None)
    return ("serve", None) if reason is None else ("skip", reason)


def native_cell_refusal(cell: str) -> Optional[str]:
    """Why ``cell`` cannot be PLANNED under ``--serving-path lora_native`` — None when it can. A
    single-cell tinycap configuration whose object KIND is skip-class (a Class B kind outside
    ``defense_cells.NATIVE_LORA_SERVABLE_KINDS``: antidote, alphasteer, …) has nothing to serve
    natively, so the plan refuses it BY NAME here, before any Modal call, and names the escape
    hatch; the standup (capctrl's partition) would refuse the same cell after an H200 was
    allocated. The residual-slot kinds (psr / vector / vector_all / diffmean / static_r) PLAN
    natively since native-psr-serving — the kind alone is servable; the OBJECT's position mode is
    judged at standup from the record (``defense_cells.native_serving_disposition`` with the
    resolved spec), where an unjudgeable record refuses by name. ``none`` and the prompted cells
    are passthrough legs on either engine."""
    kind = native_kind_of_cell(cell)
    if kind is None:
        return None
    verdict, reason = native_serving_disposition(kind)
    if verdict == "serve":
        return None
    return (f"cell {cell!r} (kind {kind!r}) cannot be served on the native multi-LoRA engine — {reason}; "
            f"a native tinycap configuration of it has nothing to serve. Pass {SERVING_PATH_FLAG} "
            f"{SERVING_PATH_LENS} to run it on the lens standup (a kind outside "
            "defense_cells.NATIVE_LORA_SERVABLE_KINDS stays on the lens; the residual-slot kinds — "
            "psr / vector / vector_all / diffmean / static_r — serve natively since native-psr-serving, "
            "their position mode judged from the OBJECT at standup)")


def lora_max_module_dim(model_key: object, sg=None) -> Optional[int]:
    """D of the kernel ceiling for ``model_key``: W-A's ``geometry.LORA_MAX_MODULE_DIM_BY_MODEL``
    when the (staged) geometry module carries it, else the launcher's pinned fallback; None for a
    model neither knows."""
    table = getattr(sg, "LORA_MAX_MODULE_DIM_BY_MODEL", None) if sg is not None else None
    if not isinstance(table, Mapping):
        table = _LORA_MAX_MODULE_DIM_BY_MODEL_FALLBACK
    d = table.get(str(model_key)) if model_key is not None else None
    return int(d) if d else None


def kernel_ceiling_adjustment(model_key: object, L: int, S_identity: int, *, sg=None) -> Optional[dict]:
    """§1.8, PURE: the kernel step ``{kind, from_S, to_S, D, ceiling}`` when the LoRA kernel's int32
    index ceiling ``(2^31-1) // D`` lowers S at window ``L`` (``to_S = min(S_identity,
    ceiling // L)``, present iff it lowers), else None. Through W-A's
    ``geometry.kernel_ceiling_adjustment`` when the module has it. Refuses a model whose D is
    unknown (``ValueError``) — never a silent identity."""
    fn = getattr(sg, "kernel_ceiling_adjustment", None) if sg is not None else None
    if callable(fn):
        adj = fn(model_key, int(L), int(S_identity))
        return dict(adj) if adj else None
    D = lora_max_module_dim(model_key, sg)
    if D is None:
        raise ValueError(f"no widest-module dim is pinned for model {model_key!r} (LORA_MAX_MODULE_DIM_BY_MODEL); "
                         "the kernel ceiling step cannot be pre-computed")
    ceiling = LORA_KERNEL_INDEX_LIMIT // D
    to_S = min(int(S_identity), ceiling // int(L))
    if to_S >= int(S_identity):
        return None
    return {"kind": ADJUSTMENT_KERNEL, "from_S": int(S_identity), "to_S": int(to_S), "D": int(D), "ceiling": int(ceiling)}


def geometry_adjustment_problem(block: Mapping, *, model_key: object, L: int, S_identity: int, S_served: object,
                                sg=None, native: Optional[bool] = None, served_lora: Optional[Tuple[int, int]] = None) -> Optional[str]:
    """§1.8: why a ``geometry`` block's ``adjustments`` do NOT account for ``S_served`` — None when they
    do. Through W-A's ``geometry.geometry_adjustment_problem`` when present; else the same rule: an
    ordered list over :data:`ADJUSTMENT_KINDS` — ``[]`` (then ``S_served == S_identity``), the kernel
    step FIRST and only where the model's D lowers S at ``L`` with EXACTLY the formula's ``to_S``, the
    KV step LAST through the existing ``kv_shrink_problem`` against the PREVIOUS step's S (the block's
    ``kv_shrink`` record, its ``configured_max_num_seqs`` = that S) — and ``S_served`` equal to the
    last step's ``to_S``. Anything else (an unknown kind, a repeated or reordered step, a kernel step
    on a model whose D does not lower, a ``to_S`` off the formula, a bare smaller S) is a NAMED
    problem, never "a smaller S".

    ``native`` (keyword-only, default None — the same contract as W-A's function): the ENGINE when
    the caller knows it. ``True`` additionally requires the kernel step to be PRESENT whenever the
    formula lowers (the step is present IFF it lowers; a native record that omitted it served the
    budget's S past the kernel's ceiling, or is torn); ``False`` refuses ANY kernel step (a lens
    engine has no LoRA kernel); ``None`` checks self-consistency only. The endpoint reader derives
    it from the record's own ``engine`` (:func:`served_geometry_of_endpoint`)."""
    fn = getattr(sg, "geometry_adjustment_problem", None) if sg is not None else None
    if callable(fn):
        # the standup's ATTESTED adapter class rides along when the shared validator takes it (3f1a19b48: a `launch_class` step must be THIS
        # standup's class, not a class that happens to re-derive) — exactly the driver's pass-through (served_capability_run._native_geometry_problem)
        import inspect as _inspect
        if "served_lora" in _inspect.signature(fn).parameters:
            return fn(block, model_key=model_key, L=int(L), S_identity=int(S_identity), S_served=S_served, native=native, served_lora=served_lora)
        return fn(block, model_key=model_key, L=int(L), S_identity=int(S_identity), S_served=S_served, native=native)
    adjustments = block.get(GEOMETRY_ADJUSTMENTS_KEY) if isinstance(block, Mapping) else None
    if not isinstance(adjustments, list):
        return f"geometry.{GEOMETRY_ADJUSTMENTS_KEY} is {adjustments!r}, not a list of adjustment records"
    if isinstance(S_served, bool) or not isinstance(S_served, int) or S_served < 1:
        return f"the served max_num_seqs {S_served!r} is not a positive int"
    kinds = [a.get("kind") if isinstance(a, Mapping) else a for a in adjustments]
    unknown = [k for k in kinds if k not in ADJUSTMENT_KINDS]
    if unknown:
        return f"geometry.{GEOMETRY_ADJUSTMENTS_KEY} names unknown adjustment kind(s) {unknown} (known: {list(ADJUSTMENT_KINDS)})"
    if len(kinds) != len(set(kinds)):
        return f"geometry.{GEOMETRY_ADJUSTMENTS_KEY} repeats a step: {kinds}"
    if ADJUSTMENT_LAUNCH_CLASS in kinds:
        # the class step is re-derived from the PINNED SITE RECORD (the launches that set the window's S for the served class); only the
        # shared validator can do that — this fallback never guesses, never passes it through (a loud, named refusal)
        return (f"geometry.{GEOMETRY_ADJUSTMENTS_KEY} carries a {ADJUSTMENT_LAUNCH_CLASS!r} step, which only the shared validator "
                f"(geometry.geometry_adjustment_problem, re-deriving it from the pinned site record for model {model_key!r} at L={L}) can accept; "
                f"the launcher's fallback cannot re-derive it — refusing by name")
    order = [ADJUSTMENT_KINDS.index(k) for k in kinds]
    if order != sorted(order):
        return (f"geometry.{GEOMETRY_ADJUSTMENTS_KEY} steps are out of order ({kinds}); the kernel step is applied to the "
                "budget's S first and the KV shrink to the kernel-lowered S")
    if native is False and ADJUSTMENT_KERNEL in kinds:
        return (f"a {ADJUSTMENT_KERNEL!r} step on a LENS engine — the lens has no LoRA kernel, so this record "
                "cannot be a lens standup's")
    if native is True and ADJUSTMENT_KERNEL not in kinds:
        try:
            due = kernel_ceiling_adjustment(model_key, L, int(S_identity), sg=sg)
        except (ValueError, KeyError) as e:
            return f"the kernel ceiling step cannot be re-derived for a native record: {e}"
        if due is not None:
            return (f"a native standup on {model_key!r} at L={L} must record the {ADJUSTMENT_KERNEL!r} step "
                    f"({S_identity} -> {due['to_S']}; D={due['D']}, ceiling={due['ceiling']:,}) and this record names none")
    S_prev = int(S_identity)
    for adj in adjustments:
        kind = adj["kind"]
        from_S, to_S = adj.get("from_S"), adj.get("to_S")
        if any(isinstance(v, bool) or not isinstance(v, int) or v < 1 for v in (from_S, to_S)):
            return f"adjustment {kind!r}: from_S / to_S must be positive ints, got {from_S!r} / {to_S!r}"
        if from_S != S_prev:
            return f"adjustment {kind!r}: from_S {from_S} is not the previous step's S {S_prev}"
        if kind == ADJUSTMENT_KERNEL:
            try:
                want = kernel_ceiling_adjustment(model_key, L, S_prev, sg=sg)
            except (ValueError, KeyError) as e:
                return f"adjustment {kind!r}: {e}"
            if want is None:
                return (f"adjustment {kind!r}: the kernel ceiling does not lower S={S_prev} at L={L} for model "
                        f"{model_key!r} (D={lora_max_module_dim(model_key, sg)}) — no kernel step is due")
            if to_S != want["to_S"]:
                return (f"adjustment {kind!r}: to_S {to_S} is not the formula's {want['to_S']} "
                        f"(min(S, ((2^31-1)//{want['D']})//{L}))")
        else:
            problem = _kv_shrink_problem(block.get(ADJUSTMENT_KV), configured=S_prev, L=int(L), served=to_S, sg=sg)
            if problem:
                return f"adjustment {kind!r}: {problem}"
        S_prev = int(to_S)
    if int(S_served) != S_prev:
        return f"the standup served max_num_seqs={S_served}, but the recorded adjustments end at S={S_prev}"
    return None


def _kv_shrink_problem(shrink, *, configured: int, L: int, served: int, sg=None) -> Optional[str]:
    if sg is None:
        from sisteer.capeval.serving import geometry as sg  # noqa: F811 — the (staged) module, as the callers use
    if shrink is None:
        return f"no {sg.KV_SHRINK_KEY} record beside the kv_shrink adjustment"
    return sg.kv_shrink_problem(shrink, configured_max_num_seqs=int(configured), max_model_len=int(L),
                                served_max_num_seqs=served)


def endpoint_geometry_adjustments(endpoint: Mapping) -> List[dict]:
    """The ``geometry.adjustments`` list a standup's record carries (``[]`` when absent)."""
    g = endpoint.get("geometry") if isinstance(endpoint, Mapping) else None
    adj = g.get(GEOMETRY_ADJUSTMENTS_KEY) if isinstance(g, Mapping) else None
    return [dict(a) if isinstance(a, Mapping) else a for a in adj] if isinstance(adj, list) else []


def endpoint_served_lora(endpoint: Mapping) -> Optional[Tuple[int, int]]:
    """The standup's ATTESTED adapter class from endpoint.json's ``lora_config`` (``max_lora_rank``, ``max_loras``), when both are
    positive ints; else None — the driver's reading (served_capability_run._native_geometry_problem, 3f1a19b48)."""
    lc = endpoint.get("lora_config") if isinstance(endpoint, Mapping) else None
    if not isinstance(lc, Mapping):
        return None
    r_, n_ = lc.get("max_lora_rank"), lc.get("max_loras")
    if all(isinstance(v, int) and not isinstance(v, bool) and v >= 1 for v in (r_, n_)):
        return (int(r_), int(n_))
    return None


def _with_seqs_source(geom, S: int, source: str):
    """``geom`` at another S AND another ``seqs_source`` — the class step's effect (native_standup.launch_class_geometry replaces both)."""
    try:
        return dataclasses.replace(geom, max_num_seqs=int(S), seqs_source=source)
    except TypeError:
        import copy as _copy
        g = _copy.copy(geom)
        g.max_num_seqs = int(S)
        g.seqs_source = source
        return g


def _with_seqs(geom, S: int):
    """``geom`` at another S (``dataclasses.replace`` on the resolved geometry; attribute copy on a
    plain namespace). ``seqs_source`` stays what it was — the adjustment is applied to the budget's
    S, which is what it records (§1.8); ``is_identity`` reads False by itself."""
    try:
        return dataclasses.replace(geom, max_num_seqs=int(S))
    except TypeError:
        import copy as _copy
        g = _copy.copy(geom)
        g.max_num_seqs = int(S)
        return g


def expected_geometry_for(geom, *, native: bool, name: str = "") -> Tuple[object, Optional[dict]]:
    """§1.8, the PRE-STANDUP half: under native the kernel step is PURE (the model's D, the window,
    the budget's S), so the expected S is known BEFORE the standup and the pre-standup resume
    decision lands on the right store — ``(geometry at the expected S, the kernel step | None)``.
    Under lens: ``(geom, None)``, byte for byte. A native geometry naming no model, or a model with
    no pinned D, refuses (:class:`IdentityUnderivable`) — a narrower expectation would let a store
    at the budget's S resume onto a run the kernel lowers."""
    if not native:
        return geom, None
    from sisteer.capeval.serving import geometry as sg
    model_key = getattr(geom, "model_key", None)
    if not model_key:
        raise IdentityUnderivable(
            f"{name or 'this configuration'}: a native expectation pre-computes the LoRA kernel ceiling step from the "
            "served model's widest adapted module, and the resolved geometry names no model_key")
    try:
        adj = kernel_ceiling_adjustment(model_key, int(geom.max_model_len), int(geom.max_num_seqs), sg=sg)
    except (ValueError, KeyError) as e:          # geometry.UnknownModelKey is a KeyError
        raise IdentityUnderivable(f"{name or 'this configuration'}: {e}") from None
    return (_with_seqs(geom, adj["to_S"]) if adj else geom), adj


def proxy_engine_kind(endpoint: Mapping, *, timeout_s: float = 30.0) -> Tuple[Optional[str], Optional[str]]:
    """The LIVE proxy's ``/v1/models`` -> ``petri_proxy.engine.kind`` — ``(kind, None)``, or
    ``(None, why)`` when the block is missing, malformed or unreachable (the caller refuses; a
    proxy that states no engine block is a lens proxy or a build before the native landing)."""
    import urllib.request
    url = str(endpoint.get("proxy_url") or "").rstrip("/") if isinstance(endpoint, Mapping) else ""
    if not url:
        return None, "endpoint.json names no proxy_url"
    req = urllib.request.Request(f"{url}/models")
    token = endpoint.get("proxy_token")
    if token:
        req.add_header("Authorization", f"Bearer {token}")
    try:
        with urllib.request.urlopen(req, timeout=timeout_s) as resp:
            listing = json.loads(resp.read().decode())
    except Exception as e:  # noqa: BLE001 — recorded and refused by the caller, never read around
        return None, f"GET {url}/models failed: {type(e).__name__}: {e}"
    meta = listing.get(PROXY_IDENTITY_KEY) if isinstance(listing, Mapping) else None
    if not isinstance(meta, Mapping):
        return None, f"/v1/models exposes no {PROXY_IDENTITY_KEY!r} identity block ({str(listing)[:200]})"
    eng = meta.get(PROXY_IDENTITY_ENGINE_KEY)
    if eng is None:
        return None, (f"/v1/models {PROXY_IDENTITY_KEY}.{PROXY_IDENTITY_ENGINE_KEY} is absent — the proxy attests no "
                      "engine (a lens proxy, or a build before the native landing)")
    if not isinstance(eng, Mapping) or not isinstance(eng.get("kind"), str):
        return None, f"/v1/models {PROXY_IDENTITY_KEY}.{PROXY_IDENTITY_ENGINE_KEY} is malformed: {str(eng)[:200]}"
    return str(eng["kind"]), None


def store_serving_engine(manifest: Mapping) -> Tuple[str, str]:
    """``(engine, where it was read)`` of a tinycap store's manifest — the route block's UNHASHED
    ``serving_engine`` (W-C's writers stamp it on both engines), else the hashed
    ``tinycap.served.serving_engine`` (PRESENT IFF native), else ``lens`` BY ERA: a manifest with no
    engine anywhere predates this landing and every such store was served by the lens (the
    ``REDUCTION_MODE_LEGACY`` pattern). A malformed value is returned verbatim so the caller
    refuses it by name."""
    route = manifest.get(C.MANIFEST_KEY_ROUTE)
    if isinstance(route, Mapping) and SERVED_ENGINE_FIELD in route:
        return str(route[SERVED_ENGINE_FIELD]), f"route.{SERVED_ENGINE_FIELD}"
    tinycap = manifest.get(C.MANIFEST_KEY_TINYCAP)
    served = tinycap.get("served") if isinstance(tinycap, Mapping) else None
    if isinstance(served, Mapping) and SERVED_ENGINE_FIELD in served:
        return str(served[SERVED_ENGINE_FIELD]), f"tinycap.served.{SERVED_ENGINE_FIELD}"
    return ENGINE_LENS, "absent (a store from before the native landing: lens by era)"


def engine_conflict_at_output(out_dir: str | Path, expected) -> Optional[Dict[str, object]]:
    """The TERMINAL engine conflict at the OUTPUT boundary: every
    ``<out_dir>/cells/*/manifest.json`` — identity-matching or not — is read for the engine it
    records (:func:`store_serving_engine`), and any store served by another engine than this run's
    is a conflict: ``{expected_engine, stores: [{store, engine, source, cell_id, tasks}]}``, else
    None. ``expected`` is an :class:`ExpectedIdentity` or an engine name.

    Why terminal, and why here: a lens store under a native run is not merely "untrusted" — the
    resume would file it ``done_in=None``, re-plan its controls as remaining work and let the driver
    create a NEW hashed cell dir beside it, REGENERATING a completed lens configuration natively,
    against the rule that existing evals are never re-run. So the caller refuses with
    ``SERVING_ENGINE_CONFLICT`` before any sidecar write, any ``VOL.commit`` and any standup, and
    never re-plans. A store is single-engine: the whole root is judged, whatever its stores'
    controls (judgement call, W-G: the root pins model / cell / mode; a root mixing engines across
    controls would still hand the pairing a cross-engine cell dir). An unreadable manifest is a
    conflict too (its engine cannot be read; fail closed)."""
    want = expected if isinstance(expected, str) else expected.serving_engine
    root = Path(out_dir) / "cells"
    if not root.is_dir():
        return None
    conflicts: List[Dict[str, object]] = []
    for m in sorted(root.glob("*/manifest.json")):
        doc, err = _read_json_object(m)
        if doc is None:
            conflicts.append({"store": m.parent.name, "engine": None, "source": None, "cell_id": None,
                              "tasks": None, "problem": f"manifest.json {err} — its engine cannot be read"})
            continue
        engine, source = store_serving_engine(doc)
        if engine == want:
            continue
        tinycap = doc.get(C.MANIFEST_KEY_TINYCAP)
        conflicts.append({"store": m.parent.name, "engine": engine, "source": source, "cell_id": doc.get("cell_id"),
                          "tasks": (list(tinycap.get("tasks") or []) if isinstance(tinycap, Mapping) else None),
                          "problem": (f"served by {engine!r} ({source}), this run serves {want!r}"
                                      if engine in ENGINES else f"records an unknown engine {engine!r} ({source})")})
    return {"expected_engine": want, "stores": conflicts} if conflicts else None


def engine_conflict_error(conflict: Mapping[str, object], out_dir: str | Path) -> str:
    stores = conflict.get("stores") or []
    return (f"{out_dir} already holds {len(stores)} store(s) of another serving engine than this run's "
            f"{conflict.get('expected_engine')!r}: "
            + "; ".join(f"{s['store']}: {s['problem']}" for s in stores)
            + " — a store is single-engine and an existing configuration is never re-generated on the other "
              "engine (fixed decision); nothing written, no standup. Launch under the engine that produced "
              f"these stores ({SERVING_PATH_FLAG} {SERVING_PATH_LENS} for a lens root), or give the run a fresh "
              "out root (a native launch's default root is the `native/` namespace)")


def smoke_out_subdir(sha: str, *, now: Optional[float] = None) -> str:
    """The NATIVE smoke's out-subdir, unique per invocation: ``smoke-<sha8>-<utc>`` (§5's per-job
    scratch claim; two smokes never resume into each other). The lens smoke keeps
    :data:`SMOKE_OUT_SUBDIR` byte for byte."""
    stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime(now if now is not None else time.time()))
    return f"smoke-{str(sha)[:8]}-{stamp}"


#: The workspace's named HF secret — the repo's Modal scripts' standing
#: convention (e4b_wave / verify_teacher / the HPO drivers). The STAGE
#: function ALONE carries it: anonymous hub traffic from Modal's shared egress
#: hit ``429 maximum queue size reached`` on the third dataset snapshot
#: (2026-09-03), and inspect_evals' stock ``xstest`` loads the gated
#: ``walledai/XSTest``. The GPU containers run ``HF_HUB_OFFLINE=1`` and carry
#: no secret. Only the token's PRESENCE is ever recorded.
HF_TOKEN_SECRET = "hf-token"
#: hub 429 backoff: attempts, and the first delay (x3 each retry)
HUB_RETRIES = 5
HUB_RETRY_DELAY_S = 5.0


# --------------------------------------------------------------------------- #
# the run matrix (pure; tested)                                                #
# --------------------------------------------------------------------------- #


def is_prompted(cell: str) -> bool:
    """The cell carries an SI PREFIX. Not the same question as
    :func:`is_steered`: the base cell ``none`` is neither."""
    return cell.startswith(C.PROMPTED_CELL_PREFIX)


def is_base(cell: str) -> bool:
    """The un-steered, no-SI base cell (``none``). Its served
    route is a ``passthrough`` identity exactly like a prompted cell's
    (``defense_cells.enumerate_cells`` assigns ``path = "passthrough"`` to
    both), so the driver's steering-bites probe does not apply to it —
    ``bon_served._is_lens`` is False and ``_served_evidence`` records
    ``steering_bites {applicable: False}`` — while the salt-isolation check,
    a property of the whole route SET rather than of the served cell, runs
    for every kind as before."""
    return C.is_base_cell(cell)


def is_steered(cell: str) -> bool:
    """The cell serves a fitted OBJECT on the lens route (neither ``none``
    nor ``prompted__<si>``) — the kind whose evidence includes the
    steering-bites probe."""
    return not is_base(cell) and not is_prompted(cell)


def standup_declared(cfg: Mapping) -> bool:
    """Whether this configuration's standup carries the DECLARED cell spelling
    (contract §2.5.1 / §2.5.10 Q8 / §2.5.11 Q7(ii)) — the launcher's wrapper
    over the ONE predicate, ``contracts.is_declared_configuration``: out of
    support (the planner LIFTED a refusal — ``IDENTITY_KEY_OUT_OF_SUPPORT_THINKING``),
    the whole thinking-ON arm, and a LENS cell. The ``none`` standups and every
    OFF standup are undeclared — ``--cell`` bare. ``_standup_cmd``,
    ``expected_identity``, the worker's attestation lookup and the dry run all
    read this, so the standup, the hashed expectation and the compare can never
    disagree about the spelling a configuration wears."""
    return C.is_declared_configuration(
        cfg["cell"], arm=cfg["mode"],
        out_of_support=cfg.get(C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING))


def spellings_for(cfg: Mapping) -> C.CellSpellings:
    """This configuration's cell at the doors (``contracts.cell_spellings``,
    the ONE helper): the ``@thinking`` spellings iff :func:`standup_declared`,
    else today's bare ones byte for byte."""
    return C.cell_spellings(cfg["cell"], declared=standup_declared(cfg))


def authorised_psr_cell(cell: str) -> bool:
    """The authorised experiment's fitted cell (``contracts.OOS_CELL_KIND``
    kind ``psr``, a lens cell) — the one whose ATTESTED resumed-prefill policy
    the worker holds to ``conditional``. Any other
    cell, incl. the base route, is not held to it. The launcher's wrapper over
    ``contracts.is_authorised_psr_cell``."""
    return C.is_authorised_psr_cell(cell)


def authorised_psr_leg(cfg: Mapping) -> bool:
    """A configuration serving the authorised experiment's psr cell on the
    authorised MODEL — the two psr legs of the 2x2 (the OFF leg is planned
    in-support and keys exactly as the campaign's would, so it is told apart
    from the campaign's other models by the model alone). The worker holds
    exactly these to the attested resumed-prefill policy;
    every other model's standups are untouched."""
    cell = cfg["cell"]
    return authorised_psr_cell(cell) and C.is_authorised_psr_leg(cell, row_of(cfg).slug)


def serves_oos_on(cfg: Mapping, controls: Sequence[str]) -> bool:
    """Whether this configuration serves a task thinking-ON OUT OF SUPPORT over
    the REQUESTED ``controls`` (the worker re-derives it from the controls it
    was handed, like every other plan-time verdict there): the planner's marker
    AND at least one ON task among them. The template-digest and artifact
    requirements bind exactly these configurations."""
    if cfg.get(C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING) is not True:
        return False
    return any(arm == C.THINKING_ON
               for arm in thinking_by_task_of(cfg["mode"], controls).values())


def battery_kind(cell: str) -> str:
    """The contracts' battery kind of a cell (``BATTERY_PROMPTED`` /
    ``BATTERY_FITTED``). The split was ever about STEERING (PB10's
    BFCL-on-a-lens-route refusal), so the un-steered base cell takes the
    prompted kind — the two lists are identical today (O7 / PW18b), and if
    they ever diverge again the base cell belongs with the un-steered arm."""
    return C.BATTERY_FITTED if is_steered(cell) else C.BATTERY_PROMPTED


def default_controls(cell: str, *, in_depth: bool = False) -> Tuple[str, ...]:
    """The ``--pass1`` default for a cell: its kind's STANDARD battery with
    the staging exclusions applied (``CONTROLS_PROMPTED`` / ``CONTROLS_FITTED``),
    plus ``contracts.IN_DEPTH_EXTRAS`` when ``in_depth`` (``--in-depth``)."""
    return apply_default_exclusions(C.battery_controls(battery_kind(cell), in_depth=in_depth))


def battery_split(cell: str, controls: Sequence[str]) -> Dict[str, List[str]]:
    """Which of a configuration's control tokens are its kind's STANDARD
    battery, which are IN-DEPTH extras, and which are neither (an explicit
    ``--controls`` list's atoms) — for the dry run and the REC, so the print
    always says what is standard and what is not."""
    standard = set(default_controls(cell))
    extras = set(C.IN_DEPTH_EXTRAS)
    return {"standard": [c for c in controls if c in standard],
            "in_depth": [c for c in controls if c in extras],
            "other": [c for c in controls if c not in standard and c not in extras]}


def needs_tool_calls(controls: Sequence[str]) -> bool:
    """E3: ``--tool-calls`` only when a TOOL-CALLING family is among the
    controls (``contracts.TOOL_CALL_CONTROLS``: ``bfcl`` and, since
    bcb-bfcl-200, the pinned ``bfcl_200``)."""
    return any(C.control_family(a) in C.TOOL_CALL_CONTROLS
               for c in controls for a in C.expand_control(c))


class ThinkingUnservable(ValueError):
    """A configuration asks for thinking-ON where the family cannot serve it.
    Refused at PLAN time, with the reason — never downgraded to
    a silent thinking-OFF run whose numbers would look like the ON arm's."""


def row_of(cfg: Mapping) -> C.ModelRow:
    """The registry row a planned configuration names. A configuration
    without a ``model`` key predates that key and takes the default model
    (the two test cells' — every such configuration IS a gemma4e4b one)."""
    return C.model_row(str(cfg.get("model") or C.MODEL_SLUG))


def is_ifeval_configuration(cfg: Mapping) -> bool:
    """Whether a planned configuration is an IFEval one: it carries the
    planner's ``ifeval_cap`` (every configuration
    :func:`plan_configurations` plans with the ``ifeval`` atom does) or — a
    hand-built cfg — names the atom among its controls. The ONE predicate the
    driver line, the hashed identity's version, the geometry routing and the
    preflight's flag probe key on."""
    if cfg.get("ifeval_cap") is not None:
        return True
    return any(atom == C.CONTROL_IFEVAL for c in (cfg.get("controls") or ()) for atom in C.expand_control(c))


def ifeval_lens_configuration(cfg: Mapping) -> bool:
    """An IFEval configuration on a LENS cell (a fitted object): its driver
    builds the per-row identity under ``--bank-view`` and
    ``contracts.row_identity_block`` refuses a lens cell without the 64-hex
    object sha — so the digest the standup was held to rides
    ``--expect-object-sha256`` here too (the landed-lens legs' flag), or the
    container would die AFTER the standup was paid for."""
    return is_ifeval_configuration(cfg) and C.is_lens_cell(cfg["cell"])


_IFEVAL_VIEW_BY_SLUG: Mapping[str, str] = {slug: view for (_key, view), slug in C.IFEVAL_SLUGS.items()}


def ifeval_view_of(row: C.ModelRow) -> str:
    """The bank VIEW an IFEval registry row serves (``main`` / ``it``), read off
    ``contracts.IFEVAL_SLUGS`` — the ModelRow carries no view field, and the
    slug's ``-sdfbase-<view>`` tail is the roster's own spelling. Refuses a row
    outside the seven IFEval slugs by name."""
    try:
        return _IFEVAL_VIEW_BY_SLUG[row.slug]
    except KeyError:
        raise ValueError(f"{row.slug!r} is not one of the IFEval wave's slugs {sorted(_IFEVAL_VIEW_BY_SLUG)} "
                         "(contracts.IFEVAL_SLUGS) — it serves no bank view") from None


def ifeval_driver_kwargs(cfg: Mapping) -> Dict[str, object]:
    """The IFEval tail of ``contracts.driver_argv`` for a planned IFEval
    configuration: identity version 2, the cap
    STATEMENT ``ifeval=<executed cap>`` (the planner's ``ifeval_cap`` — the
    driver holds it equal to its own resolution), the OFF setter map and the
    rung subset path (each None at pass 1, so driver_argv emits neither) and
    the bank view. ``{}`` for every other configuration, so its argv is
    byte-identical to before the tail existed."""
    if not is_ifeval_configuration(cfg):
        return {}
    if cfg.get("ifeval_cap") is None or cfg.get("bank_view") is None:
        raise ValueError(
            f"{cfg.get('name', cfg.get('cell'))}: an IFEval configuration carries no ifeval_cap / bank_view — "
            "plan it through plan_configurations (the driver line states the executed cap and the view)")
    return {"identity_version": C.TINYCAP_IDENTITY_VERSION_2,
            "max_tokens_by_task": {C.IFEVAL_TASK_NAME: int(cfg["ifeval_cap"])},
            "off_cap_by_task": (dict(cfg["off_cap_by_task"]) if cfg.get("off_cap_by_task") else None),
            "item_subset": (str(cfg["item_subset"]) if cfg.get("item_subset") else None),
            "bank_view": str(cfg["bank_view"])}


def ifeval_probe_flags(cfgs: Sequence[Mapping]) -> Tuple[str, ...]:
    """What the preflight's argparse probe adds on an IFEval launch:
    ``contracts.IFEVAL_DRIVER_FLAGS`` (the tail's six VALUED flags) when any
    planned configuration is an IFEval one, plus the digest flag when an IFEval
    LENS cell is planned and no landed-lens configuration already probes it.
    ``()`` otherwise, so every other launch's probe is byte-identical."""
    if not any(is_ifeval_configuration(c) for c in cfgs):
        return ()
    flags = tuple(C.IFEVAL_DRIVER_FLAGS)
    if any(ifeval_lens_configuration(c) for c in cfgs) and not any(landed_lens_configuration(c) for c in cfgs):
        flags += (C.FLAG_EXPECT_OBJECT_SHA256,)
    # the follow-up (Appendix A; merge finding M6): every IFEval cell's driver line carries the
    # prompt-budget artifact the CONTAINER writes and a fresh attempt id, so both are probed here
    # (the budget flag once: an out-of-support / comparator launch already probes it)
    if not any(serves_oos_on_cfg(c) or serves_offcap(c) for c in cfgs):
        flags += (C.FLAG_OOS_PROMPT_BUDGET,)
    flags += (C.FLAG_ATTEMPT_ID,)
    return flags


def thinking_by_task_of(mode: str, controls: Sequence[str], *, family: object = None) -> Dict[str, str]:
    """``{row task: on|off|not_available}`` for the tasks a configuration actually
    runs — the per-task map the driver serves under ONE standup and the store
    identity records (``thinking_by_task``, the key name fixed with the driver).
    Under a whole-arm mode every task takes that arm, so the map is still filed:
    a store never has to be read to find out which arm a task ran. ``family``
    (the driver's `contracts.apply_no_switch_policy`): a no-switch family's OFF
    arms read ``not_available`` — the expectation must hash what the driver
    hashes, or every Llama store is refused on resume."""
    out = {task: C.thinking_of_task(mode, task) for c in controls for task in expected_tasks(c, mode)}
    return C.apply_no_switch_policy(out, family) if family is not None else out


def parser_needed(mode: str, controls: Sequence[str]) -> bool:
    """Whether the standup must compose a reasoning parser: under a whole-arm
    mode, iff the arm is ON; under ``per-task``, iff ANY requested task is ON —
    one standup serves the whole battery, so a single ON task means the parser
    has to be there for it (and the OFF tasks send ``enable_thinking: false``
    per request, which the parser does not touch)."""
    return any(arm == C.THINKING_ON for arm in thinking_by_task_of(mode, controls).values())


def standup_extra_for(row: C.ModelRow, *, tool_calls: bool, thinking: str,
                      controls: Sequence[str] = (),
                      allow_out_of_support: bool = False,
                      cell: Optional[str] = None,
                      sampling_mode: str = C.SAMPLING_DEFAULT) -> List[str]:
    """The standup extras for a configuration of THIS model: the family's
    reasoning-parser pin when any served task thinks, and the family's VERIFIED
    tool-parser manifest under ``--tool-calls`` — never the gemma manifest on
    a llama target (job 232411: a parser foreign to the served tokenizer is a
    healthy-looking server that 500s on every chat request half an hour in).

    ``allow_out_of_support`` (PW-oos) lets a thinking-ON standup compose NO
    reasoning parser on a family that has none pinned, instead of refusing —
    see ``contracts.OUT_OF_SUPPORT_THINKING_NOTE``. It never invents a parser
    and it is refused for a family with no thinking switch at all.

    ``cell``: on a thinking-ON out-of-support standup of a LENS
    cell the cell SPELLING is the declaration (contract §2.5.1: ``--cell
    <cell>@thinking``, no new flag), so the declared spelling must be
    derivable at PLAN time — ``contracts.cell_spellings(cell, declared=True)``
    refuses while ``OOS_STANDUP_CELL_SUFFIX`` / ``OOS_EXPECT_SHA_KEY`` read
    ``None`` (both are filled from the contract; a ``None`` is a mutated
    module), and that refusal is turned into a plan-time
    :class:`ThinkingUnservable` naming the constant, so a ``--dry-run`` says
    exactly what is missing instead of planning a standup that would come up
    undeclared."""
    arm = thinking
    if C.check_thinking_arg(thinking) == C.THINKING_PER_TASK:
        # ONE standup, mixed per-request flags: the parser is a LAUNCH option,
        # so it is composed iff some task needs it
        arm = C.THINKING_ON if parser_needed(thinking, controls) else C.THINKING_OFF
    if (allow_out_of_support and cell is not None and arm == C.THINKING_ON
            and C.is_lens_cell(cell)):
        try:
            C.cell_spellings(cell, declared=True)
        except C.OutOfSupportDeclarationUnreconciled as e:
            raise ThinkingUnservable(
                f"model {row.slug!r} cell {cell!r}: a thinking-ON out-of-support standup of a "
                f"lens cell is DECLARED by its cell spelling (contract §2.5.1: --cell "
                f"<cell>{C.VARIANT_SEP}{C.VARIANT_THINKING}), which cannot be derived: {e}. Step "
                "B0 fills these constants from contract-2.5.md; refusing to plan a standup that "
                "would come up undeclared") from None
    extra = C.standup_extra_argv(tool_calls=tool_calls, thinking=arm,
                                 family=row.family,
                                 manifest=row.petri_manifest or C.PETRI_MANIFEST_GEMMA4E4B,
                                 allow_out_of_support=allow_out_of_support)
    if C.check_sampling_arg(sampling_mode) == C.SAMPLING_PROTOCOL:
        # The standup lifts vLLM's _MAX_TEMP clamp so BFCL's 0.001 executes
        # literally — the ONE launch difference a protocol configuration
        # composes; every other mode's argv is byte-identical
        extra += [C.FLAG_SAMPLING_CLAMP_OVERRIDE, C.SAMPLING_CLAMP_OVERRIDE_ARG]
    return extra


def thinking_refusal_for(row: C.ModelRow, cell: str, mode: str,
                         controls: Sequence[str], *,
                         allow_out_of_support: bool = False) -> Optional[str]:
    """Why this configuration cannot be served — or None. Both refusals
    at PLAN time and never a silent OFF:

    (a) the family has no VERIFIED reasoning parser, so thought text would land
        in ``content`` where every extractor reads it as the answer; and
    (b) a FITTED cell of a family whose served render is pinned thinking-OFF
        and whose assistant header MOVES between modes — the object would be
        applied to a different span than it was fit at.

    Under ``per-task`` the question is asked of the tasks that actually think:
    a battery whose ON tasks are all excluded needs no parser and is allowed.

    ``allow_out_of_support`` (PW-oos, U10 item 5) is the ONE way past this, and
    it is never a default: with it named, a family the override may lift for
    (``contracts.out_of_support_thinking_overridable`` — not a family whose
    template carries no thinking switch, where there is no ON render to serve)
    returns None here, and :func:`thinking_override_for` carries the refusals
    that were lifted into the plan, the REC and the dry run."""
    if not parser_needed(mode, controls):
        return None
    why = C.thinking_on_refusal(row.family, fitted=is_steered(cell))
    if why is None:
        return None
    if allow_out_of_support and C.out_of_support_thinking_overridable(row.family):
        return None
    on_tasks = sorted(t for t, arm in thinking_by_task_of(mode, controls).items()
                      if arm == C.THINKING_ON)
    asked = (f"--modes {mode} asks for thinking-ON on {on_tasks}"
             if mode == C.THINKING_PER_TASK else f"--modes {mode} asks for thinking-ON")
    return (f"model {row.slug!r} cell {cell!r}: {asked}, but {why}. Run this cell thinking-OFF "
            f"(--modes off), or drop the ON tasks from --controls; the launcher will not serve "
            f"an ON request as OFF."
            + ("" if C.out_of_support_thinking_overridable(row.family)
               else f" ({C.OUT_OF_SUPPORT_THINKING_NOT_OVERRIDABLE})")
            + (f" (The authorised experiment's override is {C.FLAG_ALLOW_OOS_THINKING}.)"
               if C.out_of_support_thinking_overridable(row.family) else ""))


def thinking_override_for(row: C.ModelRow, cell: str, mode: str,
                          controls: Sequence[str]) -> Optional[dict]:
    """What ``--allow-out-of-support-thinking`` LIFTS for this configuration —
    ``None`` when it lifts nothing (the configuration was servable anyway, or
    it asks for no thinking-ON task at all).

    An overridden refusal is never a vanished one: this record travels into the
    plan, the REC, the dry run and the container log, carrying EVERY refusal
    the flag suppressed (on qwen3_5 both bind — the fit-regime header move and
    the missing reasoning parser) plus the note that states what the override
    does and does not do."""
    if not parser_needed(mode, controls):
        return None
    lifted = C.thinking_on_override_refusals(row.family, fitted=is_steered(cell))
    if not lifted or not C.out_of_support_thinking_overridable(row.family):
        return None
    return {"flag": C.FLAG_ALLOW_OOS_THINKING, "model": row.slug, "cell": cell,
            "family": row.family, "mode": mode,
            "on_tasks": sorted(t for t, arm in thinking_by_task_of(mode, controls).items()
                               if arm == C.THINKING_ON),
            "refusals_lifted": list(lifted),
            "reasoning_parser_composed": row.family in C.REASONING_PARSER_BY_FAMILY,
            "note": C.OUT_OF_SUPPORT_THINKING_NOTE}


def _controls_without_tool_calls(controls: Sequence[str]) -> List[str]:
    """``controls`` minus the tool-calling ones (:func:`needs_tool_calls`, per control) — the remedy every
    tool-parser refusal names (``run the rest of the battery with --controls …``)."""
    return [c for c in controls if not needs_tool_calls([c])]


def no_tool_parser_message(row: C.ModelRow, controls: Sequence[str]) -> str:
    """Why BFCL cannot be planned for a model whose family has no VERIFIED
    tool-parser pairing — with the remedy, so the operator is not left
    guessing which control to drop."""
    keep = _controls_without_tool_calls(controls)
    # bcb-bfcl-200-widen S4: the pinned families are READ off the table, never
    # retyped — a family the lane's parser probe promotes appears here by itself
    from sisteer.capeval.serving.vllm_server import TOOL_PARSER_BY_FAMILY
    pinned = " / ".join(sorted(TOOL_PARSER_BY_FAMILY))
    return (f"model {row.slug!r} (family {row.family!r}) has no petri manifest with a VERIFIED "
            f"tool-call parser for vLLM's pinned wheel — vllm_server.TOOL_PARSER_BY_FAMILY "
            f"pins {pinned} only, and composing an unverified parser gives a "
            f"healthy-looking server that 500s on every chat request once tool traffic arrives "
            f"(job 232411). Refusing to plan BFCL here: run the rest of the battery with "
            f"--controls {','.join(keep)}, or verify the pairing (the lane's parser probe: "
            f"scripts/bfcl_parser_probe.py) and pin a manifest in the registry row in the same change.")


def no_live_tool_parser_message(row: C.ModelRow, controls: Sequence[str], *, tree: Optional[str | Path] = None) -> str:
    """Why BFCL cannot be planned for a PROBE family (contracts.TOOL_PARSER_PROBE_FAMILIES) whose LIVE parser-probe
    PASS record is not filed: the table pin and the manifest are the offline half; the live raw-token replay is the
    second gate, and it binds a direct invocation exactly as it binds the lane roster. ``tree`` is where the
    checked-in verdict is READ from (see tool_parser_problem)."""
    keep = _controls_without_tool_calls(controls)
    return (f"model {row.slug!r} (family {row.family!r}): {C.tool_parser_live_gate_problem(row.family, tree=tree)}. "
            f"Refusing to plan BFCL here: run the rest of the battery with --controls {','.join(keep)}, or run the live probe and file its PASS record.")


def tool_parser_problem(row: C.ModelRow, controls: Sequence[str], *, tree: Optional[str | Path] = None) -> Optional[str]:
    """The FIRST reason a tool-calling leg cannot be planned for ``row`` under ``controls`` (None = may) — the ONE
    gate the planner raises and the per-container worker files as ``NO_VERIFIED_TOOL_PARSER``: no manifest (no
    VERIFIED parser pairing), else a probe family whose LIVE parser-probe PASS record is not filed (binding on a
    DIRECT invocation too). ``tree`` is the root the checked-in verdict is READ from: the STAGED tree for the
    launch sha in the worker and the in-container replan, the source checkout on the grading host when None. The
    image ships no copy of the verdict on purpose — one source of truth, the tree that also pins the roster and
    the row configs; `contracts` refuses loudly when it is imported from the image mount and handed no tree."""
    if not needs_tool_calls(controls):
        return None
    if not row.petri_manifest:
        return no_tool_parser_message(row, controls)
    if C.tool_parser_live_gate_problem(row.family, tree=tree):
        return no_live_tool_parser_message(row, controls, tree=tree)
    return None


def plan_configurations(cells: Optional[Sequence[str]] = None,
                        modes: Optional[Sequence[str]] = None,
                        controls: Optional[Sequence[str]] = None, *,
                        in_depth: bool = False,
                        model: str = C.MODEL_SLUG,
                        allow_out_of_support_thinking: bool = False,
                        sampling_mode: str = C.SAMPLING_DEFAULT,
                        samples: int = C.MATH500_SAMPLES_PER_ITEM,
                        allow_off_cap_override: bool = False,
                        reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
                        pass_no: int = 1,
                        off_cap_by_task: Optional[Mapping[str, int]] = None,
                        item_subset: Optional[str] = None,
                        bank_view: Optional[str] = None,
                        out_dir: Optional[str] = None,
                        ifeval_matrix: Optional[Mapping[str, object]] = None,
                        ifeval_matrix_tree: Optional[str | Path] = None,
                        serving_path: str = SERVING_PATH_LIBRARY_DEFAULT) -> List[dict]:
    """The configurations to run: ``cells`` x ``modes`` (defaults: the two
    test cells x thinking off, on), each with its GENERATED container name,
    task list (the cell kind's STANDARD battery, plus the in-depth extras
    under ``in_depth``, or the explicit ``controls`` override), its
    standard / in-depth split (``battery``), ``--tool-calls`` decision and
    standup extra argv, plus the cell-kind flags ``prompted`` (carries an SI
    prefix), ``base`` (``none``) and ``steered`` (serves an object on the lens
    route). Refuses an ill-formed cell / mode / control token, and
    ``in_depth`` together with an explicit ``controls`` list (the extras are
    named in the list instead — a flag that silently did nothing would be
    the worse failure).

    E50 #3: under ``allow_out_of_support_thinking`` EVERY planned configuration
    must be the ONE authorised experiment (``contracts.AUTHORISED_OOS_THINKING``)
    — model, cell, controls, mode and the draw (``sampling_mode`` / ``samples``,
    which is why they are planning inputs at all). The check runs BEFORE the
    refusal is lifted, so an unauthorised run is refused as unauthorised rather
    than being served out of support and then stamping the authorised
    experiment's identity. This is the planner ``main`` AND the preflight both
    go through (E40 M6), so both doors carry it.

    Under ``allow_off_cap_override`` EVERY planned
    configuration must be the ONE authorised comparator
    (``contracts.AUTHORISED_OFF_CAP_COMPARATOR``) — checked BEFORE anything else
    per configuration; the configuration then carries the planner marker
    ``off_cap_override`` (the twin of ``thinking_override``: nothing is lifted,
    the executed OFF cap of the named tasks and the hashed cap key change). The
    two overrides are mutually exclusive (``contracts.check_override_flags_exclusive``),
    refused here first — so the preflight, which replans from the same mapping,
    refuses the pair too.

    ``reduction_mode`` (the code review's H2) is the lens reduction mode this
    launch ASKS for (``--reduction-mode``; the launcher default per_row) and is a
    planning input for the same reason the draw is: both tuples name one, so
    neither authorisation can be made without it. Before this the planner and
    the preflight's planning input omitted it, and ``--reduction-mode stacked``
    under either flag planned, passed the dry run and would have stood up every
    container before the driver's served-identity check refused. The mode the
    standup actually ATTESTS is still held by the worker and the driver.

    ``pass_no`` (the code review's H3) is the geometry pass this launch asks for
    (``--pass1`` / ``--pass2``; 1 by default) and a planning input for the same
    reason: both tuples fix the geometry CLASS (pass 1, the certified window the
    prompt budget is proven against). Before this the preflight budgeted a
    hardcoded pass 1 and ``--pass2 --pf`` on the comparator was approved at
    16,384 while both containers would have served L 4,608 x S 78 — refused by
    the driver only after the GPU standup. The pass is compared here, before
    anything is planned or any remote call is made.

    Every configuration now carries the
    draw it was planned under (``sampling_mode`` / ``samples`` — the worker reads
    THESE, E54 #6). A configuration whose controls name the ``ifeval`` atom is
    an IFEval configuration and gains ``off_cap_by_task`` (the OFF setter map, a
    rung's ``{ifeval: 4096 | 8192}``; None at pass 1), ``item_subset`` (the
    rung_subset json's path; None at pass 1), ``bank_view`` (the slug's view —
    the ModelRow has none, so it is read off ``contracts.IFEVAL_SLUGS``; an
    explicit one must agree) and ``ifeval_cap`` (the EXECUTED cap: the setter's,
    else ``contracts.IFEVAL_MAX_TOKENS_OFF``), its ``geometry_keys`` is the cap's
    own ``capability:ifeval_<cap>`` entry and its ``out_dir`` the explicit one
    when given. Refused by name: any of the four inputs without the atom; the
    atom beside another control, on a row outside the IFEval slugs, or under an
    arm that would serve it thinking-ON; a subset without a setter; a setter
    naming another task or a cap outside ``contracts.OFF_CAP_BY_TASK_ALLOWED``;
    a bank view disagreeing with the slug's.

    Every IFEval configuration is checked against the FROZEN matrix's row status
    (``contracts.ifeval_hold_problem`` over ``ifeval_matrix`` — the local
    checkout's ``configs/sdfbase/ifeval/matrix.json`` by default, the same rows
    the dispatcher's ``select_rows`` reads): a HELD row (P41) or a DEFERRED slot
    refuses HERE, at plan time, whatever ``--cells`` names — the direct
    launcher's ``--cells … --pass1 --pf`` path used to plan and spawn the two
    held constitution rows. A cell the matrix has no row for (the shakedown's
    probe cell) is admitted; every IFEval configuration records its
    ``matrix_status``. The container repeats the check against the STAGED
    tree's matrix (``_run_configuration``).

    The matrix's SOURCE is explicit. ``ifeval_matrix`` is the document when the
    caller holds it (tests); else it is read off ``ifeval_matrix_tree``, the
    LOCAL checkout (``REPO_LOCAL``) by default — the right source for ``main``
    and the dispatcher, which plan on the operator's machine. Inside a Modal
    container ``REPO_LOCAL`` is the launcher's mounted directory
    (``_repo_local``'s fallback), which carries the sibling module and
    ``sisteer`` but no ``configs/``, so the default read raised
    ``IfevalMatrixUnreadable`` in every remote planner: the ordinary IFEval
    preflight before its first check, and the Nemotron probe inside its GPU
    allocation. Every remote planner therefore resolves its STAGED tree first
    and hands it here (``preflight``, ``_nemotron_probe``); the document is read
    only when an IFEval configuration is planned, so a non-IFEval plan on a tree
    without the matrix is untouched.

    ``serving_path`` — ``lens`` (this library default:
    today's plan byte for byte) or ``lora_native`` (``main``'s default). Under native every
    cell is judged through the disposition (:func:`native_cell_refusal`) HERE, before any
    Modal call: a skip-class object cell (AlphaSteer, antidote, …; PSR / vector cells PLAN natively
    since native-psr-serving) has nothing to serve on the native engine and refuses by name naming
    ``--serving-path lens``; ``none`` and the prompted cells
    are passthrough legs on either engine (a ``none``-only plan is the zero-adapter-only
    standup). A native configuration's ``out_dir`` lives under the ``native/`` namespace
    (:func:`native_gen_root`) and carries the plan marker :data:`SERVING_PATH_KEY` — the ONE
    fact the worker reads (E54 #6)."""
    if controls and in_depth:
        raise ValueError(
            "--in-depth adds the in-depth extras to the DEFAULT battery; with an explicit "
            f"--controls list name them in it instead ({', '.join(C.IN_DEPTH_EXTRAS)})")
    C.check_override_flags_exclusive(out_of_support_thinking=allow_out_of_support_thinking,
                                     off_cap_override=allow_off_cap_override, where="launch plan")
    row = C.model_row(model)                    # UnknownModel on a bad slug
    serving_path = check_serving_path_arg(serving_path)
    native = is_native_path(serving_path)
    cells = tuple(cells) if cells else C.TEST_CELLS
    modes = tuple(modes) if modes else MODE_ORDER
    for cell in cells:
        # ANY cell the serving side can express — `none`,
        # `prompted__<si>`, `<si>__<arm>` — not just the two test cells. The
        # grammar is the standup's own (contracts.parse_launcher_cell hands
        # the translated harness id to defense_cells.parse_cell_id), so a
        # token accepted here is one the standup can serve and a token
        # refused here would have died on a GPU.
        C.parse_launcher_cell(cell)
        if native:
            # native-serving-default: the disposition — a lens-only kind (AlphaSteer, antidote, ...) refuses
            # by name here, before any allocation, naming the lens escape hatch; a PSR / vector cell plans
            # natively since native-psr-serving (its position mode is judged at standup)
            why = native_cell_refusal(cell)
            if why is not None:
                raise ValueError(f"launch plan: {why}")
    for mode in modes:
        # The family gate on a whole-arm mode — `not_available` on a switched family refuses here
        C.check_thinking_arg_for_family(mode, row.family) if mode in C.THINKING_MODES else C.check_thinking_arg(mode)
    if controls:
        for c in controls:
            C.expand_control(c)                 # raises ControlNameError on a bad token
    # The IFEval planning inputs. Every
    # refusal is by name and happens HERE, before a container name is minted —
    # the dispatcher plans one configuration per (row, cap) through this door.
    C.check_sampling_arg(sampling_mode)
    atoms = {atom for c in (controls or ()) for atom in C.expand_control(c)}
    ifeval_planned = C.CONTROL_IFEVAL in atoms
    given = [name for name, value in (("off_cap_by_task", off_cap_by_task), ("item_subset", item_subset),
                                      ("bank_view", bank_view), ("out_dir", out_dir)) if value is not None]
    if given and not ifeval_planned:
        raise ValueError(
            f"launch plan: {given} are IFEval planning inputs — nothing but the {C.CONTROL_IFEVAL!r} control "
            f"consumes them, and these controls ({list(controls or ())}) do not name it")
    ifeval_off_cap: Optional[Dict[str, int]] = None
    ifeval_view: Optional[str] = None
    ifeval_cap = int(C.IFEVAL_MAX_TOKENS_OFF)
    if ifeval_planned:
        if not C.is_ifeval_row(row):
            raise ValueError(
                f"launch plan: the {C.CONTROL_IFEVAL!r} control runs on the IFEval wave's rows only "
                f"({sorted(C.IFEVAL_SLUGS.values())}); {row.slug!r} is not one (contracts.is_ifeval_row)")
        if atoms != {C.CONTROL_IFEVAL}:
            raise ValueError(
                f"launch plan: an IFEval configuration runs the {C.CONTROL_IFEVAL!r} atom ALONE — its window is "
                "the cap's own capability:ifeval_<cap> entry and its version-2 identity hashes that one executed "
                f"cap; {sorted(atoms - {C.CONTROL_IFEVAL})} would pool other traffic into it (plan §8.1)")
        if off_cap_by_task is not None:
            ifeval_off_cap = {str(t): int(v) for t, v in dict(off_cap_by_task).items()}
            for task, cap in sorted(ifeval_off_cap.items()):
                allowed = C.OFF_CAP_BY_TASK_ALLOWED.get(task)
                if task != C.IFEVAL_TASK_NAME or allowed is None:
                    raise ValueError(
                        f"launch plan: off_cap_by_task names {task!r}; the OFF setter raises {C.IFEVAL_TASK_NAME!r} "
                        f"alone here (contracts.OFF_CAP_BY_TASK_ALLOWED: {sorted(C.OFF_CAP_BY_TASK_ALLOWED)})")
                if cap not in allowed:
                    raise ValueError(
                        f"launch plan: off_cap_by_task {task}={cap} is not a rung the plan allows "
                        f"({list(allowed)}; contracts.OFF_CAP_BY_TASK_ALLOWED) — pass 1 runs at "
                        f"{C.IFEVAL_MAX_TOKENS_OFF} with no setter")
            ifeval_cap = ifeval_off_cap[C.IFEVAL_TASK_NAME]
        if item_subset is not None:
            if not str(item_subset):
                raise ValueError("launch plan: item_subset must be the rung_subset json's path, got ''")
            if ifeval_off_cap is None:
                raise ValueError(
                    f"launch plan: item_subset {item_subset!r} without off_cap_by_task — pass 1 (cap "
                    f"{C.IFEVAL_MAX_TOKENS_OFF}) runs the full item set; a subset is a RUNG's, above it")
        ifeval_view = ifeval_view_of(row)
        # The matrix's hold / deferred policy, at the planner — before a container name is minted.
        # Read off the tree the CALLER names (the staged tree in a container; REPO_LOCAL there is the
        # launcher's mount, which has no configs/), the local checkout only by default.
        # EVERY registered IFEval matrix document is read — the frozen 40-row matrix and the batch-64
        # seed sibling (contracts.IFEVAL_MATRIX_DOCUMENTS) — so the sibling's row statuses are enforced
        # here exactly like the frozen matrix's; a registered document missing from the tree refuses
        matrix_doc = ifeval_matrix if ifeval_matrix is not None else C.load_ifeval_matrices(
            ifeval_matrix_tree if ifeval_matrix_tree is not None else REPO_LOCAL)
        matrix_status_by_cell: Dict[str, Optional[str]] = {}
        for cell in cells:
            problem = C.ifeval_hold_problem(matrix_doc, slug=row.slug, cell=cell)
            if problem is not None:
                raise ValueError(f"launch plan: {problem}")
            matrix_status_by_cell[cell] = C.ifeval_matrix_row_status(matrix_doc, slug=row.slug, cell=cell)[0]
        if bank_view is not None:
            # The IFEval view vocabulary — the two instrument views + the six seed lane views (contracts.IFEVAL_VIEWS)
            if bank_view not in C.IFEVAL_VIEWS:
                raise ValueError(f"launch plan: bank_view {bank_view!r} is not one of {list(C.IFEVAL_VIEWS)}")
            if bank_view != ifeval_view:
                raise ValueError(
                    f"launch plan: bank_view {bank_view!r} disagrees with the slug's view {ifeval_view!r} "
                    f"({row.slug!r} serves the {ifeval_view!r} bank; contracts.IFEVAL_SLUGS)")
        if out_dir is not None and not str(out_dir):
            raise ValueError("launch plan: out_dir must be a path on the volume, got ''")
    out = []
    for cell in cells:
        # The whole-configuration thinking arm selected HERE by --modes is the
        # pass-1 design. The per-task policy — contracts.THINKING_BY_TASK,
        # contracts.battery_thinking(kind): ON for the generative math /
        # knowledge tasks, OFF for the letter / loglikelihood reads, EvalPlus
        # and BFCL, never both arms on one task — makes a cell's battery ONE
        # standup (reasoning parser composed) serving per-task flags, with the
        # store identity recording the per-task map. The driver / provider
        # plumbing for mixed flags under one standup is the driver's own
        # change; until it lands `--modes` stays the arm selector and the
        # pass-1 ON / OFF pairs stand as measurements.
        for mode in sorted(modes, key=MODE_PLAN_ORDER.index):
            ctl = tuple(controls) if controls else default_controls(cell, in_depth=in_depth)
            tools = needs_tool_calls(ctl)
            # The live verdict is read from the same root the frozen IFEval matrix is — the
            # staged tree when the preflight replans inside the container, the local checkout
            # (None) on the grading host
            tool_parser_why = tool_parser_problem(row, ctl, tree=ifeval_matrix_tree)
            if tool_parser_why:
                raise ValueError(tool_parser_why)
            cfg_name = C.container_name(cell, mode, model_slug=row.slug)
            by_task = thinking_by_task_of(mode, ctl)
            if ifeval_planned and C.enable_thinking(by_task[C.IFEVAL_TASK]):
                # IFEval is a thinking-OFF
                # instrument (contracts.THINKING_BY_TASK — the fit render); refused by
                # name here, before the family's parser question is even asked
                raise ThinkingUnservable(
                    f"launch configuration {cfg_name!r}: {C.CONTROL_IFEVAL!r} runs thinking OFF "
                    f"(contracts.THINKING_BY_TASK[{C.IFEVAL_TASK!r}]; the fit render, plan §4) — the {mode!r} "
                    "arm would serve it ON")
            if ifeval_planned:
                # Identity-version-2 configurations (= the IFEval atom's): the FAMILY-resolved
                # map — a no-switch family's OFF arm reads `not_available`, exactly as the driver
                # hashes it once it knows the served family; the ON case was refused just above,
                # so the policy can never raise here. Legacy configurations keep the mode's arms.
                by_task = C.apply_no_switch_policy(by_task, row.family)
            if C.check_sampling_arg(sampling_mode) == C.SAMPLING_PROTOCOL:
                # Under `protocol` EVERY filed task
                # must have a reference row (the two pinned legs) — a battery with
                # a prefill / EvalPlus / other task refuses at PLAN time, by name,
                # before any Modal call (the driver would refuse the same way)
                try:
                    C.protocol_rows_by_task(by_task)
                except C.ProtocolSamplingUnavailable as e:
                    raise ValueError(f"launch configuration {cfg_name!r}: {e}") from None
            if allow_out_of_support_thinking:
                # E50 #3: naming the flag is CLAIMING to be the authorised
                # experiment; the tuple decides, not the family
                C.check_out_of_support_thinking_authorised(
                    model=row.slug, cell=cell, controls=ctl, mode=mode,
                    sampling_mode=sampling_mode, samples=samples, reduction_mode=reduction_mode,
                    pass_no=pass_no, where=f"launch configuration {cfg_name!r}")
            offcap_marker = None
            if allow_off_cap_override:
                # The comparator tuple decides; nothing is
                # lifted (thinking_refusal_for / thinking_override_for are NOT
                # called with the flag), the marker records what changes
                C.check_off_cap_override_authorised(
                    model=row.slug, cell=cell, controls=ctl, mode=mode,
                    sampling_mode=sampling_mode, samples=samples, reduction_mode=reduction_mode,
                    pass_no=pass_no, where=f"launch configuration {cfg_name!r}")
                offcap_marker = {
                    "flag": C.FLAG_ALLOW_OFF_CAP_OVERRIDE, "model": row.slug, "cell": cell,
                    "family": row.family, "mode": mode,
                    "caps": offcap_caps_by_task(by_task, name=cfg_name),
                    "note": C.OFF_CAP_OVERRIDE_NOTE}
            refusal = thinking_refusal_for(
                row, cell, mode, ctl,
                allow_out_of_support=allow_out_of_support_thinking)
            if refusal:
                raise ThinkingUnservable(refusal)
            override = (thinking_override_for(row, cell, mode, ctl)
                        if allow_out_of_support_thinking else None)
            out.append({
                "name": cfg_name,
                "model": row.slug, "cell": cell, "mode": mode,
                "prompted": is_prompted(cell), "base": is_base(cell),
                "steered": is_steered(cell), "controls": list(ctl), "tool_calls": tools,
                "in_depth": bool(in_depth), "battery": battery_split(cell, ctl),
                "thinking_by_task": by_task,
                "standup_extra": standup_extra_for(
                    row, tool_calls=tools, thinking=mode, controls=ctl,
                    allow_out_of_support=allow_out_of_support_thinking, cell=cell,
                    sampling_mode=sampling_mode),
                # ifeval-canonical-battery: the explicit out root when the dispatcher
                # names one (a rung's own root), else the cell's
                # native-serving-default (§1.7): a native launch writes under the `native/` namespace
                # (defence in depth); an explicit out root is the operator's and is left as named
                "out_dir": (str(out_dir) if out_dir is not None
                            else C.cell_out_dir(native_gen_root() if native else C.VOL_GEN_ROOT, cell, mode,
                                                model_slug=row.slug)),
                "geometry_keys": geometry_keys_for(cell, mode, ctl, off_cap_by_task=ifeval_off_cap),
                # The IFEval planning inputs, on an
                # IFEval configuration only — the OFF setter map (None at pass 1), the rung
                # subset path (None at pass 1), the bank view the rows are stamped with
                # (the slug's), the EXECUTED cap (the setter's, else the OFF table's) and
                # the explicit k the driver's --samples states (P2: the worker reads THIS,
                # E54 #6, never a copy of its own); every other plan is byte-identical
                **({"off_cap_by_task": ifeval_off_cap,
                    "item_subset": (str(item_subset) if item_subset is not None else None),
                    "bank_view": ifeval_view, "ifeval_cap": ifeval_cap, "samples": int(samples),
                    # The frozen matrix's verdict on this row (launch | None for a cell it has no row for)
                    "matrix_status": matrix_status_by_cell.get(cell)} if ifeval_planned else {}),
                # PW-oos: identity ONLY where an out-of-support refusal was
                # actually lifted — a configuration the flag changed nothing
                # for keys exactly as it did before the flag existed
                **({C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING: True,
                    "thinking_override": override} if override else {}),
                # The comparator's planner marker — the
                # ONLY difference from the in-support plan of the same cell
                **({OFFCAP_MARKER_KEY: offcap_marker} if offcap_marker else {}),
                # The draw's MODE, present ONLY
                # when it is not the driver's default — every card plan is
                # byte-identical; the worker reads it (absent = card)
                **({SAMPLING_MODE_KEY: sampling_mode} if sampling_mode != C.SAMPLING_DEFAULT else {}),
                # native-serving-default (§1.7): the serving path, present ONLY under native — every
                # lens plan is byte-identical; the worker reads THIS (serving_path_of), never a kwarg
                **({SERVING_PATH_KEY: serving_path} if native else {}),
            })
    return out


def geometry_keys_for(cell: str, mode: str, controls: Sequence[str], *,
                      off_cap_by_task: Optional[Mapping[str, int]] = None) -> Tuple[str, ...]:
    """The geometry sub-entries a configuration's traffic pools into (the
    ledger is the basis of each; pass 1 serves them all at one footprint).
    ``prompted`` selects the tiny entry measured WITH a long SI prefix, so the
    base cell — which carries no prefix at all and therefore the shortest
    prompts of the three kinds — pools into plain ``capability:tiny``, the
    entry measured without one. A prompted cell's SI selects MATH-500's
    window by PROMPT CLASS (``contracts.geometry_subentry``'s ``si``):
    the safety SI keeps ``capability:gen_long_math``, the constitution /
    irrelevant SIs take ``capability:gen_long_math_longsi``, and an SI in
    neither class is refused by name HERE, at plan time
    (``Math500PromptClassUnmeasured``) — before any allocation. An object
    cell carries no system turn whatever SI it was fitted on, so it passes
    no SI and pools with the base cell.

    The ``ifeval`` atom keys the cap's OWN
    entry with the cap the OFF setter names (``off_cap_by_task``;
    ``IFEVAL_MAX_TOKENS_OFF`` at pass 1) — ``contracts.ifeval_geometry_entry(cell,
    cap)``: ``capability:ifeval_<cap>`` for the short prompt class (no system turn,
    or the safety SI) and ``capability:ifeval_longsi_<cap>`` for the constitution
    SI (the follow-up) — never ``geometry_subentry``, whose class map would
    hand it ``capability:gen_long``, a window measured for something else."""
    prompted = is_prompted(cell)
    si = C.parse_launcher_cell(cell).si if prompted else None
    keys = set()
    for c in controls:
        for atom in C.expand_control(c):
            if atom == C.CONTROL_IFEVAL:
                cap = int((off_cap_by_task or {}).get(C.IFEVAL_TASK_NAME, C.IFEVAL_MAX_TOKENS_OFF))
                if cap not in C.IFEVAL_GEOMETRY_ENTRY_BY_CAP:
                    raise ValueError(
                        f"no capability:ifeval_<cap> geometry entry for cap {cap} (the ladder is "
                        f"{list(C.IFEVAL_CAP_LADDER)}; contracts.IFEVAL_GEOMETRY_ENTRY_BY_CAP)")
                # the follow-up: the cap's entry OF THE CELL'S PROMPT CLASS — the constitution-
                # prompted cell (~6.4k-token prompts) takes capability:ifeval_longsi_<cap>, every
                # other cell the short entry; an unmeasured prompted SI refuses here, at plan time
                keys.add(C.ifeval_geometry_entry(cell, cap))
                continue
            cls = C.GEOMETRY_CLASS_OF_CONTROL[C.control_family(atom)]
            for task in C.TASKS_OF_CONTROL[atom]:
                if task.endswith(C.OPEN_VARIANT_SUFFIX):
                    continue          # the ON-arm twin; never planned (U5 / expected_tasks)
                arm = C.thinking_of_task(mode, task)
                keys.add(C.geometry_subentry(cls, prompted=prompted,
                                             thinking=C.enable_thinking(arm), si=si))
    return tuple(sorted(keys))


def smoke_cells_required_message() -> str:
    """The ONE wording for a native smoke that names no cells (``smoke_plan`` raises it as a
    ``ValueError`` for a direct caller; ``main`` refuses with it before any plan or Modal call)."""
    return (f"--smoke under {SERVING_PATH_FLAG} {SERVING_PATH_LORA_NATIVE} needs --cells: the historical smoke "
            f"cell {C.CELL_PSRKL_SAFETY!r} is a PSR object with no PEFT form. Name the LoRA cell to smoke "
            "(and `none` for the zero-adapter-only configuration), e.g. --cells <si>__lora_r4_ce,none — or "
            f"pass {SERVING_PATH_FLAG} {SERVING_PATH_LENS} for the lens smoke")


def smoke_plan(controls: Optional[Sequence[str]] = None, *,
               cells: Optional[Sequence[str]] = None,
               serving_path: str = SERVING_PATH_LIBRARY_DEFAULT,
               in_depth: bool = False, model: str = C.MODEL_SLUG,
               allow_out_of_support_thinking: bool = False,
               sampling_mode: str = C.SAMPLING_DEFAULT,
               samples: int = C.MATH500_SAMPLES_PER_ITEM,
               allow_off_cap_override: bool = False,
               reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
               pass_no: int = 1,
               off_cap_by_task: Optional[Mapping[str, int]] = None,
               item_subset: Optional[str] = None,
               bank_view: Optional[str] = None,
               out_dir: Optional[str] = None,
               ifeval_matrix_tree: Optional[str | Path] = None) -> List[dict]:
    """The smoke: ONE thinking-OFF fitted container, on the cell's
    default controls (plus the in-depth extras under ``in_depth``) or the
    ``--controls`` override (e.g. ``gsm8k`` alone). The smoke is thinking-OFF
    by construction, so the PW-oos override lifts nothing here; it is threaded
    only so ``plan_for`` has one signature — and under E50 #3 a smoke that
    names the flag is refused like any other unauthorised configuration.

    Under ``lora_native`` the smoke HONOURS
    the requested cells — they are REQUIRED (``--cells``: the rule predates native-psr-serving,
    when the historical PSR smoke cell had no native form; it PLANS natively now, its position
    mode judged at standup, and the smoke still names its cells) and EACH named cell becomes its
    own thinking-OFF configuration (a lens-only kind — AlphaSteer, antidote — refuses at planning
    through the disposition; ``none`` is the zero-adapter-only configuration). Under ``lens`` the
    smoke is TODAY's plan, byte for byte — the retained PSR
    smoke cell — and ``cells`` is NOT consulted (judgement call, W-G: the lens smoke keeps its
    historical shape; ``tests/test_ifeval_container_layout`` plans a lens smoke beside an
    explicit cell list and expects the PSR cell)."""
    serving_path = check_serving_path_arg(serving_path)
    if is_native_path(serving_path):
        if not cells:
            raise ValueError(smoke_cells_required_message())
        chosen: Tuple[str, ...] = tuple(cells)
    else:
        chosen = (C.CELL_PSRKL_SAFETY,)
    return plan_configurations(cells=chosen, modes=(C.THINKING_OFF,),
                               controls=controls, in_depth=in_depth, model=model,
                               allow_out_of_support_thinking=allow_out_of_support_thinking,
                               sampling_mode=sampling_mode, samples=samples,
                               allow_off_cap_override=allow_off_cap_override,
                               reduction_mode=reduction_mode, pass_no=pass_no,
                               off_cap_by_task=off_cap_by_task, item_subset=item_subset,
                               bank_view=bank_view, out_dir=out_dir, ifeval_matrix_tree=ifeval_matrix_tree,
                               serving_path=serving_path)


def plan_for(*, smoke: bool = False, cells: Optional[Sequence[str]] = None,
             modes: Optional[Sequence[str]] = None, controls: Optional[Sequence[str]] = None,
             in_depth: bool = False, model: str = C.MODEL_SLUG,
             allow_out_of_support_thinking: bool = False,
             sampling_mode: str = C.SAMPLING_DEFAULT,
             samples: int = C.MATH500_SAMPLES_PER_ITEM,
             allow_off_cap_override: bool = False,
             reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
             pass_no: int = 1,
             off_cap_by_task: Optional[Mapping[str, int]] = None,
             item_subset: Optional[str] = None,
             bank_view: Optional[str] = None,
             out_dir: Optional[str] = None,
             ifeval_matrix_tree: Optional[str | Path] = None,
             serving_path: str = SERVING_PATH_LIBRARY_DEFAULT) -> List[dict]:
    """The ONE planner behind both the launch and the preflight (E40 M6): the
    smoke plan under ``smoke``, else :func:`plan_configurations` over exactly
    the cells / modes / controls / ``in_depth`` / model the invocation named.
    ``main`` builds these arguments once (``plan_args``), plans from them, and
    hands the SAME mapping to ``preflight``, which plans from it again inside
    the container — so the configuration names and geometry keys the preflight
    validates are the launch's by construction. Before this the preflight
    planned from modes + model alone (cells passed, controls and ``--in-depth``
    not), so a custom control battery could pass on the default battery's
    geometry and fail inside the paid container.

    ``sampling_mode`` / ``samples`` are planning inputs for ONE reason (E50 #3):
    the authorised out-of-support experiment names a draw, so the authorisation
    check cannot be made without them. Neither composes launcher argv — the
    driver's default IS the ruling (§PW-sampling-2 item 8). ``reduction_mode``
    is one for the same reason (code review H2): both tuples name per_row; and so
    is ``pass_no`` (code review H3): both tuples name geometry pass 1, and the
    preflight budgets the pass it is handed.

    ``ifeval_matrix_tree`` is NOT a planning input and never rides
    ``plan_args``: it names where the frozen IFEval matrix is READ from — the local
    checkout by default (``main``), the STAGED tree when the preflight replans inside
    the container, where the launcher's mount carries no ``configs/``."""
    # The IFEval planning inputs ride the same
    # mapping, so the preflight replans the SAME rung / view / out root the launch runs
    ifeval_kw = dict(off_cap_by_task=off_cap_by_task, item_subset=item_subset, bank_view=bank_view, out_dir=out_dir,
                     ifeval_matrix_tree=ifeval_matrix_tree)
    if smoke:
        # native-serving-default: the smoke honours the requested cells
        return smoke_plan(controls, cells=cells, serving_path=serving_path, in_depth=in_depth, model=model,
                          allow_out_of_support_thinking=allow_out_of_support_thinking,
                          sampling_mode=sampling_mode, samples=samples,
                          allow_off_cap_override=allow_off_cap_override,
                          reduction_mode=reduction_mode, pass_no=pass_no, **ifeval_kw)
    return plan_configurations(cells, modes, controls, in_depth=in_depth, model=model,
                               allow_out_of_support_thinking=allow_out_of_support_thinking,
                               sampling_mode=sampling_mode, samples=samples,
                               allow_off_cap_override=allow_off_cap_override, serving_path=serving_path,
                               reduction_mode=reduction_mode, pass_no=pass_no, **ifeval_kw)


def isolate_out_dirs(cfgs: Sequence[Mapping], suffix: str) -> List[dict]:
    """Every configuration's ``out_dir`` moved under ``<out_dir>/<suffix>/``
    (resume markers, ledger, stores and served_geometry.json all follow)."""
    suffix = suffix.strip("/")
    if not suffix:
        return [dict(c) for c in cfgs]
    return [dict(c, out_dir=f"{str(c['out_dir']).rstrip('/')}/{suffix}") for c in cfgs]


def gpu_container_count(n_cfgs: int, *, row_launch: bool, nemotron_probe: bool = False) -> int:
    """How many GPU containers ONE invocation of ``main`` spawns — what :func:`gpu_container_budget` counts.
    Per-cell launches spawn one container per configuration; a ROW launch (tinycap-shared-standup §1.1:
    ``--row``) serves every configuration of the row from ONE container, so its count is 1 however many cells
    it carries (0 when there is nothing to serve). The Nemotron backend probe is one container, in either
    mode."""
    if n_cfgs < 0:
        raise ValueError(f"n_cfgs must be >= 0, got {n_cfgs}")
    cells = (1 if n_cfgs else 0) if row_launch else n_cfgs
    return cells + (1 if nemotron_probe else 0)


def gpu_container_budget(n_gpu_containers: int, *, allow_extra: bool = False) -> None:
    """The cost trip-wire: more than ``MAX_GPU_CONTAINERS`` GPU containers in one
    invocation refuses unless ``--allow-extra``."""
    if n_gpu_containers > C.MAX_GPU_CONTAINERS and not allow_extra:
        raise SystemExit(
            f"[tinycap] refusing {n_gpu_containers} GPU containers > MAX_GPU_CONTAINERS "
            f"{C.MAX_GPU_CONTAINERS} (plan §6 trip-wire) — pass --allow-extra on purpose")


#: The REC statuses that mean "this container owes nothing more" — the ONLY
#: two ``main`` exits 0 on. ``OK`` = the driver
#: returned 0 with no control left; ``DONE`` = every task was validly done
#: before the standup, so no GPU minute was spent. Everything else
#: (``INCOMPLETE``, ``STANDUP_FAILED``, ``NO_TREE``, ``PRODUCER_TREE_MISMATCH``,
#: ``REDUCTION_MODE_MISMATCH``, ``REDUCTION_MODE_UNATTESTED``,
#: ``EVALPLUS_ARCHIVES_MISSING``, the out-of-support experiment's
#: :data:`OOS_WORKER_RECS`, a merge /
#: spot-check ``FAILED``…) leaves work undone and must reach the operator as a
#: NON-ZERO exit: attempt 1 at 1983322 printed ``0/1 container(s) OK`` and
#: exited 0, so its wrapper wrote ``exit 0`` into the ``.DONE`` sentinel and
#: the wave's watcher read a failed cell as a finished one.
#: ``PARTIAL_COMPLETE``: a truncation-
#: ladder rung-2 container whose every selected item is validly filed under a
#: PARTIAL marker — the ladder's COMPLETE state (a selection run ends PARTIAL by
#: contract), so the first successful scoring invocation exits 0, and a relaunch
#: that finds every cell complete returns it with zero GPU calls.
#: Spelled in the contracts since tinycap-shared-standup landing 2 (the driver writes RESULT lines too); bound here so
#: every harness reader keeps its name (``tests/test_inspect_served_verification_phase.py`` holds the binding by source)
LADDER_REC_STATUS = C.LADDER_REC_STATUS
REC_OK_STATUSES: Tuple[str, ...] = C.REC_OK_STATUSES
#: ifeval-canonical-battery (the wave shakedown, 2026-09-13): the ladder planner's ``store_status`` reads the cluster
#: lane's ``RESULT`` stamp (a ``result=COMPLETE`` line beside the store), which no Modal container wrote — every Modal
#: store read "outcomes present, DONE marker present, RESULT not COMPLETE — the store's records disagree". The
#: container appends ONE line per REC (a resume appends its own); ``result=`` is COMPLETE iff the REC is an OK status.
RESULT_FILENAME = C.RESULT_FILENAME
RESULT_COMPLETE = C.RESULT_COMPLETE


def result_stamp_line(rec: Mapping[str, object], *, driver_rc: object) -> str:
    """ONE RESULT line for a REC — the grammar is ``cpu_verify.result_line``'s (the driver writes lines of it too
    since landing 2), rendered from the REC's name / status / tree sha and the driver's rc."""
    return CV.result_line(name=rec.get("name"), status=rec.get("status"), tree_sha=rec.get("tree_sha"), rc=driver_rc)

#: The out-of-support experiment's typed worker refusals (each ends the
#: run, no relaunch without a diagnosis). After the
#: standup, from ``endpoint.json`` against the launcher's PURE expectation:
#: ``OOS_DECLARATION_UNATTESTED`` — ``lens_serve_declarations_error`` non-null
#: (every configuration), or an out-of-support configuration whose standup
#: attests no ``lens_serve_declarations`` at all, or a declared cell whose own
#: attestation key is absent; ``OOS_DECLARATION_MISMATCH`` — the own key's
#: core is not the expected ``["thinking"]``, the twin ``none__lens0`` is
#: absent or disagrees on a declared standup, an UNDECLARED configuration's
#: own key is present, a malformed map, or the served artifact digest(s)
#: disagree with the one the launcher passed; ``OOS_SALT_POLICY_UNEXPECTED``
#: — the authorised psr cell's attested resumed-prefill policy is not
#: ``conditional`` or ``lens_salt_policy`` is not
#: ``attested``; ``OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH``
#: (``contracts.REC_OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH``) — the served
#: ``chat_template_hash`` is not the prompt-budget artifact's digest,
#: or no artifact reached the container. BEFORE the standup (a saved standup):
#: ``OOS_TORN_STORE_UNREPAIRABLE`` — a DONE out-of-support task whose outcome
#: record is torn and whose retained ``.eval`` log is gone, so the driver's
#: repair could only refuse.
#: The literals live ONCE, in ``contracts`` (the driver
#: names the same RECs in the refusals it exits with); these are re-exports by
#: reference, so a log reads one word from either side of the standup.
REC_OOS_DECLARATION_UNATTESTED = C.REC_OOS_DECLARATION_UNATTESTED
REC_OOS_DECLARATION_MISMATCH = C.REC_OOS_DECLARATION_MISMATCH
REC_OOS_SALT_POLICY_UNEXPECTED = C.REC_OOS_SALT_POLICY_UNEXPECTED
REC_OOS_TORN_STORE_UNREPAIRABLE = C.REC_OOS_TORN_STORE_UNREPAIRABLE
OOS_WORKER_RECS: Tuple[str, ...] = (
    REC_OOS_DECLARATION_UNATTESTED, REC_OOS_DECLARATION_MISMATCH,
    REC_OOS_SALT_POLICY_UNEXPECTED, C.REC_OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH,
    REC_OOS_TORN_STORE_UNREPAIRABLE)


def failed_recs(recs: Sequence[Mapping], *, also_ok: Sequence[str] = ()) -> List[Tuple[str, str]]:
    """``(name, status)`` for every REC outside :data:`REC_OK_STATUSES` — the
    basis of ``main``'s exit code. A REC with no ``status`` at all counts as
    failed and is named ``"<missing>"``: a container that did not say how it
    ended is exactly the case this rule exists for. ``also_ok`` widens the
    accepted set for ONE invocation (code review R2-1: a warm-only row's
    ``WARMED`` cells, which are no completed store anywhere else); the default
    is today's rule byte for byte."""
    ok = tuple(REC_OK_STATUSES) + tuple(also_ok)
    out: List[Tuple[str, str]] = []
    for r in recs:
        status = r.get("status")
        if status not in ok:
            out.append((str(r.get("name") or r.get("cell") or "?"),
                        str(status) if status is not None else "<missing>"))
    return out


def rec_failure_message(recs: Sequence[Mapping], *, also_ok: Sequence[str] = ()) -> str:
    """What ``main`` exits with when :func:`failed_recs` is non-empty: every
    failed container named with its status, plus — for an ``INCOMPLETE`` whose
    only remaining controls are the EvalPlus pair — the note that this is the
    EXPECTED two-stage handoff (the execution sandbox runs next and
    the merge follows). It is still a non-zero exit: the cell is not complete
    until the sandbox stage lands, and a wrapper that recorded ``exit 0`` here
    would be claiming otherwise. ``also_ok`` as in :func:`failed_recs`."""
    ok = tuple(REC_OK_STATUSES) + tuple(also_ok)
    head = (f"[tinycap] {len(failed_recs(recs, also_ok=also_ok))}/{len(recs)} container(s) did NOT finish "
            f"(status outside {list(ok)}):")
    lines = [head]
    for r in recs:
        status = r.get("status")
        if status in ok:
            continue
        name = r.get("name") or r.get("cell") or "?"
        line = f"   {name}: {status if status is not None else '<missing>'}"
        remaining = list(r.get("controls_still_remaining") or ())
        if status == "INCOMPLETE" and remaining and all(
                C.control_family(a) in C.EVALPLUS_CONTROLS
                for c in remaining for a in C.expand_control(c)):
            line += (f" — remaining {remaining} is the EvalPlus pair only: the EXPECTED "
                     "two-stage handoff (plan §5.3), the execution sandbox "
                     "(tinycap_sandbox.py) runs next and the merge follows; non-zero "
                     "because the cell is not complete until it does")
        elif remaining:
            line += f" — still remaining: {remaining}"
        if r.get("error"):
            line += f" — {str(r['error'])[:300]}"
        lines.append(line)
    return "\n".join(lines)


def done_marker_name(task: str) -> str:
    """``<cell_dir>/done/<task with / -> __>.json`` (P34) — the contract's
    ``marker_filename`` (which refuses a non-tinycap task)."""
    return C.marker_filename(task)


def expected_tasks(control: str, mode: str) -> Tuple[str, ...]:
    """The row tasks a control produces in a mode: the ``:open`` EvalPlus
    variants exist under thinking-ON only (contracts.TASKS_OF_CONTROL) — and
    NEVER under ``per-task``, whose policy runs every EvalPlus leg OFF, so the
    ON-arm twin does not arise (``contracts.battery_thinking`` leaves it out
    for the same reason)."""
    tasks = [t for a in C.expand_control(control) for t in C.TASKS_OF_CONTROL[a]]
    if C.check_thinking_arg(mode) != C.THINKING_ON:
        tasks = [t for t in tasks if not t.endswith(C.OPEN_VARIANT_SUFFIX)]
    return tuple(tasks)


def _read_json_object(path: Path) -> Tuple[Optional[Mapping], Optional[str]]:
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        return None, f"unreadable ({type(e).__name__}: {str(e)[:120]})"
    if not isinstance(doc, Mapping):
        return None, "not a JSON object"
    return doc, None


def cell_key_hash_prefixes(cell_dir_name: str) -> Optional[Tuple[str, str]]:
    """``(ihash8, chash8)`` from a store's directory name (the frozen
    ``<arm>__<tier>__t<trial>__a<attempt>__<ihash8>__<chash8>`` layout of
    ``capeval.store.cell_key``); None for a name outside that layout."""
    parts = cell_dir_name.split("__")
    if len(parts) < 6:
        return None
    ihash8, chash8 = parts[-2], parts[-1]
    if len(ihash8) != 8 or len(chash8) != 8:
        return None
    return ihash8, chash8


# --------------------------------------------------------------------------- #
# resume identity (E12 item 1): the FULL expected identity, derived from the    #
# run's RESOLVED inputs BEFORE any done marker is read                         #
# --------------------------------------------------------------------------- #

#: row task -> the control atom that produces it (reverse of TASKS_OF_CONTROL)
_ATOM_OF_TASK: Mapping[str, str] = {
    t: atom for atom, tasks in C.TASKS_OF_CONTROL.items() for t in tasks}
_SHA40 = re.compile(r"^[0-9a-f]{40}$")


class IdentityUnderivable(ValueError):
    """A contract identity field this launcher has NO derivation for: the
    expected identity is built field by field from the contracts' tuples,
    so a name added to ``SERVED_IDENTITY_FIELDS`` without a derivation here
    refuses loudly — never a silently narrower comparison."""


def reasoning_parser_of(standup_extra: Sequence[str]) -> Optional[str]:
    """The reasoning parser a standup argv COMPOSES (the value after
    ``--reasoning-parser``), None when the flag is absent — what the
    standup's endpoint.json will record and the driver copies into the
    store identity."""
    argv = list(standup_extra)
    if C.FLAG_REASONING_PARSER not in argv:
        return None
    i = argv.index(C.FLAG_REASONING_PARSER)
    if i + 1 >= len(argv):
        raise ValueError(f"{C.FLAG_REASONING_PARSER} carries no value in {argv}")
    return argv[i + 1]


def agent_loop_entry_of(standup_extra: Sequence[str]) -> bool:
    """The proxy's Petri-facing agent-loop entry a standup argv COMPOSES
    (PW18 / U4(b)): ON unless the argv states the opt-out
    (``--no-petri-agent-loop``, ``contracts.FLAG_NO_PETRI_AGENT_LOOP``) — the
    standup's own default, what its ``endpoint.json`` records as
    ``agent_loop_entry`` and the driver hashes into the served identity. The
    launcher never composes the opt-out; the derivation reads the argv so the
    expected identity can never disagree with the argv it launches."""
    return C.FLAG_NO_PETRI_AGENT_LOOP not in list(standup_extra)


def sampling_clamp_override_of(standup_extra: Sequence[str]) -> Optional[Dict[str, object]]:
    """The protocol sampling CLAMP OVERRIDE record a standup argv COMPOSES
    (bcb-bfcl-200-widen): ``contracts.SAMPLING_CLAMP_OVERRIDE`` when the
    argv carries ``--sampling-clamp-override <T>`` at the pinned value, None
    when it does not — what the standup's ``endpoint.json`` will record and the
    driver copies into the hashed served block. Read off the argv, like the
    parser and the agent-loop entry, so the expectation can never disagree
    with the launch; a value other than the pinned one refuses here (the
    standup would refuse it too)."""
    argv = list(standup_extra)
    if C.FLAG_SAMPLING_CLAMP_OVERRIDE not in argv:
        return None
    if argv.count(C.FLAG_SAMPLING_CLAMP_OVERRIDE) != 1:
        # code review: only the FIRST occurrence used to be read — two spellings are two sources for one fact
        raise ValueError(f"{C.FLAG_SAMPLING_CLAMP_OVERRIDE} appears {argv.count(C.FLAG_SAMPLING_CLAMP_OVERRIDE)} times in the "
                         "standup argv — one override, stated once")
    at = argv.index(C.FLAG_SAMPLING_CLAMP_OVERRIDE)
    value = argv[at + 1] if at + 1 < len(argv) else None
    if value != C.SAMPLING_CLAMP_OVERRIDE_ARG:
        raise ValueError(
            f"{C.FLAG_SAMPLING_CLAMP_OVERRIDE} {value!r} is not the pinned {C.SAMPLING_CLAMP_OVERRIDE_ARG} "
            "(contracts.BFCL_PROTOCOL_TEMPERATURE, D13) — another override is another instrument")
    return dict(C.SAMPLING_CLAMP_OVERRIDE)


def reduction_mode_expected(environ: Optional[Mapping[str, str]] = None) -> str:
    """The reduction mode a standup launched under ``environ`` would serve —
    ``contracts.reduction_mode_from_env``, the parser's rule exactly (E29 /
    PW18b: unset / empty / 1 / stacked -> stacked, 0 / per_row / off -> per_row,
    else refuses; unset = STACKED since E46, because the landing is merged and a
    worker spawned from this tree serves stacked). Note this is deliberately NOT
    ``REDUCTION_MODE_LAUNCHER_DEFAULT``, which stays per_row: this says what an
    environment WOULD serve, that says what the launcher ASKS for.
    The launcher never relies on it implicitly:
    ``--reduction-mode`` is written into the standup environment as ONE
    canonical value, and the standup's attestation (``endpoint.json``
    ``lens_reduction_mode``; absent = a pre-landing server = per_row) is
    compared with that expectation the moment the record appears."""
    return C.reduction_mode_from_env(os.environ if environ is None else environ)


#: ``endpoint.json``'s companion to :data:`contracts.PROXY_IDENTITY_REDUCTION_MODE`:
#: the REASON a post-landing standup has no mode to state
#: (``lens_worker.LENS_REDUCTION_MODE_ERROR_KEY``, by value — see
#: :func:`endpoint_reduction_mode` for why this launcher may not import it).
LENS_REDUCTION_MODE_ERROR_KEY = "lens_reduction_mode_error"


class ReductionModeUnattested(RuntimeError):
    """A standup endpoint record states no reduction mode AND says why it could
    not determine one — the launcher-side twin of
    ``lens_worker.ReductionModeUnattested`` and of the copy main ships in
    ``capctrl_served``, raised instead of falling back to the pre-landing
    default."""


def endpoint_reduction_mode(endpoint, *, source: str = "standup endpoint record") -> str:
    """The reduction mode a consumer must read out of a WHOLE standup endpoint
    record. Three readings, and only three (E61):

    * ``lens_reduction_mode`` NAMED (a member of :data:`contracts.
      REDUCTION_MODES`) — that mode;
    * NEITHER ``lens_reduction_mode`` nor
      :data:`LENS_REDUCTION_MODE_ERROR_KEY` stated — a PRE-LANDING standup,
      which served ``per_row``. A null mode with NO reason is the same
      reading: the record stated nothing either way;
    * ``lens_reduction_mode`` null WITH a stated reason —
      :exc:`ReductionModeUnattested` quoting it.

    The third case is the whole point, and is what
    :func:`contracts.resolve_reduction_mode` structurally cannot see: it is
    handed VALUES, so ``endpoint.get(PROXY_IDENTITY_REDUCTION_MODE)`` reaches
    it as a bare ``None`` and reads as the pre-landing default. A post-landing
    standup ALWAYS writes the key and writes null plus a reason when its
    workers attest nothing or DISAGREE, so defaulting there would label a
    store ``per_row`` while the standup that produced it said its arithmetic
    could not be determined. An unknown value and an unreadable record refuse
    the same way.

    A deliberate SECOND COPY of ``sisteer.capeval.serving.lens_worker.
    endpoint_reduction_mode``, pinned to it case by case by
    ``tests/test_tinycap_launcher.py`` — the same call main makes in
    ``capctrl_served`` and for the same reason: the read site is inside the
    container, runs after the H200 bring-up, and by then the STAGED CANDIDATE
    tree's ``src`` is FIRST on ``sys.path`` (``_geometry_module`` put it
    there), so an import of the resolver at the read site is a crash the cell
    cannot recover from on any pre-landing sha. This function imports nothing;
    keep it in step with the two it copies.

    The ENGINE is read FIRST, in all three copies —
    the engine is read the way ``contracts.endpoint_is_native`` / ``lens_worker`` read it —
    ``engine`` as the bare kind (``endpoint.json``) or the ``/v1/models`` block's ``{"kind": …}``,
    the row-facing ``serving_engine`` spelling beside it (a pair that disagrees is torn and
    refuses) — and ``lora_native`` -> :data:`REDUCTION_MODE_NOT_APPLICABLE` with NO
    ``lens_reduction_mode`` consulted (the native engine has no lens hook and attests ``engine``
    instead; an explicit value, so a resume guard reading ``route.get(reduction_mode, per_row)``
    never falls to per_row); a native record that nevertheless STATES a lens mode is torn and
    refuses. ``engine`` absent or ``lens``: the three lens readings above, byte for byte. Any
    other ``engine`` refuses (an unknown engine has no reduction-mode reading)."""
    if not isinstance(endpoint, Mapping):
        raise ReductionModeUnattested(
            f"{source}: not a mapping ({type(endpoint).__name__}) — no "
            f"{C.PROXY_IDENTITY_REDUCTION_MODE} can be read from it")
    stated = endpoint.get(C.PROXY_IDENTITY_REDUCTION_MODE)
    engine = endpoint.get(ENDPOINT_KEY_ENGINE)
    if isinstance(engine, Mapping):
        engine = engine.get("kind")        # the /v1/models identity block spells the engine as a block
    row_engine = endpoint.get(SERVED_ENGINE_FIELD)
    if engine is not None and row_engine is not None and engine != row_engine:
        raise ReductionModeUnattested(
            f"{source}: states {ENDPOINT_KEY_ENGINE}={engine!r} and {SERVED_ENGINE_FIELD}={row_engine!r} — two "
            "spellings of one engine that disagree; a torn record, refusing to read either")
    engine = engine if engine is not None else row_engine
    if engine == ENGINE_LORA_NATIVE:
        if stated is not None:
            raise ReductionModeUnattested(
                f"{source}: a native multi-LoRA standup ({ENDPOINT_KEY_ENGINE}={ENGINE_LORA_NATIVE!r}) states "
                f"{C.PROXY_IDENTITY_REDUCTION_MODE}={stated!r} — it has no lens hook to attest a reduction mode "
                "for; a torn record, refusing rather than reading either fact")
        return REDUCTION_MODE_NOT_APPLICABLE
    if engine is not None and engine != ENGINE_LENS:
        raise ReductionModeUnattested(
            f"{source}: {ENDPOINT_KEY_ENGINE}={engine!r} is neither {ENGINE_LENS!r} nor {ENGINE_LORA_NATIVE!r} — "
            "no reduction mode can be read for an unknown engine")
    why_none = endpoint.get(LENS_REDUCTION_MODE_ERROR_KEY)
    if stated is None:
        if why_none:
            raise ReductionModeUnattested(
                f"{source}: {C.PROXY_IDENTITY_REDUCTION_MODE} is null and "
                f"{LENS_REDUCTION_MODE_ERROR_KEY} is {why_none!r} — the standup could not "
                "determine the lens reduction mode its own workers served, so this is not a "
                f"pre-landing server (which states neither key and means "
                f"{C.REDUCTION_MODE_PER_ROW!r}); refusing rather than recording the default "
                "as served identity")
        return C.REDUCTION_MODE_PER_ROW
    if stated not in C.REDUCTION_MODES:
        raise ReductionModeUnattested(
            f"{source}: {C.PROXY_IDENTITY_REDUCTION_MODE}={stated!r} is not one of "
            f"{list(C.REDUCTION_MODES)}")
    return stated


def client_lock_sha256(tree: Optional[str | Path]) -> Optional[str]:
    """sha256 of the staged tree's client lock — what the driver records as
    ``frameworks.client_lock_sha256`` (None when there is no tree or the
    tree carries no lock, exactly as the driver records null then)."""
    if not tree:
        return None
    p = Path(tree) / C.CLIENT_LOCK_TXT
    return hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None


def tree_sha_of(tree: Optional[str | Path]) -> Optional[str]:
    """The staged tree's ``TREE_SHA`` stamp — what the driver running from it
    records as ``manifest.producer.tree_sha`` (``_producer_block``). None
    when there is no tree or no stamp, exactly as the launcher's other
    tree-derived facts read null then; the stamp itself is enforced by
    :func:`staged_tree_sha` at resolution."""
    if not tree:
        return None
    p = Path(tree) / C.TREE_SHA_FILENAME
    if not p.is_file():
        return None
    text = p.read_text(encoding="utf-8").strip()
    return text if _SHA40.match(text) else None


class ExpectedIdentity(NamedTuple):
    """What a store must record to be trusted for THIS run: the cell, the
    thinking mode, the pass, the served identity (exactly
    ``contracts.SERVED_IDENTITY_FIELDS``, resolved — never read off a
    store), the active limits, the avg@k width, and the staged tree's
    client-lock sha AND its ``TREE_SHA`` stamp (E14 B: the producer sha is
    not hashed identity, so without comparing it a partial store from
    another revision keys the same and would be resumed onto). (A
    NamedTuple, not a dataclass: the tests load this
    module by file path without a ``sys.modules`` entry, and a dataclass
    under ``from __future__ import annotations`` resolves its string
    annotations through ``sys.modules[cls.__module__]``.)"""

    cell: str
    mode: str
    pass_no: int
    served: Mapping[str, object]
    limits: Mapping[str, int]
    samples: int
    client_lock_sha256: Optional[str]
    tree_sha: Optional[str] = None
    #: ``{row task: on|off}`` for the tasks this configuration runs (O7 item 4's
    #: fixed interface with the driver — that exact key name). Under a
    #: whole-arm mode it simply repeats the arm; under ``per-task`` it IS the
    #: configuration's thinking policy. The launcher RECORDS it (the dry run
    #: prints it, the REC carries it); the store-side comparison belongs with
    #: the driver's identity fields — see PW20b-L-5.
    thinking_by_task: Mapping[str, str] = {}
    #: PW-sampling (U8 item 1): the five hashed sampling fields
    #: (``contracts.SAMPLING_IDENTITY_FIELDS`` — the model's frozen row's
    #: temperature / top_p / top_k, the per-task k map, the seed rules) this
    #: configuration's driver WILL hash, and the ``--sampling`` mode they were
    #: derived under (the driver's default, ``card``, unless the launcher is
    #: ever taught otherwise). Compared per field by ``untrusted_store_reason``.
    sampling: Mapping[str, object] = {}
    sampling_mode: str = C.SAMPLING_DEFAULT
    #: PW-battery (U10 item 4): the OR-Bench item set this configuration's
    #: driver WILL hash (``contracts.run_or_bench_item_set`` over the REQUESTED
    #: controls — the frozen seeded 200-item subset, ``None`` when the
    #: configuration files no OR-Bench rows). The launcher never asks for the
    #: full corpus: ``--or-bench-full`` is a driver flag it does not emit
    #: (``contracts.FLAG_OR_BENCH_FULL``), so a battery wave and an
    #: operator's full-corpus run can never resume onto each other's store.
    #: Compared by ``untrusted_store_reason``.
    or_bench_item_set: Optional[Mapping[str, object]] = None
    #: PW-oos (U10 item 5): whether this configuration's driver will stamp
    #: ``out_of_support_thinking`` into its hashed identity — true only where
    #: ``--allow-out-of-support-thinking`` actually LIFTED a refusal. False is
    #: the whole campaign, and :meth:`as_dict` then omits the key entirely, so
    #: an in-support expectation is byte-identical to what it was before the
    #: override existed.
    out_of_support_thinking: bool = False
    #: fit-support transfer: the two FURTHER
    #: optional hashed keys an out-of-support store carries beside the marker.
    #: ``max_tokens_by_task`` — the raised per-task completion cap over this
    #: configuration's thinking-ON Inspect tasks (``oos_caps_by_task`` reading
    #: ``contracts.oos_max_tokens_on``: ``{inspect/gsm8k_paired200: 8192}``),
    #: so an 8192 store never keys with, or resumes onto, a 2048 one.
    #: ``serve_out_of_support`` — the CONTRACT-DERIVED declaration literal
    #: (``contracts.expected_serve_out_of_support``: ``["thinking"]`` on the
    #: declared lens cell, ``None`` on the base route), computable with NO
    #: server — never the standup's attestation, which is compared against it
    #: AFTER the standup as a refusal. Both empty / None and OMITTED from
    #: :meth:`as_dict` on an in-support expectation; which of them the hashed
    #: block carries at all is read off ``contracts.tinycap_identity_fields``
    #: (:meth:`optional_identity`), never a list typed here.
    max_tokens_by_task: Mapping[str, int] = {}
    serve_out_of_support: object = None
    #: Whether this configuration's driver will stamp the
    #: comparator's ONE optional key (``max_tokens_by_task`` alone — the
    #: comparator's raised OFF cap, ``offcap_caps_by_task``) under
    #: ``--allow-off-cap-override``. Mutually exclusive with
    #: ``out_of_support_thinking``; False is the whole campaign.
    off_cap_override: bool = False
    #: MATH-500 one-pass: the FIRST-PASS cap this configuration's MATH-500
    #: leg generates at (``contracts.math500_max_tokens_for`` at MATH's arm —
    #: 16,384 in support), the value the driver hashes as ``math500_max_tokens``
    #: from the plan builder's own rule. ``None`` and OMITTED from
    #: :meth:`as_dict` when the configuration files no ``inspect/math`` row
    #: (:attr:`files_math500`), so every non-MATH expectation is byte-identical
    #: to what it was before the key existed; on a MATH configuration a store
    #: generated at another cap is refused by name (``untrusted_store_reason``).
    math500_max_tokens: Optional[int] = None
    #: The two pinned legs' HASHED item sets
    #: (``contracts.item_set_identity`` over the pin the launcher reads from
    #: the tree: ``{seed, n, of, ids_sha256}``) and the BigCodeBench sandbox
    #: facts (``contracts.bcb_sandbox_identity``) — each present when and only
    #: when the configuration FILES that leg (``files_bigcodebench_200`` /
    #: ``files_bfcl_200`` over the thinking map, the driver's own predicate),
    #: None and OMITTED from :meth:`as_dict` otherwise, so every other
    #: expectation is byte-identical to what it was.
    bcb_item_set: Optional[Mapping[str, object]] = None
    bfcl_item_set: Optional[Mapping[str, object]] = None
    bcb_sandbox: Optional[Mapping[str, object]] = None
    #: capeval-full-tasks: the FULL legs' hashed item sets (``contracts.item_set_identity``
    #: over the full pins: ``{seed: null, n, of, ids_sha256}``), present iff the configuration
    #: files ``inspect/bigcodebench_full`` / ``inspect/bfcl_full``; the sandbox facts above ride
    #: on a full BCB configuration too (one verifier)
    bcb_full_item_set: Optional[Mapping[str, object]] = None
    bfcl_full_item_set: Optional[Mapping[str, object]] = None
    #: The truncation ladder's rung-2 tuple — the
    #: 16,384 cap per fired row task and the capped items (PINNED ids; the
    #: hashed value is ``contracts.item_selection_identity`` over them,
    #: :attr:`item_selection`) — both present when and only when the
    #: configuration carries ``ladder_rung`` (:attr:`ladder`), None and OMITTED
    #: from :meth:`as_dict` otherwise. A ladder expectation's ``limits`` are
    #: exactly ``contracts.LADDER_LIMITS`` (a selection run ends PARTIAL by
    #: contract), and ``untrusted_store_reason`` accepts that block for THIS
    #: expectation shape only.
    cap_overrides_by_task: Optional[Mapping[str, int]] = None
    item_selection_ids: Optional[Mapping[str, Sequence[str]]] = None
    #: The identity VERSION this
    #: configuration's driver stamps — 2 on an IFEval configuration
    #: (``--tinycap-identity-version 2``: ``identity_version`` and the EXECUTED
    #: per-task cap map ``max_tokens_by_task`` over every Inspect task of the run
    #: — the IFEval atom alone, ``{inspect/ifeval: <cap>}`` — join the hashed
    #: keys; ``thinking_header_ids`` never does, IFEval is thinking-OFF), the
    #: legacy 1 everywhere else, where :meth:`as_dict` is byte-identical to
    #: before the field existed.
    identity_version: int = C.TINYCAP_IDENTITY_VERSION_LEGACY
    #: a RUNG store's hashed binding to its source
    #: (``contracts.cap_rung_identity`` over the validated ``--item-subset`` file
    #: the driver reads too), present when and only when the configuration
    #: carries an item subset; None and OMITTED from :meth:`as_dict` otherwise.
    cap_rung: Optional[Mapping[str, object]] = None

    @property
    def serving_engine(self) -> str:
        """native-serving-default (§1.7): the engine this expectation is FOR — ``lora_native`` iff the
        served block carries :data:`SERVED_ENGINE_FIELD` (present iff native, by derivation), else
        ``lens`` (every historical expectation, byte for byte)."""
        return ENGINE_LORA_NATIVE if SERVED_ENGINE_FIELD in self.served else ENGINE_LENS

    @property
    def native(self) -> bool:
        return self.serving_engine == ENGINE_LORA_NATIVE

    @property
    def identity_v2(self) -> bool:
        return int(self.identity_version) == C.TINYCAP_IDENTITY_VERSION_2

    @property
    def sampling_optional(self) -> Tuple[str, ...]:
        """The OPTIONAL sampling terms this expectation's row sets (``min_p`` /
        ``presence_penalty`` / ``repetition_penalty``, in contract order): the
        driver hashes them at the top of the tinycap block whenever the row
        carries them (``contracts.sampling_identity``), so the exact-keys
        derivation must name them — a ``vendor_preset`` qwen row sets all three;
        no ``card`` / ``greedy`` row sets any, so every existing shape is empty."""
        return tuple(f for f in C.SAMPLING_OPTIONAL_IDENTITY_FIELDS if f in self.sampling)

    @property
    def ladder(self) -> bool:
        return self.cap_overrides_by_task is not None or self.item_selection_ids is not None

    @property
    def item_selection(self) -> Optional[Dict[str, Dict[str, object]]]:
        return (C.item_selection_identity(self.item_selection_ids)
                if self.item_selection_ids is not None else None)

    @property
    def files_bigcodebench_200(self) -> bool:
        return C.files_bigcodebench_200(self.thinking_by_task)

    @property
    def files_bfcl_200(self) -> bool:
        return C.files_bfcl_200(self.thinking_by_task)

    @property
    def files_bigcodebench_full(self) -> bool:
        return C.files_bigcodebench_full(self.thinking_by_task)

    @property
    def files_bfcl_full(self) -> bool:
        return C.files_bfcl_full(self.thinking_by_task)

    @property
    def protocol_sampling(self) -> bool:
        """Whether this configuration decodes
        under ``protocol`` — the ONE predicate behind the hashed
        ``sampling_by_task`` key, the served block's ``sampling_clamp_override``
        member and the manifest block's ``by_task`` (all present iff)."""
        return self.sampling_mode == C.SAMPLING_PROTOCOL

    @property
    def files_math500(self) -> bool:
        """Whether this configuration files MATH-500 — ``contracts.files_math500``
        over the tasks the thinking map names, the SAME predicate the driver
        stamps by, so the two agree on whether ``math500_max_tokens`` is hashed."""
        return C.files_math500(self.thinking_by_task)

    @property
    def declared(self) -> bool:
        """The standup this expectation belongs to carries the DECLARED cell
        spelling (out of support, the whole ON arm, a lens cell) — the same
        predicate :func:`standup_declared` applies to a planned configuration,
        so the attestation-map key ``untrusted_store_reason`` looks up is the
        one the standup was told."""
        return C.is_declared_configuration(self.cell, arm=self.mode,
                                           out_of_support=self.out_of_support_thinking)

    def optional_identity(self) -> Dict[str, object]:
        """The OPTIONAL hashed identity keys this expectation carries, keyed
        exactly as the driver stamps them: the keys
        ``contracts.tinycap_identity_fields(out_of_support_thinking=...)``
        returns BEYOND ``TINYCAP_IDENTITY_FIELDS``, each with this
        expectation's value — derived from that ONE field-set, never a list
        typed here, so the launcher's expectation and the driver's exact-keys
        assertion widen together (the two further keys join the derivation in
        the change that teaches the driver to stamp them; the MATH-500
        first-pass cap joins it on a configuration that files
        ``inspect/math``). An optional key the derivation names that this
        expectation cannot value refuses (:class:`IdentityUnderivable`), never
        a silent gap. Empty on a non-MATH in-support expectation, byte for
        byte."""
        values = {C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING: True,
                  C.IDENTITY_KEY_MAX_TOKENS_BY_TASK: dict(sorted(self.max_tokens_by_task.items())),
                  C.IDENTITY_KEY_SERVE_OUT_OF_SUPPORT: self.serve_out_of_support,
                  C.IDENTITY_KEY_MATH500_MAX_TOKENS: self.math500_max_tokens,
                  # bcb-bfcl-200: the pinned legs' item sets + the sandbox facts,
                  # valued only when the derivation names them (the leg is filed)
                  C.IDENTITY_KEY_BCB_ITEM_SET: (dict(self.bcb_item_set)
                                                if self.bcb_item_set is not None else None),
                  C.IDENTITY_KEY_BFCL_ITEM_SET: (dict(self.bfcl_item_set)
                                                 if self.bfcl_item_set is not None else None),
                  C.IDENTITY_KEY_SANDBOX: (dict(self.bcb_sandbox)
                                           if self.bcb_sandbox is not None else None),
                  # capeval-full-tasks: the full legs' item sets, valued iff the leg is filed
                  C.IDENTITY_KEY_BCB_FULL_ITEM_SET: (dict(self.bcb_full_item_set)
                                                     if self.bcb_full_item_set is not None else None),
                  C.IDENTITY_KEY_BFCL_FULL_ITEM_SET: (dict(self.bfcl_full_item_set)
                                                      if self.bfcl_full_item_set is not None else None),
                  # bcb-bfcl-200 §S2b: the ladder tuple, valued only on a ladder rung
                  C.IDENTITY_KEY_CAP_OVERRIDES: (dict(sorted(self.cap_overrides_by_task.items()))
                                                 if self.cap_overrides_by_task is not None else None),
                  C.IDENTITY_KEY_ITEM_SELECTION: self.item_selection,
                  # IFEval canonical battery: the version-2 keys — the version
                  # itself and, on a rung, the subset binding — and the optional sampling
                  # terms the row sets (hashed at the top of the block by the driver)
                  C.IDENTITY_KEY_IDENTITY_VERSION: int(self.identity_version),
                  C.IDENTITY_KEY_CAP_RUNG: (dict(self.cap_rung) if self.cap_rung is not None else None),
                  **{f: self.sampling[f] for f in self.sampling_optional},
                  # bcb-bfcl-200-widen §S2: the per-task EXECUTED map, valued iff protocol
                  # (it rides inside the derived sampling block, `sampling_identity_for_mode`)
                  C.IDENTITY_KEY_SAMPLING_BY_TASK: (dict(self.sampling.get(C.IDENTITY_KEY_SAMPLING_BY_TASK) or {})
                                                    if self.protocol_sampling else None)}
        if self.identity_v2 and not self.max_tokens_by_task:
            raise IdentityUnderivable(
                "an identity-version-2 expectation hashes the EXECUTED per-task cap map (max_tokens_by_task) "
                "over every Inspect task of the run, and this one derived none — expected_identity values it "
                "from the planner's ifeval_cap; a store cannot be held to an empty map")
        fields = C.tinycap_identity_fields(out_of_support_thinking=self.out_of_support_thinking,
                                           off_cap_override=self.off_cap_override,
                                           files_math500=self.files_math500,
                                           files_bigcodebench_200=self.files_bigcodebench_200,
                                           files_bfcl_200=self.files_bfcl_200,
                                           # capeval-full-tasks: the full siblings' keys, iff filed
                                           files_bigcodebench_full=self.files_bigcodebench_full,
                                           files_bfcl_full=self.files_bfcl_full,
                                           ladder=self.ladder,
                                           # ifeval-canonical-battery: the same four inputs the
                                           # driver passes its own exact-keys assertion
                                           sampling_optional=self.sampling_optional,
                                           identity_version=self.identity_version,
                                           max_tokens_by_task=self.identity_v2,
                                           cap_rung=self.cap_rung is not None,
                                           # bcb-bfcl-200-widen §S2: the per-task map, iff protocol
                                           protocol_sampling=self.protocol_sampling)
        extra = [f for f in fields if f not in C.TINYCAP_IDENTITY_FIELDS]
        unknown = [f for f in extra if f not in values]
        if unknown:
            raise IdentityUnderivable(
                f"contracts.tinycap_identity_fields names optional identity key(s) {unknown}, "
                "which this launcher cannot value from the run's inputs — add the derivation to "
                "ExpectedIdentity before any store is trusted")
        # bcb-bfcl-200: a leg the derivation names must have been VALUED (the pin
        # read, the sandbox facts derived) — a None here is a wiring gap, never a
        # value the store could be held to
        unvalued = [f for f in extra if f in (*C.TINYCAP_IDENTITY_BCB_FIELDS, *C.TINYCAP_IDENTITY_BFCL200_FIELDS,
                                              *C.TINYCAP_IDENTITY_LADDER_FIELDS,
                                              *C.TINYCAP_IDENTITY_PROTOCOL_FIELDS, C.IDENTITY_KEY_CAP_RUNG)
                    and values[f] is None]
        if unvalued:
            raise IdentityUnderivable(
                f"this configuration files a pinned leg whose identity {unvalued} was not derived — "
                "expected_identity reads the pin from the staged tree; a store cannot be held to None")
        return {f: values[f] for f in extra}

    def as_dict(self) -> Dict[str, object]:
        return {"cell": self.cell, "mode": self.mode, C.GEOMETRY_PASS_FIELD: self.pass_no,
                "served": dict(self.served), "limits": dict(self.limits),
                "samples": self.samples, "client_lock_sha256": self.client_lock_sha256,
                "tree_sha": self.tree_sha,
                "thinking_by_task": dict(sorted(self.thinking_by_task.items())),
                "sampling": dict(self.sampling), "sampling_mode": self.sampling_mode,
                C.IDENTITY_KEY_OR_BENCH_ITEM_SET: (dict(self.or_bench_item_set)
                                                   if self.or_bench_item_set is not None
                                                   else None),
                **self.optional_identity()}


def expected_identity(cfg: Mapping, geom, *, pass_no: int, controls: Sequence[str],
                      samples: int, limit: int = 0, inspect_limit: int = 0,
                      tree: Optional[str | Path] = None,
                      tree_sha: Optional[str] = None,
                      reduction_mode: Optional[str] = None,
                      sampling_mode: str = C.SAMPLING_DEFAULT,
                      serving_path: str = SERVING_PATH_LIBRARY_DEFAULT,
                      concurrency: Optional[int] = None, concurrency_k: int = 1) -> ExpectedIdentity:
    """The identity the driver WILL hash for this configuration, derived from
    the resolved geometry (window and S — the driver's ``--concurrency`` IS
    the served S, ``_driver_cmd``), the standup argv the launcher composes
    (parser under thinking-ON, ``--tool-calls`` iff BFCL is REQUESTED, the
    agent-loop entry on unless opted out — PW18), the pass, the width and the
    limits. Every ``SERVED_IDENTITY_FIELDS`` name must have a derivation
    (:class:`IdentityUnderivable` otherwise). Plus the producing tree (E14 B):
    ``tree_sha`` when the caller already resolved it (``resolve_staged_tree``),
    else the stamp of ``tree``.

    The lens ``reduction_mode`` (E29 / PW18b) is the launcher's ``--reduction-mode``
    argument — ONE canonical value, written into the standup environment so the
    server serves what the launcher expects — or, when not given, what the
    serving parser makes of THIS process's environment
    (``reduction_mode_expected``). It is an expectation: the standup's
    attestation is compared with it the moment ``endpoint.json`` appears and a
    disagreement refuses before generation (``_run_configuration``).

    The sampling block (U8 / PW-sampling) is derived exactly as the driver
    derives it: the model's frozen row (``contracts.sampling_for(row.model_key,
    sampling_mode)`` — the driver looks the key up from the config's HF id,
    which for every registry row IS ``model_key``, pinned by test) and the
    per-task k over the tasks the configuration files (the thinking map's
    keys), with ``samples`` as MATH-500's explicit k. The driver's default
    mode is the launcher's (``SAMPLING_DEFAULT``); the launcher composes no
    ``--sampling`` argv, so a rowless model refuses HERE, at plan time.

    Under ``serving_path == lora_native`` the served
    block gains :data:`SERVED_ENGINE_FIELD` = ``lora_native`` and records ``reduction_mode`` as
    :data:`REDUCTION_MODE_NOT_APPLICABLE` (the lens ``reduction_mode`` argument is a planning input
    the authorised tuples name; the native engine attests no lens mode), through
    ``served_identity_fields(protocol_sampling, native=True)`` — the same key set the driver hashes,
    so a native store never keys with, or resumes onto, a lens one. The LoRA kernel's int32 index
    ceiling step is PRE-COMPUTED here (:func:`expected_geometry_for`: gemma 121 -> 107 and nemotron
    161 -> 86 at L 4864), so the expected S — and the driver's ``--concurrency`` — is the S the
    standup will serve BEFORE the standup; the KV step stays post-standup tolerated as today.
    Under ``lens`` every derivation is byte-identical."""
    tool_calls = needs_tool_calls(controls)
    oos = bool(cfg.get(C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING))
    offcap = bool(cfg.get(OFFCAP_MARKER_KEY))
    C.check_sampling_arg(sampling_mode)
    protocol = sampling_mode == C.SAMPLING_PROTOCOL
    extra = standup_extra_for(row_of(cfg), tool_calls=tool_calls, thinking=cfg["mode"],
                              controls=controls, allow_out_of_support=oos, cell=cfg["cell"],
                              sampling_mode=sampling_mode)
    native = is_native_path(check_serving_path_arg(serving_path))
    if native:
        mode = REDUCTION_MODE_NOT_APPLICABLE
        geom, _kernel_step = expected_geometry_for(geom, native=True, name=str(cfg.get("name", cfg["cell"])))
    else:
        mode = reduction_mode if reduction_mode is not None else reduction_mode_expected()
        if mode not in C.REDUCTION_MODES:
            raise ValueError(f"reduction_mode {mode!r} is not one of {list(C.REDUCTION_MODES)}")
    derive = {
        "reasoning_parser": lambda: reasoning_parser_of(extra),
        "tool_calls": lambda: tool_calls,
        "max_model_len": lambda: int(geom.max_model_len),
        "max_num_seqs": lambda: int(geom.max_num_seqs),
        # tinycap-shared-standup §1.1.1: the driver's client width — the served S (today's derivation,
        # None at K = 1) or the width a row engine drives at (landing 2, §2.1: S // K through
        # :func:`client_width`; an explicit ``concurrency`` wins); hashed store identity
        "concurrency": lambda: (int(concurrency) if concurrency is not None
                                else client_width(int(geom.max_num_seqs), concurrency_k)),
        # PW18: the proxy's agent-loop entry the argv composes (on unless the
        # opt-out is stated); PW18b: the reduction mode the launcher asks the
        # standup for (see above)
        C.AGENT_LOOP_ENTRY_KEY: lambda: agent_loop_entry_of(extra),
        C.REDUCTION_MODE_FIELD: lambda: mode,
        # bcb-bfcl-200-widen: the clamp override the argv composes, hashed
        # as a served-block member PRESENT IFF protocol (served_identity_fields)
        C.ENDPOINT_KEY_SAMPLING_CLAMP_OVERRIDE: lambda: sampling_clamp_override_of(extra),
        # native-serving-default (§1.7): the engine, hashed PRESENT IFF native (served_identity_fields)
        SERVED_ENGINE_FIELD: lambda: ENGINE_LORA_NATIVE,
    }
    served_fields = _served_identity_fields(protocol_sampling=protocol, native=native)
    underivable = [f for f in served_fields if f not in derive]
    if underivable:
        raise IdentityUnderivable(
            f"contracts.served_identity_fields names {underivable}, which this launcher cannot "
            "derive from the run's inputs — add the derivation to expected_identity before "
            "any store is trusted (a narrower comparison would let a changed served "
            "parameter resume onto an old store)")
    served = {f: derive[f]() for f in served_fields}
    if protocol and served[C.ENDPOINT_KEY_SAMPLING_CLAMP_OVERRIDE] is None:
        raise IdentityUnderivable(
            f"{cfg.get('name', cfg['cell'])}: a {C.SAMPLING_PROTOCOL} configuration's standup argv composes no "
            f"{C.FLAG_SAMPLING_CLAMP_OVERRIDE} — the served identity cannot be derived (D13)")
    limits = {k: int(v) for k, v in (("limit", limit), ("inspect_limit", inspect_limit))
              if v and k in C.LIMIT_KINDS}
    # The family policy applies to the identity-version-2 (IFEval) configurations alone
    by_task = thinking_by_task_of(cfg["mode"], controls,
                                  family=(row_of(cfg).family if is_ifeval_configuration(cfg) else None))
    # A ladder configuration — its certified rung in
    # ``ladder_rung`` — hashes the rung-2 tuple (the caps per fired task, the
    # selected PINNED ids) and is LIMITED by exactly {"item_selection": 1}; a
    # smoke cap beside it is refused (a rung is not a smoke), and the tuple must
    # name exactly the row tasks this configuration files
    ladder = bool(cfg.get("ladder_rung"))
    caps_by_task = item_ids = None
    if ladder:
        if limits:
            raise ValueError(
                f"{cfg.get('name', cfg['cell'])}: a ladder rung takes no --limit / --inspect-limit "
                f"({limits}); its only limit is {dict(C.LADDER_LIMITS)}")
        limits = dict(C.LADDER_LIMITS)
        caps_by_task = {str(t): int(v) for t, v in dict(cfg["cap_overrides_by_task"]).items()}
        item_ids = {str(t): [str(i) for i in ids] for t, ids in dict(cfg["item_selection"]).items()}
        C.item_selection_identity(item_ids)                       # valued and well-formed, or refuse here
        if set(caps_by_task) != set(by_task) or set(item_ids) != set(by_task):
            raise ValueError(
                f"{cfg.get('name', cfg['cell'])}: the ladder tuple names {sorted(caps_by_task)} / "
                f"{sorted(item_ids)} but this configuration files {sorted(by_task)} — a ladder run "
                "serves the fired legs alone")
    # PW-sampling: the model's row under every table mode (a rowless model refuses
    # HERE, at plan time); under `protocol` the
    # per-task EXECUTED rows over the filed tasks (a task with no row refuses),
    # the three run-level scalars null — contracts.sampling_identity_for_mode is
    # the ONE derivation the driver's identity mirrors
    samples_by_task = C.run_samples_by_task(by_task, sampling_mode, math_samples=int(samples))
    try:
        sampling_block = C.sampling_identity_for_mode(sampling_mode, row_of(cfg).model_key, list(by_task),
                                                      samples_by_task)
    except C.ProtocolSamplingUnavailable as e:
        raise ValueError(f"{cfg.get('name', cfg['cell'])}: {e}") from None
    # fit-support transfer: the two further optional keys, PURE —
    # the raised cap from the tuple over the REQUESTED controls' ON tasks, the
    # declaration literal from the reviewed contract; nothing here reads a
    # server, so the resume decision keeps running before any standup
    # Off-cap: the comparator's cap map from the OFF caps the tuple
    # names (the driver's plan builder derives the same, held equal by test)
    caps = (offcap_caps_by_task(by_task, name=str(cfg.get("name", cfg["cell"]))) if offcap else
            oos_caps_by_task(by_task, out_of_support=True, name=str(cfg.get("name", cfg["cell"])))
            if oos else {})
    serve = (C.expected_serve_out_of_support(lens=C.is_lens_cell(cfg["cell"]), arm=cfg["mode"],
                                             out_of_support=True)
             if oos else None)
    # An IFEval configuration's driver stamps identity VERSION 2 —
    # `identity_version` and the EXECUTED cap map over every Inspect task of the
    # run (the IFEval atom alone: {inspect/ifeval: the setter's cap, else the OFF
    # table's 2,048} = the planner's `ifeval_cap`; the driver holds its
    # --max-tokens-by-task statement equal to the same resolution) and, on a rung,
    # `cap_rung` over the validated subset file the driver reads too (a volume
    # path: readable in the container, NOT on an operator-side dry run — refused by
    # name there, never degraded). The k map above already carries IFEval's
    # explicit --samples, and `sampling_mode` is the plan's (vendor_preset).
    # The contracts' reader dispatches on the file's `schema`, so the ladder
    # planner's `rung_subset/2` (DRAW pairs) is read here exactly as the driver
    # reads it and `cap_rung.subset_sha16` is the digest over the DRAWS
    # (`contracts.item_subset_sha16_v2`) — the v1-only validator raised
    # IdentityUnderivable on every IFEval promotion before this.
    ifeval = is_ifeval_configuration(cfg)
    identity_version = C.TINYCAP_IDENTITY_VERSION_2 if ifeval else C.TINYCAP_IDENTITY_VERSION_LEGACY
    cap_rung = None
    if ifeval:
        if set(by_task) != {C.IFEVAL_TASK}:
            raise IdentityUnderivable(
                f"{cfg.get('name', cfg['cell'])}: an IFEval configuration files {sorted(by_task)}; the launcher "
                f"derives the version-2 executed cap map for the {C.CONTROL_IFEVAL!r} atom alone — run it by itself")
        if cfg.get("ifeval_cap") is None:
            raise IdentityUnderivable(
                f"{cfg.get('name', cfg['cell'])}: an IFEval configuration carries no ifeval_cap — plan it through "
                "plan_configurations (the executed cap is hashed; a hand-built cfg cannot be held to None)")
        caps = {C.IFEVAL_TASK: int(cfg["ifeval_cap"])}
        if cfg.get("item_subset"):
            try:
                cap_rung = C.cap_rung_identity(C.read_item_subset(str(cfg["item_subset"])))
            except C.ItemSubsetError as e:
                raise IdentityUnderivable(
                    f"{cfg.get('name', cfg['cell'])}: the rung's item subset {str(cfg['item_subset'])!r} could not "
                    f"be read, so cap_rung — a hashed key of every rung store — cannot be derived: {e}") from None
    # MATH-500 one-pass: the first-pass cap MATH is generated at, PURE
    # (contracts.math500_max_tokens_for at MATH's own arm in the map) — hashed
    # by the driver only on a run that files inspect/math, so None elsewhere
    math_cap = (C.math500_max_tokens_for(by_task[C.inspect_task("math")], out_of_support=oos)
                if C.files_math500(by_task) else None)
    # The pinned legs' item-set identity from the PIN
    # on the tree this run serves (the staged tree in the container, the local
    # repo for a dry run — the same commit either way; a pin that does not
    # regenerate from its rule refuses HERE, before any GPU), plus the sandbox
    # facts on a BigCodeBench configuration
    pin_root = Path(tree) if tree else REPO_LOCAL
    bcb_set = C.item_set_identity(C.load_bcb_pin(pin_root)) if C.files_bigcodebench_200(by_task) else None
    bfcl_set = C.item_set_identity(C.load_bfcl_pin(pin_root)) if C.files_bfcl_200(by_task) else None
    # capeval-full-tasks: the full siblings' item sets from their own verified pins; the
    # sandbox facts ride on EITHER BigCodeBench leg (one verifier)
    bcb_full_set = (C.item_set_identity(C.load_bcb_full_pin(pin_root))
                    if C.files_bigcodebench_full(by_task) else None)
    bfcl_full_set = (C.item_set_identity(C.load_bfcl_full_pin(pin_root))
                     if C.files_bfcl_full(by_task) else None)
    sandbox = C.bcb_sandbox_identity() if C.files_any_bigcodebench(by_task) else None
    # The hashed MODE label the driver writes for an IFEval configuration is the FAMILY-resolved arm (a
    # llama row's `off` reads `not_available`) — the store-trust compare must expect the same
    mode_label = (C.effective_arm_for_family(cfg["mode"], row_of(cfg).family)
                  if is_ifeval_configuration(cfg) and cfg["mode"] in C.THINKING_MODES else cfg["mode"])
    return ExpectedIdentity(cell=cfg["cell"], mode=mode_label, pass_no=int(pass_no),
                            served=served, limits=limits, samples=int(samples),
                            client_lock_sha256=client_lock_sha256(tree),
                            tree_sha=tree_sha or tree_sha_of(tree),
                            thinking_by_task=by_task,
                            sampling=sampling_block,
                            sampling_mode=sampling_mode,
                            or_bench_item_set=C.run_or_bench_item_set(controls),
                            out_of_support_thinking=oos,
                            max_tokens_by_task=caps, serve_out_of_support=serve,
                            off_cap_override=offcap, math500_max_tokens=math_cap,
                            bcb_item_set=bcb_set, bfcl_item_set=bfcl_set, bcb_sandbox=sandbox,
                            bcb_full_item_set=bcb_full_set, bfcl_full_item_set=bfcl_full_set,
                            cap_overrides_by_task=caps_by_task, item_selection_ids=item_ids,
                            identity_version=identity_version, cap_rung=cap_rung)


def _or_bench_label(spec) -> str:
    """A one-line name for an OR-Bench item-set spec, for a refusal message —
    the 200-element position list is not something to print at a reader."""
    if spec is None:
        return "no OR-Bench rows"
    if not isinstance(spec, Mapping):
        return f"a malformed spec ({type(spec).__name__})"
    seed = spec.get("seed")
    return (f"item_set={spec.get('item_set')!r} n={spec.get('n')} of={spec.get('of')}"
            + (f" seed={seed}" if seed is not None else ""))


def _exact_keys(block, fields: Sequence[str], what: str) -> Optional[str]:
    if not isinstance(block, Mapping):
        return f"{what} is not a mapping ({type(block).__name__})"
    if set(block) != set(fields):
        missing = sorted(set(fields) - set(block))
        extra = sorted(set(block) - set(fields))
        return (f"{what} carries {sorted(block)}, not the contract's {sorted(fields)}"
                + (f" (missing {missing})" if missing else "")
                + (f" (unknown {extra})" if extra else ""))
    return None


def _keys_within(block, required: Sequence[str], optional: Sequence[str], what: str) -> Optional[str]:
    """:func:`_exact_keys` for a block whose contract is "every required key, plus any subset of the optional keys"
    — the sampling block: ``contracts.sampling_block_fields(row)`` adds each optional identity term the row SETS
    (Qwen's vendor_preset row: min_p / presence_penalty / repetition_penalty), so the key set is row-dependent."""
    if not isinstance(block, Mapping):
        return f"{what} is not a mapping ({type(block).__name__})"
    missing = sorted(set(required) - set(block))
    extra = sorted(set(block) - set(required) - set(optional))
    if missing or extra:
        return (f"{what} carries {sorted(block)}, not the contract's {sorted(required)} (+ optional {sorted(optional)})"
                + (f" (missing {missing})" if missing else "")
                + (f" (unknown {extra})" if extra else ""))
    return None


#: The note ``untrusted_store_reason`` appends when an OPTIONAL hashed identity
#: key (``max_tokens_by_task``, ``serve_out_of_support``) disagrees with this
#: run's — WHY such a store is another measurement rather than a resumable one.
_OPTIONAL_KEY_NOTES: Mapping[str, str] = {
    C.IDENTITY_KEY_MAX_TOKENS_BY_TASK:
        " — a store filled at another completion cap is another measurement (D3.3)",
    C.IDENTITY_KEY_BCB_ITEM_SET:
        " — a BigCodeBench store filled under another pin (seed / n / of / ids) is another "
        "instrument (bcb-bfcl-200)",
    C.IDENTITY_KEY_BFCL_ITEM_SET:
        " — a BFCL-200 store filled under another pin is another instrument (bcb-bfcl-200)",
    C.IDENTITY_KEY_BCB_FULL_ITEM_SET:
        " — a FULL BigCodeBench store filled under another pin (n / of / ids) is another instrument "
        "(capeval-full-tasks)",
    C.IDENTITY_KEY_BFCL_FULL_ITEM_SET:
        " — a FULL BFCL store filled under another pin is another instrument (capeval-full-tasks)",
    C.IDENTITY_KEY_SANDBOX:
        " — a store whose verdicts ran in another sandbox image or under another verifier "
        "timeout is another verifier (bcb-bfcl-200)",
    C.IDENTITY_KEY_MATH500_MAX_TOKENS:
        " — a MATH-500 store generated at another first-pass cap is another instrument's "
        "evidence, never resumed (D33)",
    C.IDENTITY_KEY_CAP_OVERRIDES:
        " — a ladder store generated at another rung-2 cap is another rung (bcb-bfcl-200 §S2b)",
    C.IDENTITY_KEY_ITEM_SELECTION:
        " — a ladder store generated on another item selection (n / ids digest) was not this "
        "selection's rerun (bcb-bfcl-200 §S2b)",
    C.IDENTITY_KEY_SERVE_OUT_OF_SUPPORT:
        " — the CONTRACT-derived declaration literal (contracts."
        "expected_serve_out_of_support), never the attestation",
}


def untrusted_store_reason(cell_dir: Path, *, expected: ExpectedIdentity,
                           kv_shrink_tolerated: bool = False) -> Optional[str]:
    """Why a ``<out_dir>/cells/<key>/`` store may NOT be resumed from for THIS
    run — ``None`` when it may. The store's manifest must name
    ``expected.cell``; its key must carry the manifest's
    ``intervention_hash`` / ``harness_config_hash`` prefixes; the recorded
    ``harness_config_hash`` must BE the hash of the recorded
    ``resolved_config`` and the ``tinycap`` block must mirror the hashed
    one (a hand-edited or copied store is caught); the identity must carry
    EXACTLY ``TINYCAP_IDENTITY_FIELDS`` (a legacy manifest lacking a field
    is refused, never read around) — plus ``math500_max_tokens`` when and
    only when the STORE's own hashed thinking map files ``inspect/math``
    (a MATH store from before the cap was hashed is refused; the cap is
    compared only where this run files MATH too, so a standard store still
    lends its other controls to an in-depth run); ``served`` must carry EXACTLY
    ``SERVED_IDENTITY_FIELDS`` and equal the expected values per field;
    ``geometry.pass`` must be this pass; ``thinking.mode`` / ``samples`` /
    an EMPTY ``limits`` / the hashed ``tinycap.pass`` (this pass) / the
    frameworks block (client-lock sha, pinned versions) / the ``producer``
    block (a 40-hex ``tree_sha`` EQUAL to the staged tree's and the served
    driver's name) must all check out; and the manifest's own ``geometry`` /
    ``concurrency`` / ``thinking`` / ``route`` blocks must agree with the
    hashed identity. Structural failures return at once; field disagreements
    are ALL named, ``;``-joined.

    ``kv_shrink_tolerated`` (the PRE-standup call only): a store whose
    manifest geometry carries a ``kv_shrink`` record shrinking this expectation's
    configured S by the KV-derived rule is held to the identity at ITS served S
    (:func:`kv_shrink_adjusted_expectation`); a record that does not hold is a
    refusal. After the standup the expectation IS the served S and the default
    (no tolerance) holds every store to it exactly."""
    failed = sampling_validation_failure(Path(cell_dir).parent.parent)
    if failed is not None:
        # bcb-bfcl-200-widen code review: the store root carries a DURABLE sampling-
        # validation failure — its outcomes were generated behind a re-clamped server and are
        # never protocol evidence, whatever their markers say
        return (f"the store root carries {C.SAMPLING_VALIDATION_FAILED_FILENAME} ({failed.get('status')}: "
                f"{str(failed.get('error'))[:160]}) — nothing under it is resumable; relaunch into a NEW --out-suffix")
    if not (cell_dir / "manifest.json").is_file():
        return "no manifest.json"
    manifest, err = _read_json_object(cell_dir / "manifest.json")
    if manifest is None:
        return f"manifest.json {err}"
    if manifest.get("cell_id") != expected.cell:
        return f"manifest cell_id {manifest.get('cell_id')!r} != {expected.cell!r}"
    if kv_shrink_tolerated:
        expected, why = kv_shrink_adjusted_expectation(manifest, expected)
        if why:
            return why
    prefixes = cell_key_hash_prefixes(cell_dir.name)
    ihash, chash = manifest.get("intervention_hash"), manifest.get("harness_config_hash")
    if (prefixes is None or not isinstance(ihash, str) or not isinstance(chash, str)
            or (ihash[:8], chash[:8]) != prefixes):
        return ("the directory key does not carry the manifest's intervention_hash / "
                "harness_config_hash prefixes (a copied or renamed store)")
    resolved = manifest.get("resolved_config")
    if not isinstance(resolved, Mapping) or not resolved:
        return "manifest has no resolved_config (the hashed identity is unverifiable)"
    try:
        rehash = cs.harness_config_hash(resolved)
    except Exception as e:  # noqa: BLE001 — a config that cannot be hashed is a refusal, named
        return f"resolved_config cannot be re-hashed ({type(e).__name__}: {str(e)[:120]})"
    if rehash != chash:
        return (f"harness_config_hash {chash} is not the hash of the recorded resolved_config "
                f"({rehash}) — a hand-edited or torn manifest")
    # P1-1: the canonical provenance reader at THIS boundary too — a store
    # whose template-check class cannot be read, or whose fit witness /
    # fit_provenance block disagree with it, is never trusted as complete
    # (a v3 store with the class missing was refused by the reader and then
    # accepted here). sweep is torch-free; a historical store (class
    # "unrecorded") is required to carry neither block.
    from sisteer.eval import sweep as _sweep
    problems = _sweep.store_provenance_problems(manifest)
    if problems:
        return "provenance: " + "; ".join(problems) + " (P1-1)"
    tinycap = manifest.get(C.MANIFEST_KEY_TINYCAP)
    if not isinstance(tinycap, Mapping):
        return "manifest has no tinycap identity block (not a tinycap store)"
    if resolved.get(C.MANIFEST_KEY_TINYCAP) != tinycap:
        return "manifest.tinycap does not mirror resolved_config.tinycap (the hashed identity)"
    # WHICH key set a store must carry follows the STORE's own tasks — one
    # that files inspect/math must record its first-pass cap, one that does not
    # must not — read off its hashed thinking map (a map that is not a mapping
    # of row tasks fails the exact-keys rule, or is named here). The support
    # state stays THIS run's: a cross-support resume is refused either way.
    store_by_task = tinycap.get(C.IDENTITY_KEY_THINKING_BY_TASK)

    def store_files(pred) -> bool:
        return bool(isinstance(store_by_task, Mapping) and pred(store_by_task))
    try:
        store_files_math = store_files(C.files_math500)
        # bcb-bfcl-200: the two pinned legs' keys follow the STORE's tasks the
        # same way (a store filing bigcodebench_200 must record its item set
        # and sandbox facts; one that does not must not)
        store_files_bcb = store_files(C.files_bigcodebench_200)
        store_files_bfcl200 = store_files(C.files_bfcl_200)
        # capeval-full-tasks: the full siblings' keys follow the STORE's tasks the same way
        store_files_bcb_full = store_files(C.files_bigcodebench_full)
        store_files_bfcl_full = store_files(C.files_bfcl_full)
    except ValueError as e:
        return f"tinycap.{C.IDENTITY_KEY_THINKING_BY_TASK} is not a map over row tasks ({e})"
    # bcb-bfcl-200 §S2b: the ladder tuple follows the EXPECTATION (like the
    # out-of-support marker): a ladder run reads only ladder stores, a battery
    # run never reads one — the two can never resume onto each other
    # IFEval canonical battery: the identity VERSION, the rung binding
    # and the row's optional sampling terms follow the EXPECTATION the same way —
    # the version key's presence is hashed, so a version-2 run reads version-2
    # stores only, a rung reads rung stores only, and a legacy run never reads either
    fields = C.tinycap_identity_fields(out_of_support_thinking=expected.out_of_support_thinking,
                                       off_cap_override=expected.off_cap_override,
                                       files_math500=store_files_math,
                                       files_bigcodebench_200=store_files_bcb,
                                       files_bfcl_200=store_files_bfcl200,
                                       files_bigcodebench_full=store_files_bcb_full,
                                       files_bfcl_full=store_files_bfcl_full,
                                       ladder=expected.ladder,
                                       sampling_optional=expected.sampling_optional,
                                       identity_version=expected.identity_version,
                                       max_tokens_by_task=expected.identity_v2,
                                       cap_rung=expected.cap_rung is not None,
                                       # bcb-bfcl-200-widen §S2: the per-task map, iff THIS run is protocol
                                       protocol_sampling=expected.protocol_sampling)
    bad = _exact_keys(tinycap, fields, "tinycap identity")
    if bad:
        if C.IDENTITY_KEY_IDENTITY_VERSION in bad or C.IDENTITY_KEY_CAP_RUNG in bad:
            return (bad + f" — {C.IDENTITY_KEY_IDENTITY_VERSION} / {C.IDENTITY_KEY_CAP_RUNG} are stamped by exactly "
                    f"the identity-version-2 runs ({C.FLAG_TINYCAP_IDENTITY_VERSION} 2: the IFEval wave; a rung "
                    f"under {C.FLAG_ITEM_SUBSET}), so a version-2 store and a legacy one — or a rung store and "
                    "its source — never resume onto each other (ifeval-canonical-battery plan §8.1)")
        if any(k in bad for k in C.TINYCAP_IDENTITY_PROTOCOL_FIELDS):
            return (bad + f" — {C.IDENTITY_KEY_SAMPLING_BY_TASK} is stamped by exactly the runs under "
                    f"{C.FLAG_SAMPLING} {C.SAMPLING_PROTOCOL} (the per-task executed rows), so a protocol store "
                    "and a card / greedy store can never resume onto each other (bcb-bfcl-200-widen §S2)")
        if any(k in bad for k in C.TINYCAP_IDENTITY_LADDER_FIELDS):
            return (bad + " — the truncation ladder's tuple is stamped by exactly the rung-2 runs "
                    f"({C.FLAG_CAP_OVERRIDE} / {C.FLAG_ITEM_SELECTION}), so a ladder store and a battery "
                    "store can never resume onto each other (bcb-bfcl-200 §S2b)")
        # PW-oos: the two directions are named, because "unknown
        # out_of_support_thinking" and "missing out_of_support_thinking" are
        # the cross-support resume this optional field exists to refuse — not
        # a stale-manifest problem an operator should go hunting for
        if C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING in bad:
            return (bad + f" — {C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING} is stamped only by a run "
                    f"launched with {C.FLAG_ALLOW_OOS_THINKING}, so an out-of-support store and "
                    "an in-support one can never resume onto each other (U10 item 5)")
        if C.IDENTITY_KEY_MAX_TOKENS_BY_TASK in bad:
            # Off-cap: the cap key alone is the comparator's shape —
            # present under --allow-off-cap-override, absent in support
            return (bad + f" — {C.IDENTITY_KEY_MAX_TOKENS_BY_TASK} is stamped only by a run under a "
                    f"named override ({C.FLAG_ALLOW_OFF_CAP_OVERRIDE} alone, or "
                    f"{C.FLAG_ALLOW_OOS_THINKING} with its two sibling keys): a store filled at "
                    "another completion cap is another measurement (D3.3) — the comparator's "
                    "OFF/8192 store and the campaign's OFF/512 store never resume onto each other")
        # a MATH-500 store from before the first-pass cap was hashed lacks
        # the key — it may have been generated at another cap, and is never
        # resumed; a non-MATH store carrying it was not written by this driver
        if C.IDENTITY_KEY_MATH500_MAX_TOKENS in bad:
            return (bad + f" — {C.IDENTITY_KEY_MATH500_MAX_TOKENS} is stamped by exactly the runs "
                    "that file inspect/math, recording the first-pass cap they generated at, so a "
                    "MATH-500 store from before the cap was hashed (possibly generated at "
                    "another cap) is never resumed, and a store carrying it without filing "
                    "inspect/math was not written by this driver (D33)")
        if any(k in bad for k in (*C.TINYCAP_IDENTITY_BCB_FULL_FIELDS, *C.TINYCAP_IDENTITY_BFCL_FULL_FIELDS)):
            return (bad + " — the FULL legs' item-set keys are stamped by exactly the runs that file "
                    "inspect/bigcodebench_full / inspect/bfcl_full (capeval-full-tasks), so a store filing "
                    "them without the keys, or carrying them without filing, was not written by this driver")
        if any(k in bad for k in (*C.TINYCAP_IDENTITY_BCB_FIELDS, *C.TINYCAP_IDENTITY_BFCL200_FIELDS)):
            return (bad + " — the pinned legs' item-set / sandbox keys are stamped by exactly the runs "
                    "that file inspect/bigcodebench_200 / inspect/bfcl_200 (bcb-bfcl-200), so a store "
                    "filing them without the keys, or carrying them without filing, was not written by "
                    "this driver")
        return bad + " — a manifest from before the current identity discipline is never trusted"
    reasons: List[str] = []
    # fit-support transfer: the OPTIONAL hashed keys, compared BY NAME —
    # the key SET is the same derivation _exact_keys just held the block to, so
    # every key read here is present. The marker must be the positive True; the
    # raised cap and the declaration literal must be this run's (an 8192 store
    # never resumes onto a 2048 one; a store served under another
    # declaration never continues here)
    for f, want in expected.optional_identity().items():
        if f not in fields:
            # this run files MATH and the store does not — its first-pass cap
            # is not a fact about this store, which may still lend the controls it
            # DID request (math500 then reads "never requested", not "untrusted")
            continue
        have = tinycap[f]
        if f == C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING:
            if have is not True:
                reasons.append(f"tinycap.{f} {have!r} is not the positive marker True")
        elif have != want:
            reasons.append(
                f"tinycap.{f}: the store records {have!r} but this run hashes {want!r}"
                + _OPTIONAL_KEY_NOTES.get(f, ""))
    thinking = tinycap["thinking"]
    got_mode = thinking.get("mode") if isinstance(thinking, Mapping) else None
    if got_mode != expected.mode:
        reasons.append(f"tinycap.thinking.mode {got_mode!r} != {expected.mode!r}")
    limits = tinycap["limits"]
    if not isinstance(limits, Mapping):
        reasons.append(f"tinycap.limits {limits!r} is not a mapping")
    elif dict(limits) != dict(expected.limits):
        reasons.append(f"tinycap.limits {dict(limits)} != this run's {dict(expected.limits)}")
    elif limits and not expected.ladder:
        reasons.append(f"a LIMITED store (limits {dict(limits)}) never completes a control")
    if tinycap["samples"] != expected.samples:
        reasons.append(f"tinycap.samples {tinycap['samples']!r} != {expected.samples}")
    # PW-sampling (U8): the draw is identity — every one of the five fields
    # must be this run's (a greedy store under a card run, another model's
    # card row, another per-task k, another seed rule: all refused by name)
    for f in C.SAMPLING_IDENTITY_FIELDS:
        if tinycap[f] != expected.sampling[f]:
            reasons.append(f"tinycap.{f}: the store records {tinycap[f]!r} but this run draws "
                           f"{expected.sampling[f]!r}")
    # U10 item 4 / PW-battery: WHICH OR-Bench items — 200 frozen positions or
    # the whole pinned corpus — is the difference between two refusal rates, so
    # a store filed under one never continues under the other
    if tinycap[C.IDENTITY_KEY_OR_BENCH_ITEM_SET] != expected.or_bench_item_set:
        got = tinycap[C.IDENTITY_KEY_OR_BENCH_ITEM_SET]
        reasons.append(
            f"tinycap.{C.IDENTITY_KEY_OR_BENCH_ITEM_SET}: the store records "
            f"{_or_bench_label(got)} but this run files {_or_bench_label(expected.or_bench_item_set)}")
    if tinycap[C.GEOMETRY_PASS_FIELD] != expected.pass_no:
        # PW8 (E16 A2): the HASHED pass — the top-level geometry.pass below
        # is a cross-check on it, not identity
        reasons.append(f"tinycap.{C.GEOMETRY_PASS_FIELD} {tinycap[C.GEOMETRY_PASS_FIELD]!r} != "
                       f"this run's pass {expected.pass_no}")
    versions = tinycap["versions"]
    if not isinstance(versions, Mapping) or versions.get("tinycap") != C.TINYCAP_VERSION:
        reasons.append(f"tinycap.versions {versions!r} does not name {C.TINYCAP_VERSION!r}")
    tasks = tinycap["tasks"]
    if (not isinstance(tasks, list) or not tasks
            or any(a not in C.CONTROL_ATOMS for a in tasks)):
        reasons.append(f"tinycap.tasks {tasks!r} is not a non-empty list of control atoms")
    served = tinycap["served"]
    # bcb-bfcl-200-widen: the served block's key set is mode-aware —
    # `sampling_clamp_override` PRESENT IFF protocol — so a protocol store never
    # resumes onto one served without the override (or the reverse)
    # native-serving-default (§1.7): ... and ENGINE-aware — `serving_engine` PRESENT IFF native, so a
    # native store never resumes onto a lens one or the reverse (refused BY NAME, never by a value)
    served_fields = (_served_identity_fields(protocol_sampling=expected.protocol_sampling, native=True)
                     if expected.native else
                     C.served_identity_fields(protocol_sampling=expected.protocol_sampling))
    bad = _exact_keys(served, served_fields, "tinycap.served")
    if bad:
        reasons.append(bad + (f" — {C.ENDPOINT_KEY_SAMPLING_CLAMP_OVERRIDE} is hashed by exactly the runs under "
                              f"{C.FLAG_SAMPLING} {C.SAMPLING_PROTOCOL} (a server whose vLLM clamp was lifted, D13)"
                              if C.ENDPOINT_KEY_SAMPLING_CLAMP_OVERRIDE in bad else "")
                       + (f" — {SERVED_ENGINE_FIELD} is hashed by exactly the runs under {SERVING_PATH_FLAG} "
                          f"{SERVING_PATH_LORA_NATIVE}: a native store and a lens store never resume onto each other "
                          f"(this run serves {expected.serving_engine!r}; native-serving-default §1.7)"
                          if SERVED_ENGINE_FIELD in bad else ""))
    else:
        for f in served_fields:
            if served[f] != expected.served[f]:
                reasons.append(f"served.{f}: the store records {served[f]!r} but this run serves "
                               f"{expected.served[f]!r}")
    frameworks = tinycap[C.MANIFEST_KEY_FRAMEWORKS]
    bad = _exact_keys(frameworks, C.FRAMEWORKS_BLOCK_FIELDS, "tinycap.frameworks")
    if bad:
        reasons.append(bad)
    else:
        if frameworks["client_lock_sha256"] != expected.client_lock_sha256:
            reasons.append(f"frameworks.client_lock_sha256 {frameworks['client_lock_sha256']!r} != "
                           f"the staged tree's {expected.client_lock_sha256!r}")
        for name, pin in C.FRAMEWORK_PINS.items():
            got = frameworks.get(name)
            if got is not None and got != pin:
                reasons.append(f"frameworks.{name} {got!r} != the pinned {pin!r}")
        if manifest.get(C.MANIFEST_KEY_FRAMEWORKS) != frameworks:
            reasons.append("manifest.frameworks does not mirror the hashed tinycap.frameworks")
    # the manifest's own blocks must agree with what it hashed
    geom_block = manifest.get(C.MANIFEST_KEY_GEOMETRY)
    if not isinstance(geom_block, Mapping):
        reasons.append("manifest has no geometry block (a store from before the geometry record)")
    else:
        if geom_block.get(C.GEOMETRY_PASS_FIELD) != expected.pass_no:
            reasons.append(f"geometry.{C.GEOMETRY_PASS_FIELD} {geom_block.get(C.GEOMETRY_PASS_FIELD)!r} "
                           f"!= this run's pass {expected.pass_no}")
        for k in ("max_model_len", "max_num_seqs"):
            if geom_block.get(k) != expected.served.get(k):
                reasons.append(f"geometry.{k} {geom_block.get(k)!r} != the served identity's "
                               f"{expected.served.get(k)!r}")
    if manifest.get(C.MANIFEST_KEY_CONCURRENCY) != expected.served.get("concurrency"):
        reasons.append(f"manifest.concurrency {manifest.get(C.MANIFEST_KEY_CONCURRENCY)!r} != "
                       f"{expected.served.get('concurrency')!r}")
    th = manifest.get(C.MANIFEST_KEY_THINKING)
    if not isinstance(th, Mapping) or th.get("reasoning_parser") != expected.served.get("reasoning_parser"):
        reasons.append(f"manifest.thinking.reasoning_parser "
                       f"{(th or {}).get('reasoning_parser') if isinstance(th, Mapping) else th!r} "
                       f"!= {expected.served.get('reasoning_parser')!r}")
    route = manifest.get(C.MANIFEST_KEY_ROUTE)
    if not isinstance(route, Mapping) or route.get("tool_calls") != expected.served.get("tool_calls"):
        reasons.append(f"manifest.route.tool_calls "
                       f"{route.get('tool_calls') if isinstance(route, Mapping) else route!r} "
                       f"!= {expected.served.get('tool_calls')!r}")
    # PW18: the route block also mirrors the agent-loop entry and the lens
    # reduction mode (a route block without the mode is legacy = per_row, E25)
    if isinstance(route, Mapping):
        if route.get(C.AGENT_LOOP_ENTRY_KEY) != expected.served.get(C.AGENT_LOOP_ENTRY_KEY):
            reasons.append(f"manifest.route.{C.AGENT_LOOP_ENTRY_KEY} "
                           f"{route.get(C.AGENT_LOOP_ENTRY_KEY)!r} != "
                           f"{expected.served.get(C.AGENT_LOOP_ENTRY_KEY)!r}")
        have_mode = route.get(C.REDUCTION_MODE_FIELD, C.REDUCTION_MODE_DEFAULT)
        if have_mode != expected.served.get(C.REDUCTION_MODE_FIELD):
            reasons.append(f"manifest.route.{C.REDUCTION_MODE_FIELD} {have_mode!r} != "
                           f"{expected.served.get(C.REDUCTION_MODE_FIELD)!r}")
        # native-serving-default (§1.7): the route block's UNHASHED engine mirror — a native
        # store's route names lora_native (the driver stamps it on every served store going
        # forward); a lens store's names lens or, from before this landing, nothing at all
        have_engine = route.get(SERVED_ENGINE_FIELD)
        if expected.native:
            if have_engine != ENGINE_LORA_NATIVE:
                reasons.append(f"manifest.route.{SERVED_ENGINE_FIELD} {have_engine!r} != {ENGINE_LORA_NATIVE!r} "
                               "(a native store's route block names its engine)")
        elif have_engine is not None and have_engine != ENGINE_LENS:
            reasons.append(f"manifest.route.{SERVED_ENGINE_FIELD} {have_engine!r} != {ENGINE_LENS!r} "
                           "(this run serves the lens)")
        if expected.out_of_support_thinking:
            # fit-support transfer (contract §2.5.1 <ROUTE_KEY>): the driver
            # copies the RAW attested map into route.lens_serve_declarations; its
            # core under THIS cell's attestation key (the variant spelling on a
            # declared standup) must equal the hashed expectation — the mirror
            # rule route.reduction_mode obeys above. Absent map / absent key reads
            # None, so a declared store with no map is refused by name and an
            # undeclared one (the base route) needs nothing
            key = C.cell_spellings(expected.cell, declared=expected.declared).harness
            where = f"manifest.route.{C.ROUTE_KEY_SERVE_DECLARATIONS}[{key!r}]"
            # review round B, P2-1: the RAW map must EXIST and be a mapping on
            # every out-of-support store — `{}` is the attested "nothing
            # declared" of the none/ON leg, but a missing or null map is missing
            # EVIDENCE (a torn or hand-edited manifest), and reading it as the
            # None the base route expects would let such a store read DONE
            # without the live checks that would have refused its standup
            raw_map = route.get(C.ROUTE_KEY_SERVE_DECLARATIONS)
            if not isinstance(raw_map, Mapping):
                reasons.append(
                    f"manifest.route.{C.ROUTE_KEY_SERVE_DECLARATIONS} is "
                    f"{'absent' if C.ROUTE_KEY_SERVE_DECLARATIONS not in route else repr(raw_map)}, "
                    "not the per-cell map the driver copies off every out-of-support standup "
                    "(`{}` when nothing is declared) — missing evidence, never an attested "
                    "empty map")
            else:
                try:
                    core = C.serve_out_of_support_attested(
                        {C.PROXY_IDENTITY_SERVE_DECLARATIONS: raw_map}, key)
                except C.OutOfSupportAttestationError as e:
                    reasons.append(f"{where}: {e}")
                else:
                    if core != expected.serve_out_of_support:
                        reasons.append(
                            f"{where} core {core!r} does not mirror the hashed "
                            f"tinycap.{C.IDENTITY_KEY_SERVE_OUT_OF_SUPPORT} "
                            f"{expected.serve_out_of_support!r} (the store's standup attested "
                            "another declaration than this run expects)")
    # PW-sampling (U8): the manifest's sampling block must exist in the
    # contract's shape, name this run's mode, and MIRROR the hashed fields
    smp = manifest.get(C.MANIFEST_KEY_SAMPLING)
    # under `protocol` the block carries by_task
    # too (contracts.sampling_block_fields(None, mode=protocol)); every other
    # expectation holds the block to exactly the legacy key set, as before
    block_fields = (C.sampling_block_fields(None, mode=C.SAMPLING_PROTOCOL) if expected.protocol_sampling
                    else C.SAMPLING_BLOCK_FIELDS)
    # ifeval-canonical-battery (the wave shakedown, 2026-09-13): a row that SETS optional sampling terms writes them
    # into the block (``contracts.sampling_block_fields(row)``: Qwen's vendor_preset row carries min_p /
    # presence_penalty / repetition_penalty), exactly as the driver's own resume guard admits
    # (``served_capability_run._check_manifest_sampling``). This reader held every block to the legacy key set and
    # filed the probe cell's COMPLETE store (driver rc 0, 1,082 draws, DONE marker) as INCOMPLETE — "unknown ['min_p',
    # 'presence_penalty', 'repetition_penalty']" — which the dispatcher would then have re-run from scratch. Same rule
    # as the driver: the base fields present, any extra within the optional identity fields, and every optional term
    # present MIRRORS the hashed identity (below).
    bad = _keys_within(smp, block_fields, C.SAMPLING_OPTIONAL_IDENTITY_FIELDS, f"manifest.{C.MANIFEST_KEY_SAMPLING}")
    if bad:
        reasons.append(bad + " (a store from before the sampling contract cannot vouch for how "
                             "its rows were drawn)")
    else:
        if smp.get("mode") != expected.sampling_mode:
            reasons.append(f"manifest.{C.MANIFEST_KEY_SAMPLING}.mode {smp.get('mode')!r} != this run's "
                           f"{expected.sampling_mode!r}")
        for f in C.SAMPLING_IDENTITY_FIELDS:
            if smp.get(f) != tinycap[f]:
                reasons.append(f"manifest.{C.MANIFEST_KEY_SAMPLING}.{f} {smp.get(f)!r} does not mirror "
                               f"the hashed tinycap.{f} {tinycap[f]!r}")
        for f in C.SAMPLING_OPTIONAL_IDENTITY_FIELDS:
            # an optional term rides the block iff the row sets it; wherever either side names it, they must agree
            if (f in smp or tinycap.get(f) is not None) and smp.get(f) != tinycap.get(f):
                reasons.append(f"manifest.{C.MANIFEST_KEY_SAMPLING}.{f} {smp.get(f)!r} does not mirror "
                               f"the hashed tinycap.{f} {tinycap.get(f)!r}")
        if expected.protocol_sampling:
            # the per-task EXECUTED rows in by_task must MIRROR the hashed map,
            # task for task (a hand-edited by_task, or one written for another
            # protocol table, is not this store's)
            by_task = smp.get(C.SAMPLING_BLOCK_KEY_BY_TASK)
            mirror = ({t: dict(b.get("executed") or {}) for t, b in by_task.items()}
                      if isinstance(by_task, Mapping) else None)
            if mirror != tinycap.get(C.IDENTITY_KEY_SAMPLING_BY_TASK):
                reasons.append(f"manifest.{C.MANIFEST_KEY_SAMPLING}.{C.SAMPLING_BLOCK_KEY_BY_TASK}.*.executed "
                               f"{mirror!r} does not mirror the hashed tinycap.{C.IDENTITY_KEY_SAMPLING_BY_TASK} "
                               f"{tinycap.get(C.IDENTITY_KEY_SAMPLING_BY_TASK)!r}")
    producer = manifest.get(C.MANIFEST_KEY_PRODUCER)
    bad = _exact_keys(producer, C.PRODUCER_BLOCK_FIELDS, f"manifest.{C.MANIFEST_KEY_PRODUCER}")
    if bad:
        reasons.append(bad + " (a store that cannot name the tree that produced it)")
    else:
        if not isinstance(producer["tree_sha"], str) or not _SHA40.match(producer["tree_sha"]):
            reasons.append(f"producer.tree_sha {producer['tree_sha']!r} is not a full commit sha")
        elif producer["tree_sha"] != expected.tree_sha:
            # E14 B: the producer sha is NOT hashed, so a store from another
            # revision keys the same; only this comparison keeps rows from two
            # revisions out of one store (the driver's own resume gate refuses
            # too, but only after a standup has been spent)
            reasons.append(f"producer.tree_sha {producer['tree_sha']} was produced by another "
                           f"revision than the staged tree {expected.tree_sha}")
        if producer["driver"] != C.PRODUCER_DRIVER_SERVED:
            reasons.append(f"producer.driver {producer['driver']!r} != {C.PRODUCER_DRIVER_SERVED!r}")
    return "; ".join(reasons) if reasons else None


def store_atoms(cell_dir: Path) -> Set[str]:
    """The control atoms a trusted store REQUESTED (``tinycap.tasks``): a
    done marker for a task whose atom the store never ran is foreign."""
    manifest, _ = _read_json_object(cell_dir / "manifest.json")
    tasks = (manifest or {}).get(C.MANIFEST_KEY_TINYCAP, {}).get("tasks") or []
    return {a for a in tasks if isinstance(a, str)}


def invalid_done_marker_reason(cell_dir: Path, task: str) -> Optional[str]:
    """R2 (launcher half): why ``task`` is NOT validly done under
    ``cell_dir`` — ``None`` when it is. The done marker must exist, parse,
    carry EXACTLY ``DONE_MARKER_FIELDS``, name this task, count a positive
    ``n_items`` equal to the frozen full count where the contracts state one
    (:data:`FULL_ITEM_COUNT_OF_TASK`), have NO partial marker beside it, and
    its ``summary/<task>.json`` must exist and agree on ``n`` (the merge
    reads that file; a marker without it is a torn store)."""
    name = done_marker_name(task)
    marker_path = cell_dir / C.DONE_DIR / name
    if not marker_path.is_file():
        return "no done marker"
    if (cell_dir / C.PARTIAL_DIR / name).is_file():
        return "a partial marker sits beside the done marker (a store mix-up)"
    marker, err = _read_json_object(marker_path)
    if marker is None:
        return f"done marker {err}"
    # E55 #2: the REQUIRED set is still exact; the samples binding rides as an
    # optional key, so a marker written before it stays trusted and one written
    # with it is not "extra fields"
    # ifeval-canonical-battery (P30, the draw-subset contract; the wave shakedown 2026-09-13): a k > 1 store's marker
    # also carries the DRAW counts (``contracts.DONE_MARKER_DRAW_FIELDS``: n_draws / n_expected_draws — the writer
    # ``completion.finish_task`` and its validator admit them as optional); this reader did not, so the probe cell's
    # complete store read "done marker fields … != the contract's" and INCOMPLETE. Same optional set as completion's.
    optional = (*C.DONE_MARKER_OPTIONAL_FIELDS, *C.DONE_MARKER_DRAW_FIELDS)
    extra = sorted(set(marker) - set(C.DONE_MARKER_FIELDS) - set(optional))
    if set(C.DONE_MARKER_FIELDS) - set(marker) or extra:
        return (f"done marker fields {sorted(marker)} != the contract's "
                f"{sorted(C.DONE_MARKER_FIELDS)} (optionally {sorted(optional)})")
    if marker["task"] != task:
        return f"done marker names task {marker['task']!r}"
    n = marker["n_items"]
    if isinstance(n, bool) or not isinstance(n, int) or n <= 0:
        return f"done marker n_items {n!r} is not a positive count"
    full = FULL_ITEM_COUNT_OF_TASK.get(task)
    if full is not None and n != full:
        return f"done marker n_items {n} != the frozen full item count {full}"
    summary_path = cell_dir / C.SUMMARY_DIR / name
    if not summary_path.is_file():
        return f"no {C.SUMMARY_DIR}/{name} beside the done marker (the merge would refuse it)"
    summary, err = _read_json_object(summary_path)
    if summary is None or not summary:
        return f"summary payload {err or 'empty'}"
    if C.METRIC_N in summary and summary[C.METRIC_N] != n:
        return f"summary n {summary[C.METRIC_N]!r} != done marker n_items {n}"
    # For a store POSITIVELY marked out_of_support_thinking, a valid all-attempted
    # outcome record beside the marker is part of being done — the same reason
    # function the driver's skip predicate uses, so the two sites cannot disagree.
    # The manifest read here is a trusted store's (untrusted_store_reason ran first
    # in resume_report); an in-support store is never asked for a sidecar.
    if _store_requires_outcomes(cell_dir):
        reason = completion.task_outcomes_reason(cell_dir, task)
        if reason is not None:
            return reason
    return None


def _store_requires_outcomes(cell_dir: Path) -> bool:
    """``completion.store_requires_outcomes``: EITHER
    positive producer marker — an out-of-support store, or a comparator store
    carrying the cap key alone — owes a valid outcome record beside every done
    marker. The ONE predicate ``invalid_done_marker_reason`` and the
    pre-standup ``torn_store_unrepairable`` read; an in-support store (no key)
    is never asked for a sidecar."""
    return completion.store_requires_outcomes(cell_dir)


def resume_report(out_dir: str | Path, controls: Sequence[str], expected: ExpectedIdentity,
                  *, kv_shrink_tolerated: bool = False) -> Dict[str, object]:
    """The resume decision, with its reasons: ``expected`` = the identity
    every store is held to; ``stores`` = every ``<out_dir>/cells/<key>/``
    directory -> None (trusted for that identity) | why not; ``controls``
    = per control the ONE trusted store that REQUESTED its atoms and in
    which EVERY task it produces is validly done (``done_in``), else
    ``why_not`` per store and task. Never a union of markers across stores."""
    return _resume_report(out_dir, controls, expected, lambda d, t: invalid_done_marker_reason(d, t),
                          kv_shrink_tolerated=kv_shrink_tolerated)


def ladder_resume_report(out_dir: str | Path, controls: Sequence[str], expected: ExpectedIdentity
                         ) -> Dict[str, object]:
    """:func:`resume_report`'s shape over
    the truncation ladder's STRICT per-task rule :func:`ladder_partial_reason` —
    ``done_in`` names the ONE trusted store (``untrusted_store_reason`` under a
    ladder expectation: the hashed tuple, ``limits == {"item_selection": 1}``,
    the rung's served window / S) in which every task of the control is a valid
    ladder PARTIAL. The ONE validator both the CPU preflight (``ladder_admission``)
    and ``_run_configuration`` after the driver exits run, so the first
    successful scoring invocation reads ``PARTIAL_COMPLETE`` and a relaunch
    that finds every cell complete spends no GPU."""
    if not expected.ladder:
        raise ValueError("ladder_resume_report needs a ladder expectation (cap_overrides_by_task + item_selection)")
    return _resume_report(out_dir, controls, expected,
                          lambda d, t: ladder_partial_reason(d, t, expected))


def _resume_report(out_dir: str | Path, controls: Sequence[str], expected: ExpectedIdentity,
                   task_reason, *, kv_shrink_tolerated: bool = False) -> Dict[str, object]:
    cells_root = Path(out_dir) / "cells"
    dirs = sorted(p for p in cells_root.iterdir() if p.is_dir()) if cells_root.is_dir() else []
    stores = {d.name: untrusted_store_reason(d, expected=expected, kv_shrink_tolerated=kv_shrink_tolerated)
              for d in dirs}
    atoms_of = {d.name: store_atoms(d) for d in dirs if stores[d.name] is None}
    report: Dict[str, object] = {"expected": expected.as_dict(), "stores": stores, "controls": {}}
    for control in controls:
        tasks = expected_tasks(control, expected.mode)
        atoms = set(C.expand_control(control))
        done_in = None
        why_not: Dict[str, object] = {}
        for d in dirs:
            if stores[d.name] is not None:
                why_not[d.name] = stores[d.name]
                continue
            never_ran = sorted(atoms - atoms_of[d.name])
            if never_ran:
                why_not[d.name] = f"the store never requested {never_ran} (tinycap.tasks)"
                continue
            bad = {t: r for t in tasks if (r := task_reason(d, t)) is not None}
            if not bad:
                done_in = d.name
                break
            why_not[d.name] = bad
        report["controls"][control] = {
            "tasks": list(tasks), "done_in": done_in,
            "why_not": why_not if done_in is None else {}}
    return report


def ladder_partial_reason(cell_dir: Path, task: str, expected: ExpectedIdentity) -> Optional[str]:
    """Why ``task`` is NOT a validly complete ladder
    rung-2 result under ``cell_dir`` — None when it is. STRICT: no done marker;
    a PARTIAL marker with exactly ``PARTIAL_MARKER_FIELDS`` naming this task,
    ``limits == {"item_selection": 1}``, ``n_items == selection.n``,
    ``n_expected_full`` = the leg's frozen full count; the summary present with
    ``n == n_items`` and ``max_tokens == cap_overrides_by_task[task]``; the
    outcome record present, shape-checked, at that cap, its item ids (LOG
    vocabulary) == the selection EXACTLY. (The store's hashed tuple — the caps,
    the selection digest, the served rung, the limits — is
    ``untrusted_store_reason``'s under a ladder expectation.)"""
    if not expected.ladder or expected.item_selection_ids is None or expected.cap_overrides_by_task is None:
        return "the expectation is not a ladder rung"
    if task not in expected.item_selection_ids or task not in expected.cap_overrides_by_task:
        return f"{task} is not in the ladder's selection {sorted(expected.item_selection_ids)}"
    # the ONE validator, shared with the driver's dispatch skip
    return RP.ladder_task_partial_reason(
        cell_dir, task, log_ids=C.ladder_log_ids(task, expected.item_selection_ids[task]),
        cap=int(expected.cap_overrides_by_task[task]), n_expected_full=FULL_ITEM_COUNT_OF_TASK.get(task))


def producer_tree_conflicts(out_dir: str | Path, *, expected: ExpectedIdentity,
                            kv_shrink_tolerated: bool = False) -> Dict[str, str]:
    """``{cell key: its producer sha}`` for the stores under
    ``<out_dir>/cells/`` that this run's driver would land on and REFUSE
    (E14 B): every identity field matches, so the store keys the same, but
    it was produced by another revision — ``CellStore.validate_resume``
    then refuses before any manifest rewrite. Detected by asking whether the
    store would be trusted for an identity carrying ITS OWN tree sha: if it
    would, the tree sha is the ONLY difference. Reported before the standup
    so a doomed configuration costs no GPU minute."""
    root = Path(out_dir) / "cells"
    out: Dict[str, str] = {}
    if not root.is_dir():
        return out
    for d in sorted(p for p in root.iterdir() if p.is_dir()):
        got = producer_tree_sha(d)
        if not got or got == expected.tree_sha:
            continue
        if untrusted_store_reason(d, expected=expected._replace(tree_sha=got),
                                  kv_shrink_tolerated=kv_shrink_tolerated) is None:
            out[d.name] = got
    return out


def remaining_controls(out_dir: str | Path, controls: Sequence[str],
                       expected: ExpectedIdentity) -> List[str]:
    """Resume (R2 / E12 item 1): the controls with NO trusted store under
    ``<out_dir>/cells/`` — trusted for ``expected`` — in which every task
    they produce is validly done (:func:`resume_report`). A partially done
    control re-runs whole; its stores are idempotent."""
    report = resume_report(out_dir, controls, expected)
    return [c for c in controls if report["controls"][c]["done_in"] is None]


# --------------------------------------------------------------------------- #
# the staged tree and its TREE_SHA stamp (E12 item 3)                          #
# --------------------------------------------------------------------------- #


class NoStagedTree(FileNotFoundError):
    """No staged tree answers to the sha (``--upload-tree --stage`` first)."""


class TreeShaMissing(FileNotFoundError):
    """A staged tree without its ``TREE_SHA`` stamp: staged before the
    producer discipline — the driver could not record which tree produced a
    store, so the tree is refused until re-uploaded."""


class TreeShaMismatch(ValueError):
    """The stamp does not name the sha the tree was staged as (or several
    staged trees claim one sha)."""


def tree_sha_stamp_text(full_sha: str) -> str:
    """The ``TREE_SHA`` file's content: the full 40-hex commit, one line."""
    if not _SHA40.match(full_sha or ""):
        raise ValueError(f"TREE_SHA takes the full 40-hex commit, got {full_sha!r}")
    return full_sha + "\n"


def archive_argv(repo: str | Path, full_sha: str, stamp_path: str | Path) -> List[str]:
    """``git archive`` of ``full_sha`` with the stamp file added at the
    archive ROOT (``--add-file`` places a file by its basename, so the stamp
    is named ``TREE_SHA`` on disk before archiving)."""
    if Path(stamp_path).name != C.TREE_SHA_FILENAME:
        raise ValueError(f"the stamp must be named {C.TREE_SHA_FILENAME!r}, got {stamp_path!r}")
    return ["git", "-C", str(repo), "archive", "--format=tar.gz",
            f"--add-file={stamp_path}", full_sha]


def staged_tree_sha(tree: str | Path, sha: str) -> str:
    """The full commit a staged tree's ``TREE_SHA`` names; refuses a tree
    without the stamp (:class:`TreeShaMissing`), a malformed stamp, or one
    that does not start with the sha the tree is addressed by
    (:class:`TreeShaMismatch`)."""
    stamp = Path(tree) / C.TREE_SHA_FILENAME
    if not stamp.is_file():
        raise TreeShaMissing(
            f"no {C.TREE_SHA_FILENAME} at {tree} — a tree staged before the producer discipline; "
            f"remove it and re-run --upload-tree --stage at {sha} so every store it produces "
            "can name its tree (manifest.producer.tree_sha)")
    text = stamp.read_text(encoding="utf-8").strip()
    if not _SHA40.match(text):
        raise TreeShaMismatch(f"{stamp} does not hold a full 40-hex commit: {text[:60]!r}")
    if not text.startswith(sha.strip().lower()):
        raise TreeShaMismatch(f"{stamp} names {text} but the tree is addressed as {sha!r}")
    return text


def bind_full22_roster(tree: Path) -> Path:
    """Point the bank-view vocabulary at the STAGED tree's full22 roster (``$SISTEER_FULL22_ROSTER``, the hook
    ``contracts.full22_roster_candidates`` reads first) and return ``tree`` unchanged. Inside a container the
    ``sisteer`` package is mounted at ``/root/sisteer`` with no ``configs/`` beside it, so the module-relative and
    cwd candidates miss and ``driver_argv`` refused every LANE view (``--bank-view 's1' is not one of ['main',
    'it'] (no full22 roster found at /configs/…, /root/configs/…)`` — the IFEval seed canary, 2026-09-23). The
    tree that produces a store is the one authority for its views (the same rule the live tool-parser verdict
    follows); a tree without the roster leaves the variable alone, so the refusal keeps naming the paths tried
    instead of admitting a view nothing declares."""
    roster = Path(tree) / C.FULL22_ROSTER_REL
    if roster.is_file():
        os.environ[C.ENV_FULL22_ROSTER] = str(roster)
    return Path(tree)


#: tinycap-shared-standup §1.9.1 (inode rule 1): where a container unpacks a staged tree — NODE-LOCAL
#: disk (the container's own filesystem, gone with it), never the volume. Before rule 1 ``stage``
#: extracted every tree INTO the volume (~4,150 inodes per tree, kept beside its tarball); now the
#: volume holds the ONE tarball (1 inode) and every consumer — the stage's priming steps, the CPU
#: preflight, the GPU workers, the probes — unpacks it here through :func:`resolve_staged_tree`.
#: ``TINYCAP_TREE_LOCAL_ROOT`` re-points it (the tests).
TREE_LOCAL_ROOT = "/tmp/tree"
TREE_LOCAL_ROOT_ENV = "TINYCAP_TREE_LOCAL_ROOT"
#: ``stage_manifest.json``'s ``steps.tree.on_volume`` / the preflight's ``tree`` check: how the tree
#: sits on the volume — the tarball alone (rule 1) or a tree extracted before the rule (still used).
TREE_ON_VOLUME_TARBALL_ONLY = "tarball_only"
TREE_ON_VOLUME_EXTRACTED_LEGACY = "extracted_legacy"


def staged_tarball_path(sha: str, repos_root: Optional[str | Path] = None) -> Path:
    """``<repos>/sisteer-<sha>.tar.gz`` — the ONE inode a staged tree keeps on the volume (the
    upload's spelling, :func:`_upload_tree`)."""
    root = Path(repos_root if repos_root is not None else C.VOL_REPOS_ROOT)
    return root / f"sisteer-{sha}.tar.gz"


#: ``tarball_tree_sha`` is a full gzip pass (~1 s on a tree archive) and was run before
#: ``unpack_tree_local``'s idempotency short-circuit and twice on ``resolve_staged_tree``'s abbreviation path;
#: the answer is a pure function of the archive's bytes, so it is memoised per (resolved path, size, mtime_ns)
_TARBALL_TREE_SHA_CACHE: Dict[Tuple[str, int, int], Optional[str]] = {}


def tarball_tree_sha(tarball: str | Path) -> Optional[str]:
    """The full commit a tarball's ``TREE_SHA`` member names (``git archive --add-file`` puts it at
    the archive root), or ``None`` when the archive carries no such member, a malformed one, or is
    not a readable archive. Reads the one member; extracts nothing. Memoised per (resolved path,
    st_size, st_mtime_ns): a rewritten archive is re-read, an unchanged one is not."""
    try:
        st = os.stat(tarball)
        key = (str(Path(tarball).resolve()), int(st.st_size), int(st.st_mtime_ns))
    except OSError:
        return None
    if key in _TARBALL_TREE_SHA_CACHE:
        return _TARBALL_TREE_SHA_CACHE[key]
    _TARBALL_TREE_SHA_CACHE[key] = _read_tarball_tree_sha(tarball)
    return _TARBALL_TREE_SHA_CACHE[key]


def _read_tarball_tree_sha(tarball: str | Path) -> Optional[str]:
    import tarfile
    try:
        with tarfile.open(tarball) as tf:
            for name in (C.TREE_SHA_FILENAME, f"./{C.TREE_SHA_FILENAME}"):
                try:
                    member = tf.getmember(name)
                except KeyError:
                    continue
                fh = tf.extractfile(member)
                text = fh.read().decode("utf-8", errors="replace").strip() if fh is not None else ""
                return text if _SHA40.match(text) else None
    except (tarfile.TarError, OSError, EOFError):
        return None
    return None


def unpack_tree_local(tarball: str | Path, sha: str, local_root: Optional[str | Path] = None, *,
                      full: Optional[str] = None) -> Tuple[Path, str]:
    """Unpack a staged tarball to node-local ``<local root>/sisteer-<full sha>`` and return
    ``(tree, full sha)``. The archive's ``TREE_SHA`` member must start with ``sha`` (the tree is
    addressed by it — :class:`TreeShaMismatch` otherwise, :class:`TreeShaMissing` without the
    stamp); the unpacked tree is verified by the same :func:`staged_tree_sha` rule every consumer
    applies. IDEMPOTENT: a tree already unpacked in this container (stamp + ``src/sisteer`` present)
    is returned as is; a torn earlier unpack is replaced whole. Extraction goes to a temp dir beside
    the target and is renamed into place, so a crash mid-unpack never leaves a half tree at the
    final path. Binds the full22 roster (:func:`bind_full22_roster`) like every resolution."""
    import tarfile
    tarball = Path(tarball)
    if not tarball.is_file():
        raise NoStagedTree(f"no staged tarball at {tarball} — run --upload-tree first")
    full = full if full is not None else tarball_tree_sha(tarball)      # `full`: the sha a caller already read off it
    if full is None:
        raise TreeShaMissing(
            f"{tarball} carries no {C.TREE_SHA_FILENAME} member at its root — a tarball uploaded before the "
            f"producer discipline; remove it and re-run --upload-tree --stage at {sha} so every store it "
            "produces can name its tree (manifest.producer.tree_sha)")
    want = sha.strip().lower()
    if not full.startswith(want):
        raise TreeShaMismatch(f"{tarball} names {full} but the tree is addressed as {sha!r}")
    root = Path(local_root if local_root is not None else (os.environ.get(TREE_LOCAL_ROOT_ENV) or TREE_LOCAL_ROOT))
    tree = root / f"sisteer-{full}"
    if (tree / "src" / "sisteer").is_dir() and (tree / C.TREE_SHA_FILENAME).is_file():
        return bind_full22_roster(tree), staged_tree_sha(tree, sha)      # already unpacked in this container
    root.mkdir(parents=True, exist_ok=True)
    tmp = Path(tempfile.mkdtemp(prefix=f".sisteer-{full[:12]}.", dir=root))
    try:
        with tarfile.open(tarball) as tf:
            tf.extractall(tmp, filter="data")
        tree_sha = staged_tree_sha(tmp, sha)         # the archive carries its stamp, or is refused
        if tree_sha != full:
            raise TreeShaMismatch(f"{tarball}: the {C.TREE_SHA_FILENAME} member names {full} but the unpacked "
                                  f"stamp names {tree_sha}")
        if not (tmp / "src" / "sisteer").is_dir():
            raise NoStagedTree(f"{tarball} unpacks to no src/sisteer — not a sisteer tree archive")
        if tree.exists():
            shutil.rmtree(tree)                      # a torn earlier unpack (no stamp / no src): replaced whole
        tmp.rename(tree)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    return bind_full22_roster(tree), tree_sha


def resolve_staged_tree(sha: str, repos_root: Optional[str | Path] = None, *,
                        local_root: Optional[str | Path] = None) -> Tuple[Path, str]:
    """``(tree dir, full sha)`` for ``sha``. Resolution order (tinycap-shared-standup §1.9.1, inode
    rule 1): (1) a tree EXTRACTED on the volume before the rule, ``<repos>/sisteer-<sha>`` (its stamp
    must name the sha) — a legacy tree still wins, nothing re-unpacks it; (2) the tarball
    ``<repos>/sisteer-<sha>.tar.gz``, unpacked NODE-LOCAL (:func:`unpack_tree_local`: idempotent,
    stamp-verified); (3) an abbreviation: the ONE legacy tree or tarball whose ``TREE_SHA`` starts
    with ``sha`` — so a merge chained with a store's FULL producer sha finds the tree the operator
    staged under an abbreviation (a tarball is opened only when its NAME is prefix-compatible with
    ``sha``, so a volume holding many waves' tarballs is not read member by member). None ->
    :class:`NoStagedTree`; several -> :class:`TreeShaMismatch`. Every consumer inherits: the
    preflight, the GPU workers, the probes, the stage's own priming steps."""
    root = Path(repos_root if repos_root is not None else C.VOL_REPOS_ROOT)
    direct = root / f"sisteer-{sha}"
    if (direct / "src" / "sisteer").is_dir():
        return bind_full22_roster(direct), staged_tree_sha(direct, sha)
    tarball = staged_tarball_path(sha, root)
    if tarball.is_file():
        return unpack_tree_local(tarball, sha, local_root)
    want = sha.strip().lower()
    matches: List[Tuple[Path, str, str]] = []
    for stamp in sorted(root.glob(f"sisteer-*/{C.TREE_SHA_FILENAME}")):
        text = stamp.read_text(encoding="utf-8").strip()
        if _SHA40.match(text) and text.startswith(want) and (stamp.parent / "src" / "sisteer").is_dir():
            matches.append((stamp.parent, text, "tree"))
    for tb in sorted(root.glob("sisteer-*.tar.gz")):
        named = tb.name[len("sisteer-"):-len(".tar.gz")].lower()
        if not (named.startswith(want) or want.startswith(named)):
            continue
        full = tarball_tree_sha(tb)
        if full is not None and full.startswith(want):
            matches.append((tb, full, "tarball"))
    if len(matches) == 1:
        path, full, kind = matches[0]
        if kind == "tree":
            return bind_full22_roster(path), full
        return unpack_tree_local(path, sha, local_root, full=full)
    if not matches:
        raise NoStagedTree(
            f"no staged tree for sha {sha!r} under {root}: neither {direct}, nor {tarball.name}, nor a "
            f"sisteer-*/{C.TREE_SHA_FILENAME} or a sisteer-*.tar.gz naming it — run --upload-tree --stage")
    raise TreeShaMismatch(
        f"several staged trees claim sha {sha!r}: {[str(m[0]) for m in matches]} — address one "
        "by its full sha")


# --------------------------------------------------------------------------- #
# geometry (from the STAGED tree in-container, the local checkout otherwise)   #
# --------------------------------------------------------------------------- #


def _geometry_module(tree: Optional[str] = None):
    if tree and f"{tree}/src" not in sys.path:
        sys.path.insert(0, f"{tree}/src")
    from sisteer.capeval.serving import geometry
    return geometry


class Pass2Unpartitioned(ValueError):
    """Pass 2 asked for a configuration whose traffic pools into SEVERAL
    geometry sub-entries: one server can serve one measured window, so
    picking ``geometry_keys[0]`` would size every other key's traffic to a
    window measured for something else (R5). The eventual design partitions
    pass 2 per key — one standup per sub-entry, each at its own measured
    entry (recorded as a follow-on, not built); until then pass 2 takes a
    ``--controls`` list whose atoms share one key."""


class Pass1FootprintCannotHold(ValueError):
    """Pass 1 asked for a configuration that pools, beside other sub-entries,
    a key the certified footprint CANNOT hold. ``pass1_geometry`` serves
    every key of a configuration at the one certified window so the pooled
    ledgers measure (or extend) each entry at that footprint; an entry sized to
    its prompt MAX (``GeometryBasis.sized_to_max_prompt`` — MATH-500's
    ``capability:gen_long_math`` / ``capability:gen_long_math_longsi``, whose driver refuses a clamped cap-bound
    sample by name) needs ``max_prompt + requested_max_tokens`` tokens for its
    every cap-bound request, and when that exceeds the footprint the footprint
    cannot serve it at all: a live request overflows the context, and the
    driver refuses the whole task after the standup was paid for. ALONE, such
    a key is served at its own measured window in pass 1 as in pass 2
    (:func:`configuration_geometry`); pooled beside other keys it is refused
    HERE, before any allocation, because one standup at its window would size
    every other key's traffic to a window measured for something else and
    shrink their concurrency (R5's objection, in pass 1) — run it alone
    (``--controls math500``) and the rest of the battery without it."""


def keys_beyond_footprint(sg, keys: Sequence[str], footprint: int) -> List[Tuple[str, int]]:
    """``(key, tokens needed)`` for every sub-entry of ``keys`` the certified
    footprint cannot hold: a MEASURED entry sized to its prompt MAX
    (``GeometryBasis.sized_to_max_prompt``) needs ``max_prompt +
    requested_max_tokens`` tokens for its every cap-bound request — the
    driver's ``assert_pass_fits_window`` refuses the task otherwise — and the
    footprint is too small when that exceeds it. An entry sized by a p99
    branch is never listed: its prompt tail is the once-only clamp's business,
    not a refusal, so the footprint serves it for measurement as designed."""
    out: List[Tuple[str, int]] = []
    for key in keys:
        b = sg.geometry_for(key).basis
        if b.sized_to_max_prompt:
            need = int(b.max_prompt) + int(b.requested_max_tokens)
            if need > int(footprint):
                out.append((key, need))
    return out


def controls_pooling_into(cell: str, mode: str, controls: Sequence[str], key: str) -> List[str]:
    """The ``controls`` tokens whose traffic :func:`geometry_keys_for` pools
    into ``key`` — the inverse read, for a refusal that must name the control
    an operator types rather than the sub-entry it resolves to."""
    return [c for c in controls if key in geometry_keys_for(cell, mode, [c])]


#: How a refusal names a control's workload (the control token is what an
#: operator types; the workload is what the numbers are about).
_CONTROL_WORKLOAD_NAMES: Mapping[str, str] = {C.CONTROL_MATH500: "MATH-500", C.CONTROL_IFEVAL: "IFEval"}


class Math500WindowCannotHoldClass(ValueError):
    """A MATH-500 configuration resolved a window that cannot hold the measured
    prompt MAX of its ACTUAL prompt class at the cap. The driver would
    refuse the task by name after generation (``assert_pass_fits_window``); the
    launcher refuses it here, before any allocation."""


def math500_prompt_class_of(cfg: Mapping) -> Optional[str]:
    """The MATH-500 prompt class of a configuration that runs MATH-500 — by the
    system turn its CELL carries (``contracts.math500_prompt_class_of_si``:
    none for the base / object cells, the SI of a prompted cell) — or None
    when no control of the configuration is MATH-500. Refuses an SI with no
    measured class by name (``Math500PromptClassUnmeasured``)."""
    if not any(C.control_family(a) == C.CONTROL_MATH500
               for c in cfg["controls"] for a in C.expand_control(c)):
        return None
    cell = cfg["cell"]
    return C.math500_prompt_class_of_si(C.parse_launcher_cell(cell).si if is_prompted(cell) else None)


def assert_math500_class_fits(cfg: Mapping, geom, sg):
    """The pre-allocation FIT CHECK of a MATH-500 configuration, returning
    ``geom`` when it holds: the window the configuration resolved must hold
    the measured prompt MAX of its ACTUAL prompt class plus the cap it
    generates at — the entry MEASURED for that class
    (``contracts.math500_geometry_key``) must be the one the configuration
    pooled into and resolved, and that entry's ``max_prompt`` + the cap must
    fit ``geom.max_model_len``. The class max is the class's own measurement,
    never whichever entry's default: before this, `--pass1 --cells
    prompted__si_irrelevant --modes off --controls math500` was checked
    against the entry it happened to pool into (1,041 + 16,384 <= 17,664)
    while its real prompts were 7,5xx tokens (the irrelevant SI alone is
    6,560 on Gemma), so the requests would have been window-clamped and the
    driver refused the task after the standup was paid for. Nothing to check
    for a configuration without MATH-500."""
    cls = math500_prompt_class_of(cfg)
    if cls is None:
        return geom
    key = C.math500_geometry_key(cls)
    entry = sg.geometry_for(key)
    oos = cfg.get(C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING) is True
    cap = C.math500_max_tokens_for(cfg["thinking_by_task"][C.inspect_task("math")], out_of_support=oos)
    need = int(entry.basis.max_prompt) + int(cap)
    if key not in cfg["geometry_keys"] or geom.eval != key or need > int(geom.max_model_len):
        raise Math500WindowCannotHoldClass(
            f"configuration {cfg.get('name', '?')!r} runs MATH-500 on cell {cfg['cell']!r}, prompt class "
            f"{cls!r} (measured prompt max {entry.basis.max_prompt:,} tokens under the pinned tokenizers; "
            f"its entry {key} is {entry.max_model_len:,}), at cap {cap:,}: every cap-bound request needs "
            f"{need:,} tokens, but the configuration resolved {geom.eval} at max_model_len "
            f"{geom.max_model_len:,} (keys pooled: {list(cfg['geometry_keys'])}) — vLLM would clamp those "
            "completions to the window and the driver would refuse the task after generation "
            "(assert_pass_fits_window). Refusing before allocation (D80)")
    return geom


_UNSET_MODEL_KEY = object()

#: ifeval-canonical-battery: the three capability:ifeval_<cap> entries — NOT tinycap
#: sub-entries (``pass1_geometry`` refuses them), each resolved at its own measured window
_IFEVAL_KEYS = frozenset(C.IFEVAL_GEOMETRY_ENTRIES)


class IfevalGeometryPooled(ValueError):
    """An IFEval entry pooled beside another sub-entry: one standup
    serves one window, and the cap's entry is sized for IFEval's prompts + its
    cap alone — pooling would serve the other traffic at a window measured for
    something else. Run the ``ifeval`` atom alone."""


def configuration_geometry(cfg: Mapping, pass_no: int, tree: Optional[str] = None, *,
                           model_key=_UNSET_MODEL_KEY):
    """Pass 1: the certified WINDOW through ``pass1_geometry`` (the
    configuration's first sub-entry labels it; all its keys share the one
    window) — EXCEPT for a key the footprint cannot hold
    (:func:`keys_beyond_footprint`: MATH-500's ``capability:gen_long_math`` /
    ``capability:gen_long_math_longsi``, sized to their prompt max + the
    cap): alone, that key is resolved at
    its OWN measured window exactly as pass 2 would (there is no footprint
    pass to run for it — the entry's basis is the prompt budget, not a ledger
    — and one key is one window); pooled beside other keys it is refused
    (:class:`Pass1FootprintCannotHold`) rather than dragging them to a window
    measured for something else. Pass 2: the MEASURED entry through
    ``resolve_geometry`` — which refuses while the entry is still
    provisional, so pass 2 cannot run before the measurement is accepted —
    for a configuration with EXACTLY one sub-entry
    (:class:`Pass2Unpartitioned` otherwise). Both passes size S from
    ``model_key``'s measured budget at the window (``geometry.BUDGET_BY_MODEL``
    via ``ModelBudget.seqs_at``) — the CONFIGURATION's registry row
    by default (one invocation is one model, and every model has
    its own measured budget); ``None`` gives the footprint's own S, and an
    explicit key overrides the row. Every resolution passes
    :func:`assert_math500_class_fits`: a MATH-500 configuration's window
    must hold its ACTUAL prompt class's measured prompt max at the cap — the
    class's own number, never the default entry's.

    A configuration whose one key is a
    ``capability:ifeval_<cap>`` entry resolves it through ``resolve_geometry``
    (S from ``model_key``'s budget) for EITHER pass — one key, one measured
    window: the entry's basis is the prompt budget (468 + the cap), not a
    ledger, so there is no footprint pass to run for it (the same rationale as
    a key beyond the footprint above), and ``pass1_geometry`` refuses a
    non-tinycap key by construction. Pooled beside another key it is refused
    by name (:class:`IfevalGeometryPooled`); MATH-500's fit check does not
    apply."""
    sg = _geometry_module(tree)
    if model_key is _UNSET_MODEL_KEY:
        model_key = row_of(cfg).model_key
    keys = tuple(cfg["geometry_keys"])
    if any(k in _IFEVAL_KEYS for k in keys):
        if len(keys) != 1:
            raise IfevalGeometryPooled(
                f"configuration {cfg.get('name', '?')!r} pools the IFEval entry "
                f"{[k for k in keys if k in _IFEVAL_KEYS]} beside {[k for k in keys if k not in _IFEVAL_KEYS]}: "
                "one standup serves one window, and the cap's entry is sized for IFEval's prompts + its cap "
                f"alone — run --controls {C.CONTROL_IFEVAL} by itself (plan §8.1)")
        if int(pass_no) not in (1, 2):
            raise ValueError(f"pass must be 1 or 2, got {pass_no!r}")
        return sg.resolve_geometry(keys[0], strict_identity=True, model_key=model_key)
    if int(pass_no) == 1:
        footprint = sg.pass1_geometry(keys[0], model_key=model_key)
        beyond = keys_beyond_footprint(sg, keys, footprint.max_model_len)
        if not beyond:
            return assert_math500_class_fits(cfg, footprint, sg)
        if len(keys) == 1:
            # the one key's own MEASURED window — pass 2's resolution —
            # because the footprint cannot hold its cap from the longest
            # prompt and there is no ledger pass to run at the footprint
            return assert_math500_class_fits(
                cfg, sg.resolve_geometry(keys[0], strict_identity=True, model_key=model_key), sg)
        needs, alone = [], []
        for key, need in beyond:
            entry = sg.geometry_for(key)
            ctl = controls_pooling_into(cfg["cell"], cfg["mode"], cfg["controls"], key)
            alone.extend(ctl)
            what = ", ".join(_CONTROL_WORKLOAD_NAMES.get(c, c) for c in ctl) or key
            needs.append(
                f"{what} at cap {entry.basis.requested_max_tokens:,}, which needs {need:,} tokens "
                f"(prompt max {entry.basis.max_prompt:,} + the cap) and its own window, "
                f"{key} ({entry.max_model_len:,})")
        others = [k for k in keys if k not in dict(beyond)]
        raise Pass1FootprintCannotHold(
            f"pass 1 refuses configuration {cfg.get('name', '?')!r}: the certified footprint "
            f"{footprint.max_model_len:,} cannot hold {'; '.join(needs)} — and the configuration "
            f"pools it beside {others}, which one standup at that window would serve at a window "
            "measured for something else, with fewer sequences for every other task. Launch it "
            f"ALONE — --controls {','.join(alone)} resolves its own window in pass 1 and pass 2 "
            "alike — and the rest of the battery without it (D76)")
    if int(pass_no) == 2:
        if len(keys) != 1:
            raise Pass2Unpartitioned(
                f"pass 2 refuses configuration {cfg.get('name', '?')!r}: its controls pool into "
                f"{len(keys)} geometry sub-entries {list(keys)} and one standup serves one "
                "measured window — narrow --controls to atoms of ONE sub-entry (the partitioned "
                "per-key pass 2 is the recorded follow-on, decisions PW2)")
        return assert_math500_class_fits(
            cfg, sg.resolve_geometry(keys[0], strict_identity=True, model_key=model_key), sg)
    raise ValueError(f"pass must be 1 or 2, got {pass_no!r}")


def model_budget_record(geom, tree: Optional[str] = None) -> dict:
    """What sized S, for the run's ``served_geometry.json`` and the dry run:
    the model's OWN budget row (``geometry.BUDGET_BY_MODEL``) with its basis,
    the resolved S x L against it, and the S the Llama-certified footprint
    would have served at this window instead. REFUSES (:class:`UnmeasuredBudget`)
    a geometry whose S is not ``MODEL_BUDGET_SOURCE`` from that row — an
    unmeasured model falls to the Llama default in the geometry module (with a
    warning), and that S is exactly what this launcher must never serve.

    A PROVISIONAL row (``geometry.PROVISIONAL_BUDGET_SOURCE``: a conservative
    ceiling chosen from an observed engine-init failure, 2026-09-06) is served
    — it is the model's own number and it is SMALLER than the default this gate
    exists to keep out — and the record stamps ``provisional`` and the
    ``budget_source`` so every store says which kind of number sized it."""
    sg = _geometry_module(tree)
    rb = getattr(geom, "budget", None)
    if rb is None or not rb.per_model or geom.seqs_source != MODEL_BUDGET_SOURCE:
        raise UnmeasuredBudget(
            f"S {geom.max_num_seqs} at window {geom.max_model_len} did not come from the "
            f"MODEL's own batched-token budget row: it is not MEASURED and not "
            f"{sg.PROVISIONAL_BUDGET_SOURCE} sizing (seqs_source={geom.seqs_source!r}, "
            f"model_key={geom.model_key!r}, budget_source={geom.budget_source!r}; rows: "
            f"{sorted(sg.BUDGET_BY_MODEL)}) — refusing to serve an S the Llama-certified "
            "default sized; measure the model with scripts/served_decode_sweep.py "
            "--phase budget and land it in geometry.BUDGET_BY_MODEL")
    if str(geom.model_key) in tuple(getattr(sg, "ONBOARDED_MODEL_KEYS", ()) or ()) and bool(rb.provisional):
        # geometry.ONBOARDED_MODEL_KEYS (the 2026-09-29 ruling): an onboarded model never serves from its provisional row — its
        # measured budgets live in the SITE geometry overlay (geometry.site_geometry_dir); a provisional reading here means
        # the overlay did not reach THIS process
        raise UnmeasuredBudget(
            f"S {geom.max_num_seqs} at window {geom.max_model_len} was sized from {geom.model_key!r}'s PROVISIONAL row "
            f"(budget_source={rb.source!r}) — an onboarded model serves only from its MEASURED site overlay; this process read "
            f"none ({sg.SITE_GEOMETRY_DIR_ENV}={os.environ.get(sg.SITE_GEOMETRY_DIR_ENV)!r})")
    return budget_record_fields(geom, rb, sg)


def budget_record_fields(geom, rb, sg) -> dict:
    """The record fields :func:`model_budget_record` and
    :func:`ladder_budget_record` share — every number computed from ``geom`` and
    the budget row it was sized from; the REFUSALS are each caller's own."""
    entry = rb.entry
    return {
        "model_key": geom.model_key,
        "batched_token_budget": rb.batched_token_budget,
        "budget_source": rb.source,
        "provisional": bool(rb.provisional),
        "certified": bool(entry.certified),
        "max_model_len": geom.max_model_len,
        "max_num_seqs": geom.max_num_seqs,
        "batched_tokens": geom.batched_tokens,
        "identity": bool(geom.is_identity),
        "over_budget": bool(geom.over_budget),
        # the S the Llama-certified footprint serves at this window (what E7 replaced)
        "footprint_max_num_seqs": sg.identity_seqs(geom.max_model_len),
        "certified_budget_tokens": sg.BATCHED_TOKEN_BUDGET,
        "ratio_to_certified": round(rb.batched_token_budget / sg.BATCHED_TOKEN_BUDGET, 3),
        "allow_over_budget": False,
        "basis": dataclasses.asdict(entry.basis),
    }


def served_geometry(cfg: Mapping, pass_no: int, tree: Optional[str] = None):
    """What a configuration's standup and driver actually run: the pass's
    window and its S from the model's measured budget, both through
    :func:`configuration_geometry`; plus :func:`model_budget_record` (which
    refuses any S not sized that way). ``(geometry, model_budget)``.

    A configuration carrying
    ``ladder_rung`` — the truncation ladder's certified rung, ``{max_model_len,
    max_num_seqs, seqs_source, rung_source}`` — takes :func:`ladder_geometry`
    instead, through this ONE entry point, so the preflight, the dry run and the
    container all serve the rung and are all held to its gate
    (:func:`ladder_budget_record`)."""
    if cfg.get("ladder_rung"):
        return ladder_geometry(cfg, tree)
    geom = configuration_geometry(cfg, pass_no, tree)
    return geom, model_budget_record(geom, tree)


class LadderGeometryRefused(ValueError):
    """bcb-bfcl-200 §S2b: a ladder rung the gate will not serve — off the
    ladder, over the measured budget, an unmeasured budget, a source that does
    not say what S is."""


def ladder_geometry(cfg: Mapping, tree: Optional[str] = None):
    """The truncation ladder's geometry: the configuration's pass-1
    resolution — its model, its budget row, its key, through
    :func:`configuration_geometry`, so ``model_key`` travels exactly as on every
    launch and no new ``resolve_geometry`` call is made — re-dimensioned to the
    certified rung by ``dataclasses.replace``: ``max_model_len`` = the ladder
    window, ``max_num_seqs`` = the rung's S, ``window_source`` =
    ``rung_probe.LADDER_WINDOW_SOURCE``, ``seqs_source`` = ``"model_budget"``
    when S IS the budget's identity S at that window, else ``"override"`` —
    TRUE to every existing predicate (``overridden``, ``is_identity == False``,
    ``over_budget == False``); the WHY is the rung's separate ``rung_source``.
    Then :func:`ladder_budget_record`, which refuses everything the ladder must
    not serve. ``(geometry, record)``.

    Under ``lora_native`` the rung's S is the ENGINE-SERVED S
    (the certificate's accepted S, the store identity's) and the geometry's ``max_num_seqs`` is the REQUESTED
    rung the standup is ASKED for it (``rung_probe.requested_rung_for``: served 15 <- 18, the budget's
    identity S; 14 <- 14), so the engine's own kernel step lowers it to the served S and RECORDS the step —
    the reading the scoring driver re-derives from the record's budget (``served_capability_run.
    _geometry_block``) — and ``seqs_source`` is read against the budget's identity, as on every native
    standup. Under ``lens`` every line is byte-identical."""
    rung = cfg["ladder_rung"]
    base = configuration_geometry(cfg, 1, tree)
    L, S = int(rung["max_model_len"]), int(rung["max_num_seqs"])
    serving_path = serving_path_of(cfg)
    if is_native_path(serving_path):
        # an S off the served ladder falls through to ladder_budget_record's refusal, by name
        spec = ladder_spec_for(base, serving_path)
        S_ask = RP.requested_rung_for(spec, S) if S in spec.seqs else S
        geom = dataclasses.replace(base, max_model_len=L, max_num_seqs=S_ask, window_source=RP.LADDER_WINDOW_SOURCE,
                                   seqs_source=RP.seqs_source_for(S_ask, int(spec.requested_identity_S)))
        return geom, ladder_budget_record(geom, rung, tree, serving_path=serving_path)
    geom = dataclasses.replace(base, max_model_len=L, max_num_seqs=S,
                               window_source=RP.LADDER_WINDOW_SOURCE)
    # (lens) the identity the rung's S is read against is the budget's S (geom.identity_S), read off the
    # configuration's plan marker (serving_path_of; E54 #6)
    geom = dataclasses.replace(geom, seqs_source=RP.seqs_source_for(S, ladder_identity_S(geom, serving_path)))
    return geom, ladder_budget_record(geom, rung, tree, serving_path=serving_path)


def ladder_spec_of(geom_or_row) -> "RP.LadderSpec":
    """bcb-bfcl-200-widen S6: the MODEL's ladder for a resolved geometry or a
    registry row — ``rung_probe.ladder_spec(model_key)``; a provisional budget refuses there
    (qwen35_4b until S6e), so the gate never sizes a ladder from another model's numbers."""
    key = getattr(geom_or_row, "model_key", None)
    if not key:
        raise LadderGeometryRefused("the ladder needs a model key to size from (geometry.model_key is empty)")
    try:
        return RP.ladder_spec(str(key))
    except RP.LadderError as e:
        raise LadderGeometryRefused(str(e)) from None


def ladder_spec_for(geom_or_row, serving_path: str) -> "RP.LadderSpec":
    """The ladder a launch on ``serving_path`` walks:
    the MODEL's lens ladder (:func:`ladder_spec_of`, byte-identical) under ``lens``; under
    ``lora_native`` the ENGINE-SERVED ladder ``rung_probe.native_ladder_spec`` derives from it — every
    requested rung through the pre-computed LoRA kernel ceiling step (the same step
    :func:`expected_geometry_for` applies to every native configuration), the rungs that collapse onto
    one served S coalesced (gemma at 32,768: 18 and 16 -> 15; served (15, 14, 12), identity 15), the
    engine and the mapping in the spec's ``block()``. The native sizing's refusals (a model with no
    pinned width, every rung below the floor) are :class:`LadderGeometryRefused`, by name — the ONE
    narrow refusal of a native ladder; nothing else about it refuses for being native."""
    spec = ladder_spec_of(geom_or_row)
    if not is_native_path(serving_path):
        return spec
    try:
        return RP.native_ladder_spec(spec)
    except RP.LadderError as e:
        raise LadderGeometryRefused(f"{SERVING_PATH_FLAG} {SERVING_PATH_LORA_NATIVE}: {e}") from None


def ladder_identity_S(geom, serving_path: str) -> int:
    """The identity S a ladder rung's ``seqs_source`` / ``rung_source`` are read against: the budget's
    (``geom.identity_S``) on the lens, the engine-served identity on the native engine."""
    if not is_native_path(serving_path):
        return int(geom.identity_S)
    return int(ladder_spec_for(geom, serving_path).identity_S)


def ladder_budget_record(geom, rung: Mapping, tree: Optional[str] = None, *,
                         serving_path: str = SERVING_PATH_LIBRARY_DEFAULT) -> dict:
    """The ladder's gate and record. REFUSES
    (:class:`LadderGeometryRefused`) unless: the geometry was sized from the
    model's OWN MEASURED budget row (``geom.budget.per_model and
    geom.budget.measured`` — a provisional or default budget refuses: the ladder
    serves nothing the model did not measure); ``max_model_len ==
    rung_probe.LADDER_WINDOW``; ``max_num_seqs in LADDER_SEQS``; ``S x L <=`` the
    budget; ``window_source`` is the ladder's; the rung's ``seqs_source`` and
    ``rung_source`` are the geometry's and consistent with S (``identity`` <=>
    ``S == identity_S`` <=> ``model_budget``; ``probe`` / ``operator`` <=> ``S <
    identity_S`` <=> ``override``, ``ladder_reduced_s: True``, intentionally
    non-identity). The record is :func:`model_budget_record`'s fields
    (:func:`budget_record_fields`) plus ``rung_source``, ``ladder_window``,
    ``ladder_seqs``, ``identity_max_num_seqs``, ``ladder_reduced_s``. The
    ORDINARY :func:`model_budget_record` refusal is untouched: an ``"override"``
    geometry outside the ladder path still refuses there.

    ``serving_path``: the ladder the rung is held to
    is the ENGINE's — the model's lens ladder by default (byte-identical), the engine-served ladder
    (:func:`ladder_spec_for`) under ``lora_native``, whose rungs and identity are the S the native
    standup SERVES; the record then also names the engine, the requested ladder and the mapping."""
    sg = _geometry_module(tree)
    rb = getattr(geom, "budget", None)
    if rb is None or not rb.per_model or not rb.measured:
        raise LadderGeometryRefused(
            f"the ladder serves only a MEASURED model budget row; S {geom.max_num_seqs} at window "
            f"{geom.max_model_len} was sized from {getattr(rb, 'source', None)!r} "
            f"(model_key={geom.model_key!r}) — a provisional or Llama-default budget is refused")
    native = is_native_path(serving_path)
    spec = ladder_spec_for(geom, serving_path)       # the MODEL's rungs (S6), on THIS launch's engine
    L, S = int(geom.max_model_len), int(geom.max_num_seqs)
    if native:
        # under native the RUNG's S (the certificate's accepted S, the store identity's) is the engine-SERVED
        # S and the geometry's S is the requested rung the standup is ASKED for it; on the lens the two
        # are one number and every line below reads as before
        S_rung = rung.get("max_num_seqs")
        if isinstance(S_rung, bool) or not isinstance(S_rung, int) or S_rung < 1:
            raise LadderGeometryRefused(f"ladder rung max_num_seqs {S_rung!r} is not a positive int")
        S = int(S_rung)
    if L != spec.window:
        raise LadderGeometryRefused(f"ladder window {L} != LADDER_WINDOW {spec.window}")
    if S not in spec.seqs:
        raise LadderGeometryRefused(f"ladder S {S} is not on the ladder {list(spec.seqs)}")
    S_ask = RP.requested_rung_for(spec, S) if native else S
    if native and int(geom.max_num_seqs) != S_ask:
        raise LadderGeometryRefused(
            f"the geometry asks the standup S {geom.max_num_seqs}, not the requested rung {S_ask} the {ENGINE_LORA_NATIVE} "
            f"engine serves at the rung's S {S} (rung_probe.requested_rung_for: the budget's rung a served rung stands for)")
    if S_ask * L > rb.batched_token_budget:
        raise LadderGeometryRefused(
            f"S x L = {S_ask} x {L} = {S_ask * L:,} > the measured budget {rb.batched_token_budget:,}")
    if geom.window_source != RP.LADDER_WINDOW_SOURCE:
        raise LadderGeometryRefused(f"window_source {geom.window_source!r} != {RP.LADDER_WINDOW_SOURCE!r}")
    ident = int(spec.identity_S) if native else int(geom.identity_S)     # the engine-served identity under native
    src = rung.get("rung_source")
    if src not in RP.RUNG_SOURCES:
        raise LadderGeometryRefused(f"rung_source {src!r} not in {list(RP.RUNG_SOURCES)}")
    want_seqs = RP.seqs_source_for(S, ident)
    if native and RP.seqs_source_for(S_ask, int(spec.requested_identity_S)) != want_seqs:
        raise LadderGeometryRefused(
            f"the served rung S {S} (identity {ident}) and the requested rung S {S_ask} (identity "
            f"{spec.requested_identity_S}) disagree on seqs_source — a torn requested -> served mapping")
    if geom.seqs_source != want_seqs or rung.get("seqs_source") != want_seqs:
        raise LadderGeometryRefused(
            f"seqs_source (geometry {geom.seqs_source!r}, rung {rung.get('seqs_source')!r}) != {want_seqs!r} "
            f"for S {S} at identity S {ident}")
    if src == RP.RUNG_SOURCE_IDENTITY and S != ident:
        raise LadderGeometryRefused(f"rung_source {src!r} but S {S} != identity S {ident}")
    if src != RP.RUNG_SOURCE_IDENTITY and S >= ident:
        raise LadderGeometryRefused(f"rung_source {src!r} but S {S} is not below identity S {ident}")
    rec = budget_record_fields(geom, rb, sg)
    rec.update(rung_source=src, ladder_window=spec.window, ladder_seqs=list(spec.seqs),
               identity_max_num_seqs=ident, ladder_reduced_s=bool(S < ident), ladder_model_key=spec.model_key)
    if native:
        # the native ladder's record: the engine, the requested ladder the served rungs were mapped from,
        # the mapping and the requested rungs THIS served rung stands for
        rec.update({SERVED_ENGINE_FIELD: ENGINE_LORA_NATIVE, "ladder_requested_seqs": list(spec.requested_seqs),
                    "ladder_requested_identity_S": int(spec.requested_identity_S),
                    "ladder_served_rungs": spec.block()["served_rungs"],
                    "ladder_requested_for_S": [int(r) for s_, reqs in spec.served_rungs if int(s_) == S for r in reqs],
                    # the served S this rung IS and the requested S the standup is asked for it
                    "ladder_served_max_num_seqs": S, "ladder_requested_max_num_seqs": S_ask})
        if S_ask < int(spec.requested_identity_S):
            # the §1.8 record of the ladder's DELIBERATE reduction (geometry.ladder_reduction_record: the budget's
            # identity S -> the requested rung asked, on the requested ladder, why) — what the scoring driver composes
            # into the standup's block before the adjustment contract runs, so a rung below the identity re-derives
            # from the identity S instead of reading as "a smaller S with no step"; the identity rung records none
            make = getattr(sg, "ladder_reduction_record", None)
            if not callable(make):
                raise LadderGeometryRefused(
                    f"the tree's geometry module has no ladder_reduction_record — a {ENGINE_LORA_NATIVE} ladder rung below "
                    "the budget's identity S cannot be recorded for the scoring driver on this tree (native-serving-default "
                    "review r3); stage a tree that carries geometry.LADDER_REDUCTION_KEY")
            try:
                rec[GEOMETRY_LADDER_REDUCTION_KEY] = make(identity_S=int(spec.requested_identity_S), requested_S=S_ask,
                                                          max_model_len=L, ladder_seqs=spec.requested_seqs, rung_source=src)
            except ValueError as e:
                raise LadderGeometryRefused(f"the ladder reduction record does not hold: {e}") from None
    return rec


def measured_footprint_reserves(cfg: Mapping, geom, pass_no: int,
                                tree: Optional[str] = None) -> List[Dict[str, object]]:
    """The configuration's geometry keys whose entry is MEASURED but is being
    served at the certified MEASUREMENT FOOTPRINT anyway. ``pass1_geometry``
    serves a measured tinycap entry at the footprint so a pass-1 re-run can
    EXTEND its ledger (``window_source`` = ``geometry.MEASUREMENT_SOURCE``,
    ``ResolvedGeometry.measurement_pass``) — a bigger window and a smaller S
    than the entry's own measurement says it needs, which is real, redundant
    GPU spend. It must be NAMED rather than left to be inferred from a window
    number, so this returns one record per such key — the key, the measured
    L x S ``resolve_geometry`` gives it, the footprint L x S it is served at —
    for the run log (:func:`log_measured_footprint`) and the REC. Empty for a
    pass 2 (the measured window IS what is served), for a MATH-only pass 1
    (served at MATH's own window, not the footprint), for a still-PROVISIONAL
    key (nothing measured for the footprint to be redundant against) and for
    an informational one (no launcher serves it)."""
    sg = _geometry_module(tree)
    if int(pass_no) != 1 or not getattr(geom, "measurement_pass", False):
        return []
    mk = getattr(geom, "model_key", None)        # size both readings from what this run serves
    out: List[Dict[str, object]] = []
    for key in cfg["geometry_keys"]:
        try:
            served = sg.pass1_geometry(key, model_key=mk)
        except ValueError:
            continue                        # informational, or not a tinycap sub-entry
        if served.window_source != sg.MEASUREMENT_SOURCE:
            continue                        # still provisional: nothing measured to compare
        rec: Dict[str, object] = {"key": key, "window_source": served.window_source,
                                  "served_max_model_len": served.max_model_len,
                                  "served_max_num_seqs": served.max_num_seqs}
        try:
            measured = sg.resolve_geometry(key, strict_identity=True, model_key=mk)
        except ValueError as e:             # a measured entry that will not resolve: say so
            rec.update(measured_max_model_len=None, measured_max_num_seqs=None, error=str(e))
        else:
            rec.update(measured_max_model_len=measured.max_model_len,
                       measured_max_num_seqs=measured.max_num_seqs)
        out.append(rec)
    return out


def log_measured_footprint(records: Sequence[Mapping[str, object]]) -> List[str]:
    """One line per :func:`measured_footprint_reserves` record — printed to the
    run log and returned. Nothing at all when no key is in that position, so a
    quiet log means every key is served at the window it was measured for."""
    lines = [
        f"[geometry] {r['key']}: MEASURED entry re-served at the certified measurement "
        f"footprint ({r['window_source']}) — measured "
        + (f"{r['measured_max_model_len']} x {r['measured_max_num_seqs']}"
           if r.get("measured_max_model_len") else f"UNRESOLVED ({r.get('error')})")
        + f", served {r['served_max_model_len']} x {r['served_max_num_seqs']}; the pass-1 re-run "
          "extends this entry's ledger and the difference is redundant GPU spend"
        for r in records]
    for line in lines:
        print(line, flush=True)
    return lines


# --------------------------------------------------------------------------- #
# argv builders (pure; tested)                                                 #
# --------------------------------------------------------------------------- #


def _free_port() -> int:
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return int(s.getsockname()[1])


def _standup_cmd(tree: str, cfg_path: str, cell: "str | Sequence[str]", ddir: str, srv: Path, stop: Path,
                 geom, top_logprobs: int, extra: Sequence[str], *,
                 object_sha256: str = "", object_sha256_by_cell: Optional[Mapping[str, str]] = None,
                 declared: bool = False,
                 text_only_mm: bool = False, mamba_contract: Optional[str] = None,
                 allow_over_budget: bool = False,
                 serving_path: str = SERVING_PATH_LIBRARY_DEFAULT,
                 adapter_bank: Optional[str] = None,
                 kv_derived_seqs: bool = True) -> List[str]:
    """The standup argv with the RESOLVED geometry (never a literal window) and
    the configuration's extra flags (``--tool-calls --manifest …`` for BFCL,
    ``--reasoning-parser gemma4`` under thinking-ON). The dims travel
    EXPLICITLY — a provisional entry cannot be re-derived by the standup from
    ``--eval`` (its resolver refuses provisional entries) — PLUS ``--model-key``
    when the geometry was sized for a model, so the standup's own budget guard
    and its ``endpoint.json`` are held to the SAME budget this resolution used.
    No ``--allow-over-budget``: S x L is the model's budget and the identity
    holds by construction (the standup would refuse otherwise).

    ``object_sha256`` (E40 H1) is the preflight-verified sha256 of the fitted
    cell's artifact; it travels as :data:`OBJECT_DIGEST_FLAG` and the standup
    compares it against the bytes it copies into the worker registry — the
    bytes the server loads — refusing a swap made after the preflight.

    ``top_logprobs`` is the ROW's letter-read width (§PW-nanfix-2), passed
    here as the server's ``--max-logprobs`` and to the driver as
    ``--top-logprobs``: ONE number, because vLLM 400s a request whose
    ``top_logprobs`` exceeds the server's ceiling.

    ``declared``: the thinking-ON out-of-support standup of a lens cell — the ONE
    place the launcher composes ``--cell`` and the digest flag, so the mapping
    ``(ON, out of support, lens cell) -> <cell>@thinking`` lives here and nowhere
    else: ``--cell`` takes the VARIANT spelling
    (``safety_refusal__psr_kl_all@thinking``) ALONE — ``none`` is NOT added
    (``bring_up`` prepends the base cell and ``enumerate_cells`` derives the
    twin ``none__lens0``, declared with its donor) — and the digest flag takes
    the keyed form ``<that spelling>=<artifact sha256>`` (``OOS_EXPECT_SHA_KEY``;
    the sha is the ARTIFACT's, identical for base and variant). Undeclared
    (every OFF standup, every ``none`` standup, every in-support run): the
    bare cell and the bare sha, byte for byte as before.

    EVERY tinycap standup carries ``contracts.FLAG_UPSTREAM_TIMEOUT_S
    <contracts.PROXY_UPSTREAM_TIMEOUT_S>`` — the proxy's UPSTREAM (proxy -> vLLM)
    timeout, the SAME number as the driver's aiohttp client, the ledger's
    upstream call and the Inspect provider's request timeout — in the FIXED
    part of the argv (after ``--ready-timeout-s``, before the digest and the
    extras). Without it the proxy kept its own 600 s default under a 7,200 s
    client: a cap-bound thinking-ON draw on the slower steered route was
    504'd and re-sampled while the base route's at-cap draws completed —
    differential censoring of the steered leg.

    EVERY tinycap standup also carries
    ``contracts.FLAG_ENABLE_LOG_REQUESTS`` right after the timeout — vLLM then logs
    each request's ENGINE-RESOLVED ``SamplingParams`` (never the prompt), which the
    worker reads back into the store root after the driver
    (:func:`record_resolved_sampler`). Fixed, not an extra: unhashed by design.

    EVERY standup also carries ``STANDUP_KV_DERIVED_SEQS_FLAG on`` in the fixed
    part (a valued pair, right after ``--gpu-mem-util``): the standup serves the
    configured S when the container's KV cache backs it and floor(the reported
    KV-backed concurrency) when it does not, recording the shrink; the launcher reads
    that record back (:func:`served_geometry_of_endpoint`) and refuses anything else.

    ``text_only_mm`` / ``mamba_contract`` / ``allow_over_budget``: the zero-image /
    zero-video multimodal pin (the IFEval rows of :data:`TEXT_ONLY_MM_FAMILIES`), the
    STAGED tree's reviewed Nemotron contract the standup attests against (a
    ``nemotron_h`` row) and — the Nemotron probe's PEER standup and the budget
    MEASUREMENT only — the over-budget allowance; every other launch's argv is
    byte-identical.

    EVERY standup states its serving PATH —
    ``--serving-path lora_native | lens`` in the FIXED part, right after the readback flag and
    before the digest and the extras. Stated on the lens launch too, deliberately: the standup's
    own default is native since this landing, so a lens launch that omitted the flag would
    silently stand up the other engine ("nothing silently falls back"); a pre-flip staged tree,
    whose standup takes no such flag, is refused by the preflight (``standup_accepts_flags``)
    rather than launched. Under native the argv ALSO carries ``--adapter-bank <root>/<model key>``
    (:func:`adapter_bank_for`: the deterministic default the core's ``resolve_adapter_bank`` would
    derive from the container's SISTEER_ADAPTER_BANK_ROOT, stated so ``endpoint.json.adapter_bank``
    records it) — required there, refused on a lens standup.

    ``kv_derived_seqs``: the KV-derived-S flag's VALUE — ``on`` (the default; every non-ladder
    argv byte-identical) or ``off``, which the truncation LADDER composes for EVERY ladder standup
    on BOTH engines: the rung PROBE (on the native and the lens probe alike — a KV shortfall must
    REFUSE readiness there, the verdict the ladder steps down on, rather than come up at a shrunk S
    the certificate then names as the requested one) and every ladder SCORING standup, whose rung
    is the certificate's and never steps down (a shortfall is a named STANDUP_FAILED before the
    driver, not a store at an S the merge then refuses). A probe's certificate and the scoring
    standup that consumes it thus share ONE fixed-rung policy.

    tinycap-shared-standup §1.2: ``cell`` may be a SEQUENCE — the cells of one ROW standup. Then the
    argv carries one ``--cell <c>`` per cell (``none`` first when present, the caller's order
    otherwise) in the cell slot and one keyed ``--expect-object-sha256 <cell>=<sha>`` per FITTED
    cell from ``object_sha256_by_cell`` in the digest slot (the keyed form the standup already
    parses, ``capctrl_serving_up.parse_object_digest_args``); a fitted cell without a digest, a
    digest keyed to a cell that is not served, a bare ``object_sha256`` or ``declared`` beside
    several cells refuse before any Popen. A scalar ``cell`` composes today's argv byte for byte."""
    serving_path = check_serving_path_arg(serving_path)
    multi = not isinstance(cell, str)
    if multi:
        cells = [str(c) for c in cell]
        if not cells:
            raise ValueError("a row standup needs at least one cell — none was given")
        if len(set(cells)) != len(cells):
            raise ValueError(f"a row standup names a cell twice: {cells}")
        if declared:
            raise ValueError(f"a DECLARED standup serves one cell (the @thinking spelling); {cells} were offered "
                             "together — a row standup is undeclared by construction")
        if object_sha256:
            raise ValueError(f"a row standup takes its digests KEYED per fitted cell (object_sha256_by_cell), not "
                             f"the bare object_sha256 {object_sha256[:12]}…")
        if "none" in cells:
            cells = ["none"] + [c for c in cells if c != "none"]
        by_cell = {str(k): str(v) for k, v in dict(object_sha256_by_cell or {}).items()}
        fitted = [c for c in cells if is_steered(c)]
        missing = [c for c in fitted if not by_cell.get(c)]
        if missing:
            raise ValueError(f"fitted cell(s) {missing} of this row standup have no preflight-verified artifact "
                             f"sha256 ({OBJECT_DIGEST_FLAG} <cell>=<sha>) — every fitted cell is held to its digest "
                             "(E40 H1) or not served")
        stray = sorted(set(by_cell) - set(fitted))
        if stray:
            raise ValueError(f"digest(s) offered for {stray}, which are not fitted cells of this row standup "
                             f"{cells} — a wiring error, not a launch")
        bad = [c for c in fitted if not C.is_sha256_hex(by_cell[c])]
        if bad:
            raise ValueError(f"the digest(s) of {bad} are not 64-hex sha256 values")
    if is_native_path(serving_path):
        if not adapter_bank:
            raise ValueError(f"a {SERVING_PATH_LORA_NATIVE} standup needs its adapter bank ({ADAPTER_BANK_FLAG} "
                             f"{ADAPTER_BANK_ROOT}/<model key>; adapter_bank_for(geom.model_key)) — none was given")
    elif adapter_bank:
        raise ValueError(f"{ADAPTER_BANK_FLAG} {adapter_bank!r} was offered to a lens standup — the bank is the "
                         "native engine's; a wiring error, not a launch")
    bank = [ADAPTER_BANK_FLAG, str(adapter_bank)] if adapter_bank else []
    model_key = ["--model-key", str(geom.model_key)] if getattr(geom, "model_key", None) else []
    if multi:
        cell_args = [tok for c in cells for tok in ("--cell", c)]
        digest = [tok for c in fitted for tok in (OBJECT_DIGEST_FLAG, f"{c}={by_cell[c]}")]
    else:
        cell_args = ["--cell", cell]
        digest = [OBJECT_DIGEST_FLAG, str(object_sha256)] if object_sha256 else []
    if declared:
        sp = C.cell_spellings(cell, declared=True)
        cell_args = ["--cell", sp.traintest]
        if not object_sha256:
            raise ValueError(
                f"a declared standup of {cell!r} needs the preflight-verified artifact sha256 "
                f"({OBJECT_DIGEST_FLAG} {sp.expect_key}=<sha>) — none was given")
        digest = [OBJECT_DIGEST_FLAG,
                  (f"{sp.expect_key}={object_sha256}" if sp.expect_key else str(object_sha256))]
    return [sys.executable, f"{tree}/scripts/capctrl_serving_up.py",
            "--repo-dir", tree, "--config", cfg_path, *cell_args,
            "--defenses-dir", ddir, "--out", str(srv), "--stop-file", str(stop),
            "--max-model-len", str(geom.max_model_len),
            "--max-num-seqs", str(geom.max_num_seqs), *model_key,
            "--max-logprobs", str(int(top_logprobs)),
            "--gpu-mem-util", "0.90", STANDUP_KV_DERIVED_SEQS_FLAG, ("on" if kv_derived_seqs else "off"),
            "--ready-timeout-s", "2700",
            # EVERY tinycap standup carries the proxy's UPSTREAM timeout — the
            # SAME number as the driver's aiohttp client, the ledger and the
            # Inspect provider — in the FIXED part of the argv (after
            # --ready-timeout-s, before the digest and the extras). Without it
            # the proxy kept its own 600 s default under a 7,200 s client: a
            # cap-bound draw on the slower steered route was 504'd and
            # re-sampled while the base route's at-cap draws completed
            C.FLAG_UPSTREAM_TIMEOUT_S, f"{C.PROXY_UPSTREAM_TIMEOUT_S:g}",
            # EVERY tinycap standup asks vLLM to log the RESOLVED SamplingParams
            # of each request (one INFO line, no prompt) — the engine's own attestation
            # of the decode column, read back after the driver by
            # scripts/sdfbase/record_resolved_sampler.py into the store root
            # (contracts.RESOLVED_SAMPLER_FILENAME). In the FIXED part, like the timeout:
            # a log level changes no decoding, so it is not a per-configuration extra and
            # the hashed served identity gains nothing; endpoint.json records the opt-in.
            C.FLAG_ENABLE_LOG_REQUESTS,
            # native-serving-default (§1.7 / §1.9): the serving path, stated on EVERY standup (see the
            # docstring), then the adapter bank under native — still before the digest and the extras
            SERVING_PATH_FLAG, serving_path, *bank,
            *digest, *extra,
            # For the IFEval rows: the zero-image / zero-video multimodal pin
            # (qwen3_5), the STAGED tree's reviewed Nemotron contract the standup
            # attests against (composed for a nemotron_h row; the launcher refuses
            # NEMO_BACKEND_UNATTESTED without one), and — the probe's PEER standup and
            # the budget MEASUREMENT (scripts/modal/tinycap_budget_measure.py)
            # only — the over-budget allowance; every other launch's argv is byte-identical
            *([STANDUP_TEXT_ONLY_MM_FLAG, "on"] if text_only_mm else []),
            *([STANDUP_MAMBA_CONTRACT_FLAG, str(mamba_contract)] if mamba_contract else []),
            *(["--allow-over-budget"] if allow_over_budget else [])]


def served_geometry_of_endpoint(endpoint: Mapping, geom, *, ladder_record: Optional[Mapping] = None
                                ) -> Tuple[object, Optional[Mapping], Optional[str]]:
    """The geometry the standup SERVED, read off its ``endpoint.json``:
    ``(served geometry, the kv_shrink record or None, a problem or None)``.

    ``ladder_record``: a truncation-ladder rung's record
    (:func:`ladder_budget_record`, the reduction at its top) — given, a NATIVE record is read the way the
    scoring driver reads it (:func:`native_ladder_geometry_problem`: the record's own budget's identity S,
    the launcher's reduction composed, the standup's steps from the requested rung it was asked) instead of
    against the S this launcher asked; a rung asked below the budget's identity records ``identity: False``
    with no step of its own, which the asked-S framing read as torn and the production framing reads as
    the reduction. Absent (every other standup), byte-identical.
    The configured S when the record's geometry equals the resolved one; the
    KV-derived S when the geometry block carries a ``kv_shrink`` record that
    holds the rule against THIS run's configured numbers
    (``geometry.kv_shrink_problem``: floor of the reported concurrency, below the
    configured S, at this window, equal to the S served). Anything else — another
    window, another S with no record, a record that does not hold — is a problem
    the caller refuses (``REC_SERVED_GEOMETRY_MISMATCH``), never a value read
    around. PW5-4: the served S is store identity, so the served geometry is what
    the expectation, the driver's ``--concurrency`` and the resume decision are
    re-derived from.

    ONE geometry-adjustment contract: a record that carries
    ``geometry.adjustments`` (the native core's ordered list: ``[]``, ``[kernel]``, ``[kv]`` or
    ``[kernel, kv]``) is judged through :func:`geometry_adjustment_problem` — every step
    re-derived (the kernel step from the model's widest adapted module, the window and the
    identity S; the KV step through ``kv_shrink_problem`` against the PREVIOUS step's S) and the
    served S required to be the LAST step's ``to_S``. The kernel lowering (gemma 121 -> 107,
    nemotron 161 -> 86 at L 4864) is NOT a KV shrink and is never read as one; ``[kv]`` alone and a
    record without the key read exactly as today (byte-identical); anything malformed is a named
    problem, never "a smaller S"."""
    from sisteer.capeval.serving import geometry as sg
    g = endpoint.get("geometry") if isinstance(endpoint, Mapping) else None
    if not isinstance(g, Mapping):
        return geom, None, "endpoint.json has no geometry block"
    L_, S_ = g.get("max_model_len"), g.get("max_num_seqs")
    if L_ != int(geom.max_model_len):
        return geom, None, f"the standup served max_model_len={L_!r}, not the resolved {geom.max_model_len}"
    shrink = g.get(sg.KV_SHRINK_KEY)
    adjustments = g.get(GEOMETRY_ADJUSTMENTS_KEY)
    # the ENGINE the record itself attests decides the "present iff it lowers" half of the kernel
    # rule (W-A's `native=`): a native record must carry the kernel step wherever the formula
    # lowers — whether it spells `adjustments: []` or omits the key — and a lens record may carry
    # no kernel step at all. A torn engine spelling is a problem before any geometry is read.
    try:
        native_record = endpoint_is_native(endpoint)
    except ValueError as e:
        return geom, shrink, f"the standup record's engine cannot be read: {e}"
    if adjustments is not None or native_record:
        if adjustments is not None and not isinstance(adjustments, list):
            return geom, None, f"the standup's geometry.{GEOMETRY_ADJUSTMENTS_KEY} is not a list: {adjustments!r}"
        if adjustments is not None and not adjustments and shrink is not None:
            return geom, None, (f"the standup records geometry.{GEOMETRY_ADJUSTMENTS_KEY} = [] beside a "
                                f"{sg.KV_SHRINK_KEY} record — a shrink is an adjustment; the record contradicts itself")
        if ladder_record is not None and native_record:
            problem = native_ladder_geometry_problem(endpoint, geom, ladder_record, sg=sg)
            if problem:
                return geom, shrink, (f"the scoring driver would refuse this standup record (§1.8, the production reading "
                                      f"from the budget's identity S): {problem}")
        else:
            problem = geometry_adjustment_problem(g, model_key=getattr(geom, "model_key", None),
                                                  L=int(geom.max_model_len), S_identity=int(geom.max_num_seqs),
                                                  S_served=S_, sg=sg, native=native_record, served_lora=endpoint_served_lora(endpoint))
            if problem:
                return geom, shrink, f"the standup's geometry.{GEOMETRY_ADJUSTMENTS_KEY} do not hold: {problem}"
        # the steps as recorded (W-A's reader derives the ONE kv step from a pre-contract record
        # that carries only `kv_shrink`; the launcher's fallback reads the list verbatim)
        steps_of = getattr(sg, "geometry_adjustments", None)
        steps = list(steps_of(g)) if callable(steps_of) else list(adjustments or [])
        served = geom
        for adj in steps:
            if adj.get("kind") == ADJUSTMENT_LAUNCH_CLASS:
                # the class step, validated above against the pinned record: S -> the class-specific to_S with seqs_source "override" —
                # EXACTLY what the native standup records when it applies it (native_standup.launch_class_geometry); never the KV path
                served = _with_seqs_source(served, int(adj["to_S"]), "override")
            elif adj.get("kind") == ADJUSTMENT_KERNEL:
                served = _with_seqs(served, int(adj["to_S"]))          # the budget's S, kernel-lowered
            else:
                # the KV step from the PREVIOUS S: the top-level record when the standup wrote one
                # (held equal to the step by the validator), else the step's own inline record
                served = sg.kv_shrunk_geometry(served, shrink if shrink is not None else adj)
        return served, (shrink if shrink is not None else None), None
    if shrink is None:
        if S_ != int(geom.max_num_seqs):
            return geom, None, (f"the standup served max_num_seqs={S_!r}, not the resolved "
                                f"{geom.max_num_seqs}, and records no {sg.KV_SHRINK_KEY}")
        return geom, None, None
    problem = sg.kv_shrink_problem(shrink, configured_max_num_seqs=int(geom.max_num_seqs),
                                   max_model_len=int(geom.max_model_len), served_max_num_seqs=S_)
    if problem:
        return geom, shrink, f"the standup's {sg.KV_SHRINK_KEY} record does not hold: {problem}"
    return sg.kv_shrunk_geometry(geom, shrink), shrink, None


def served_geometry_record(record: Mapping, geom_served, shrink: Optional[Mapping],
                           adjustments: Optional[Sequence[Mapping]] = None) -> Dict[str, object]:
    """The REC's ``geometry`` block (``served_geometry.json``'s too) re-stated
    at the KV-derived S: ``max_num_seqs`` / ``batched_tokens`` / ``identity`` /
    ``seqs_source`` become the SERVED ones, the asked S moves to
    ``configured_max_num_seqs``, and the standup's ``kv_shrink`` record rides
    beside them — so the driver's cross-check of this record against the standup's
    endpoint (``_geometry_block``) agrees and the report tables served L x S.

    native-serving-default (§1.8): a standup whose ``geometry.adjustments`` account for the
    served S is re-stated the same way, the validated list copied whole (``adjustments``) and
    the ``kv_shrink`` record beside it only when a KV step fired; ``seqs_source`` stays the
    budget's on a kernel-only lowering (the adjustment is applied to the budget's S)."""
    from sisteer.capeval.serving import geometry as sg
    out = dict(record)
    out.update({"configured_max_num_seqs": int(record["max_num_seqs"]),
                "max_num_seqs": int(geom_served.max_num_seqs),
                "batched_tokens": int(geom_served.batched_tokens),
                "identity": bool(geom_served.is_identity),
                "seqs_source": geom_served.seqs_source})
    if shrink is not None:
        out[sg.KV_SHRINK_KEY] = dict(shrink)
    if adjustments is not None:
        out[GEOMETRY_ADJUSTMENTS_KEY] = [dict(a) for a in adjustments]
    return out


def served_lxs(endpoint: Mapping, geom) -> Dict[str, object]:
    """The served L x S off a standup's endpoint (the configured S beside it, and
    the kv_shrink record when the standup shrank) — for records that table the
    served geometry (the Nemotron probe's duty bursts)."""
    g = endpoint.get("geometry") if isinstance(endpoint, Mapping) else None
    g = g if isinstance(g, Mapping) else {}
    return {"max_num_seqs": int(g.get("max_num_seqs", geom.max_num_seqs)),
            "max_model_len": int(g.get("max_model_len", geom.max_model_len)),
            "configured_max_num_seqs": int(geom.max_num_seqs), "kv_shrink": g.get("kv_shrink")}


def client_width(served_seqs: int, concurrency_k: int = 1) -> int:
    """tinycap-shared-standup §2.1: the driver's ``--concurrency`` (the hashed ``served.concurrency``) at a served S
    under K concurrent cell drivers — ``S // K``, never below 1. K = 1 is today's derivation (the served S itself),
    so every solo store and every landing-1 row store keys exactly as before; a K > 1 store keys DIFFERENTLY (S9:
    the gate compares no ``concurrency``)."""
    k = int(concurrency_k)
    if isinstance(concurrency_k, bool) or k < 1:
        raise ValueError(f"concurrency_k must be a positive int, got {concurrency_k!r}")
    return max(1, int(served_seqs) // k)


def expected_at_served_seqs(expected: "ExpectedIdentity", served_seqs: int, *, concurrency_k: int = 1) -> "ExpectedIdentity":
    """``expected`` at another SERVED S: ``served.max_num_seqs`` and the
    client width ``served.concurrency`` (the driver's ``--concurrency`` IS the served
    S — ``_driver_cmd``) move together; nothing else in the identity reads S
    (``expected_identity``'s derivations — held by test). The one substitution the
    post-standup re-derivation and the pre-standup store tolerance both make.
    ``concurrency_k``: under K > 1 the width is :func:`client_width` of
    the served S; K = 1 is byte-identical to before."""
    s_ = int(served_seqs)
    # tinycap-shared-standup: a client width BELOW the served S (a row engine driven at S // K) is kept;
    # today's runs (concurrency == the configured S >= the served S) read s_ exactly as before
    width = (min(int(expected.served["concurrency"]), s_) if int(concurrency_k) == 1
             else client_width(s_, concurrency_k))
    return expected._replace(served={**expected.served, "max_num_seqs": s_, "concurrency": width})


def kv_shrink_adjusted_expectation(manifest: Mapping, expected: "ExpectedIdentity"
                                   ) -> Tuple["ExpectedIdentity", Optional[str]]:
    """PRE-STANDUP store trust under the KV-derived S: a store whose manifest
    ``geometry`` carries a ``kv_shrink`` record shrinking THIS run's configured S at
    THIS window by the rule is held to the identity AT ITS SERVED S (the served S is
    store identity; the standup this run pays for reproduces that S when the
    container's KV cache agrees, and the launcher re-takes the decision EXACTLY — no
    tolerance — once the standup has said what it serves). A record that does not
    hold is a refusal (``(expected, why)``); a store without one is held to the
    configured identity unchanged."""
    from sisteer.capeval.serving import geometry as sg
    g = manifest.get(C.MANIFEST_KEY_GEOMETRY) if isinstance(manifest, Mapping) else None
    shrink = g.get(sg.KV_SHRINK_KEY) if isinstance(g, Mapping) else None
    if shrink is None:
        return expected, None
    served = shrink.get("served_max_num_seqs") if isinstance(shrink, Mapping) else None
    problem = sg.kv_shrink_problem(shrink, configured_max_num_seqs=int(expected.served["max_num_seqs"]),
                                   max_model_len=int(expected.served["max_model_len"]),
                                   served_max_num_seqs=served)
    if problem:
        return expected, f"manifest geometry.{sg.KV_SHRINK_KEY}: {problem}"
    return expected_at_served_seqs(expected, int(served)), None


def _ledger_cmd(python: str, proxy_url: str, port: int, ledger_path: str,
                endpoint_json: str) -> List[str]:
    """The usage-ledger process (client venv, loopback) in front of the proxy."""
    return [python, "-m", "sisteer.capeval.serving.usage_ledger",
            "--upstream", proxy_url, "--port", str(int(port)), "--host", "127.0.0.1",
            "--ledger-path", ledger_path, "--endpoint-json", endpoint_json]


def oos_lens_configuration(cfg: Mapping) -> bool:
    """The configuration whose DRIVER runs a lens cell under the out-of-support
    override — exactly the condition under which ``served_capability_run``
    refuses without ``--expect-object-sha256`` (a run with neither
    the digest nor the in-support default refuses, ``OOS_DECLARATION_UNATTESTED``).
    Read off the same two facts the driver reads (the override marker the argv
    carries, the cell's route), never the arm or the controls."""
    return bool(cfg.get(C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING)) and C.is_lens_cell(cfg["cell"])


def _driver_cmd(tree: str, cfg: Mapping, endpoint: Mapping, ledger_url: Optional[str], geom,
                *, controls: Sequence[str], limit: int, inspect_limit: int, samples: int,
                cfg_path: str, vllm_log: Optional[str],
                oos_prompt_budget: Optional[str] = None,
                expect_object_sha256: Optional[str] = None,
                attempt_id: Optional[str] = None,
                protocol_check: Optional[str] = None,
                row_engine_record: Optional[str] = None,
                concurrency_k: int = 1,
                verification_phase: str = C.VERIFICATION_PHASE_COUPLED) -> List[str]:
    """``contracts.driver_argv`` for this configuration, plus — on an
    out-of-support thinking-ON configuration only — the prompt-budget artifact
    the worker wrote into the out-root, as ``contracts.FLAG_OOS_PROMPT_BUDGET
    <path>`` (the driver compares its digest to the served
    template's and its max to the live ``/v1/tokenize`` pass), and — on the
    out-of-support LENS configuration (:func:`oos_lens_configuration`) — the
    artifact digest the launcher held the standup to, as
    ``contracts.FLAG_EXPECT_OBJECT_SHA256 <64-hex>`` (the driver
    compares ``endpoint.json.object_artifact_sha256`` and the per-cell map to
    it, and REFUSES such a run told no digest — so the container would die
    after the standup was paid for were the flag left off here). Required
    there, refused anywhere else (a digest offered to a configuration whose
    driver would not compare it is a wiring error). Every other
    configuration's argv is byte-identical to before.

    A comparator configuration (``serves_offcap``) rides
    ``--allow-off-cap-override``; its LENS leg is a landed lens configuration
    (:func:`landed_lens_configuration`) and needs the digest like the
    out-of-support one; both its legs need the OFF artifact
    (:func:`needs_prompt_budget`).

    ifeval-canonical-battery follow-up (plan Appendix A): an IFEval configuration's
    line also carries the container-written prompt-budget artifact
    (:func:`needs_prompt_budget` admits it) and ``--attempt-id a<k>``, the id
    :func:`next_attempt_id` mints per driver invocation — refused on any other
    configuration (their argv stays byte-identical).

    tinycap-shared-standup landing 2: ``concurrency_k`` (§2.1) makes the client width
    :func:`client_width` of the served S (K = 1: the served S, byte-identical);
    ``verification_phase`` (§2.2.3) appends ``contracts.FLAG_VERIFICATION_PHASE <phase>``
    LAST — after the row-engine record — when it is not ``coupled``, and only in row
    mode (a ``generate`` driver writes its markers into the row dir the record names)."""
    if verification_phase not in C.VERIFICATION_PHASES:
        raise ValueError(f"{cfg.get('name', cfg['cell'])}: {C.FLAG_VERIFICATION_PHASE} {verification_phase!r} is not one of "
                         f"{list(C.VERIFICATION_PHASES)}")
    if verification_phase == C.VERIFICATION_PHASE_VERIFY:
        raise ValueError(f"{cfg.get('name', cfg['cell'])}: {C.FLAG_VERIFICATION_PHASE} {C.VERIFICATION_PHASE_VERIFY} is the CPU "
                         "verifier's subcommand (served_capability_run.py verify), never a generate driver's phase")
    if verification_phase != C.VERIFICATION_PHASE_COUPLED and not row_engine_record:
        raise ValueError(f"{cfg.get('name', cfg['cell'])}: {C.FLAG_VERIFICATION_PHASE} {verification_phase} rides a ROW launch "
                         "only (the driver writes its generation sidecar and pending marker into the row dir the "
                         f"{C.FLAG_ROW_ENGINE_RECORD} names); a solo configuration's argv stays byte-identical")
    if attempt_id is not None and not is_ifeval_configuration(cfg):
        raise ValueError(
            f"{cfg.get('name', cfg['cell'])}: {C.FLAG_ATTEMPT_ID} was offered to a configuration that is not an "
            "IFEval one — the attempt-scoped producer contract rides the IFEval cells only")
    landed_lens = landed_lens_configuration(cfg)
    # An IFEval LENS configuration's driver
    # builds every row's identity under --bank-view and refuses a lens cell
    # without the object sha (contracts.row_identity_block), so the digest rides
    # the same flag there — the fourth configuration kind that needs it
    ifeval_lens = ifeval_lens_configuration(cfg)
    digest_needed = landed_lens or ifeval_lens
    rung = bool(cfg.get("ladder_rung"))             # a truncation-ladder rung-2 configuration
    if digest_needed and not expect_object_sha256:
        raise ValueError(
            f"{cfg.get('name', cfg['cell'])}: a landed lens configuration (out of support, or the "
            f"off-cap comparator) or an IFEval lens configuration needs the artifact digest the standup "
            f"was held to ({C.FLAG_EXPECT_OBJECT_SHA256}); its driver refuses a run told none "
            f"({C.REC_OOS_DECLARATION_UNATTESTED}; contracts.row_identity_block on an IFEval lens cell)")
    if expect_object_sha256 and not digest_needed:
        raise ValueError(
            f"{cfg.get('name', cfg['cell'])}: an artifact digest was offered to a configuration "
            "whose driver would not compare it (not a landed lens configuration, not an IFEval lens "
            f"cell) — the flag rides {C.FLAG_EXPECT_OBJECT_SHA256} on the out-of-support and comparator "
            "lens legs and the IFEval lens cells only")
    if oos_prompt_budget and not needs_prompt_budget(cfg, controls):
        raise ValueError(
            f"{cfg.get('name', cfg['cell'])}: a prompt-budget artifact was offered to a "
            "configuration that serves nothing thinking-ON out of support and is not the off-cap "
            "comparator — the flag rides the out-of-support ON legs and the comparator's legs only")
    # tinycap-shared-standup §1.1.4: the row-engine record rides LAST, and ONLY in row mode — contracts.driver_argv's
    # own keyword (module F): None keeps every solo configuration's argv byte-identical
    argv = C.driver_argv(
        python=CLIENT_PY, script=f"{tree}/scripts/served_capability_run.py",
        proxy_url=endpoint["proxy_url"], routing_table=endpoint["routing_table"],
        cell=cfg["cell"], config=cfg_path, defenses_dir=row_of(cfg).objects_dir,
        out_root=cfg["out_dir"],
        # tinycap-shared-standup §2.1: the client width at K concurrent drivers (K = 1: the served S)
        controls=controls, thinking=cfg["mode"], concurrency=client_width(geom.max_num_seqs, concurrency_k),
        judge_model=JUDGE_MODEL, limit=limit, samples=samples, inspect_limit=inspect_limit,
        # §PW-nanfix-2: the ROW's letter-read width — the same number the
        # standup gave the server as --max-logprobs, so the request can never
        # ask for more than the server will return
        ledger_url=ledger_url, top_logprobs=row_of(cfg).top_logprobs, vllm_log=vllm_log,
        # PW-oos: the driver must stamp the SAME identity the launcher expects,
        # so the flag rides the argv for exactly the configurations the plan
        # marked out-of-support — never for any other
        allow_out_of_support_thinking=bool(
            cfg.get(C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING)),
        # the comparator flag rides exactly the configurations marked off-cap
        # (the driver stamps the SAME one-key identity)
        allow_off_cap_override=bool(cfg.get(OFFCAP_MARKER_KEY)),
        # fit-support transfer: the digest the standup was held to, on the
        # landed lens legs only (checked above)
        expect_object_sha256=(str(expect_object_sha256) if digest_needed else None),
        # the prompt-budget artifact's path, on the out-of-support ON legs only
        # (checked above); driver_argv appends it LAST, after the digest
        oos_prompt_budget=(str(oos_prompt_budget) if oos_prompt_budget else None),
        # bcb-bfcl-200 §S2b: the truncation ladder's rung-2 tuple, on a ladder
        # configuration only (both flags, always together; appended LAST)
        cap_override=(C.format_cap_overrides(cfg["cap_overrides_by_task"]) if rung else None),
        item_selection_json=(C.format_item_selection_json(cfg["item_selection"]) if rung else None),
        # the draw's MODE — SAMPLING_MODE_KEY (absent = the driver's default;
        # contracts.driver_argv spells --sampling iff it is not the default, so every
        # existing configuration's argv is byte-identical; an IFEval configuration rides
        # `vendor_preset`) and, under protocol, the preflight's resolved-parameter record
        # the worker wrote into the out root (contracts.PROTOCOL_CHECK_FILENAME)
        sampling_mode=sampling_mode_of(cfg),
        protocol_check=(str(protocol_check) if protocol_check else None),
        # the IFEval tail on an IFEval configuration alone
        # (ifeval_driver_kwargs: identity version 2, the cap statement, the setter + subset on a
        # rung, the bank view)
        **ifeval_driver_kwargs(cfg),
        # the follow-up (Appendix A): the attempt id, IFEval only (checked above); None -> byte-identical
        attempt_id=attempt_id, row_engine_record=(str(row_engine_record) if row_engine_record else None))
    if verification_phase != C.VERIFICATION_PHASE_COUPLED:
        # tinycap-shared-standup §2.2.3: the phase rides LAST of all, after the row-engine record; ``coupled`` (the
        # default) spells nothing, so every landing-1 row argv and every solo argv stay byte-identical
        argv += [C.FLAG_VERIFICATION_PHASE, str(verification_phase)]
    return argv


CONFIG_OVERLAY_FILENAME = "config_overlay.yaml"


def overlaid_config(row: C.ModelRow, tree: str, out_dir: Path) -> Tuple[str, Dict[str, object]]:
    """The ``--config`` path this configuration serves, and the keys that were
    overlaid onto it (empty for every complete config).

    ``configs/two_si_llama32_3b.yaml`` pins NEITHER the model revision NOR the
    layer — both are explicit ``null``, which is worse than a missing key:
    ``cell_controls.arm_spec_for_cell`` does ``int(cfg.get("layer", 15))``,
    which RAISES on ``None``, and the standup formats ``rev[:12]``. So the row
    supplies them (:func:`contracts.config_overrides`) and the launcher writes
    a COPY beside the run's other records — never an edit to the checked-in
    config, which other consumers read, and never inside the staged tree,
    whose sha is the producer identity. The overlay is a plain key replacement
    on the loaded mapping, so the resolved config the driver hashes differs
    from the checked-in one exactly in the keys named here and nowhere else."""
    overrides = dict(row.cfg_overrides)
    src = f"{tree}/{row.cfg}"
    if not overrides:
        return src, {}
    import yaml
    doc = yaml.safe_load(Path(src).read_text(encoding="utf-8"))
    missing = [k for k in overrides if k not in doc]
    if missing:
        raise KeyError(
            f"{row.cfg} has no key(s) {missing} for the {row.slug!r} registry row's overlay — "
            "an overlay REPLACES a pinned-but-null key, it never invents a new one; re-derive "
            "the row against the config that is actually staged")
    doc.update(overrides)
    out_dir.mkdir(parents=True, exist_ok=True)
    dest = out_dir / CONFIG_OVERLAY_FILENAME
    dest.write_text(yaml.safe_dump(doc, sort_keys=False), encoding="utf-8")
    return str(dest), dict(overrides)


def _wait_for(path: Path, proc: subprocess.Popen, timeout_s: float, step: float = 5.0) -> bool:
    deadline = time.time() + timeout_s
    while time.time() < deadline:
        if path.exists():
            return True
        if proc.poll() is not None:
            return path.exists()
        time.sleep(step)
    return path.exists()


def _tail(path: Path, n: int = 3000) -> Optional[str]:
    return path.read_text(errors="replace")[-n:] if path.exists() else None


def engine_core_tail(text: Optional[str], n_lines: int = 80) -> Optional[str]:
    """The ENGINE process's own lines from a vLLM server log (``(EngineCore pid=…)``), last
    ``n_lines``: the API server's "Engine core initialization failed. See root cause above"
    trace fills a 3,000-char tail while the root cause sits in the EngineCore lines above it;
    a STANDUP_FAILED record carries those lines beside the plain tail."""
    if not text:
        return None
    lines = [ln for ln in text.splitlines() if "EngineCore" in ln]
    return "\n".join(lines[-n_lines:]) if lines else None


#: The standup attestations the launcher records RAW off endpoint.json
#: (unhashed; a refusing REC still says what the standup attested), plus GLM's
#: M-RoPE dispatch report — the IFEval rows' reader gates a glm4v row on it
#: (`full22_endpoint_refusal`), and a lane with no GLM row records None there —
#: and whether the engine logged its resolved sampler (``enable_log_requests``,
#: the fixed flag attested by the standup).
FULL22_ATTESTATION_KEYS: Tuple[str, ...] = ("text_only_mm", "text_only_mm_record",
                                             "mrope_attestation", "mrope_attestation_error",
                                             "mamba_backend_attestation", "mamba_backend_attestation_error",
                                             C.ENDPOINT_KEY_ENABLE_LOG_REQUESTS)


def full22_attestation_record(endpoint: Mapping[str, object]) -> Dict[str, object]:
    """The RAW attestations off ``endpoint.json`` (unhashed; the REC carries them
    so a refusing REC still says what the standup attested)."""
    return {k: endpoint.get(k) for k in FULL22_ATTESTATION_KEYS}


def full22_endpoint_refusal(row: C.ModelRow, endpoint: Mapping[str, object], *, tree: Optional[str] = None
                            ) -> Optional[Tuple[str, str]]:
    """The post-standup gates of a lane or IFEval row, as ``(REC status, why)`` or None:
    the text-only multimodal pin for
    :data:`TEXT_ONLY_MM_FAMILIES` (a lane row's standup composes it under
    its ``--text-only-mm auto`` default, an IFEval row's is passed ``on``; both attest
    ``text_only_mm``), the M-RoPE dispatch attestation for ``glm4v`` (the IFEval rows'
    gate; a lane with no GLM row is not gated on it) and the Nemotron fused-Mamba
    backend attestation for ``nemotron_h`` against the STAGED tree's reviewed contract
    (a Nemotron cell never runs on the quiet pure-torch fallback). Every check reads the
    serving lane's own reader. The caller applies it to the LANE's rows
    (``contracts.is_full22_row``) and the IFEval rows (``contracts.is_ifeval_row``): a
    legacy two-SI row's launcher behaviour stays what it was."""
    if row.family in TEXT_ONLY_MM_FAMILIES and endpoint.get("text_only_mm") is not True:
        return (C.REC_TEXT_ONLY_MM_UNPINNED,
                f"family {row.family!r} must serve with the zero-image/zero-video pin, but endpoint.json "
                f"attests text_only_mm={endpoint.get('text_only_mm')!r} "
                f"({json.dumps(endpoint.get('text_only_mm_record'), default=str)[:400]})")
    if row.family == "glm4v":
        # The M-RoPE dispatch report the standup attests for a GLM row, read by
        # the serving lane's own reader
        ma = _mrope_attest()
        problems = ma.endpoint_mrope_problems(endpoint, row.model_key)
        if problems:
            return (C.REC_MROPE_UNATTESTED, "; ".join(problems))
    mb = _mamba_backend()
    if row.family == mb.NEMOTRON_FAMILY:
        expected_sha = None
        if tree:
            try:
                expected_sha = mb.contract_sha256(Path(tree) / mb.CONTRACT_RELPATH)
            except (OSError, ValueError, mb.MambaBackendError) as e:
                return (C.REC_NEMO_BACKEND_UNATTESTED, f"the staged tree's {mb.CONTRACT_RELPATH} is unreadable: {e}")
        problems = mb.endpoint_attestation_problems(endpoint, contract_sha256_expected=expected_sha)
        if problems:
            return (C.REC_NEMO_BACKEND_UNATTESTED, "; ".join(problems))
    return None


# --------------------------------------------------------------------------- #
# one configuration container                                                  #
# --------------------------------------------------------------------------- #


def _run_configuration(cfg: dict, sha: str, *, limit: int = 0, inspect_limit: int = 0,
                       samples: int = C.MATH500_SAMPLES_PER_ITEM, pass_no: int = 1,
                       controls: Optional[Sequence[str]] = None,
                       reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
                       object_digests: Optional[Mapping[str, Mapping[str, object]]] = None,
                       oos_prompt_budget: Optional[Mapping[str, object]] = None,
                       run_id: str = "", ladder: Optional[Mapping[str, object]] = None,
                       protocol_check: Optional[Mapping[str, object]] = None) -> dict:
    """Stand up the steered server for one configuration from the STAGED tree,
    start the usage ledger in front of its proxy, run the served capability
    driver against the ledger, tear down, gather timing + evidence.
    ``reduction_mode`` (E29 / PW18b) is the ONE canonical lens reduction mode
    this run asks for: written into the standup's (and the driver's)
    environment as ``SISTEER_LENS_STACKED_REDUCTIONS``, hashed into the
    expected identity, and held to the standup's attestation the moment its
    ``endpoint.json`` appears — a disagreement is ``REDUCTION_MODE_MISMATCH``
    before generation (a pre-landing server attests no key, which equals
    per_row only when per_row was asked for).

    ``oos_prompt_budget``: the VALIDATED prompt-budget artifact the preflight
    wrote for this tree (``rep["oos_prompt_budget"]``, handed on by ``main`` as
    an object — never a re-resolved path). REQUIRED on an out-of-support
    thinking-ON configuration: refused before the standup when missing or for
    another tree, held to ``endpoint.json.chat_template_hash`` the moment the
    record appears, written into the out-root and passed to the driver
    (``contracts.FLAG_OOS_PROMPT_BUDGET``) for its live pass."""
    ctx: Dict[str, object] = {"cfg": cfg, "sha": sha}
    early = _cell_plan_doors(ctx, limit=limit, inspect_limit=inspect_limit, samples=samples, pass_no=pass_no,
                             controls=controls, reduction_mode=reduction_mode, protocol_check=protocol_check,
                             object_digests=object_digests, ladder=ladder)
    if early is not None:
        return early
    early = _cell_identity(ctx, limit=limit, inspect_limit=inspect_limit, reduction_mode=reduction_mode)
    if early is not None:
        return early
    rec, row, geom, tree, tree_sha, engine = (ctx[k] for k in ("rec", "row", "geom", "tree", "tree_sha", "engine"))
    cfg = ctx["cfg"]
    # The WORKER-SIDE, fail-closed twin of the preflight's
    # `nemotron_backend_attested` — a nemotron_h row's container re-derives the
    # attestation key for THIS configuration's resolved geometry (the entry the
    # standup will serve), this tree and this reduction mode and reads the same-GPU
    # duty certification off the volume itself; a missing or foreign certificate
    # refuses HERE, before the standup is paid for, whatever the operator-side gate
    # did (a dispatch that skipped --pf, or preflighted another cap's entry).
    # Checked after the DONE resume above (no GPU work) and before the object digest
    # backstop below.
    admission = nemotron_worker_admission(row, tree=tree, tree_sha=tree_sha, geom=geom, reduction_mode=reduction_mode,
                                          serving_engine=engine)
    if admission is not None:
        rec["nemotron_backend_admission"] = {k: v for k, v in admission.items() if k != "problems"}
        if not admission["ok"]:
            return {**rec, "status": C.REC_NEMO_BACKEND_UNATTESTED,
                    "error": (f"{cfg['name']} ({geom.max_model_len} x {geom.max_num_seqs}, {'/'.join(cfg['geometry_keys'])}): "
                              "the container found no admitting Nemotron backend certification for this tree / "
                              "geometry / reduction mode — " + "; ".join(admission["problems"]))}
    early = _cell_object_door(ctx, object_digests=object_digests)
    if early is not None:
        return early
    early = _cell_prompt_budget_door(ctx, oos_prompt_budget=oos_prompt_budget)
    if early is not None:
        return early
    out_dir, wanted, rung, remaining = ctx["out_dir"], ctx["wanted"], ctx["rung"], ctx["remaining"]
    srv = Path(f"/tmp/srv_{cfg['name']}")
    srv.mkdir(parents=True, exist_ok=True)
    stop = srv / "STOP"
    try:
        cfg_path, overlaid = overlaid_config(row, tree, out_dir)
    except (KeyError, OSError, ValueError) as e:
        return {**rec, "status": "CONFIG_OVERLAY_FAILED", "error": f"{type(e).__name__}: {e}"}
    rec["config"] = cfg_path
    if overlaid:
        rec["config_overlay"] = overlaid
    ctx["cfg_path"] = cfg_path
    env = _serving_env(tree, reduction_mode)
    # the sandbox OWNER this container declares for
    # every sandbox its driver creates — (run_id minted by the launcher, this
    # cell, THIS FunctionCall = the attempt) — into the driver's environment,
    # with the durable record path; and, when a sandboxed leg is among the
    # remaining controls, the per-attempt pointer the external watcher reads
    # (every attempt, sandboxed or not, also writes its COMPLETION record at
    # the end of its drive — `_drive_cell`, COMPLETION_FIELDS — the receipt's
    # per-control attribution)
    # A ladder rung's driver is ALWAYS
    # handed the FULL control list — the hashed tuple (caps, selection, tasks)
    # IS the store's identity, so a trimmed list would key another store and the
    # driver refuses maps naming tasks it does not file; the validly complete
    # leg is skipped at dispatch by the same strict validator that trimmed
    # `remaining` here (inspect_served.run_one_task), so nothing is re-generated
    driven = wanted if rung else remaining
    rec["controls_driven"] = driven
    owner = sandbox_owner(run_id, cfg["cell"])
    sandboxed = sandboxed_controls(driven, cfg["mode"])
    record = sandbox_record_path(out_dir, owner)
    env.update(scope.owner_env(owner, record))
    rec["sandbox_owner"] = owner.as_dict()
    rec["sandboxed"] = sandboxed
    if sandboxed:
        rec["sandbox_record"] = str(record)
        # round 4: the per-attempt sandbox EVENT file — the path the driver appends to — is
        # created EMPTY before the pointer is published, so an attempt whose driver never starts
        # (STANDUP_FAILED below) leaves a pointer + an empty event file (+ the watcher's empty sweep):
        # the shape the analysis's provenance check already admits. A pointer with NO event file used
        # to refuse the whole wave permanently, even after a successful retry under the same suffix.
        record.parent.mkdir(parents=True, exist_ok=True)
        if not record.exists():
            record.touch()
        rec["sandbox_pointer"] = str(write_attempt_pointer(
            out_dir, owner, cfg=cfg, controls=driven, tree_sha=tree_sha, record=record))
        VOL.commit()

    refusal, facts = _standup_and_attest([ctx], srv=srv, stop=stop, cfg_path=cfg_path, cells=cfg["cell"], env=env,
                                         reduction_mode=reduction_mode, object_sha256=ctx["object_sha256"],
                                         declared=standup_declared(cfg), rung=rung, persist_dirs=[out_dir])
    if refusal is not None:
        return rec
    return _drive_cell(ctx, facts=facts, srv_row=srv, srv=srv, stop=stop, env=env, endpoint=facts["endpoint"],
                       driven=driven, owner=owner, record=record, sandboxed=sandboxed, protocol_check=protocol_check,
                       run_id=run_id, controls=controls, limit=limit, inspect_limit=inspect_limit)


def _cell_plan_doors(ctx: Dict[str, object], *, limit: int, inspect_limit: int, samples: int, pass_no: int,
                     controls: Optional[Sequence[str]], reduction_mode: str,
                     protocol_check: Optional[Mapping[str, object]],
                     object_digests: Optional[Mapping[str, Mapping[str, object]]],
                     ladder: Optional[Mapping[str, object]],
                     resolved_tree: Optional[Tuple[Path, str]] = None) -> Optional[dict]:
    """tinycap-shared-standup §1.1.1: the PLAN-LEVEL doors of one configuration — everything
    :func:`_run_configuration` checks from ``row_of(cfg)`` through the ladder admission and the
    out-dir / sampling-failure / engine-conflict / roster-snapshot block, byte for byte. ``ctx``
    carries ``cfg`` and ``sha`` in and gains the resolved facts (``rec``, ``row``, the serving path
    and engine, ``wanted``, ``rung``, the sampling mode, the OOS / offcap markers, the staged tree
    and its sha, ``out_dir``, the effective ``samples`` and ``pass_no``) on the way out. Returns
    the REC of an early exit (a refusal), else ``None``. ``resolved_tree`` (row mode) hands in the
    tree the row resolved ONCE; the solo path resolves it here as before."""
    cfg = ctx["cfg"]
    sha = ctx["sha"]
    row = row_of(cfg)
    rec = {"name": cfg["name"], "model": row.slug, "cell": cfg["cell"], "mode": cfg["mode"],
           "sha": sha[:7], "pass": int(pass_no), "out": cfg["out_dir"],
           "geometry_keys": list(cfg["geometry_keys"]),
           # §PW-nanfix-2: the row's letter-read width, stated in the REC so a
           # wave log says what K its letter reads were taken at (it is
           # hashed identity, so two waves at different K are different stores)
           "top_logprobs": row.top_logprobs,
           "reduction_mode_requested": reduction_mode}
    # native-serving-default (§1.7): the serving PATH is read off the configuration the plan marked
    # (SERVING_PATH_KEY, present iff native — the SAMPLING_MODE_KEY pattern, E54 #6), never off a
    # kwarg beside it; the engine it implies is what every later check holds the standup to
    try:
        serving_path = serving_path_of(cfg)
    except ValueError as e:
        return {**rec, "status": REC_SERVING_ENGINE_MISMATCH, "error": f"{cfg['name']}: {e}"}
    native = is_native_path(serving_path)
    engine = engine_of_serving_path(serving_path)
    rec["serving_path"] = serving_path
    rec[SERVED_ENGINE_FIELD] = engine
    if reduction_mode not in C.REDUCTION_MODES:
        return {**rec, "status": "REDUCTION_MODE_MISMATCH",
                "error": f"--reduction-mode {reduction_mode!r} is not one of {list(C.REDUCTION_MODES)}"}
    if native and reduction_mode != C.REDUCTION_MODE_LAUNCHER_DEFAULT:
        # a lens fact the native engine cannot attest: only the
        # launcher default (the authorised tuples' per_row, recorded not_applicable) is accepted
        return {**rec, "status": "REDUCTION_MODE_MISMATCH",
                "error": (f"--reduction-mode {reduction_mode!r} is a lens fact; under {SERVING_PATH_FLAG} "
                          f"{SERVING_PATH_LORA_NATIVE} the native engine attests no lens reduction mode (recorded "
                          f"{REDUCTION_MODE_NOT_APPLICABLE!r}) — drop the flag, or launch the lens")}
    try:
        # the container's own environment (rare: an image / secret setting it)
        # must agree with the argument — two sources for one fact never coexist
        C.check_reduction_mode_expectation(
            reduction_mode, reduction_mode_expected() if C.LENS_STACKED_REDUCTIONS_ENV in os.environ else None,
            expected_source=f"the container's {C.LENS_STACKED_REDUCTIONS_ENV}")
    except ValueError as e:
        return {**rec, "status": "REDUCTION_MODE_MISMATCH", "error": f"--reduction-mode vs env: {e}"}
    # Plan-level refusals BEFORE the volume is touched: neither depends on the
    # staged tree, and both are re-derived from the REQUESTED controls here so a
    # resume that narrows --controls cannot slip past the plan-time check.
    wanted = list(controls) if controls else list(cfg["controls"])
    rec["controls_requested"] = wanted
    # A ladder rung-2 container serves the certified
    # rung as a FIXED footprint (never stepping down: a KV refusal here is
    # STANDUP_FAILED), takes no smoke cap (its only limit is the selection), and
    # ends PARTIAL_COMPLETE when every selected item is validly filed
    rung = bool(cfg.get("ladder_rung"))            # the flag; `ladder` is the carried certificate kwarg
    rec["ladder_rung"] = dict(cfg["ladder_rung"]) if rung else None
    if rung and (limit or inspect_limit):
        return {**rec, "status": "LADDER_LIMITED",
                "error": f"a ladder rung takes no --limit / --inspect-limit (limit={limit}, "
                         f"inspect_limit={inspect_limit}); its only limit is {dict(C.LADDER_LIMITS)}"}
    # The draw's MODE, in one place: the plan's SAMPLING_MODE_KEY (absent = the
    # driver's default, `card`; bcb-bfcl-200-widen §S2 adds `protocol`, which the
    # driver argv then spells; an IFEval configuration carries `vendor_preset`).
    # Both the authorisation check below and the hashed `expected_identity` read
    # THIS local, so a per-run sampling mode cannot reach one and not the other
    # (E54 #6 — a check that derives its own copy of a fact can pass while the
    # run hashes another).
    sampling_mode = sampling_mode_of(cfg)
    rec[SAMPLING_MODE_KEY] = sampling_mode
    if is_ifeval_configuration(cfg):
        # ifeval-canonical-battery (P2): the explicit k the plan fixed for IFEval
        # (`--samples 2`) — the driver stamps it into samples_by_task and the
        # manifest's `samples`, so the expectation below reads the same number
        samples = int(cfg.get("samples", samples))
    protocol = sampling_mode == C.SAMPLING_PROTOCOL
    if protocol and protocol_check is None:
        # A protocol container is held to the
        # preflight's resolved-parameter record (the manifest's by_task.effective
        # is copied from it, and the driver refuses without it) — refused HERE,
        # before the staged tree is touched or a standup paid for
        return {**rec, "status": "PROTOCOL_CHECK_MISSING",
                "error": (f"a {C.SAMPLING_PROTOCOL} configuration launches only behind --pf: the container "
                          "is handed the preflight's check_protocol_sampling record (protocol_check), and "
                          "this invocation passed none")}
    # PW-oos: this configuration's own plan-time verdict, re-derived from the
    # REQUESTED controls. The flag is read off the CONFIGURATION the plan
    # marked, never off a container-wide switch, so a resume that narrows
    # --controls cannot turn an in-support cell into an overridden one.
    oos = bool(cfg.get(C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING))
    rec[C.IDENTITY_KEY_OUT_OF_SUPPORT_THINKING] = oos
    # the comparator's marker, read off the CONFIGURATION the
    # plan marked (the twin of the OOS marker); the two are exclusive
    offcap = serves_offcap(cfg)
    rec[OFFCAP_MARKER_KEY] = cfg.get(OFFCAP_MARKER_KEY)
    try:
        C.check_override_flags_exclusive(out_of_support_thinking=oos, off_cap_override=offcap,
                                         where=f"container run of {cfg['name']!r}")
    except C.OverrideFlagsExclusive as e:
        return {**rec, "status": C.REC_OFFCAP_UNAUTHORISED, "error": str(e)}
    # Both checks below compare the reduction mode this container was TOLD to
    # serve (`reduction_mode`, one canonical value) against the tuple's (code
    # review H2), so a stacked comparator / OOS container refuses HERE, before
    # a standup is paid for; the mode the standup ATTESTS is still held below.
    # The geometry pass it was told to serve (`pass_no`) the same way (H3).
    # E54 #6: the boolean is a CLAIM to be the authorised experiment, and this
    # decorated worker is a SEPARATE entry point — a direct
    # `run_configuration.remote(cfg, ...)` with a hand-built or hand-edited cfg
    # never passes through `plan_configurations`. Until this check the container
    # took the boolean as sufficient, resolved the staged tree, created the out
    # dir and started the standup; only the CHILD driver made the exact-tuple
    # comparison, so an unauthorised invocation spent an H200 and left partial
    # state behind. The comparison happens HERE, first: before the staged tree
    # is touched, before any directory is made, before the standup — and, as at
    # the other two doors, BEFORE `thinking_refusal_for` lifts anything, so an
    # unauthorised run is refused as unauthorised rather than served out of
    # support and refused later.
    if oos:
        try:
            C.check_out_of_support_thinking_authorised(
                model=row.slug, cell=cfg["cell"], controls=wanted, mode=cfg["mode"],
                sampling_mode=sampling_mode, samples=samples, reduction_mode=reduction_mode,
                pass_no=pass_no, where=f"container run of {cfg['name']!r}")
        except C.OutOfSupportThinkingUnauthorised as e:
            return {**rec, "status": "OOS_UNAUTHORISED", "error": str(e)}
    if offcap:
        # the marker is a CLAIM to be the
        # authorised comparator — the tuple decides, HERE, before the staged
        # tree is touched or a standup paid for (a hand-built cfg under the ON
        # arm refuses `mode differs` here, never THINKING_UNSERVABLE below)
        try:
            C.check_off_cap_override_authorised(
                model=row.slug, cell=cfg["cell"], controls=wanted, mode=cfg["mode"],
                sampling_mode=sampling_mode, samples=samples, reduction_mode=reduction_mode,
                pass_no=pass_no, where=f"container run of {cfg['name']!r}")
        except C.OffCapOverrideUnauthorised as e:
            return {**rec, "status": C.REC_OFFCAP_UNAUTHORISED, "error": str(e)}
        print(f"[offcap] {C.FLAG_ALLOW_OFF_CAP_OVERRIDE} is in force for {cfg['name']}: "
              f"{json.dumps(cfg.get(OFFCAP_MARKER_KEY), default=str)}", flush=True)
    refusal = thinking_refusal_for(row, cfg["cell"], cfg["mode"], wanted,
                                   allow_out_of_support=oos)
    if refusal:
        return {**rec, "status": "THINKING_UNSERVABLE", "error": refusal}
    if oos:
        override = thinking_override_for(row, cfg["cell"], cfg["mode"], wanted)
        rec["thinking_override"] = override
        print(f"[oos] {C.FLAG_ALLOW_OOS_THINKING} is in force for {cfg['name']}: "
              f"{json.dumps(override, default=str)}", flush=True)
    try:
        if resolved_tree is not None:
            # tinycap-shared-standup §1.1.2 step 3: the ROW resolved the tree once; every cell reads that
            tree_path, tree_sha = resolved_tree
        else:
            tree_path, tree_sha = resolve_staged_tree(sha)
    except NoStagedTree as e:
        return {**rec, "status": "NO_TREE", "tree": f"{C.VOL_REPOS_ROOT}/sisteer-{sha}",
                "error": str(e)}
    except (TreeShaMissing, TreeShaMismatch) as e:
        return {**rec, "status": "NO_TREE_SHA", "tree": f"{C.VOL_REPOS_ROOT}/sisteer-{sha}",
                "error": str(e)}
    tree = str(tree_path)
    rec["tree"] = tree
    rec["tree_sha"] = tree_sha
    # The worker-side tool-parser gate reads the checked-in live verdict from the STAGED tree it just
    # resolved — never from the launcher process's own module path (the image mounts `sisteer` at /root with no
    # configs/), so a promoted BFCL leg admits here exactly when the tree for this sha carries the PASS artifact
    tool_parser_why = tool_parser_problem(row, wanted, tree=tree)
    if tool_parser_why:
        return {**rec, "status": "NO_VERIFIED_TOOL_PARSER", "error": tool_parser_why}
    if is_ifeval_configuration(cfg):
        # The WORKER-SIDE twin of the planner's hold check — this container is a
        # separately callable entry point, so a hand-built configuration for a HELD or
        # DEFERRED matrix row is refused HERE against the STAGED tree's frozen matrix (the same
        # rows the dispatcher reads), before any directory is made or standup started; the
        # REC is a refusal the dispatcher never retries on GPU
        matrix_doc: Optional[Mapping[str, object]] = None
        try:
            # Every registered document (the frozen matrix + the seed sibling) off the STAGED tree
            matrix_doc = C.load_ifeval_matrices(tree)
            problem = C.ifeval_hold_problem(matrix_doc, slug=row.slug, cell=cfg["cell"])
        except (C.IfevalMatrixUnreadable, ValueError) as e:
            problem = str(e)
        rec["matrix_status"] = (C.ifeval_matrix_row_status(matrix_doc, slug=row.slug, cell=cfg["cell"])[0]
                                if problem is None and matrix_doc is not None else None)
        if problem is not None:
            return {**rec, "status": C.REC_IFEVAL_ROW_HELD, "error": f"{cfg['name']}: {problem}"}
    # bcb-bfcl-200 §S2b: this worker is a separately callable
    # entry point — the rung it was handed is admitted ONLY against the
    # certificate carried with it (validated HERE against this tree, this row,
    # the verified object digests and the launch's selection / caps), and the
    # certificate must be the one filed on the volume; refused before any
    # directory is made or standup started
    if ladder or rung:
        refusal = ladder_worker_admission(cfg, row=row, tree=tree, tree_sha=tree_sha,
                                          object_digests=object_digests, ladder=ladder)
        if refusal is not None:
            status, why = refusal
            return {**rec, "status": status, "error": why}
        # bcb-bfcl-200-widen S6: the carrier is {launch, certificates: {cell: cert}, admission}; the REC
        # records the wave record's digest and, for a probed cell, its own certificate's
        rec["ladder_admission_sha256"] = RP.certificate_sha256(dict(ladder["admission"]))
        own = (ladder.get("certificates") or {}).get(cfg["cell"])
        rec["ladder_certificate_sha256"] = RP.certificate_sha256(dict(own)) if own else None
    out_dir = Path(cfg["out_dir"])
    # bcb-bfcl-200-widen code review: a store root whose earlier attempt FAILED its
    # sampling validation (the clamp warning in the server log — BFCL executed at 0.01 behind the
    # protocol label) is refused BEFORE anything is written or resumed: its markers say DONE, its
    # evidence is not protocol evidence, and a retry must never turn it into a success
    failed = sampling_validation_failure(out_dir)
    if failed is not None:
        return {**rec, "status": C.REC_SAMPLING_VALIDATION_FAILED, "sampling_validation_failure": failed,
                "error": (f"{out_dir / C.SAMPLING_VALIDATION_FAILED_FILENAME} records {failed.get('status')} from attempt "
                          f"{failed.get('function_call_id')!r} (run {failed.get('run_id')!r}): {str(failed.get('error'))[:300]} — "
                          "the root's outcomes and Inspect logs are not protocol evidence; relaunch into a NEW "
                          "--out-suffix (or the general-plugin fallback), never resume here")}
    # native-serving-default (§1.7): the TERMINAL engine conflict at the output
    # boundary — EVERY store under <out_dir>/cells/ (identity-matching or not) must have been served
    # by THIS run's engine; a lens store under a native run (or the reverse) refuses HERE, before
    # any sidecar write (the roster snapshot below), any VOL.commit and any standup, and is never
    # re-planned as remaining work (which would regenerate a completed configuration on the other
    # engine). A native launch's DEFAULT root is the `native/`
    # namespace, so this fires only where an operator pointed it at a lens root.
    conflict = engine_conflict_at_output(out_dir, engine)
    if conflict is not None:
        return {**rec, "status": REC_SERVING_ENGINE_CONFLICT, "engine_conflict": conflict,
                "error": f"{cfg['name']}: {engine_conflict_error(conflict, out_dir)}"}
    # The LAUNCH-TIME roster snapshot — the fitted store's generation label bound to the
    # roster AS LAUNCHED (never the current roster) — written beside the manifest as
    # `lane_roster.json` from what `--roster-snapshot` handed main; validated again here
    # (a relabelled block refuses before any standup). The filed record is IMMUTABLE —
    # an existing one is compared BEFORE any write; a compatible relaunch (only
    # `launched_at` moved) is appended to the retry record beside it, an incompatible one
    # (another roster sha / generation / object / entry) refuses without a write
    snap = cfg.get("roster_snapshot")
    if snap is not None:
        problems = WR.snapshot_problems(snap)
        if problems or snap.get("cell_id") != cfg["cell"]:
            return {**rec, "status": C.REC_ROSTER_SNAPSHOT_INVALID,
                    "error": "; ".join(problems) or f"snapshot names cell {snap.get('cell_id')!r}, not {cfg['cell']!r}"}
        # round 7: the container re-checks the carried snapshot's wave / entry against the STAGED
        # tree's lane roster — a relabelled block naming a blocked cell refuses before any standup
        refusal = lane_roster_refusal(tree, row, str(cfg["cell"]), snap)
        if refusal is not None:
            return {**rec, "status": refusal[0], "error": refusal[1]}
        filed_path = out_dir / WR.SNAPSHOT_FILENAME
        if filed_path.is_file():
            filed, ferr = _read_json_object(filed_path)
            conflicts = ([f"filed record {ferr}"] if filed is None else WR.snapshot_conflicts(filed, snap))
            if conflicts:
                return {**rec, "status": C.REC_ROSTER_SNAPSHOT_CONFLICT, "roster_snapshot_filed": filed,
                        "error": (f"{filed_path} is the store's launch-time record and is immutable; this launch's snapshot "
                                  f"disagrees ({'; '.join(conflicts)}) — nothing written; relaunch into a NEW --out-suffix")}
            if filed != dict(snap):
                with (out_dir / WR.SNAPSHOT_RETRY_FILENAME).open("a") as fh:
                    fh.write(json.dumps(dict(snap), sort_keys=True) + "\n")
                rec["roster_snapshot_retry"] = True
            rec["roster_snapshot"] = dict(filed)
        else:
            out_dir.mkdir(parents=True, exist_ok=True)
            filed_path.write_text(json.dumps(dict(snap), indent=1, sort_keys=True) + "\n")
            rec["roster_snapshot"] = dict(snap)
    ctx.update({"rec": rec, "row": row, "serving_path": serving_path, "native": native, "engine": engine,
                "wanted": wanted, "rung": rung, "sampling_mode": sampling_mode, "protocol": protocol, "oos": oos,
                "offcap": offcap, "tree": tree, "tree_sha": tree_sha, "out_dir": out_dir, "samples": samples,
                "pass_no": int(pass_no)})
    return None


def _cell_identity(ctx: Dict[str, object], *, limit: int, inspect_limit: int, reduction_mode: str,
                   concurrency_k: int = 1) -> Optional[dict]:
    """tinycap-shared-standup §1.1.1: the IDENTITY stage of one configuration — the standup
    extras, the resolved geometry, the hashed expectation, the pre-standup resume decision (a
    DONE store returns the REC with no GPU minute spent), the torn-store and producer-tree doors
    and the EvalPlus archives, byte for byte. ``concurrency_k`` (landing 2, §2.1) derives the client
    width ``S // K`` in :func:`expected_identity` from the S the expectation pre-computes
    (:func:`client_width`; K = 1 is the served S, today's derivation). Returns the
    early REC (DONE, or a refusal), else ``None``; ``ctx`` gains ``extra``, ``geom``, ``expected``, ``resume``,
    ``remaining`` and ``evalplus_env`` (``tool_calls`` and ``model_budget`` live on the REC, not the ctx)."""
    cfg, rec, row, out_dir, wanted, rung, oos = (ctx[k] for k in ("cfg", "rec", "row", "out_dir", "wanted", "rung", "oos"))
    sampling_mode, serving_path, native, tree, tree_sha = (ctx[k] for k in ("sampling_mode", "serving_path", "native", "tree", "tree_sha"))
    samples, pass_no = ctx["samples"], ctx["pass_no"]
    out_dir.mkdir(parents=True, exist_ok=True)
    # E12 item 1: the FULL identity this run will serve is resolved BEFORE any
    # marker is read — geometry (window + S), the standup's parser / tool-call
    # composition (from the REQUESTED controls, so every resume of one
    # configuration serves one identity), pass, width, limits, lock sha
    tool_calls = needs_tool_calls(wanted)
    extra = standup_extra_for(row, tool_calls=tool_calls, thinking=cfg["mode"],
                              controls=wanted, allow_out_of_support=oos, cell=cfg["cell"],
                              sampling_mode=sampling_mode)
    rec["thinking_by_task"] = thinking_by_task_of(cfg["mode"], wanted,
                                                  family=(row.family if is_ifeval_configuration(cfg) else None))
    rec["tool_calls"] = tool_calls
    rec["standup_extra"] = extra
    geom, model_budget = served_geometry(cfg, pass_no, tree)
    print(geom.describe(), flush=True)
    print(f"[geometry] per-model budget (E7 / geometry.BUDGET_BY_MODEL): "
          f"{json.dumps(model_budget, default=str)}", flush=True)
    rec["geometry"] = {**geom.as_dict(), C.GEOMETRY_PASS_FIELD: int(pass_no),
                       "model_budget": model_budget}
    if rung and native and isinstance(model_budget, Mapping) and GEOMETRY_LADDER_REDUCTION_KEY in model_budget:
        # the ladder's reduction record rides at the TOP of the launcher's geometry block — beside the
        # standup's adjustments / kv_shrink once served_geometry_record restates it — where the scoring driver reads
        # it off served_geometry.json (served_capability_run._geometry_block) and composes it into the standup's block
        rec["geometry"][GEOMETRY_LADDER_REDUCTION_KEY] = dict(model_budget[GEOMETRY_LADDER_REDUCTION_KEY])
    # A MEASURED entry served at the certified footprint is redundant GPU
    # spend — name it per key in the log and the REC, never leave it to be read
    # off a window number
    rec["measured_at_footprint"] = measured_footprint_reserves(cfg, geom, pass_no, tree)
    log_measured_footprint(rec["measured_at_footprint"])
    expected = expected_identity(cfg, geom, pass_no=pass_no, controls=wanted, samples=samples,
                                 limit=limit, inspect_limit=inspect_limit, tree=tree,
                                 tree_sha=tree_sha, reduction_mode=reduction_mode,
                                 sampling_mode=sampling_mode, serving_path=serving_path,
                                 concurrency_k=concurrency_k)
    rec["expected_identity"] = expected.as_dict()
    if native:
        # §1.8: the kernel ceiling step the expectation PRE-COMPUTED (the S the standup will serve;
        # None when the budget's S already fits under the ceiling) — recorded, and held to the
        # standup's own adjustments record the moment endpoint.json appears
        _g, kernel_step = expected_geometry_for(geom, native=True, name=str(cfg["name"]))
        rec["expected_geometry_adjustments"] = [kernel_step] if kernel_step else []
    # BEFORE the standup the served S is a prediction (the configured S, or the
    # KV-derived S a store of this configuration already recorded) — a store shrunk from
    # this configured S by the rule is provisionally trusted here; the decision is
    # re-taken EXACTLY at the served S once the standup has said what it serves
    resume = resume_report(out_dir, wanted, expected, kv_shrink_tolerated=True) if not rung else ladder_resume_report(out_dir, wanted, expected)
    remaining = [c for c in wanted if resume["controls"][c]["done_in"] is None]
    # A TWO-PHASE store is DONE only when its manifest's
    # verification_pass reads verified AND no pending marker stands — a verifier killed after filing the task (done
    # marker + summary) but before the verified manifest / the marker's removal must reach the pending door and have
    # its verifier queued, never be declared complete off the done marker alone
    hold = two_phase_verification_hold(out_dir, cell=str(cfg["cell"]), wanted=wanted, mode=str(cfg["mode"]))
    if hold["held"]:
        remaining = [c for c in wanted if c in remaining or c in hold["held"]]
        rec["two_phase_hold"] = hold
    rec["controls_remaining"] = remaining
    rec["resume"] = resume
    if not remaining:
        if rung:
            rec["status"] = LADDER_REC_STATUS      # every selected item validly filed: no GPU minute spent
            return rec
        rec["status"] = "DONE"                     # every task validly done: no GPU minute spent
        return rec
    # the torn-store rule: a DONE out-of-support task whose outcome record is torn is
    # REPAIRED by the driver from the task's retained .eval logs — or REFUSED
    # when none survives. The refusal would come AFTER the standup; when the
    # log is already gone, refuse HERE and save the standup
    torn = torn_store_unrepairable(out_dir, remaining, expected, resume, tree=tree)
    if torn:
        return {**rec, "status": REC_OOS_TORN_STORE_UNREPAIRABLE, "error": torn}
    # E14 B: a store this run's driver would land on but was produced by
    # another revision — its validate_resume refuses before any manifest
    # rewrite, so say so HERE instead of spending a standup to find out
    conflicts = producer_tree_conflicts(out_dir, expected=expected, kv_shrink_tolerated=True)
    if conflicts:
        return {**rec, "status": "PRODUCER_TREE_MISMATCH", "producer_conflicts": conflicts,
                "error": _producer_conflict_error(conflicts, out_dir, tree_sha)}
    evalplus_env: Dict[str, str] = {}
    if any(C.control_family(a) in C.EVALPLUS_CONTROLS for c in remaining for a in C.expand_control(c)):
        try:
            evalplus_env = evalplus_override_env(tree)
        except FileNotFoundError as e:
            return {**rec, "status": "EVALPLUS_ARCHIVES_MISSING", "error": str(e)}
    rec["evalplus_override"] = evalplus_env
    ctx.update({"extra": extra, "geom": geom, "expected": expected, "resume": resume, "remaining": remaining,
                "evalplus_env": evalplus_env})
    return None


#: the per-cell bytes door found the object's bytes disagreeing with the
#: digest the launch holds it to — that cell is dropped, named; the row proceeds without it
REC_OBJECT_DIGEST_MISMATCH = "OBJECT_DIGEST_MISMATCH"


def _cell_object_door(ctx: Dict[str, object], *,
                      object_digests: Optional[Mapping[str, Mapping[str, object]]],
                      verify_bytes: bool = False) -> Optional[dict]:
    """tinycap-shared-standup §1.1.1 / §1.3: the E40 H1 door — a fitted configuration serves its
    object only against the digest the preflight verified (byte for byte the solo door), PLUS, under
    ``verify_bytes`` (row mode), the launcher's OWN read of the object's bytes against that digest:
    a disagreement is :data:`REC_OBJECT_DIGEST_MISMATCH` for THIS cell alone (the core's whole-standup
    refusal stays the second belt, S3). The solo path keeps ``verify_bytes=False``."""
    cfg, rec = ctx["cfg"], ctx["rec"]
    # E40 H1: a FITTED configuration serves its object only against the digest
    # the preflight verified — passed INTO the standup (OBJECT_DIGEST_FLAG) and
    # compared THERE against the bytes the server loads. Checked HERE, right
    # before the standup (a DONE resume above needs no object at all), as the
    # container-side backstop of main's "--pf is required for a fitted cell".
    object_sha256 = ""
    if cfg.get("steered", is_steered(cfg["cell"])):
        try:
            object_sha256 = object_digest_for(cfg["cell"], object_digests)
        except ValueError as e:
            return {**rec, "status": "NO_OBJECT_DIGEST", "error": str(e)}
        rec["object_digest"] = dict((object_digests or {})[cfg["cell"]])
    if verify_bytes and object_sha256:
        try:
            path = planned_object_paths(ctx["row"].objects_dir, [cfg["cell"]])[cfg["cell"]]
            actual = sha256_file(path)
        except (OSError, ValueError, KeyError, ImportError) as e:
            return {**rec, "status": "NO_OBJECT_DIGEST",
                    "error": (f"{cfg['name']}: the object bytes of {cfg['cell']!r} could not be read for the per-cell "
                              f"identity check (E40 H1): {type(e).__name__}: {e}")}
        rec["object_bytes_sha256"] = actual
        if actual != object_sha256:
            return {**rec, "status": REC_OBJECT_DIGEST_MISMATCH,
                    "error": (f"{cfg['name']}: the object bytes of {cfg['cell']!r} hash to {actual} but this launch "
                              f"holds the cell to {object_sha256} (E40 H1) — the cell is not served; the row proceeds "
                              "without it")}
    ctx["object_sha256"] = object_sha256
    return None


def _cell_prompt_budget_door(ctx: Dict[str, object], *,
                             oos_prompt_budget: Optional[Mapping[str, object]]) -> Optional[dict]:
    """tinycap-shared-standup §1.1.1: the prompt-budget artifact doors of one configuration (the
    out-of-support / off-cap legs and the IFEval cells), byte for byte; every lane row passes
    through untouched. ``ctx`` gains ``oos_on``, ``ifeval_cfg``, ``budgeted`` and the artifact."""
    cfg, rec, row, out_dir, wanted, tree, tree_sha, geom = (
        ctx[k] for k in ("cfg", "rec", "row", "out_dir", "wanted", "tree", "tree_sha", "geom"))
    # An out-of-support thinking-ON
    # configuration is held to the prompt-budget artifact — its digest against
    # the served template after the standup, its max in the driver's live pass —
    # so a container handed none (or another tree's) refuses HERE, before the
    # standup, the way a fitted cell without its digest does above
    oos_on = serves_oos_on(cfg, wanted)
    # The artifact is required on the comparator's legs too, and its ARM and CAP are
    # held to this configuration's BEFORE the standup — an ON artifact, or an OFF one
    # written for the table's 512, refuses here. Its FIT against the window THIS
    # container resolved (`geom.max_model_len`, the standup's own argument) is the
    # second door, here — before this only arm + cap were compared, and a container
    # whose resolved window was pass 2's 4,608 reached `_standup_cmd` and paid for the
    # standup the driver's live pass then refused.
    # An IFEval configuration's artifact is written HERE, in the container, from the
    # staged tree — its own cell's prompt class (the constitution SI, or none / the
    # safety SI) at the executed cap, held to the cap's geometry entry by the script's
    # own .fit.json sidecar (exit 2 on a non-fit) — so the budget-artifact fit check
    # rides every IFEval cell without a preflight round trip; a handed-in artifact
    # (the preflight's) is kept
    ifeval_cfg = is_ifeval_configuration(cfg)
    if ifeval_cfg and oos_prompt_budget is None:
        budget_out = out_dir / C.OOS_PROMPT_BUDGET_FILENAME
        try:
            oos_prompt_budget = run_ifeval_prompt_budget(tree, row, cfg, str(budget_out), tree_sha=tree_sha)
        except (AssertionError, ValueError, C.OutOfSupportPromptBudgetError) as e:
            return {**rec, "status": C.REC_OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH,
                    "error": f"the container's IFEval prompt-budget artifact: {e}"}
        rec["ifeval_prompt_budget"] = {"source": "container", "path": str(budget_out),
                                       "geometry_eval": str(cfg["geometry_keys"][0]),
                                       "argv": ifeval_prompt_budget_argv(tree, row, cfg, str(budget_out), tree_sha=tree_sha)}
    budgeted = needs_prompt_budget(cfg, wanted)
    if budgeted:
        why = oos_prompt_budget_problem(oos_prompt_budget, tree_sha=tree_sha)
        if why:
            return {**rec, "status": C.REC_OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH, "error": why}
        caps = budget_caps(cfg)
        task = str(oos_prompt_budget.get("cap_task"))
        if task not in caps:
            return {**rec, "status": C.REC_OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH,
                    "error": (f"the prompt-budget artifact budgets {task!r} but this configuration's "
                              f"raised-cap tasks are {sorted(caps)}")}
        try:
            fit = C.prompt_budget_fit(oos_prompt_budget, arm=served_budget_arm(row, str(cfg["mode"])), cap=caps[task],
                                      max_model_len=int(geom.max_model_len),
                                      where=f"{cfg['name']}: the container's prompt-budget artifact")
        except C.OutOfSupportPromptBudgetError as e:
            return {**rec, "status": C.REC_OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH, "error": str(e)}
        rec["oos_prompt_budget"] = {k: oos_prompt_budget.get(k) for k in (
            "n", "max", "p99", "arm", "cap", "cap_task", "chat_template_hash", "tree_sha")}
        rec["oos_prompt_budget_fit"] = fit
    ctx.update({"oos_on": oos_on, "ifeval_cfg": ifeval_cfg, "budgeted": budgeted, "oos_prompt_budget": oos_prompt_budget})
    return None


def _serving_env(tree: str, reduction_mode: str) -> Dict[str, str]:
    """The environment every standup and driver child of a container inherits (one function since
    tinycap-shared-standup: the row worker builds it once for its one standup and every driver)."""
    env = dict(os.environ)
    env["PYTHONPATH"] = f"{tree}/src:{tree}/scripts"
    # E29 / PW18b: ONE canonical reduction mode for the standup (the serving
    # parser reads it) and the driver (its expectation cross-check reads it)
    env[C.LENS_STACKED_REDUCTIONS_ENV] = reduction_mode
    # native-serving-default (§1.9): the adapter bank root, exported into EVERY container (the
    # native core's resolve_adapter_bank reads it when neither cluster root exists); the argv
    # ALSO names the bank explicitly under native (_standup_cmd)
    env[ADAPTER_BANK_ROOT_ENV] = ADAPTER_BANK_ROOT
    return env


def _standup_and_attest(ctxs: Sequence[Dict[str, object]], *, srv: Path, stop: Path, cfg_path: str,
                        cells, env: Mapping[str, str], reduction_mode: str,
                        object_sha256: str = "", object_sha256_by_cell: Optional[Mapping[str, str]] = None,
                        declared: bool = False, rung: bool = False,
                        persist_dirs: Sequence[Path] = (), concurrency_k: int = 1) -> Tuple[Optional[str], Dict[str, object]]:
    """ONE standup for ``ctxs`` (one configuration on the solo path, every served cell of a
    row otherwise) and the post-readiness doors — the served geometry, the clamp override,
    the engine, the reduction mode, the serve attestation per cell, the full22 gates and the
    per-cell ``served_geometry.json`` — in the order :func:`_run_configuration` always ran
    them. A refusal is applied to EVERY ctx's REC (a row refusal names every served cell) and
    returned as the status; ``facts`` carries the standup handle, the argv, the endpoint,
    ``standup_s`` and the served geometry. ``cells`` is the one cell (a str: today's argv byte
    for byte) or the row's list (keyed digests per fitted cell)."""
    first = ctxs[0]
    row, native, serving_path, engine = first["row"], first["native"], first["serving_path"], first["engine"]
    protocol, sampling_mode, tree = first["protocol"], first["sampling_mode"], first["tree"]
    geom, extra = first["geom"], first["extra"]
    facts: Dict[str, object] = {"stop": stop}

    def _refuse(status: str, **kw) -> str:
        """The row-wide refusal: EVERY served cell's REC names it (a row refusal names every cell)."""
        for ctx in ctxs:
            rec = ctx["rec"]
            rec.update(status=status, **kw)
        return status

    # --- standup (vLLM venv) -----------------------------------------------------
    t0 = time.time()
    # bcb-bfcl-200-widen S1-f: a nemotron_h row's standup judges its fused-Mamba backend against
    # the STAGED tree's reviewed contract (never the image's mounted copy)
    mamba_contract = (f"{tree}/{_mamba_backend().CONTRACT_RELPATH}"
                      if row.family == _mamba_backend().NEMOTRON_FAMILY else None)
    standup_argv = _standup_cmd(tree, cfg_path, cells, row.objects_dir, srv, stop, geom,
                                row.top_logprobs, extra, object_sha256=object_sha256,
                                object_sha256_by_cell=object_sha256_by_cell,
                                declared=declared,
                                # ifeval-canonical-battery (the ported full22 hunks): the IFEval
                                # rows compose the text-only pin explicitly (as the worker does;
                                # a lane row's standup composes it under its own `auto` default);
                                # every other row's argv is byte-identical
                                text_only_mm=(C.is_ifeval_row(row) and row.family in TEXT_ONLY_MM_FAMILIES),
                                mamba_contract=mamba_contract,
                                # native-serving-default (§1.7 / §1.9): the path on every standup, the bank
                                # (the deterministic default) under native
                                serving_path=serving_path,
                                adapter_bank=(adapter_bank_for(getattr(geom, "model_key", None)) if native else None),
                                # A LADDER scoring standup serves
                                # the certified rung as a FIXED footprint on BOTH engines — KV-derived S OFF, so a KV
                                # shortfall in this container refuses readiness (STANDUP_FAILED, `kv_refusal` named below)
                                # instead of coming up at a shrunk S: with it on, a probe that certified S=15 met a slightly
                                # smaller scoring-container cache, the standup appended a kv_shrink step to 14, this worker
                                # re-derived its expected identity at 14 and drove the whole run there, and the merge then
                                # refused the S=14 store against the S=15 certificate — fail-safe, the run spent for nothing.
                                # Every NON-ladder standup keeps the default (`on`), byte-identical.
                                kv_derived_seqs=not rung)
    for ctx in ctxs:
        ctx["rec"]["standup_argv"] = standup_argv
    facts.update(standup_argv=standup_argv, t_standup_start=t0)
    standup = subprocess.Popen(
        standup_argv,
        env=env, stdout=(srv / "standup.log").open("w"), stderr=subprocess.STDOUT)
    facts["standup"] = standup
    ep = srv / "endpoint.json"
    if not _wait_for(ep, standup, STANDUP_WAIT_S):
        _refuse("STANDUP_FAILED", standup_tail=_tail(srv / "standup.log"),
                vllm_tail=_tail(srv / "vllm_server.log"))
        if rung:
            # the rung is FIXED here: a KV refusal is named, never stepped down from
            for ctx in ctxs:
                ctx["rec"]["kv_refusal"] = RP.kv_coverage_refusal(_tail(srv / "standup.log", 200_000) or "")
        for d in persist_dirs:
            _persist_logs(srv, Path(d))
        VOL.commit()
        return "STANDUP_FAILED", facts
    endpoint = json.loads(ep.read_text())
    standup_s = round(time.time() - t0, 1)
    facts.update(endpoint=endpoint, endpoint_path=ep, standup_s=standup_s, t_standup_ready=time.time())
    for ctx in ctxs:
        ctx["rec"]["standup_s"] = standup_s
        ctx["rec"]["proxy_url"] = endpoint["proxy_url"]
    # the geometry the standup SERVED — the configured S, or the KV-derived S the
    # container's own scheduler report backs (the standup's kv_shrink record, held to the
    # rule against THIS run's configured numbers). Anything else is refused, torn down.
    # on a native ladder rung the reader makes the PRODUCTION reading before the driver — the
    # block the driver will validate (the standup's geometry + this launch's ladder reduction), from the identity S
    # the record's own budget buys — so no store is generated at a footprint the driver then refuses
    rec = first["rec"]
    geom_served, kv_shrink, geometry_problem = served_geometry_of_endpoint(
        endpoint, geom, ladder_record=(rec["geometry"] if rung and native else None))
    for ctx in ctxs:
        ctx["rec"]["kv_shrink"] = kv_shrink
    if geometry_problem is not None:
        for ctx in ctxs:
            rec = ctx["rec"]
            rec.update(status=C.REC_SERVED_GEOMETRY_MISMATCH, error=geometry_problem,
                       standup_tail=_tail(srv / "standup.log"))
        _tear_down_standup(stop, standup)
        for d in persist_dirs:
            _persist_logs(srv, Path(d))
        VOL.commit()
        return C.REC_SERVED_GEOMETRY_MISMATCH, facts
    adjustments = endpoint_geometry_adjustments(endpoint)
    for ctx in ctxs:
        ctx["rec"]["geometry_adjustments"] = adjustments
    if kv_shrink is not None or adjustments:
        # PW5-4: the served S is store identity — the expectation, the REC's geometry
        # block (served_geometry.json), the driver's --concurrency and the resume decision
        # are re-derived at the SERVED S, exactly (no tolerance now that it is known).
        # native-serving-default (§1.8): a kernel-lowered S the expectation already
        # pre-computed is re-stated here too (a no-op on the identity when the prediction
        # held; the validated adjustments list is copied whole into the record)
        for ctx in ctxs:
            rec, expected = ctx["rec"], ctx["expected"]
            rec["geometry"] = served_geometry_record(rec["geometry"], geom_served, kv_shrink)
            if adjustments:
                rec["geometry"][GEOMETRY_ADJUSTMENTS_KEY] = [dict(a) for a in adjustments]
            rec["expected_identity_configured"] = expected.as_dict()
            expected = expected_at_served_seqs(expected, geom_served.max_num_seqs, concurrency_k=concurrency_k)
            rec["expected_identity"] = expected.as_dict()
            ctx["expected"] = expected
        geom = geom_served
        if kv_shrink is not None:
            print(f"[geometry] KV-derived S: the standup served {geom.max_model_len} x {geom.max_num_seqs} "
                  f"(configured S {kv_shrink['configured_max_num_seqs']}; the container's KV cache backs "
                  f"{kv_shrink['kv_backed_concurrency']:.2f} full-length sequences, "
                  f"{kv_shrink['kv_capacity_tokens']:,} tokens; {kv_shrink['basis']})", flush=True)
        else:
            print(f"[geometry] adjusted S: the standup served {geom.max_model_len} x {geom.max_num_seqs} under "
                  f"{json.dumps(adjustments, default=str)} (§1.8; the LoRA kernel index ceiling is not a KV shrink)",
                  flush=True)
    for ctx in ctxs:
        ctx["geom"] = geom
    facts.update(geom=geom, kv_shrink=kv_shrink, adjustments=adjustments)
    for ctx in ctxs:
        _retake_resume(ctx, rung=rung)
    # bcb-bfcl-200-widen: the clamp override the standup RECORDS is held to
    # this configuration's mode the moment the record appears — present and
    # EXACTLY the pinned record under protocol, absent otherwise — refused
    # before generation (the driver re-checks; this saves the generation)
    have_override = endpoint.get(C.ENDPOINT_KEY_SAMPLING_CLAMP_OVERRIDE)
    for ctx in ctxs:
        ctx["rec"][C.ENDPOINT_KEY_SAMPLING_CLAMP_OVERRIDE] = have_override
    want_override = dict(C.SAMPLING_CLAMP_OVERRIDE) if protocol else None
    if (have_override if have_override is None else dict(have_override)) != want_override:
        _refuse("CLAMP_OVERRIDE_MISMATCH",
                error=(f"the standup records {C.ENDPOINT_KEY_SAMPLING_CLAMP_OVERRIDE}={have_override!r} but "
                       f"this {sampling_mode!r} configuration expects {want_override!r} (D13: lifted iff "
                       f"{C.FLAG_SAMPLING} {C.SAMPLING_PROTOCOL})"),
                standup_tail=_tail(srv / "standup.log"))
        _tear_down_standup(stop, standup)
        VOL.commit()
        return "CLAMP_OVERRIDE_MISMATCH", facts
    # PW18: what the standup declared (the driver hashes both into the identity)
    for ctx in ctxs:
        ctx["rec"][C.AGENT_LOOP_ENTRY_KEY] = endpoint.get(C.AGENT_LOOP_ENTRY_KEY)
    # E29 / PW18b: the standup's ATTESTED reduction mode (endpoint.json
    # lens_reduction_mode; unstated = a pre-landing server = per_row) is held to
    # the mode this run asked for THE MOMENT the record appears — a
    # disagreement is refused before generation, named, and never recorded.
    #
    # E61: read the WHOLE record, never the one key. `resolve_reduction_mode` is
    # handed VALUES, so a post-landing standup that wrote the mode null AND said
    # why (workers attesting nothing, or disagreeing) reached it as a bare None
    # and read as the pre-landing per_row default: with per_row requested the
    # expectation check then passed and the run went on to write a store
    # LABELLED per_row whose standup had said its arithmetic could not be
    # determined. `endpoint_reduction_mode` is the reading that can see the
    # second key, and it ships in THIS file (it imports nothing — see its
    # docstring) because by here the staged candidate tree is first on sys.path.
    # Same shape as the driver's `_standup_endpoint`: the launcher's VOCABULARY
    # reading runs first, so an unknown mode still refuses in contracts' words;
    # the record-aware reading refuses the reason-bearing shapes before any
    # comparison; the drift guard refuses rather than picking one if the two
    # ever part.
    #
    # the ENGINE is read FIRST — endpoint.json's `engine`
    # (absent = lens by era) must be the engine this run's serving path asks for, and under
    # native the LIVE proxy's /v1/models petri_proxy.engine.kind must agree with it; a
    # disagreement is SERVING_ENGINE_MISMATCH, torn down before generation. Under native the
    # lens-mode readers are NOT consulted (the engine attests no lens hook): the record's mode
    # is `not_applicable`, an explicit value. Under lens the block below runs byte for byte.
    try:
        served_engine = endpoint_engine(endpoint)
    except ValueError as e:
        _refuse(REC_SERVING_ENGINE_MISMATCH, error=f"standup record {ep}: {e}",
                standup_tail=_tail(srv / "standup.log"))
        _tear_down_standup(stop, standup)
        VOL.commit()
        return REC_SERVING_ENGINE_MISMATCH, facts
    for ctx in ctxs:
        ctx["rec"]["served_engine"] = served_engine
    if served_engine != engine:
        _refuse(REC_SERVING_ENGINE_MISMATCH,
                error=(f"standup record {ep} attests {ENDPOINT_KEY_ENGINE}={served_engine!r} but this run's "
                       f"{SERVING_PATH_FLAG} {serving_path} expects {engine!r} — the standup did not serve the "
                       "engine the launch asked for; refusing rather than recording either"),
                standup_tail=_tail(srv / "standup.log"))
        _tear_down_standup(stop, standup)
        VOL.commit()
        return REC_SERVING_ENGINE_MISMATCH, facts
    if native:
        kind, why = proxy_engine_kind(endpoint)
        for ctx in ctxs:
            ctx["rec"]["proxy_engine_kind"] = kind
        if kind != ENGINE_LORA_NATIVE:
            _refuse(REC_SERVING_ENGINE_MISMATCH,
                    error=(f"the live proxy's /v1/models {PROXY_IDENTITY_KEY}.{PROXY_IDENTITY_ENGINE_KEY}.kind is "
                           f"{kind!r} but standup record {ep} attests {ENDPOINT_KEY_ENGINE}={served_engine!r}"
                           + (f" ({why})" if why else "") + " — the record does not vouch for the proxy answering"),
                    standup_tail=_tail(srv / "standup.log"))
            _tear_down_standup(stop, standup)
            VOL.commit()
            return REC_SERVING_ENGINE_MISMATCH, facts
        try:
            # the engine-first resolver (the three-copy rule, pinned against lens_worker's): not_applicable
            # for a native record; a native record that nevertheless STATES a lens mode is torn and
            # refuses — the record's two facts disagree about what engine served
            attested = endpoint_reduction_mode(endpoint, source=f"standup record {ep}")
        except ReductionModeUnattested as e:
            _refuse("REDUCTION_MODE_UNATTESTED", error=str(e), standup_tail=_tail(srv / "standup.log"))
            _tear_down_standup(stop, standup)
            VOL.commit()
            return "REDUCTION_MODE_UNATTESTED", facts
        if attested != REDUCTION_MODE_NOT_APPLICABLE:
            # unreachable once the engine read lora_native above; a drift guard between the two readings
            _refuse("REDUCTION_MODE_MISMATCH",
                    error=(f"standup record {ep}: attests {ENDPOINT_KEY_ENGINE}={served_engine!r} but "
                           f"endpoint_reduction_mode reads {attested!r}, not {REDUCTION_MODE_NOT_APPLICABLE!r} — "
                           "two readings of one record have drifted; refusing rather than recording either"),
                    standup_tail=_tail(srv / "standup.log"))
            _tear_down_standup(stop, standup)
            VOL.commit()
            return "REDUCTION_MODE_MISMATCH", facts
        for ctx in ctxs:
            ctx["rec"][C.REDUCTION_MODE_FIELD] = attested
            ctx["rec"]["reduction_mode_attestation"] = (
                f"native engine ({ENGINE_LORA_NATIVE}): no lens reduction mode — "
                f"{REDUCTION_MODE_NOT_APPLICABLE!r}, no {C.PROXY_IDENTITY_REDUCTION_MODE} consulted")
    else:
        keyless = endpoint.get(C.PROXY_IDENTITY_REDUCTION_MODE) is None
        try:
            attested = C.resolve_reduction_mode(endpoint.get(C.PROXY_IDENTITY_REDUCTION_MODE),
                                                sources=("standup endpoint.json",))
            resolved = endpoint_reduction_mode(endpoint, source=f"standup record {ep}")
            if resolved != attested:
                raise ValueError(
                    f"standup record {ep}: this launcher reads "
                    f"{C.PROXY_IDENTITY_REDUCTION_MODE}={attested!r} from the record and "
                    f"endpoint_reduction_mode reads {resolved!r} — the two readings of one "
                    "record have drifted; refusing rather than recording either")
            C.check_reduction_mode_expectation(attested, reduction_mode,
                                               expected_source="--reduction-mode", keyless=keyless)
        except ReductionModeUnattested as e:
            _refuse("REDUCTION_MODE_UNATTESTED", error=str(e), standup_tail=_tail(srv / "standup.log"))
            _tear_down_standup(stop, standup)
            VOL.commit()
            return "REDUCTION_MODE_UNATTESTED", facts
        except ValueError as e:
            _refuse("REDUCTION_MODE_MISMATCH", error=str(e), standup_tail=_tail(srv / "standup.log"))
            _tear_down_standup(stop, standup)
            VOL.commit()
            return "REDUCTION_MODE_MISMATCH", facts
        for ctx in ctxs:
            ctx["rec"][C.REDUCTION_MODE_FIELD] = attested
            if keyless:
                ctx["rec"]["reduction_mode_attestation"] = ("pre-landing server: no lens_reduction_mode stated "
                                                            "(and no reason for its absence) -> per_row")
    facts["served_engine"] = served_engine
    # fit-support transfer: the lens half's ATTESTATION, compared
    # against the launcher's PURE expectation the moment the record appears —
    # a REFUSAL, never an identity input. The RAW values are recorded first
    # (unhashed: the REC, served_geometry.json's endpoint dump, the manifest's
    # route block), so a refusing REC still says what the standup attested;
    # then the compare (oos_attestation_refusal: the error key on every
    # configuration; the own key — and the twin — on a declared standup; the
    # served template digest against the artifact's; the authorised psr cell's
    # attested resumed-prefill policy; lens_salt_policy; the artifact digest(s)).
    # Same shape as the reduction-mode refusals: torn down, committed, returned.
    # tinycap-shared-standup: PER CELL of the row (each fitted cell against ITS digest).
    for ctx in ctxs:
        rec, cfg, expected = ctx["rec"], ctx["cfg"], ctx["expected"]
        oos_on, offcap, budgeted, ifeval_cfg = ctx["oos_on"], ctx["offcap"], ctx["budgeted"], ctx["ifeval_cfg"]
        oos_prompt_budget = ctx["oos_prompt_budget"]
        rec.update(oos_attestation_record(endpoint, cfg))
        refusal = oos_attestation_refusal(endpoint, cfg, expected=expected, object_sha256=ctx["object_sha256"],
                                          budget=(oos_prompt_budget if (oos_on or offcap) else None),
                                          oos_on=oos_on, offcap=offcap, source=f"standup record {ep}")
        if refusal is None and budgeted and ifeval_cfg and not (oos_on or offcap):
            # An IFEval cell's container-written artifact is held to the SERVED
            # template the moment the record appears (the same equality the driver and the
            # out-of-support legs apply, contracts.prompt_budget_template_mismatch)
            why = C.prompt_budget_template_mismatch(
                oos_prompt_budget, endpoint.get(C.ENDPOINT_KEY_CHAT_TEMPLATE_HASH),
                served_source=f"standup record {ep} {C.ENDPOINT_KEY_CHAT_TEMPLATE_HASH}")
            if why:
                refusal = (C.REC_OOS_PROMPT_BUDGET_TEMPLATE_MISMATCH, why)
        if refusal is not None:
            status, why = refusal
            _refuse(status, error=why, standup_tail=_tail(srv / "standup.log"))
            _tear_down_standup(stop, standup)
            VOL.commit()
            return status, facts
    # bcb-bfcl-200-widen S1-f (tinycap-full22 §4.1 / §5.3): the standup's ATTESTATIONS a lane
    # row is held to, read off endpoint.json the moment it appears and REFUSED before any
    # generation — the text-only multimodal pin (qwen3_5) and the Nemotron backend attestation
    # (nemotron_h; against the staged tree's reviewed contract). Recorded raw first.
    # ifeval-canonical-battery: the IFEval rows (their own matrix; not full22 rows) are held to
    # the same gates — plus the M-RoPE dispatch report for glm4v — through the same reader; the
    # two predicates are disjoint, so exactly one call is made per row, and a legacy two-SI
    # row's standup keeps its behaviour.
    for ctx in ctxs:
        rec = ctx["rec"]
        rec.update(full22_attestation_record(endpoint))
    refusal = full22_endpoint_refusal(row, endpoint, tree=tree) if C.is_full22_row(row) else None
    if refusal is None and C.is_ifeval_row(row):
        refusal = full22_endpoint_refusal(row, endpoint, tree=tree)
    if refusal is not None:
        status, why = refusal
        _refuse(status, error=why, standup_tail=_tail(srv / "standup.log"))
        _tear_down_standup(stop, standup)
        VOL.commit()
        return status, facts
    # the served-geometry record ON THE VOLUME (the srv dir dies with the
    # container): what was asked (model budget + basis), what the standup says
    # it launched (its endpoint.json: max_model_len / max_num_seqs /
    # tool_calls / reasoning_parser / agent_loop_entry / lens_reduction_mode),
    # and the argv — for the measurement proposal
    # (scripts/tinycap_geometry_measure.py) and the report
    # the path asked for and the engine attested are NATIVE-only keys — a lens sidecar is
    # byte-identical to the one the pre-landing launcher wrote (main fafbec6c; held to that
    # commit's own code by test_tinycap_lens_records_golden), the spec's rule that the lens
    # path's records never change. The REC above carries both facts on either engine: it is
    # this container's printed result, not a record on the volume.
    for ctx in ctxs:
        rec, out_dir = ctx["rec"], ctx["out_dir"]
        # a ROW's record names its last served cell: each store's copy names THIS store's cell (per_cell_endpoint; a
        # solo record — one cell, or no `cell` key — is byte-identical to before)
        (out_dir / SERVED_GEOMETRY_FILENAME).write_text(json.dumps(
            {"geometry": rec["geometry"], "standup_argv": standup_argv,
             "endpoint": per_cell_endpoint(endpoint, str(ctx["cfg"]["cell"])) if isinstance(endpoint, Mapping) else endpoint,
             "reduction_mode_requested": reduction_mode,
             **({"serving_path": serving_path, SERVED_ENGINE_FIELD: served_engine} if native else {})},
            indent=1, default=str))
        # fit-support transfer: the VALIDATED artifact into the out-root, for the
        # driver's live /v1/tokenize pass (its max) and digest compare — the object
        # this container was handed and just held the standup to, never a re-read of
        # the preflight's volume path
        budget_path: Optional[Path] = None
        if ctx["budgeted"]:
            budget_path = out_dir / C.OOS_PROMPT_BUDGET_FILENAME
            budget_path.write_text(json.dumps(dict(ctx["oos_prompt_budget"]), indent=1, sort_keys=True))
        ctx["budget_path"] = budget_path
    return None, facts


def _retake_resume(ctx: Dict[str, object], *, rung: bool) -> None:
    """The resume decision re-taken EXACTLY at the served S once the standup has said what it serves
    (one cell of the row; :func:`_standup_and_attest` calls it per served cell)."""
    rec, out_dir, wanted, expected, resume = ctx["rec"], ctx["out_dir"], ctx["wanted"], ctx["expected"], ctx["resume"]
    rec["resume_prestandup"] = resume
    resume = resume_report(out_dir, wanted, expected) if not rung else ladder_resume_report(out_dir, wanted, expected)
    rec["resume"] = resume
    remaining = [c for c in wanted if resume["controls"][c]["done_in"] is None]
    rec["controls_remaining"] = remaining
    ctx.update({"resume": resume, "remaining": remaining})


def _drive_cell(ctx: Dict[str, object], *, facts: Mapping[str, object], srv_row: Path, srv: Path, stop: Path,
                env: Mapping[str, str], endpoint: Mapping[str, object], driven: Sequence[str],
                owner: "scope.Owner", record: Path, sandboxed: bool,
                protocol_check: Optional[Mapping[str, object]], run_id: str,
                controls: Optional[Sequence[str]], limit: int, inspect_limit: int,
                shared_standup: bool = False, row_facts: Optional[Mapping[str, object]] = None,
                sweep_dir: Optional[Path] = None, concurrency_k: int = 1,
                verification_phase: str = C.VERIFICATION_PHASE_COUPLED) -> dict:
    """tinycap-shared-standup §1.1.1: ONE cell's drive against a ready standup — its own usage
    ledger in front of the proxy, its own driver, the resolved-sampler record, the clamp
    belt, the ledger stats, the teardown (the ledger; the standup too on the solo path), the
    sweep of ITS owner, the resume re-read and the RESULT stamp, byte for byte the solo flow.

    ``srv`` is THIS cell's serve dir — the standup's own dir on the solo path, ``srv_row/cells/<cell>`` on a row
    (:func:`bind_cell_serve_dir`: the cell's routing table, its copy of the standup record, its ledger's endpoint
    record and log, and the row's ONE ``vllm_server.log`` by symlink), so every read here spells ``srv / …`` on
    both paths; ``srv_row`` is the row's server dir, read only to refresh the store's ``standup/`` files.
    ``shared_standup`` (row mode): the standup outlives this cell (the row tears it down once), a driver
    failure refreshes the cell store's ``standup/vllm_server.log`` instead of persisting the row's logs into
    the store root, and the sweep certificate goes to ``sweep_dir`` (the row dir) with the cell suffix.
    ``row_facts`` (row mode) stamps the REC's row facts and the RESULT line's ``standup=`` token.
    Landing 2: ``concurrency_k`` (§2.1) sets the driver's client width to the served S // K — K drives of a row
    run in parallel threads, so the ledger's port pick + bind is serialised (:data:`_LEDGER_START_LOCK`);
    ``verification_phase`` ``generate`` (§2.2.3) rides to the driver, and a driver that returned 0 with its
    BigCodeBench task(s) left is GENERATED — not INCOMPLETE — iff every task left carries this store's pending
    marker under the row dir (:func:`generation_pending_verdict`); the RESULT then reads ``result=GENERATED``."""
    rec, cfg, out_dir, tree, tree_sha = ctx["rec"], ctx["cfg"], ctx["out_dir"], ctx["tree"], ctx["tree_sha"]
    row, geom, expected, wanted, rung = ctx["row"], ctx["geom"], ctx["expected"], ctx["wanted"], ctx["rung"]
    sampling_mode, protocol, ifeval_cfg, samples = ctx["sampling_mode"], ctx["protocol"], ctx["ifeval_cfg"], ctx["samples"]
    evalplus_env, object_sha256, cfg_path = ctx["evalplus_env"], ctx["object_sha256"], ctx["cfg_path"]
    budget_path = ctx.get("budget_path")
    standup = facts["standup"]
    t1 = t2 = None

    # --- the usage ledger IN FRONT of the proxy (client venv, loopback) -----------
    ledger_path = out_dir / C.LEDGER_FILENAME
    ledger_ep = srv / "ledger_endpoint.json"
    with _LEDGER_START_LOCK:
        # landing 2 (§2.1): K drives start ledgers concurrently — the free-port pick and the bind are one critical
        # section, so two threads can never be handed the same ephemeral port (the second ledger would fail to bind)
        ledger = subprocess.Popen(
            _ledger_cmd(CLIENT_PY, endpoint["proxy_url"], _free_port(), str(ledger_path),
                        str(ledger_ep)),
            env=env, stdout=(srv / "ledger.log").open("w"), stderr=subprocess.STDOUT)
        ledger_ready = _wait_for(ledger_ep, ledger, LEDGER_WAIT_S, step=1.0)
    driver_rc = None
    try:
        if not ledger_ready:
            rec.update(status="LEDGER_FAILED", ledger_tail=_tail(srv / "ledger.log"))
            return rec
        ledger_url = json.loads(ledger_ep.read_text())["ledger_url"]
        rec["ledger_url"] = ledger_url
        rec["usage_ledger"] = str(ledger_path)
        env_driver = dict(env, **{C.INSPECT_BASE_URL_ENV: ledger_url,
                                  C.INSPECT_API_KEY_ENV: endpoint.get("proxy_token") or "petri"},
                          **evalplus_env)

        # --- the served capability driver (client venv) ---------------------------
        # the follow-up (Appendix A): a FRESH attempt id per driver invocation on an IFEval
        # cell, minted from the store's recorded attempts (the driver refuses a re-used one)
        attempt_id = next_attempt_id(out_dir) if ifeval_cfg else None
        rec["attempt_id"] = attempt_id
        # the preflight's resolved-parameter record
        # into the out root (the durable copy beside the store), handed to the
        # driver as --protocol-check — the manifest's by_task.effective is read
        # from it; None on every other configuration
        protocol_check_path: Optional[Path] = None
        if protocol:
            protocol_check_path = out_dir / C.PROTOCOL_CHECK_FILENAME
            protocol_check_path.write_text(json.dumps(dict(protocol_check), indent=1, sort_keys=True, default=str))
            rec["protocol_check"] = str(protocol_check_path)
        cmd = _driver_cmd(tree, cfg, endpoint, ledger_url, geom, controls=driven,
                          limit=limit, inspect_limit=inspect_limit, samples=samples,
                          cfg_path=cfg_path, vllm_log=str(srv / "vllm_server.log"),
                          protocol_check=(str(protocol_check_path) if protocol_check_path else None),
                          oos_prompt_budget=str(budget_path) if budget_path else None,
                          # the SAME digest the standup was just held to
                          # (OBJECT_DIGEST_FLAG above), on the landed lens legs and
                          # the IFEval lens cells (their rows name their object)
                          expect_object_sha256=(object_sha256 if landed_lens_configuration(cfg)
                                                or ifeval_lens_configuration(cfg) else None),
                          # tinycap-shared-standup §1.1.4: the row-engine record the driver copies
                          # into the manifest's UNHASHED row_engine block (row mode only)
                          row_engine_record=((row_facts or {}).get("row_engine_record") or None),
                          attempt_id=attempt_id,
                          # landing 2: the client width S // K (§2.1) and the verification phase (§2.2.3)
                          concurrency_k=concurrency_k, verification_phase=verification_phase)
        rec["driver_argv"] = cmd
        t1 = time.time()
        # capeval-full-tasks: a configuration filing a FULL leg runs under the full legs' own
        # driver bound (contracts.FULL_DRIVER_TIMEOUT_S); every other run keeps DRIVER_TIMEOUT_S
        r = subprocess.run(cmd, cwd=tree, env=env_driver, capture_output=True, text=True,
                           timeout=C.driver_timeout_s_for(_configuration_row_tasks(cfg, controls), DRIVER_TIMEOUT_S))
        rec["driver_s"] = round(time.time() - t1, 1)
        t2 = time.time()
        driver_rc = rec["driver_rc"] = r.returncode
        (out_dir / "driver_stdout.log").write_text(r.stdout)
        (out_dir / "driver_stderr.log").write_text(r.stderr)
        # bcb-bfcl-200-widen: the ENGINE-RESOLVED sampler, read off the
        # standup's server log (launched with --enable-log-requests, _standup_cmd) into the
        # store root beside protocol_check.json — recorded in the REC, never propagated.
        # ifeval-canonical-battery: an IFEval configuration's `vendor_preset`
        # expectation is the PINNED card-table row; the probe class is read PER KIND off the driver's
        # tags in the store root (--probe-expect kinds --probe-tags), the three OFF-leg kind caps are
        # declared, and the row's executed cap is the client cap — resolved_sampler_expectation
        # tinycap-shared-standup: in row mode the log is the ROW's one server log (log_scope: row)
        rec["resolved_sampler"] = record_resolved_sampler(
            tree, srv, out_dir,
            expectation=resolved_sampler_expectation(sampling_mode, row.model_key, list(rec["thinking_by_task"])),
            client_cap=(int(cfg["ifeval_cap"]) if is_ifeval_configuration(cfg) else None))
        if shared_standup:
            rec["resolved_sampler"]["log_scope"] = "row"
        print(f"[resolved-sampler] {cfg['name']}: "
              f"{rec['resolved_sampler'].get('verdict') or 'NO RECORD'}"
              f"{' — ' + str(rec['resolved_sampler']['error']) if rec['resolved_sampler'].get('error') else ''}"
              f" -> {rec['resolved_sampler']['path']}", flush=True)
        if protocol:
            # bcb-bfcl-200-widen: the live belt — vLLM's clamp WARNING
            # ("temperature … is less than 0.01 … maxed it out") in the server
            # log (frontend AND engine-core lines) means a request was re-clamped
            # behind the override; the store is then NOT a protocol store
            rec["clamp_warning_lines"] = clamp_warning_lines(srv / "vllm_server.log")
            if rec["clamp_warning_lines"]:
                driver_rc = rec["driver_rc"] = driver_rc if driver_rc else 1
                rec["status_override"] = C.REC_CLAMP_OVERRIDE_INEFFECTIVE
                rec["error"] = (f"{len(rec['clamp_warning_lines'])} clamp warning line(s) in vllm_server.log — the "
                                f"D13 override did not hold on this server (a spawned child re-clamped?); the "
                                "store's BFCL rows executed at 0.01, not 0.001; use the general-plugin fallback")
                # code review: the failure is made DURABLE at the store root, so every
                # resume path and the analysis refuse it — never a REC status alone
                rec["sampling_validation_failure_path"] = str(write_sampling_validation_failure(
                    out_dir, status=C.REC_CLAMP_OVERRIDE_INEFFECTIVE, error=rec["error"], run_id=run_id,
                    clamp_warning_lines=rec["clamp_warning_lines"], tree_sha=tree_sha, cell=cfg["cell"]))
        try:
            import urllib.request
            with urllib.request.urlopen(f"{ledger_url[:-len('/v1')]}/ledger/stats",
                                        timeout=30) as resp:
                rec["ledger_stats"] = json.loads(resp.read().decode())
        except Exception as e:                     # stats are a courtesy; the file is the record
            rec["ledger_stats_error"] = f"{type(e).__name__}: {e}"
        # bcb-bfcl-200-widen: how many BigCodeBench verifications rode the file transport
        # (the driver's per-store spill ledger beside the usage ledger; n_spilled 0 when none)
        rec["verifier_transport"] = VT.rec_field(out_dir)
        if shared_standup and sweep_dir is not None:
            # landing 2 follow-up: the row store's manifest.route gains the standup's per-cell digest map and the
            # relative row dir (UNHASHED, additive; the downstream reader refuses the null / absent spellings)
            rec["route_stamp"] = stamp_row_store_route(out_dir, endpoint=endpoint, row_dir=sweep_dir)
    finally:
        # --- teardown --------------------------------------------------------------
        if not shared_standup:
            stop.touch()
        try:
            ledger.terminate()
            ledger.wait(timeout=30)
        except Exception:
            ledger.kill()
        if not shared_standup:
            try:
                standup.wait(timeout=300)
            except subprocess.TimeoutExpired:
                standup.kill()
        if driver_rc != 0:
            if shared_standup:
                # the row's server log tail into the cell store's standup/ (the one log file the
                # 40-inode store carries, §1.9.2); the row dir keeps the standup + ledger logs
                copy_standup_files(srv_row, endpoint, out_dir)
            else:
                _persist_logs(srv, out_dir)
        (out_dir / "ledger.log").write_text(_tail(srv / "ledger.log", 2_000_000) or "")
        if sandboxed:
            # the in-process sweep — ONLY this
            # attempt's sandboxes (the FULL owner tuple in the list filter),
            # terminated and VERIFIED by re-list, the certificate written per
            # attempt (watch/sweep_<fcid>.json) so a resumed attempt can never
            # inherit a dead one's verified_empty; a failure to list is recorded,
            # never a silent "nothing left"
            # in row mode the certificate is the ROW dir's
            # watch/sweep_<fcid>__<cell>.json (one FunctionCall, one owner per cell)
            rec["sandbox_sweep"] = (sweep_owned_sandboxes(owner, sweep_dir, record, cell_suffix=True)
                                    if shared_standup else sweep_owned_sandboxes(owner, out_dir, record))
        VOL.commit()
    ev = out_dir / "evidence.json"
    rec["evidence"] = json.loads(ev.read_text()) if ev.exists() else None
    done = sorted(p.name for p in out_dir.glob(f"cells/*/{C.DONE_DIR}/*.json"))
    rec["done_markers"] = done
    after = resume_report(out_dir, wanted, expected) if not rung else ladder_resume_report(out_dir, wanted, expected)
    rec["resume_after"] = after
    rec["controls_still_remaining"] = [c for c in wanted if after["controls"][c]["done_in"] is None]
    complete = driver_rc == 0 and not rec["controls_still_remaining"]
    # bcb-bfcl-200 §S2b: the SAME strict ladder validator the CPU
    # preflight runs decides the ladder REC, so the first successful scoring
    # invocation is PARTIAL_COMPLETE (never INCOMPLETE)
    rec["status"] = (LADDER_REC_STATUS if rung else "OK") if complete else "INCOMPLETE"
    if verification_phase == C.VERIFICATION_PHASE_GENERATE and driver_rc == 0 and rec["controls_still_remaining"]:
        # tinycap-shared-standup §2.2.3 / §2.2.4: under `generate` the driver leaves its BigCodeBench task(s) UNSCORED
        # by contract — the store is GENERATED, not INCOMPLETE, iff every control still remaining is covered by this
        # store's pending marker in the row dir; anything else stays INCOMPLETE and names what is missing
        verdict = generation_pending_verdict(sweep_dir, cell=str(cfg["cell"]), out_dir=out_dir,
                                             remaining=rec["controls_still_remaining"], mode=str(cfg["mode"]))
        rec["verification_pending"] = verdict
        if verdict["problems"]:
            rec["error"] = (f"{cfg['name']}: {C.FLAG_VERIFICATION_PHASE} {C.VERIFICATION_PHASE_GENERATE}: the driver returned 0 with "
                            f"{rec['controls_still_remaining']} left but not every task carries this store's pending marker — "
                            + "; ".join(verdict["problems"]))
        else:
            rec["status"] = REC_GENERATED
    if rec.get("status_override"):
        # bcb-bfcl-200-widen: a re-clamped protocol server is a failed REC by name
        rec["status"] = rec.pop("status_override")
    if not shared_standup:
        # the per-attempt COMPLETION record (COMPLETION_FIELDS): what THIS attempt finished, read off the resume
        # re-read — written sandboxed or not, so a BFCL-only resumption's FunctionCall is on the volume for the
        # receipt of a later DONE relaunch to credit (a row container's cells ride its row pointer instead);
        # before the RESULT stamp, so the commit below persists both
        remaining = list(ctx["remaining"])
        completed = {c: after["controls"][c]["done_in"] for c in remaining if after["controls"][c]["done_in"] is not None}
        rec["completion_record"] = str(write_completion_record(
            out_dir, owner, cfg=cfg, controls=driven, remaining=remaining, completed=completed, status=rec["status"],
            sandboxed=sandboxed, tree_sha=tree_sha))
    standup_token = ""
    if row_facts is not None:
        # tinycap-shared-standup §1.1.2 step 8: the row facts on every cell's REC — the standup is the
        # row's (standup_s null, row_standup_s the shared bring-up), the shared id, the engine's cells
        # and this driver's own interval (diagnostics for the meter's exclusive GPU interval, §1.8)
        rec.update(standup_s=None, row_standup_s=row_facts.get("standup_s"), standup_shared=True,
                   standup_id=row_facts.get("standup_id"), engine_cells=list(row_facts.get("engine_cells") or ()),
                   driver_started_at=t1, driver_ended_at=t2)
        standup_token = f" standup={row_facts.get('standup_id')}"
    with (out_dir / RESULT_FILENAME).open("a", encoding="utf-8") as fh:       # the planner's completion stamp
        fh.write(result_stamp_line(rec, driver_rc=driver_rc) + standup_token + "\n")
    VOL.commit()
    return rec


# --------------------------------------------------------------------------- #
# sandbox ownership — pointers, records, the sweep                              #
# --------------------------------------------------------------------------- #

WATCH_DIR = "watch"
#: tinycap-shared-standup §1.10: the FULL BigCodeBench leg executes in owned sandboxes
#: exactly like the 200 leg, but was never named here — so no full store carried an attempt pointer or a
#: sweep certificate and no watcher could certify a full wave (verified on the mirrored gemma `none` store:
#: `watch/sandboxes_<fcid>.jsonl` only). Naming it makes the SOLO full path write both too (+2 inodes per
#: future solo full store, thirty-six -> thirty-eight) and lets the row runner's pointer / the watcher's `--row-dir` mode work.
SANDBOXED_ROW_TASKS: Tuple[str, ...] = (C.inspect_task("bigcodebench_200"), C.inspect_task("bigcodebench_full"))


def sandboxed_controls(controls: Sequence[str], mode: str) -> bool:
    """Whether any of ``controls`` produces a row task that executes in a
    sandbox (``SANDBOXED_ROW_TASKS``: BigCodeBench-200 and the full BigCodeBench leg)."""
    return any(t in SANDBOXED_ROW_TASKS for c in controls for t in expected_tasks(c, mode))


def current_function_call_id() -> str:
    """This container's Modal FunctionCall id — the ATTEMPT half of the owner
    tuple (``modal.current_function_call_id()``; a resumed cell is a new call).
    Outside a Modal container (a test, a hand run) a ``local-<hex>`` id, so the
    tuple is still unique per process."""
    fn = getattr(modal, "current_function_call_id", None)
    try:
        fcid = fn() if callable(fn) else None
    except Exception:  # noqa: BLE001 — not inside a container
        fcid = None
    return str(fcid) if fcid else f"local-{uuid.uuid4().hex[:12]}"


def sandbox_owner(run_id: str, cell: str, function_call_id: Optional[str] = None) -> "scope.Owner":
    """The owner tuple of THIS container's sandboxes. A launch without a run id
    (a direct ``.remote`` with a hand-built cfg) still gets a unique one, so no
    sandbox is ever created ownerless — but the id says so. ``function_call_id``
    (tinycap-shared-standup §1.1.2 step 5): a ROW container binds every cell's
    owner to ITS one FunctionCall id (read once; outside Modal every read mints a
    fresh local id, so the row passes the one it recorded); None reads it here."""
    rid = str(run_id) if run_id else f"unlaunched-{uuid.uuid4().hex[:8]}"
    return scope.Owner(rid, str(cell), str(function_call_id) if function_call_id else current_function_call_id())


def sandbox_record_path(out_dir: str | Path, owner: "scope.Owner") -> Path:
    """``<out_dir>/watch/sandboxes_<fcid>.jsonl`` — the durable per-attempt
    event record (``sandbox_scope.EVENTS``) the provider appends to."""
    return Path(out_dir) / WATCH_DIR / f"sandboxes_{owner.function_call_id}.jsonl"


def attempt_pointer_path(out_dir: str | Path, function_call_id: str) -> Path:
    return Path(out_dir) / WATCH_DIR / f"attempt_{function_call_id}.json"


def sweep_certificate_path(out_dir: str | Path, function_call_id: str, *, cell: Optional[str] = None) -> Path:
    """``<out_dir>/watch/sweep_<fcid>.json`` — or, with ``cell`` (tinycap-shared-standup §1.10: a ROW
    container sweeps one owner per cell under one FunctionCall), ``sweep_<fcid>__<cell>.json``."""
    tail = f"__{cell}" if cell else ""
    return Path(out_dir) / WATCH_DIR / f"sweep_{function_call_id}{tail}.json"


POINTER_FIELDS: Tuple[str, ...] = (
    "run_id", "cell", "function_call_id", "name", "model", "mode", "out_dir", "controls",
    "tree_sha", "sandbox_record", "sandbox_app_name", "started_at")


def write_attempt_pointer(out_dir: str | Path, owner: "scope.Owner", *, cfg: Mapping,
                          controls: Sequence[str], tree_sha: str, record: Path) -> Path:
    """``<out_dir>/watch/attempt_<fcid>.json`` — what the external watcher
    (``scripts/tinycap_sandbox_watch.py``) keys on: the FULL owner tuple, the
    record and app it lists by, and the FunctionCall it classifies."""
    doc = {"run_id": owner.run_id, "cell": owner.cell, "function_call_id": owner.function_call_id,
           "name": str(cfg.get("name")), "model": str(cfg.get("model") or C.MODEL_SLUG),
           "mode": str(cfg.get("mode")), "out_dir": str(out_dir), "controls": list(controls),
           "tree_sha": tree_sha, "sandbox_record": str(record),
           "sandbox_app_name": C.BCB_SANDBOX_APP_NAME, "started_at": time.time()}
    assert set(doc) == set(POINTER_FIELDS)
    p = attempt_pointer_path(out_dir, owner.function_call_id)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(doc, indent=1, sort_keys=True))
    return p


#: The per-attempt COMPLETION record a SOLO container writes at the end of its drive, sandboxed or not —
#: ``<out_dir>/watch/completion_<fcid>.json`` (stage 07's receipt). The attempt pointer
#: above is written BEFORE the drive and only by a sandboxed attempt (it is what the watcher sweeps by), so a
#: BFCL-only resumption — BigCodeBench validly done, ``driven = remaining = [bfcl_200]``, nothing sandboxed —
#: left NO durable record on the volume of which FunctionCall produced its store, and the receipt of a later
#: DONE relaunch could name the BigCodeBench attempt alone as the execution it reuses. This record states what
#: the attempt ITSELF finished: ``remaining`` (the controls not validly done when it started), ``completed``
#: ({control: the store key it left the control done in} — the subset of ``remaining`` done after the drive, so
#: an earlier attempt's work is never claimed), beside the owner tuple, the tree, the mode and the REC's status.
#: Solo path only: a row container's attribution is its row pointer (every cell riding one FunctionCall), and
#: a row cell's store is bounded at exactly INODES_PER_CELL_STORE with no margin.
COMPLETION_FIELDS: Tuple[str, ...] = (
    "run_id", "cell", "function_call_id", "name", "model", "mode", "out_dir", "controls", "remaining", "completed",
    "status", "sandboxed", "tree_sha", "finished_at")


def completion_record_path(out_dir: str | Path, function_call_id: str) -> Path:
    return Path(out_dir) / WATCH_DIR / f"completion_{function_call_id}.json"


def write_completion_record(out_dir: str | Path, owner: "scope.Owner", *, cfg: Mapping, controls: Sequence[str],
                            remaining: Sequence[str], completed: Mapping[str, str], status: object, sandboxed: bool,
                            tree_sha: str) -> Path:
    """``<out_dir>/watch/completion_<fcid>.json`` — what the receipt credits a store's control to: the attempt
    (the FULL owner tuple) that drove ``controls`` with ``remaining`` left to do and left ``completed`` done."""
    doc = {"run_id": owner.run_id, "cell": owner.cell, "function_call_id": owner.function_call_id,
           "name": str(cfg.get("name")), "model": str(cfg.get("model") or C.MODEL_SLUG), "mode": str(cfg.get("mode")),
           "out_dir": str(out_dir), "controls": list(controls), "remaining": list(remaining),
           "completed": {str(k): str(v) for k, v in completed.items()}, "status": str(status), "sandboxed": bool(sandboxed),
           "tree_sha": tree_sha, "finished_at": time.time()}
    assert set(doc) == set(COMPLETION_FIELDS)
    p = completion_record_path(out_dir, owner.function_call_id)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(doc, indent=1, sort_keys=True))
    return p


def owned_sandbox_lister(owner: "scope.Owner"):
    """``Sandbox.list`` under inspect-sandboxes' app, filtered by the FULL owner
    tuple (Modal returns only sandboxes carrying at least those tags)."""
    app = modal.App.lookup(C.BCB_SANDBOX_APP_NAME, create_if_missing=True)
    app_id = getattr(app, "app_id", None)
    tags = scope.owner_filter(owner)

    def _list():
        return list(modal.Sandbox.list(app_id=app_id, tags=tags))
    return _list, app_id


def sweep_owned_sandboxes(owner: "scope.Owner", out_dir: str | Path, record: Optional[Path],
                          *, by: str = "container_finally", cell_suffix: bool = False) -> Dict[str, object]:
    """The container's ``finally`` sweep: ``sandbox_scope.sweep_owned`` over
    THIS owner's live sandboxes, the certificate written to
    ``watch/sweep_<fcid>.json``. A listing that cannot be made (no Modal client,
    an RPC failure) is RECORDED as ``verified_empty: False`` with the error —
    the external watcher then owns the sweep; never a silent success."""
    try:
        lister, app_id = owned_sandbox_lister(owner)
        cert = scope.sweep_owned(list_sandboxes=lister, owner=owner, by=by, record_path=record)
        cert["sandbox_app_id"] = app_id
    except Exception as e:  # noqa: BLE001 — recorded, never a silent verified sweep
        cert = {**scope.failed_sweep_record(owner, by=by, error=e), "sandbox_app_id": None}
    cert["certificate"] = "sweep"
    # tinycap-shared-standup §1.10: a row container's certificates carry the owner's cell in the name
    p = sweep_certificate_path(out_dir, owner.function_call_id, cell=(owner.cell if cell_suffix else None))
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(cert, indent=1, sort_keys=True, default=str))
    return cert


def _producer_conflict_error(conflicts: Mapping[str, str], out_dir: Path, tree_sha: str) -> str:
    return (f"{sorted(conflicts)} under {out_dir} hold rows produced by "
            f"{sorted(set(conflicts.values()))}, not by the staged tree "
            f"{tree_sha}; the driver refuses to append another revision's rows to "
            "them (their identity is otherwise this run's, so they key the same). "
            "Run this configuration at the producing sha, or give it a fresh out "
            "root")


def _tear_down_standup(stop: Path, standup) -> None:
    """Stop a standup this configuration will not use (a post-standup DONE /
    refusal): touch the stop file and wait for the child, killing a laggard."""
    stop.touch()
    try:
        standup.wait(timeout=300)
    except Exception as e:  # noqa: BLE001 — a laggard is killed, never waited on forever
        print(f"[tinycap] standup did not exit after the stop file ({type(e).__name__}); killing",
              flush=True)
        standup.kill()


def _persist_logs(srv: Path, out_dir: Path) -> None:
    """A driver failure's root cause often lives in the ENGINE log, and the
    srv dir dies with the container — persist the tails."""
    for name in ("vllm_server.log", "standup.log", "ledger.log"):
        src = srv / name
        if src.exists():
            (out_dir / name).write_text(src.read_text(errors="replace")[-2_000_000:])


def next_attempt_id(out_dir: str | Path) -> str:
    """``a<k>`` for THIS driver invocation of an IFEval cell (plan Appendix A; the
    attempt-scoped producer contract): k = 1 + the most ``resume_attempts`` any
    store under ``<out_dir>/cells/*/manifest.json`` records — ``a1`` on a fresh out
    root. The driver stamps the id on every request-evidence record and its own
    attempt entry, and REFUSES a re-used id, so the counter reads the stores'
    recorded attempts and never guesses: a manifest that cannot be read refuses
    by name rather than being counted as zero attempts."""
    n = 0
    for m in sorted(Path(out_dir).glob("cells/*/manifest.json")):
        try:
            doc = json.loads(m.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as e:
            raise ValueError(f"{m}: cannot read the store's manifest to count its attempts ({type(e).__name__}: {e}) "
                             "— a torn manifest names no attempt count; refusing to mint an attempt id over it") from None
        attempts = doc.get(C.MANIFEST_KEY_RESUME_ATTEMPTS) or []
        n = max(n, len(attempts) if isinstance(attempts, list) else 0)
    return C.check_attempt_id_arg(f"a{n + 1}")


#: On the IFEval rows, and now on EVERY tinycap standup: the
#: engine logs the RESOLVED sampler of every request and the worker reads it back IN-PROCESS after
#: the driver (:func:`record_resolved_sampler`, main's mechanism). The flag and the endpoint key
#: are the contracts' (``FLAG_ENABLE_LOG_REQUESTS`` / ``ENDPOINT_KEY_ENABLE_LOG_REQUESTS``); the
#: local names stay as ALIASES of them so its tests keep one spelling.
STANDUP_ENABLE_LOG_REQUESTS_FLAG = C.FLAG_ENABLE_LOG_REQUESTS
ENDPOINT_KEY_ENABLE_LOG_REQUESTS = C.ENDPOINT_KEY_ENABLE_LOG_REQUESTS


def _configuration_worker(cfg: dict, sha: str, **kwargs) -> dict:
    """The ONE worker body both decorated configuration functions run — a PLAIN function:
    an earlier refactor left the ``@app.function`` decorator HERE, so ``configuration_function``
    returned an undecorated Python function for every non-Nemotron row and ``fan_out``'s ``.spawn``
    failed at once, while the Nemotron wrapper called a Modal Function object directly. The Nemotron copy
    had also drifted — it neither accepted nor forwarded ``protocol_check``, so
    every Nemotron configuration would have raised ``TypeError`` at wave time. Every keyword
    ``main`` hands ``fan_out`` (:func:`configuration_kwargs`) is forwarded verbatim."""
    rec = _run_configuration(cfg, sha, **kwargs)
    print("[tinycap] REC", json.dumps({k: v for k, v in rec.items() if k != "evidence"},
                                      default=str))
    return rec


def configuration_kwargs(*, sha: str, limit: int, inspect_limit: int, samples: int, pass_no: int,
                         controls: Optional[Sequence[str]], reduction_mode: str,
                         object_digests: Optional[Mapping[str, Mapping[str, object]]],
                         oos_prompt_budget: Optional[Mapping[str, object]], run_id: str,
                         ladder: Optional[Mapping[str, object]],
                         protocol_check: Optional[Mapping[str, object]]) -> Dict[str, object]:
    """The keyword dictionary EVERY configuration container receives (``fan_out``'s
    ``kwargs``) — the one shape both worker signatures must bind; the dispatch test binds it
    through :func:`run_configuration` AND :func:`run_configuration_nemotron`."""
    return {"sha": sha, "limit": limit, "inspect_limit": inspect_limit, "samples": samples, "pass_no": pass_no,
            "controls": controls, "reduction_mode": reduction_mode, "object_digests": object_digests,
            "oos_prompt_budget": oos_prompt_budget, "run_id": run_id,
            # the certificate every ladder container re-validates (None otherwise)
            "ladder": ladder,
            # bcb-bfcl-200-widen §S2: the preflight's resolved-parameter record every protocol
            # container writes beside its store (None otherwise)
            "protocol_check": protocol_check}


@app.function(image=image, volumes={VOL_PATH: VOL}, gpu="H200", timeout=8 * 3600,
              max_containers=C.MAX_GPU_CONTAINERS)
def run_configuration(cfg: dict, sha: str, limit: int = 0, inspect_limit: int = 0,
                      samples: int = C.MATH500_SAMPLES_PER_ITEM, pass_no: int = 1,
                      controls: Optional[List[str]] = None,
                      reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
                      object_digests: Optional[Dict[str, Dict[str, object]]] = None,
                      oos_prompt_budget: Optional[Dict[str, object]] = None,
                      run_id: str = "", ladder: Optional[Dict[str, object]] = None,
                      protocol_check: Optional[Dict[str, object]] = None) -> dict:
    return _configuration_worker(cfg, sha, limit=limit, inspect_limit=inspect_limit, samples=samples, pass_no=pass_no,
                                 controls=controls, reduction_mode=reduction_mode, object_digests=object_digests,
                                 oos_prompt_budget=oos_prompt_budget, run_id=run_id, ladder=ladder,
                                 protocol_check=protocol_check)


# bcb-bfcl-200-widen (a labelled hedge, not a diagnosed cause): the NemotronH standup
# JIT-compiles the Mamba2 SSD Triton kernel set at engine init (26 s on a 224-core cluster
# node), so the Nemotron function requests CPU explicitly instead of Modal's default share;
# the base-image function is unchanged.
NEMOTRON_FUNCTION_CPU = 8


@app.function(image=image_nemotron, volumes={VOL_PATH: VOL}, gpu="H200", timeout=8 * 3600,
              max_containers=C.MAX_GPU_CONTAINERS, cpu=NEMOTRON_FUNCTION_CPU)
def run_configuration_nemotron(cfg: dict, sha: str, limit: int = 0, inspect_limit: int = 0,
                               samples: int = C.MATH500_SAMPLES_PER_ITEM, pass_no: int = 1,
                               controls: Optional[List[str]] = None,
                               reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
                               object_digests: Optional[Dict[str, Dict[str, object]]] = None,
                               oos_prompt_budget: Optional[Dict[str, object]] = None,
                               run_id: str = "", ladder: Optional[Dict[str, object]] = None,
                               protocol_check: Optional[Dict[str, object]] = None) -> dict:
    """The SAME body as :func:`run_configuration` (``_configuration_worker``) on the Nemotron
    image (bcb-bfcl-200-widen; tinycap-full22 §5.1): the fused Mamba kernels are
    installed in the image and their use is ATTESTED at every standup
    (``full22_endpoint_refusal``) — a container refuses to serve a Nemotron row on the
    pure-torch fallback. The signature mirrors the base worker's exactly."""
    return _configuration_worker(cfg, sha, limit=limit, inspect_limit=inspect_limit, samples=samples, pass_no=pass_no,
                                 controls=controls, reduction_mode=reduction_mode, object_digests=object_digests,
                                 oos_prompt_budget=oos_prompt_budget, run_id=run_id, ladder=ladder,
                                 protocol_check=protocol_check)


@app.function(image=image, volumes={VOL_PATH: VOL}, gpu="H200", timeout=C.FULL_FUNCTION_TIMEOUT_S,
              max_containers=C.MAX_GPU_CONTAINERS)
def run_configuration_full(cfg: dict, sha: str, limit: int = 0, inspect_limit: int = 0,
                           samples: int = C.MATH500_SAMPLES_PER_ITEM, pass_no: int = 1,
                           controls: Optional[List[str]] = None,
                           reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
                           object_digests: Optional[Dict[str, Dict[str, object]]] = None,
                           oos_prompt_budget: Optional[Dict[str, object]] = None,
                           run_id: str = "", ladder: Optional[Dict[str, object]] = None,
                           protocol_check: Optional[Dict[str, object]] = None) -> dict:
    """capeval-full-tasks: the SAME body as :func:`run_configuration` on the base image, under
    the FULL legs' function timeout (``contracts.FULL_FUNCTION_TIMEOUT_S``; the 8 h default stays
    on every other run) — picked by :func:`configuration_function` when the configuration's
    controls name a full leg. The signature mirrors the base worker's exactly."""
    return _configuration_worker(cfg, sha, limit=limit, inspect_limit=inspect_limit, samples=samples, pass_no=pass_no,
                                 controls=controls, reduction_mode=reduction_mode, object_digests=object_digests,
                                 oos_prompt_budget=oos_prompt_budget, run_id=run_id, ladder=ladder,
                                 protocol_check=protocol_check)


@app.function(image=image_nemotron, volumes={VOL_PATH: VOL}, gpu="H200", timeout=C.FULL_FUNCTION_TIMEOUT_S,
              max_containers=C.MAX_GPU_CONTAINERS, cpu=NEMOTRON_FUNCTION_CPU)
def run_configuration_nemotron_full(cfg: dict, sha: str, limit: int = 0, inspect_limit: int = 0,
                                    samples: int = C.MATH500_SAMPLES_PER_ITEM, pass_no: int = 1,
                                    controls: Optional[List[str]] = None,
                                    reduction_mode: str = C.REDUCTION_MODE_LAUNCHER_DEFAULT,
                                    object_digests: Optional[Dict[str, Dict[str, object]]] = None,
                                    oos_prompt_budget: Optional[Dict[str, object]] = None,
                                    run_id: str = "", ladder: Optional[Dict[str, object]] = None,
                                    protocol_check: Optional[Dict[str, object]] = None) -> dict:
    """capeval-full-tasks: :func:`run_configuration_nemotron` under the FULL legs' function timeout."""
    return _configuration_worker(cfg, sha, limit=limit, inspect_limit=inspect_limit, samples=samples, pass_no=pass_no,
                                 controls=controls, reduction_mode=reduction_mode, object_digests=object_digests,
                                 oos_prompt_budget=oos_prompt_budget, run_id=run_id, ladder=ladder,
                                 protocol_check=protocol_check)


def controls_name_full_task(controls: Optional[Sequence[str]]) -> bool:
    """capeval-full-tasks: whether a configuration's ``--controls`` tokens expand to a FULL
    leg (``contracts.CONTROL_BIGCODEBENCH_FULL`` / ``CONTROL_BFCL_FULL``) — the ONE predicate
    behind the function variant and the driver bound."""
    atoms = [a for c in (controls or ()) for a in C.expand_control(c)]
    return any(a in (C.CONTROL_BIGCODEBENCH_FULL, C.CONTROL_BFCL_FULL) for a in atoms)


def _configuration_row_tasks(cfg: Mapping, controls: Optional[Sequence[str]]) -> List[str]:
    """The ROW tasks a configuration files (``expected_tasks`` over its controls at its mode) —
    what ``contracts.driver_timeout_s_for`` keys on."""
    return sorted({t for c in (controls or cfg.get("controls") or ()) for t in expected_tasks(c, cfg["mode"])})


def configuration_function(row: C.ModelRow, controls: Optional[Sequence[str]] = None):
    """The GPU function a row's containers run on: the Nemotron image for the
    ``nemotron_h`` family, the base image for every other row; the ``*_full``
    variant (the FULL legs' function timeout, contracts.FULL_FUNCTION_TIMEOUT_S)
    when ``controls`` name a full leg (capeval-full-tasks) — every other
    configuration's function is exactly what it was."""
    nemotron = row.family == _mamba_backend().NEMOTRON_FAMILY
    if controls_name_full_task(controls):
        return run_configuration_nemotron_full if nemotron else run_configuration_full
    return run_configuration_nemotron if nemotron else run_configuration


# --------------------------------------------------------------------------- #
# the ROW runner — ONE standup per model row, every cell                       #
# driven against it in turn, the row dir beside the stores,                    #
# the exclusive GPU interval, the 40-inode store                               #
# --------------------------------------------------------------------------- #

#: the row-level location OUTSIDE ``native/`` is ``<gen root>/<ROWS_SUBDIR>/<row slug>/<primary
#: suffix>/`` — ROWS_SUBDIR is module E's constant (the inode section below); neither the mirror's store walk nor the
#: reader's ``native/<row>/<cell>/thinking_off/<suffix>`` binding sees it as a store; it is mirrored as a RECORD.
#: exactly THREE row-level standup files are copied into each cell store: today's thirty-six
#: inodes + ``standup/`` (1 dir + these 3 files) = 40, the bound with no margin — nothing else per store
ROW_STANDUP_SUBDIR = "standup"
ROW_STANDUP_FILES: Tuple[str, str, str] = ("endpoint.json", "serving_attestation.json", "vllm_server.log")
ROW_VLLM_LOG_TAIL_BYTES = 2_000_000
#: landing 2 follow-up: the row record kept only the vLLM log's TAIL, so the `Using cache directory` line and
#: the compile factors were lost — the HEAD of the server log (the standup's first ~256 KB: the cache-dir line, the
#: compile / load lines) and vLLM's `cache_key_factors.json` (credentials redacted) are retained ONCE in the row dir
ROW_VLLM_LOG_HEAD_BYTES = 256_000
ROW_VLLM_LOG_HEAD_FILENAME = "vllm_server.head.log"
ROW_CACHE_KEY_FACTORS_FILENAME = "cache_key_factors.json"
ROW_REC_FILENAME = "row_rec.json"
GPU_INTERVAL_FILENAME = "gpu_interval.json"
ROW_ENGINE_RECORD_FILENAME = "row_engine.json"
#: landing 2, code review L2 H1: the row's EXPECTED CPU verifiers, published as durable row state in
#: ``<row dir>/watch/verifiers_<run_id>.json`` BEFORE the GPU container returns under ``generate`` (and by the
#: CPU-only resume's report, and by ``main`` after each spawn) — the watcher's ``--row-dir`` mode withholds DONE
#: until every listed cell has a terminal, certified ``phase verify`` pointer or a terminal no-verifier state.
#: One file per run id (a resume is a new run with its own dispatch); the watcher reads its run's alone. The
#: watcher spells the same name (``tinycap_sandbox_watch.verifiers_record_name``; pinned equal by test).
VERIFIERS_RECORD_TEMPLATE = "verifiers_{run_id}.json"
VERIFIERS_RECORD_SCHEMA = "tinycap_verifiers/1"
#: a listed cell's dispatch state: ``expected`` (the row container listed it; no dispatch yet), ``spawned`` (main
#: spawned its verifier: ``function_call_id`` set), or one of the TERMINAL no-verifier states — ``spawn_failed``
#: (the ``.spawn`` RPC raised; recover with the CPU-only resume), ``verified`` (a resume found the store already
#: verified), ``torn`` (a resume found the store neither pending nor verified: parked by name), ``skipped`` (nothing
#: to dispatch for it). A terminal state tells the watcher no pointer will come under THIS run id.
VERIFIER_STATE_EXPECTED, VERIFIER_STATE_SPAWNING, VERIFIER_STATE_SPAWNED = "expected", "spawning", "spawned"
#: This run JOINED an earlier run's still-running verifier (its call id is the entry's) instead of spawning
#: a second one for the same store — non-terminal: the watcher adopts that call's pointer, whatever run id it carries
VERIFIER_STATE_JOINED = "joined"
#: This run REFUSED to dispatch because an earlier owner is unresolved (a `spawning` entry with no call
#: id, or a call whose live state could not be read) — NON-terminal, and it CARRIES that owner's provenance (`prior`:
#: the earlier run id, state, call id, the probe outcome), so the next attempt re-probes the same owner instead of
#: reading a fresh record as a release. Only a POSITIVE terminal / lost probe (or the operator's explicit
#: --supersede-unresolved for an id-less `spawning`) releases it; the watcher treats it as pending, never DONE
VERIFIER_STATE_BLOCKED = "blocked"
VERIFIER_STATE_SPAWN_FAILED, VERIFIER_STATE_VERIFIED = "spawn_failed", "verified"
VERIFIER_STATE_TORN, VERIFIER_STATE_SKIPPED = "torn", "skipped"
VERIFIER_TERMINAL_STATES: Tuple[str, ...] = (VERIFIER_STATE_SPAWN_FAILED, VERIFIER_STATE_VERIFIED, VERIFIER_STATE_TORN,
                                             VERIFIER_STATE_SKIPPED)
#: the in-run repeat of a cell (§1.1.2 step 9; S10): ``<suffix>-rep2``, the same expected identity, its own store
REPEAT_CELL_SUFFIX = "-rep2"
ROW_PHASE_COUPLED = C.VERIFICATION_PHASE_COUPLED
#: the GPU row's OTHER phase — the BigCodeBench task generated UNSCORED, verified later on CPU
ROW_PHASE_GENERATE = C.VERIFICATION_PHASE_GENERATE
#: the phases a ROW LAUNCH may run (``verify`` is the CPU verifier's subcommand, never a row launch's phase)
ROW_LAUNCH_PHASES: Tuple[str, ...] = (ROW_PHASE_COUPLED, ROW_PHASE_GENERATE)
#: K concurrent cell drivers per row engine at client width S // K — 2 in the lane's launch
#: set, 3 only where landing 1's measured slot occupancy leaves headroom; anything wider refuses by name
ROW_CONCURRENCY_K_MAX = 3
#: landing 2: the row dir's ``generation/`` — the driver's per-(cell, task, STORE) sidecar + pending
#: marker (``<cell>__<task>__<store basename>.json`` / ``pending_<cell>__<task>__<store basename>.json``, the marker
#: EXACTLY ``contracts.PENDING_MARKER_FIELDS``; keyed by store since the in-run repeat runs the same ``--cell`` into
#: ``<suffix>-rep2`` — ``cpu_verify.pending_marker_path`` is the one spelling) and, written by the row container for
#: every GENERATED cell, a copy of its row-engine record the CPU verifier reads (``row_engine__<label>.json``)
#: The host-local root of the row standup's serve dir, ``<root>/srv_row_<row slug>__<suffix>`` (:func:`row_standup_dir`;
#: §1.1.2 step 6): the process's temp root — ``tempfile.gettempdir()``, i.e. ``TMPDIR`` when set, else ``/tmp``, which in
#: the row container is the same ``/tmp`` as before — never the literal ``/tmp``. The serve dir is "this container's
#: /tmp" by design, and two row runners of ONE row and suffix on ONE host break that: each ``rmtree``s and rewrites the
#: other's serve dir, and with it the row-engine record its drivers read and the row copies into the row dir. The
#: landing gate's 40 pytest shards run several per node, each under its own ``TMPDIR``, and two gates' shards of the
#: row-engine tests overlapped on one node (2026-10-09): a relaunch read a record copy naming the OTHER runner's row dir
#: and parked its store as ``torn``. A per-process root keeps each runner's own; the tests pin it under ``tmp_path``.
STANDUP_LOCAL_ROOT: Path = Path(tempfile.gettempdir())


def row_standup_dir(row_slug: str, suffix: str) -> Path:
    """The row standup's serve dir: ``STANDUP_LOCAL_ROOT / srv_row_<row slug>__<suffix>`` (§1.1.2 step 6; one per
    row and suffix under THIS process's temp root, rmtree'd and recreated by every row run)."""
    return Path(STANDUP_LOCAL_ROOT) / f"srv_row_{row_slug}__{suffix}"


ROW_GENERATION_SUBDIR = CV.GENERATION_DIR
PENDING_MARKER_PREFIX = CV.PENDING_MARKER_PREFIX
