ROW_POINTER_FIELDS: Tuple[str, ...] = (*POINTER_FIELDS, "phase", "cells", "row", "row_attempt", "records")
REC_ROW_NOT_UNIFORM = "ROW_NOT_UNIFORM"
REC_ROW_EMPTY = "ROW_EMPTY"
REC_ROW_PARTIAL = "ROW_PARTIAL"
#: An INCOMPLETE store is never resumed — a cell whose store already holds manifests but no valid marker is
#: parked, named, and recovered by the subset relaunch (§1.6.4 / §5), never driven into
REC_INCOMPLETE_STORE_PARKED = "INCOMPLETE_STORE_PARKED"
REC_STANDUP_ID_MISSING = "STANDUP_ID_MISSING"
