REC_INODE_BUDGET_EXCEEDED = "INODE_BUDGET_EXCEEDED"
REC_ROW_TOO_LONG = "ROW_TOO_LONG"
#: the row statuses that are NOT a row refusal (``row_result_recs`` appends the row's own REC for anything else): every
#: cell OK / DONE, a warm probe, a row whose failures are its cells' (ROW_PARTIAL: the failing cells' own RECs carry
#: the non-zero exit), or — landing 2 — a GENERATED row whose BigCodeBench tasks await their CPU verifiers (the cells'
#: own GENERATED RECs and the verify RECs ``main`` harvests decide the exit; GENERATED itself is never an OK status)
ROW_RESULT_OK_STATUSES: Tuple[str, ...] = ("OK", "DONE", REC_ROW_PARTIAL, REC_WARMED, REC_GENERATED)
CACHE_EXPECTATIONS: Tuple[str, str] = ("warm", "cold")
#: the one "coupled" phase: ROW_PHASE_COUPLED is the name; the --verification-phase option's spelling
#: (interfaces §16) stays as an alias
VERIFICATION_PHASE_COUPLED = ROW_PHASE_COUPLED
#: ``main --row`` refuses a row whose forecast exceeds this fraction of the function timeout (§1.1.3)
ROW_FORECAST_FRACTION = 0.8
ROW_OPTS_DEFAULTS: Mapping[str, object] = {
    "concurrency_k": 1, "repeat_cells": (), "negative_control": None, "cache_persist": True,
    "cache_expectation": "cold", "verification_phase": ROW_PHASE_COUPLED, "row_dir": None,
    "warm_cache_only": False, "inode_mount": VOL_PATH}
#: the compile cache's image tag per function image (§1.5: nemotron builds its own kernels)
COMPILE_CACHE_IMAGE_TAG_BASE = "base"
